// DLS_AUTOMATION_LIST_REFRESH_BRIDGE_V121
// Delivery List Management has two independent live inputs: the current list
// catalog and the complete newest import result. Keep both in the app's normal
// state, then call the original Admin renderer so the existing layout remains
// authoritative instead of drawing a second replacement UI.
let dlsAutomationLatestImportCheckedAt = "";
let dlsAutomationActiveDetailRefreshPromise = null;
let dlsAutomationActiveDetailRefreshListId = "";

function dlsAutomationImportResultTime(entry = {}) {
  const text = String(
    entry.checkedAt
    || entry.importedAt
    || entry.updatedAt
    || entry.createdAt
    || "",
  ).trim();
  const parsed = parseAutomationDateValue(text);

  return parsed ? parsed.getTime() : 0;
}

function dlsAutomationImportResultKey(entry = {}, index = 0) {
  const deliveryDate = String(entry.deliveryDate || "").trim();
  const sourceName = String(entry.sourceName || entry.fileName || "").trim().toLowerCase();
  const runStartedAt = String(entry.runStartedAt || entry.startedAt || "").trim();
  const runId = String(
    entry.runId
    || entry.requestId
    || entry.taskId
    || entry.importRunId
    || "",
  ).trim();
  const id = String(entry.id || entry.batchId || "").trim();
  const timestamp = String(
    entry.checkedAt
    || entry.importedAt
    || entry.updatedAt
    || entry.completedAt
    || entry.createdAt
    || "",
  ).trim();

  // One automation run can be represented twice: once by its durable database
  // rows and once by its completion notification. They share the same start time
  // even when older scheduled-run IDs used different prefixes, so start time is
  // the safest cross-source identity for one file result.
  if (runStartedAt) return `started:${runStartedAt}|${deliveryDate}|${sourceName}`;
  if (runId) return `run:${runId}|${deliveryDate}|${sourceName}`;
  if (id && !id.startsWith("-")) return `id:${id}`;
  if (deliveryDate || sourceName || timestamp) return `${deliveryDate}|${sourceName}|${timestamp}`;

  return `unkeyed:${index}`;
}

/** Normalize historical import totals that counted each operational stage copy. */
function normalizeImportResultMetrics(entry = {}) {
  const stageSummaries = (Array.isArray(entry.stageSummaries)
    ? entry.stageSummaries
    : Array.isArray(entry.stages)
      ? entry.stages
      : []).filter((row) => row && typeof row === "object");
  if (!stageSummaries.length) return { ...entry };

  const listId = (row) => String(row.listId || "").trim().toLowerCase();
  const stagePreset = (row) => stagePresetFromValuesV445(row.stage || "", row.scanner || row.stageProfile || "", row.stagePreset || "");
  const stageText = (row) => `${row.stage || ""} ${row.scanner || row.stageProfile || ""}`.trim().toLowerCase();
  const preferred = stageSummaries.find((row) => listId(row).endsWith("-staging-airport"))
    || stageSummaries.find((row) => stagePreset(row) === "airport_staging")
    || stageSummaries.find((row) => listId(row).endsWith("-outbound-airport"))
    || stageSummaries.find((row) => stagePreset(row) === "airport_outbound")
    || stageSummaries.slice().sort((a, b) => (
      Number(b.totalQty || b.originalQty || b.changedPieceQty || 0)
      - Number(a.totalQty || a.originalQty || a.changedPieceQty || 0)
    ))[0];

  const changedStages = stageSummaries.filter((row) =>
    Boolean(row.created || row.reactivated)
    || Number(row.changedLineCount || 0)
    || Number(row.changedPieceQty || 0)
    || Number(row.removedLineCount || 0)
    || Number(row.removedPieceQty || 0),
  );
  const createdStages = stageSummaries.filter((row) => Boolean(row.created));
  const createdStaging = createdStages.some((row) => (
    listId(row).endsWith("-staging-airport") || stagePreset(row) === "airport_staging"
  ));
  const createdOutbound = createdStages.some((row) => (
    listId(row).endsWith("-outbound-airport") || stagePreset(row) === "airport_outbound"
  ));
  const inferredNewDeliveryList = changedStages.length > 0
    && createdStages.length === changedStages.length
    && createdStaging
    && createdOutbound;

  return {
    ...entry,
    stageSummaries,
    newDeliveryList: Object.prototype.hasOwnProperty.call(entry, "newDeliveryList")
      ? Boolean(entry.newDeliveryList)
      : inferredNewDeliveryList,
    createdCount: createdStages.length,
    reactivatedCount: stageSummaries.filter((row) => Boolean(row.reactivated)).length,
    newPieceQty: Number(preferred?.newPieceQty || 0),
    updatedPieceQty: Number(preferred?.updatedPieceQty || 0),
    addedPieceQty: Number(preferred?.addedPieceQty || 0),
    changedPieceQty: Number(preferred?.changedPieceQty || 0),
    removedLineCount: Number(preferred?.removedLineCount || 0),
    removedPieceQty: Number(preferred?.removedPieceQty || 0),
    changedLineCount: Number(preferred?.changedLineCount || 0),
  };
}

function dlsAutomationMergeRecentImports(currentImports = [], incomingImports = []) {
  const merged = new Map();

  [...incomingImports, ...currentImports].forEach((entry, index) => {
    if (!entry || typeof entry !== "object") return;

    const normalizedEntry = normalizeImportResultMetrics(entry);

    const key = dlsAutomationImportResultKey(normalizedEntry, index);
    const existing = merged.get(key);

    if (!existing || dlsAutomationImportResultTime(normalizedEntry) >= dlsAutomationImportResultTime(existing)) {
      merged.set(key, normalizedEntry);
    }
  });

  return [...merged.values()]
    .sort((a, b) =>
      String(b.deliveryDate || "").localeCompare(String(a.deliveryDate || ""))
      || dlsAutomationImportResultTime(b) - dlsAutomationImportResultTime(a),
    )
    .slice(0, 2000);
}

function dlsAutomationDateLabel(value) {
  const parsed = parseAutomationDateValue(value, { dateOnlyAtNoon: true });
  return !parsed
    ? value
    : `${parsed.getMonth() + 1}/${parsed.getDate()}/${parsed.getFullYear()}`;
}

function dlsAutomationStageLabel(item) {
  if (typeof scanStageLabel === "function") return scanStageLabel(item);
  return String(item.stage || item.label || item.scanner || item.id || "Delivery-list stage").trim();
}

function dlsAutomationTryRenderer(renderer, name) {
  if (typeof renderer !== "function") return false;
  try {
    renderer();
    return true;
  } catch (error) {
    console.warn(`Delivery-list catalog renderer ${name} could not run.`, error);
    return false;
  }
}

function dlsAutomationApplyLastUpdatedTimestamp(value) {
  const text = String(value || dlsAutomationLatestImportCheckedAt || "").trim();
  if (!text) return;
  dlsAutomationLatestImportCheckedAt = text;
  const parsed = new Date(text);
  const label = Number.isNaN(parsed.getTime())
    ? text
    : parsed.toLocaleString(appLocale(), { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
  const target = document.getElementById("adminLastUpdated");
  if (target) target.textContent = `Last updated: ${label}`;
}

function dlsAutomationRefreshVisibleListViews(lastCheckedAt = "") {
  const adminPage = document.getElementById("adminPage");
  if (adminPage && !adminPage.hidden) {
    // renderAdmin is the maintained page renderer and preserves the exact
    // Delivery List Management layout. Older add-ons guessed at narrower
    // renderer names and could update the wrong part of the Admin page.
    let rendered = false;
    if (typeof renderAdmin === "function") {
      rendered = dlsAutomationTryRenderer(renderAdmin, "renderAdmin");
    }
    if (!rendered && typeof renderAdminDeliveryLists === "function") {
      rendered = dlsAutomationTryRenderer(renderAdminDeliveryLists, "renderAdminDeliveryLists");
    }
    if (!rendered && typeof renderAdminDeliveryListManagement === "function") {
      rendered = dlsAutomationTryRenderer(renderAdminDeliveryListManagement, "renderAdminDeliveryListManagement");
    }
    if (!rendered && typeof renderAdminDashboard === "function") {
      dlsAutomationTryRenderer(renderAdminDashboard, "renderAdminDashboard");
    }
    window.requestAnimationFrame(() => dlsAutomationApplyLastUpdatedTimestamp(lastCheckedAt));
    return;
  }

  const statisticsPage = document.getElementById("statisticsPage");
  if (statisticsPage && !statisticsPage.hidden) {
    if (typeof renderStatisticsPage === "function") {
      dlsAutomationTryRenderer(renderStatisticsPage, "renderStatisticsPage");
    }
    return;
  }

  const homePage = document.getElementById("homePage");
  if (homePage && !homePage.hidden) {
    if (typeof renderHome === "function" && dlsAutomationTryRenderer(renderHome, "renderHome")) return;
    if (typeof renderHomeDeliveryLists === "function") {
      dlsAutomationTryRenderer(renderHomeDeliveryLists, "renderHomeDeliveryLists");
    }
  }
}

/** Return the catalog fields that determine whether cached line-item detail is still current. */
function deliveryCatalogRevisionKey(list = {}) {
  return [
    list.id,
    list.deliveryDate,
    list.stage,
    list.status,
    list.revision,
    list.updatedAt,
    list.updated_at,
    list.updatedAtUtc,
    list.updated_at_utc,
    list.itemCount,
    list.totalQty,
    list.scannedQty,
  ].map((value) => String(value ?? "")).join("|");
}

/** Return whether the loaded scan rows no longer match the active catalog revision. */
function dlsAutomationActiveDetailIsStale(list = {}) {
  const activeListId = String(state.activeListId || "");
  if (!activeListId || String(list.id || "") !== activeListId) return false;
  if (String(state.meta?.id || "") !== activeListId) return false;

  const catalogRevision = Number(list.revision || 0);
  const loadedRevision = Number(state.meta?.revision || 0);
  const catalogItemCount = Number(list.itemCount || 0);
  const catalogTotalQty = Number(list.totalQty || 0);
  const loadedItemCount = Array.isArray(state.items) ? state.items.length : 0;
  const loadedTotalQty = (state.items || []).reduce((sum, item) => sum + Number(item.qty || 0), 0);

  return catalogRevision !== loadedRevision
    || catalogItemCount !== loadedItemCount
    || catalogTotalQty !== loadedTotalQty;
}

/** Reload the active scan list after an external import changes its database revision. */
function dlsAutomationRefreshActiveListDetail(listId) {
  const cleanListId = String(listId || "").trim();
  if (!state.backend || !cleanListId || String(state.activeListId || "") !== cleanListId) {
    return Promise.resolve(false);
  }
  if (dlsAutomationActiveDetailRefreshPromise && dlsAutomationActiveDetailRefreshListId === cleanListId) {
    return dlsAutomationActiveDetailRefreshPromise;
  }

  dlsAutomationActiveDetailRefreshListId = cleanListId;
  dlsAutomationActiveDetailRefreshPromise = activateList(cleanListId, false)
    .then(() => true)
    .catch((error) => {
      console.warn("The active delivery list could not be refreshed after import.", error);
      return false;
    })
    .finally(() => {
      dlsAutomationActiveDetailRefreshPromise = null;
      dlsAutomationActiveDetailRefreshListId = "";
    });
  return dlsAutomationActiveDetailRefreshPromise;
}

/**
 * Merge lightweight catalog refreshes without discarding already loaded Print / Export rows.
 * Background catalog polling normally returns list summaries. Replacing state.lists outright
 * used to remove the cached items after an idle period, making Airport look selected while
 * preview and print had no rows. Preserve detail only while the list revision is unchanged;
 * changed summaries are invalidated and reloaded on demand.
 */
function mergeDeliveryCatalogWithLoadedDetails(refreshedLists) {
  const previousById = new Map((state.lists || []).map((list) => [String(list.id || ""), list]));
  return refreshedLists.map((refreshed) => {
    const previous = previousById.get(String(refreshed?.id || ""));
    if (!previous) return { ...refreshed };

    const merged = { ...previous, ...refreshed };
    const refreshedItems = Array.isArray(refreshed?.items) ? refreshed.items : [];
    const previousItems = Array.isArray(previous?.items) ? previous.items : [];
    const sameRevision = deliveryCatalogRevisionKey(previous) === deliveryCatalogRevisionKey(refreshed);

    if (refreshedItems.length) {
      merged.items = refreshedItems;
      merged._printItemsLoaded = true;
    } else if (sameRevision && previous._printItemsLoaded && Array.isArray(previous.items)) {
      merged.items = previousItems;
      merged._printItemsLoaded = true;
    } else {
      merged.items = [];
      merged._printItemsLoaded = false;
    }
    return merged;
  });
}

function dlsAutomationApplyDeliveryCatalog(refreshedLists) {
  if (!Array.isArray(refreshedLists)) return false;

  const dateSelect = document.getElementById("deliveryDateSelect");
  const stageSelect = document.getElementById("deliveryStageSelect");
  const previousDate = String(dateSelect?.value || "");
  const previousStage = String(stageSelect?.value || state.activeListId || "");
  state.lists = mergeDeliveryCatalogWithLoadedDetails(refreshedLists);

  const deliveryDates = [...new Set(
    state.lists.map((item) => String(item.deliveryDate || "").trim()).filter(Boolean)
  )].sort();

  if (dateSelect && stageSelect && deliveryDates.length) {
    const today = new Date();
    const todayKey = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
    const selectedDate = deliveryDates.includes(previousDate)
      ? previousDate
      : deliveryDates.find((value) => value >= todayKey) || deliveryDates[deliveryDates.length - 1];

    const deliveryDateGroups = deliveryDates.map((date) => ({
      date,
      lists: state.lists.filter((item) => String(item.deliveryDate || "") === date),
    }));
    dateSelect.dataset.deliveryDateSelect = "true";
    dateSelect.innerHTML = groupedDeliveryDateOptions(
      deliveryDateGroups,
      (group) => `<option value="${escapeHtml(group.date)}">${escapeHtml(dlsAutomationDateLabel(group.date))}</option>`,
    );
    dateSelect.value = selectedDate;

    const selectedDateLists = state.lists.filter(
      (item) => String(item.deliveryDate || "") === selectedDate
    );
    stageSelect.innerHTML = selectedDateLists.map((item) => {
      const listId = String(item.id || "");
      return `<option value="${listId}">${dlsAutomationStageLabel(item)}</option>`;
    }).join("");

    const desiredListId = selectedDateLists.some((item) => String(item.id || "") === previousStage)
      ? previousStage
      : String(selectedDateLists[0]?.id || "");
    if (desiredListId) stageSelect.value = desiredListId;

    if (desiredListId && String(state.activeListId || "") !== desiredListId) {
      state.activeListId = desiredListId;
    }
  }
  return true;
}

function dlsAutomationApplyImportSnapshot(detail = {}) {
  const latestResults = Array.isArray(detail.latestImportResults)
    ? detail.latestImportResults
    : (Array.isArray(detail.recentImports) ? detail.recentImports : null);
  let changed = false;
  let activeDetailNeedsRefresh = false;
  const previousActiveListId = String(state.activeListId || "");
  let detailRefreshListId = previousActiveListId;

  if (latestResults) {
    // Never replace today's import history with only the newest run. Manual and
    // scheduled imports can finish minutes apart, and every run must remain visible.
    state.adminRecentImports = dlsAutomationMergeRecentImports(
      state.adminRecentImports,
      latestResults,
    );
    state.adminTodayImportEntries = dlsAutomationMergeRecentImports(
      state.adminTodayImportEntries,
      latestResults,
    );
    state.adminTodayImportDate = todayKey();
    state.adminTodayImportLoaded = false;
    changed = true;
  }
  if (Array.isArray(detail.lists)) {
    changed = dlsAutomationApplyDeliveryCatalog(detail.lists) || changed;
    detailRefreshListId = String(state.activeListId || "");
    const refreshedActiveList = state.lists.find((list) => String(list.id || "") === detailRefreshListId);
    activeDetailNeedsRefresh = Boolean(
      refreshedActiveList
      && (detailRefreshListId !== previousActiveListId || dlsAutomationActiveDetailIsStale(refreshedActiveList))
    );
  }
  if (detail.lastCheckedAt) {
    dlsAutomationLatestImportCheckedAt = String(detail.lastCheckedAt);
    changed = true;
  }

  if (!changed) return;
  dlsAutomationRefreshVisibleListViews(detail.lastCheckedAt || dlsAutomationLatestImportCheckedAt);
  if (latestResults && typeof refreshAdminTodayImportRuns === "function") {
    // Refresh the durable database-backed history after the newest run is rendered.
    // The immediate merge above prevents any older run from disappearing while this
    // request is in flight.
    window.setTimeout(() => refreshAdminTodayImportRuns({ render: true }), 0);
  }
  document.dispatchEvent(new CustomEvent("dls:delivery-list-catalog-synced", {
    detail: {
      listCount: state.lists.length,
      importResultCount: state.adminRecentImports.length,
      lastCheckedAt: dlsAutomationLatestImportCheckedAt,
      selectedDate: String(document.getElementById("deliveryDateSelect")?.value || ""),
      selectedListId: String(document.getElementById("deliveryStageSelect")?.value || state.activeListId || ""),
      activeDetailNeedsRefresh,
    },
  }));
  if (activeDetailNeedsRefresh) {
    window.setTimeout(() => dlsAutomationRefreshActiveListDetail(detailRefreshListId), 0);
  }
}

document.addEventListener("dls:delivery-list-data-refreshed", (event) => {
  const detail = event.detail && typeof event.detail === "object" ? event.detail : {};
  dlsAutomationApplyImportSnapshot(detail);
  window.setTimeout(() => refreshPendingUpdateDates({ force: true }).catch(() => {}), 250);
});

document.addEventListener("dls:user-line-updates-reviewed", () => {
  // v0.265: stage/date markers are authoritative per user. Do not hide an entire
  // date optimistically because route-specific stages may still need review.
  window.setTimeout(() => refreshPendingUpdateDates({ force: true }).catch(() => {}), 120);
});

document.addEventListener("dls:open-internal-reject-notification", () => {
  showPage("rejects");
  window.setTimeout(() => els.rejectHistory?.scrollIntoView({ behavior: "smooth", block: "start" }), 120);
});

