/**
 * Purpose: Run the translate dynamic UI text workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function translateDynamicUiText(cleanText) {
  const exact = SPANISH_UI_TEXT.get(cleanText);
  if (exact) return exact;

  for (const [pattern, replacement] of SPANISH_DYNAMIC_PATTERNS) {
    const match = cleanText.match(pattern);
    if (!match) continue;
    return typeof replacement === "function"
      ? replacement(...match)
      : cleanText.replace(pattern, replacement);
  }

  // v0.359: text already rendered before the live language switch can contain
  // English month/day names. Convert recognizable locale-generated dates too.
  const localizedDate = translateEnglishLocaleDateV359(cleanText);
  if (localizedDate !== cleanText) return localizedDate;
  return translateUiPhrasesV359(cleanText);
}

/**
 * Purpose: Run the translated UI value workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function translatedUiValue(value) {
  const text = String(value ?? "");
  const leading = text.match(/^\s*/)?.[0] || "";
  const trailing = text.match(/\s*$/)?.[0] || "";
  const clean = text.trim();
  if (!clean) return text;
  return `${leading}${translateDynamicUiText(clean)}${trailing}`;
}

/** Return UI text in the currently selected language for native browser surfaces. */
function localizedUiValue(value) {
  return state.language === "es" ? translatedUiValue(value) : String(value ?? "");
}

/**
 * Translate an ephemeral popup/print document. These documents do not inherit
 * the application's MutationObserver, so Spanish mode must localize them before
 * the browser print dialog opens. User-entered values remain untouched unless
 * they exactly match a maintained UI phrase.
 */
function translateStandaloneDocumentV359(doc) {
  if (state.language !== "es" || !doc?.documentElement) return;
  const walker = doc.createTreeWalker(doc.documentElement, 4);
  let node = walker.nextNode();
  while (node) {
    const parentTag = String(node.parentElement?.tagName || "").toLowerCase();
    if (!["script", "style", "textarea"].includes(parentTag)) {
      const translated = translatedUiValue(node.nodeValue || "");
      if (translated !== node.nodeValue) node.nodeValue = translated;
    }
    node = walker.nextNode();
  }
  doc.querySelectorAll?.("[title], [aria-label], [alt], [data-label]").forEach((element) => {
    ["title", "aria-label", "alt", "data-label"].forEach((attribute) => {
      if (!element.hasAttribute(attribute)) return;
      const current = element.getAttribute(attribute) || "";
      const translated = translatedUiValue(current);
      if (translated !== current) element.setAttribute(attribute, translated);
    });
  });
}

/**
 * Purpose: Run the translate UI text node workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function translateUiTextNode(node) {
  const current = node.nodeValue || "";

  if (state.language === "es") {
    if (current === node.__dlsSpanishText) return;
    node.__dlsEnglishText = current;
    const translated = translatedUiValue(current);
    node.__dlsSpanishText = translated;
    if (translated !== current) node.nodeValue = translated;
    return;
  }

  if (node.__dlsEnglishText !== undefined && current !== node.__dlsEnglishText) {
    node.nodeValue = node.__dlsEnglishText;
  }
}

/**
 * Purpose: Run the translate UI attributes workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function translateUiAttributes(element) {
  // v0.359: include accessibility text, image alternatives, and mobile table
  // labels. data-label is rendered by mobile.css through content: attr(...), so
  // it is user-visible even though it is not a DOM text node.
  const attributes = ["placeholder", "title", "aria-label", "alt", "data-label"];
  if (element.tagName === "OPTGROUP" && element.hasAttribute("label")) attributes.push("label");
  if (element.tagName === "INPUT" && ["button", "submit", "reset"].includes(String(element.type || "").toLowerCase()) && element.hasAttribute("value")) attributes.push("value");

  for (const attribute of attributes) {
    if (!element.hasAttribute?.(attribute)) continue;
    const storageKey = `dls${attribute.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase())}En`;
    const current = element.getAttribute(attribute) || "";

    if (state.language === "es") {
      const spanishKey = `${storageKey}Es`;
      if (!element.dataset[storageKey] || current !== element.dataset[spanishKey]) {
        element.dataset[storageKey] = current;
      }
      const english = element.dataset[storageKey] || current;
      const translated = attribute === "placeholder"
        ? (SPANISH_PLACEHOLDERS.get(english) || translatedUiValue(english))
        : translatedUiValue(english);
      element.dataset[spanishKey] = translated;
      if (element.getAttribute(attribute) !== translated) element.setAttribute(attribute, translated);
    } else if (element.dataset[storageKey] && element.getAttribute(attribute) !== element.dataset[storageKey]) {
      element.setAttribute(attribute, element.dataset[storageKey]);
    }
  }
}

/**
 * Purpose: Run the should skip UI translation workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function shouldSkipUiTranslation(element) {
  return Boolean(element?.closest?.("script, style, textarea, [contenteditable='true'], [data-no-translate]"));
}

/**
 * Purpose: Update the apply language to root workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function applyLanguageToRoot(root = document.body, force = false) {
  if (!root) return;
  // v0.353: English is authored directly in the DOM. Unless a language switch
  // is actively restoring translated nodes, English render paths do no text walk.
  if (state.language !== "es" && !force) return;

  if (root.nodeType === Node.TEXT_NODE) {
    if (!shouldSkipUiTranslation(root.parentElement)) translateUiTextNode(root);
    return;
  }

  if (!(root instanceof Element || root instanceof Document || root instanceof DocumentFragment)) return;

  if (root instanceof Element) translateUiAttributes(root);
  root.querySelectorAll?.("[placeholder], [title], [aria-label], [alt], [data-label], optgroup[label], input[type=button][value], input[type=submit][value], input[type=reset][value]").forEach((element) => translateUiAttributes(element));

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node = walker.nextNode();
  while (node) {
    if (!shouldSkipUiTranslation(node.parentElement)) translateUiTextNode(node);
    node = walker.nextNode();
  }
}

/**
 * Purpose: Run the sync language controls workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function syncLanguageControls() {
  const spanish = state.language === "es";
  document.documentElement.lang = spanish ? "es" : "en";
  document.body.dataset.language = spanish ? "es" : "en";
  document.title = workflowPresentationV355().applicationName;

  [els.languageToggleBtn, els.loginLanguageToggleBtn].forEach((button) => {
    if (!button) return;
    const label = button.querySelector("span:last-child");
    if (label) label.textContent = spanish ? "EN" : "ES";
    const description = spanish ? "Cambiar a Inglés" : "Cambiar a Español";
    button.title = description;
    button.setAttribute("aria-label", description);
  });
}

/**
 * Purpose: Update the set app language workflow using the existing shared UI state.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function setAppLanguage(language) {
  state.language = language === "es" ? "es" : "en";
  try {
    localStorage.setItem(LANGUAGE_KEY, state.language);
  } catch {
    // Language persistence is optional in restricted browser modes.
  }
  applyLanguageToRoot(document.body, true);
  syncLanguageControls();
  syncLanguageMutationObserver();
  applyPortablePresentationV355();
  syncAllCustomSelects();
  window.requestAnimationFrame(() => fitBayLastLocationText());
}

/**
 * Purpose: Toggle the toggle app language workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function toggleAppLanguage() {
  setAppLanguage(state.language === "es" ? "en" : "es");
}

/**
 * Purpose: Run the init language system workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function syncLanguageMutationObserver() {
  if (!languageUi.observer || !document.body) return;
  const shouldObserve = state.language === "es";
  if (shouldObserve === languageUi.observing) return;
  languageUi.observer.disconnect();
  languageUi.observing = false;
  if (!shouldObserve) return;
  languageUi.observer.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ["placeholder", "title", "aria-label", "alt", "data-label", "label", "value"],
  });
  languageUi.observing = true;
}

function initLanguageSystem() {
  if (languageUi.observer) return;
  applyLanguageToRoot(document.body);
  syncLanguageControls();

  // v0.354: English is the source markup, so there is no reason to keep a
  // document-wide MutationObserver running for normal English sessions. The
  // observer is connected only while Spanish is active and disconnected again
  // immediately when the operator returns to English.
  languageUi.observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      if (mutation.type === "characterData") {
        applyLanguageToRoot(mutation.target);
        return;
      }
      if (mutation.type === "attributes") {
        translateUiAttributes(mutation.target);
        return;
      }
      mutation.addedNodes.forEach((node) => applyLanguageToRoot(node));
    });
  });
  syncLanguageMutationObserver();
}

/**
 * Purpose: Determine whether the application is currently using the overlay drawer layout.
 * Effects: None.
 * Flow: Reads the shared responsive breakpoint so JavaScript and CSS use the same mobile boundary.
 */
function isMobileSidebarLayout() {
  return window.matchMedia(`(max-width: ${SIDEBAR_MOBILE_BREAKPOINT}px)`).matches;
}

/**
 * Purpose: Provide page-aware sidebar defaults until the operator saves a preference.
 * Effects: None.
 * Flow: Keeps the Bay Map compact by default while leaving the other workspaces expanded.
 */
function defaultSidebarCollapsedForPage(page = state.page) {
  return true;
}

/**
 * Purpose: Resolve the desktop sidebar state from the saved operator preference or page default.
 * Effects: None.
 * Flow: Honors an explicit saved choice and otherwise uses the page-aware first-run behavior.
 */
function resolvedSidebarCollapsed(page = state.page) {
  return true;
}

/**
 * Purpose: Keep sidebar classes, controls, titles, and responsive drawer state synchronized.
 * Effects: Updates application-shell classes and accessibility attributes.
 * Flow: Uses an overlay drawer on compact screens and the remembered collapsible rail on desktop.
 */
function syncSidebarState({ closeMobile = false } = {}) {
  if (!els.app) return;

  const mobile = isMobileSidebarLayout();
  if (closeMobile) state.sidebarMobileOpen = false;

  if (mobile) {
    els.app.classList.remove("is-sidebar-collapsed");
    els.app.classList.toggle("is-sidebar-mobile-open", state.sidebarMobileOpen);
    els.mobileSidebarToggleBtn?.setAttribute("aria-expanded", String(state.sidebarMobileOpen));
    els.sidebarToggleBtn?.setAttribute("aria-expanded", String(state.sidebarMobileOpen));

    const mobileLabel = state.sidebarMobileOpen ? "Close navigation" : "Open navigation";
    if (els.mobileSidebarToggleBtn) {
      els.mobileSidebarToggleBtn.title = mobileLabel;
      els.mobileSidebarToggleBtn.setAttribute("aria-label", mobileLabel);
    }
    if (els.sidebarToggleBtn) {
      els.sidebarToggleBtn.title = "Close navigation";
      els.sidebarToggleBtn.setAttribute("aria-label", "Close navigation");
      const hiddenLabel = els.sidebarToggleBtn.querySelector(".sr-only");
      if (hiddenLabel) hiddenLabel.textContent = "Close navigation";
    }
  } else {
    state.sidebarMobileOpen = false;
    els.app.classList.remove("is-sidebar-mobile-open");
    els.app.classList.add("is-sidebar-collapsed");
    els.sidebarToggleBtn?.setAttribute("aria-expanded", "false");
    els.mobileSidebarToggleBtn?.setAttribute("aria-expanded", "false");

    if (els.sidebarToggleBtn) {
      els.sidebarToggleBtn.title = "Navigation opens on hover";
      els.sidebarToggleBtn.setAttribute("aria-label", "Navigation opens on hover");
      const hiddenLabel = els.sidebarToggleBtn.querySelector(".sr-only");
      if (hiddenLabel) hiddenLabel.textContent = "Navigation opens on hover";
    }
  }

  const compact = !mobile;
  document.querySelectorAll(".app-sidebar [data-page-target]").forEach((button) => {
    const label = button.querySelector("span:last-child")?.textContent?.trim() || "Page";
    button.title = compact ? label : "";
  });
}

/**
 * Purpose: Toggle the saved desktop sidebar preference or close the mobile drawer.
 * Effects: Persists an explicit desktop preference and updates the application shell.
 * Flow: Mobile uses the control as a close action; desktop switches between rail and full navigation.
 */
function toggleSidebar() {
  if (!isMobileSidebarLayout()) return;
  state.sidebarMobileOpen = false;
  els.userMenu?.removeAttribute("open");
  syncSidebarState();
}

/**
 * Purpose: Open or close the responsive navigation drawer without changing the desktop preference.
 * Effects: Updates the mobile drawer and dismisses the profile flyout when closing.
 * Flow: Keeps compact-device navigation temporary while preserving the workstation layout choice.
 */
function toggleMobileSidebar() {
  if (!isMobileSidebarLayout()) return;
  state.sidebarMobileOpen = !state.sidebarMobileOpen;
  if (!state.sidebarMobileOpen) els.userMenu?.removeAttribute("open");
  syncSidebarState();
}

/**
 * Purpose: Run the sync fullscreen sticky panel offset workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function syncFullscreenStickyPanelOffset() {
  const headerHeight = Math.ceil(els.appHeader?.getBoundingClientRect().height || 108);
  const panelTop = headerHeight + 12;

  document.documentElement.style.setProperty("--sticky-scanner-panel-top", `${panelTop}px`);
  document.documentElement.style.setProperty("--fullscreen-sticky-panel-top", `${panelTop}px`);
}

/**
 * Purpose: Run the sync fullscreen control workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function syncFullscreenControl() {
  const active = Boolean(document.fullscreenElement);
  syncFullscreenStickyPanelOffset();
  syncSidebarState();
  renderRecent();
  if (!els.fullscreenToggleBtn) return;
  els.fullscreenToggleBtn.classList.toggle("is-active", active);
  const label = active ? "Exit fullscreen" : "Enter fullscreen";
  els.fullscreenToggleBtn.title = state.language === "es"
    ? (active ? "Salir de pantalla completa" : "Entrar en pantalla completa")
    : label;
  els.fullscreenToggleBtn.setAttribute("aria-label", els.fullscreenToggleBtn.title);
}

/**
 * Purpose: Toggle the toggle fullscreen workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function toggleFullscreen() {
  if (!document.fullscreenEnabled) {
    showInlineError(state.language === "es" ? "La pantalla completa no está disponible en este navegador." : "Fullscreen is not available in this browser.");
    return;
  }

  if (document.fullscreenElement) await document.exitFullscreen();
  else await document.documentElement.requestFullscreen();
}

/**
 * Purpose: Load the refresh page workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
function refreshPage() {
  try {
    if (document.fullscreenElement) sessionStorage.setItem(FULLSCREEN_REFRESH_KEY, "1");
    else sessionStorage.removeItem(FULLSCREEN_REFRESH_KEY);
  } catch {
    // Fullscreen restoration is optional when session storage is unavailable.
  }
  window.location.reload();
}

/**
 * Purpose: Run the consume fullscreen refresh request workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
function consumeFullscreenRefreshRequest() {
  try {
    const requested = sessionStorage.getItem(FULLSCREEN_REFRESH_KEY) === "1";
    sessionStorage.removeItem(FULLSCREEN_REFRESH_KEY);
    return requested;
  } catch {
    return false;
  }
}

/**
 * Purpose: Open the show fullscreen recovery prompt workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showFullscreenRecoveryPrompt({ eyebrow, message }) {
  showActionFeedback({
    kind: "success",
    eyebrow,
    title: "Return to fullscreen",
    message,
    primaryLabel: "Return to fullscreen",
    secondaryLabel: "Stay in windowed mode",
    onPrimary: async () => {
      if (document.fullscreenElement || !document.fullscreenEnabled) return;
      try {
        await document.documentElement.requestFullscreen();
      } catch {
        showInlineError("Fullscreen could not be resumed. Use the fullscreen button to try again.");
      }
    },
  });
}

/**
 * Purpose: Run the resume fullscreen after refresh workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function resumeFullscreenAfterRefresh() {
  if (!consumeFullscreenRefreshRequest() || document.fullscreenElement) return;
  if (!document.fullscreenEnabled) {
    showFloatingNotice(
      state.language === "es"
        ? "La página se actualizó, pero este navegador no permite pantalla completa."
        : "The page refreshed, but fullscreen is not available in this browser.",
      "notice",
    );
    return;
  }

  try {
    await document.documentElement.requestFullscreen();
  } catch {
    showFullscreenRecoveryPrompt({
      eyebrow: "Page refreshed",
      message: "The page refreshed. Your browser requires one click to enter fullscreen again.",
    });
  }
}

const customSelectUi = {
  initialized: false,
  openSelect: null,
  menu: null,
  highlightedIndex: -1,
  observer: null,
  syncTimer: null,
};

/**
 * Purpose: Run the custom select is eligible workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function customSelectIsEligible(select) {
  return (
    select instanceof HTMLSelectElement &&
    !select.multiple &&
    Number(select.size || 0) <= 1 &&
    !select.hidden &&
    !select.dataset.nativeSelect
  );
}

/**
 * Purpose: Run the custom select accessible label workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function customSelectAccessibleLabel(select) {
  const explicit = select.getAttribute("aria-label") || select.getAttribute("title");
  if (explicit) return explicit;

  const label = select.labels?.[0];
  if (label) {
    const labelText = label.querySelector(":scope > span")?.textContent || label.textContent;
    const clean = String(labelText || "").replace(/\s+/g, " ").trim();
    if (clean) return clean;
  }

  return select.id
    ? select.id.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/[-_]+/g, " ")
    : "Choose an option";
}

/**
 * Purpose: Run the custom select selected text workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function customSelectSelectedText(select) {
  const option = select.selectedOptions?.[0] || select.options?.[select.selectedIndex];
  return option?.dataset.selectedLabel?.trim() || option?.textContent?.trim() || select.getAttribute("placeholder") || "Choose an option";
}

/**
 * v0.471: Return a lightweight signature for the option set currently owned by
 * a native select. Dynamic selects can receive their options after their custom
 * menu has already opened; tracking the option set lets that open menu refresh
 * immediately instead of remaining stuck on an earlier empty snapshot.
 */
function customSelectOptionSignature(select) {
  return [...(select?.options || [])].map((option, index) => [
    index,
    option.value,
    option.textContent?.trim() || "",
    option.disabled ? "1" : "0",
    option.hidden ? "1" : "0",
  ].join(":")) .join("|");
}

function customSelectUpdateIndicatorTitle(select, option, indicatorCount) {
  const countText = indicatorCount || "Unreviewed";
  const lineText = indicatorCount === 1 ? "line" : "lines";
  if (select?.id === "deliveryStageSelect") {
    const stageLabel = String(option?.textContent || "this stage").trim() || "this stage";
    return `${countText} new or updated ${lineText} need review in ${stageLabel}`;
  }
  return `${countText} new or updated ${lineText} need review on this delivery date`;
}

/**
 * Purpose: Run the sync custom select workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function syncCustomSelect(select) {
  const shell = select.closest(".custom-select-shell");
  const trigger = shell?.querySelector(":scope > .custom-select-trigger");
  const value = trigger?.querySelector(".custom-select-value");
  if (!shell || !trigger || !value) return;

  // v0.471: custom menus are portaled to <body> and normally render their
  // option rows only when opened. If a backend response fills a select while
  // its menu is already open (Statistics common glass sizes is one example),
  // rebuild the visible rows in place and preserve any active menu search.
  if (customSelectUi.openSelect === select && customSelectUi.menu) {
    const signature = customSelectOptionSignature(select);
    if (customSelectUi.menu.dataset.optionSignatureV471 !== signature) {
      const optionsHost = customSelectUi.menu.querySelector(".custom-select-options");
      const query = customSelectUi.menu.querySelector(".custom-select-search input")?.value || "";
      if (optionsHost) renderCustomSelectOptions(select, optionsHost, query);
      customSelectUi.menu.dataset.optionSignatureV471 = signature;
      positionCustomSelectMenu();
    }
  }

  const option = select.selectedOptions?.[0] || select.options?.[select.selectedIndex];
  const disabled = Boolean(select.disabled);
  const hidden = Boolean(select.hidden);
  const sourceClasses = [...select.classList].filter((name) => name !== "custom-select-native");

  trigger.className = "custom-select-trigger";
  sourceClasses.forEach((name) => trigger.classList.add(name));
  const rackStatusCue = String(option?.dataset.rackStatus || "").trim();
  const rackRouteCue = String(option?.dataset.rackRoute || "").trim();
  const rackSetColor = String(option?.dataset.rackColor || "").trim();
  if (rackStatusCue) trigger.classList.add(`rack-select-status-${rackStatusCue}`);
  if (rackRouteCue) trigger.classList.add(`rack-select-route-${rackRouteCue}`);
  if (rackSetColor) trigger.style.setProperty("--rack-location-color", rackSetColor);
  else trigger.style.removeProperty("--rack-location-color");
  trigger.disabled = disabled;
  trigger.setAttribute("aria-disabled", disabled ? "true" : "false");
  trigger.setAttribute("aria-expanded", customSelectUi.openSelect === select ? "true" : "false");
  trigger.title = option?.textContent?.trim() || customSelectAccessibleLabel(select);
  const selectedText = customSelectSelectedText(select);
  const rackRouteLabel = String(option?.dataset.rackRouteLabel || "").trim();
  // v0.352: operational rack selectors mirror the opened option row. Route is
  // a colored cue at the front, followed by the full rack summary. Inline
  // Location editors keep their compact display through data-selected-label.
  const bayStatusBadge = String(option?.dataset.bayStatusBadge || "").trim();
  const bayStatusKind = String(option?.dataset.bayStatusKind || "").trim();
  const baySelectedLabel = String(option?.dataset.baySelectedLabel || "").trim();
  if (bayStatusBadge) {
    value.innerHTML = `<span class="bay-selected-option-v442"><span>${escapeHtml(baySelectedLabel || selectedText)}</span><b class="bay-target-status-badge-v442 is-${escapeHtml(bayStatusKind || "available")}">${escapeHtml(bayStatusBadge)}</b></span>`;
  } else if (rackStatusCue && rackRouteCue && rackRouteLabel) {
    value.innerHTML = `<span class="rack-selected-option-v352"><b class="rack-select-option-route-v345 rack-select-route-${escapeHtml(rackRouteCue)}">${escapeHtml(rackRouteLabel)}</b><span class="rack-selected-option-summary-v352">${escapeHtml(selectedText)}</span></span>`;
  } else {
    value.textContent = selectedText;
  }
  const indicator = trigger.querySelector(".custom-select-value-indicator");
  const indicatorKind = String(option?.dataset.customIndicator || "").trim();
  const indicatorCount = Math.max(Number(option?.dataset.customIndicatorCount || 0), 0);
  trigger.classList.toggle("has-indicator", Boolean(indicatorKind));
  if (indicator) {
    indicator.hidden = !indicatorKind;
    indicator.className = `custom-select-value-indicator${indicatorKind ? ` is-${indicatorKind}` : ""}`;
    indicator.textContent = indicatorKind === "new" ? "!" : "";
    indicator.title = indicatorKind === "new"
      ? customSelectUpdateIndicatorTitle(select, option, indicatorCount)
      : "";
  }

  shell.hidden = hidden;
  shell.classList.toggle("is-disabled", disabled);
  shell.classList.toggle("is-open", customSelectUi.openSelect === select);
  shell.classList.toggle("is-placeholder", !option || (!option.value && option.disabled));

  if (customSelectUi.openSelect === select && customSelectUi.menu) {
    customSelectUi.menu.querySelectorAll("[data-custom-option-index]").forEach((button) => {
      const optionIndex = Number(button.dataset.customOptionIndex);
      const selected = optionIndex === select.selectedIndex;
      button.classList.toggle("is-selected", selected);
      button.setAttribute("aria-selected", selected ? "true" : "false");
    });
  }
}

/**
 * Purpose: Run the sync all custom selects workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function syncAllCustomSelects() {
  if (customSelectUi.openSelect && !customSelectUi.openSelect.isConnected) closeCustomSelect(false);
  document.querySelectorAll("select[data-custom-select-enhanced='true']").forEach((select) => syncCustomSelect(select));
}

/**
 * Purpose: Run the position custom select menu workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function positionCustomSelectMenu() {
  const select = customSelectUi.openSelect;
  const menu = customSelectUi.menu;
  const trigger = select?.closest(".custom-select-shell")?.querySelector(":scope > .custom-select-trigger");
  if (!select || !menu || !trigger) return;

  const rect = trigger.getBoundingClientRect();
  const viewportPadding = 10;
  const longestOptionLength = [...select.options].reduce(
    (length, option) => Math.max(length, option.textContent?.trim().length || 0),
    0,
  );
  const contentWidth = Math.min(420, Math.max(210, longestOptionLength * 7.2 + 58));
  const isScanDateSelect = select.id === "deliveryDateSelect";
  const isScanStageSelect = select.id === "deliveryStageSelect";
  const isInlineRackSelect = select.matches?.("[data-line-rack-select]");
  const isInlineBaySelect = select.matches?.("[data-line-bay-select-v449]");
  const isRackSelect = [...select.options].some((option) => Boolean(option.dataset.rackStatus));
  const isCompactLocationSelect = isInlineRackSelect || isInlineBaySelect || isRackSelect;
  const isScanContextSelect = isScanDateSelect || isScanStageSelect;
  // The stage menu should follow its trigger exactly; the date menu needs a
  // little extra width so Monday-Friday headers remain readable on one line.
  // v0.350: operational rack menus intentionally open 30% smaller than the
  // previous 430px presentation. The trigger can remain full-width while the
  // body-mounted menu is a compact, scrollable operator list.
  // v0.351: expand the v0.350 compact rack menu by 13% without returning to
  // the former oversized menu. 0.791 = 0.70 * 1.13.
  const rackMenuScale = 0.791;
  const rackOpenMenuWidth = Math.max(294, Math.min(340, Math.round(rect.width * rackMenuScale)));
  const preferredWidth = isScanDateSelect
    ? Math.max(rect.width, 244)
    : isScanStageSelect
      ? rect.width
      : isCompactLocationSelect
        ? rackOpenMenuWidth
        : Math.max(rect.width, contentWidth);
  const minimumWidth = isScanDateSelect
    ? Math.max(rect.width, 220)
    : isScanStageSelect
      ? rect.width
      : isCompactLocationSelect
        ? Math.min(294, rackOpenMenuWidth)
        : 210;
  const availableWidth = Math.max(160, window.innerWidth - viewportPadding * 2);
  const menuWidth = Math.min(Math.max(preferredWidth, Math.min(minimumWidth, availableWidth)), availableWidth);

  menu.style.width = `${menuWidth}px`;
  menu.style.left = `${Math.min(Math.max(rect.left, viewportPadding), window.innerWidth - menuWidth - viewportPadding)}px`;

  const menuHeight = Math.min(menu.scrollHeight || 320, Math.max(180, window.innerHeight - viewportPadding * 2));
  const spaceBelow = window.innerHeight - rect.bottom - viewportPadding;
  const spaceAbove = rect.top - viewportPadding;
  const openAbove = spaceBelow < Math.min(menuHeight, 280) && spaceAbove > spaceBelow;

  menu.classList.toggle("opens-above", openAbove);
  const availableVertical = Math.max(160, openAbove ? spaceAbove : spaceBelow);
  const menuVerticalLimit = isCompactLocationSelect
    ? Math.max(181, Math.floor(availableVertical * rackMenuScale))
    : availableVertical;
  menu.style.maxHeight = `${menuVerticalLimit}px`;
  menu.style.top = openAbove
    ? `${Math.max(viewportPadding, rect.top - Math.min(menuHeight, menuVerticalLimit) - 7)}px`
    : `${Math.min(window.innerHeight - viewportPadding, rect.bottom + 7)}px`;
}

/**
 * Purpose: Update the set custom select highlight workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function setCustomSelectHighlight(index, focus = true) {
  const buttons = [...(customSelectUi.menu?.querySelectorAll("[data-custom-option-index]:not(:disabled)") || [])];
  if (!buttons.length) {
    customSelectUi.highlightedIndex = -1;
    return;
  }

  const safeIndex = Math.min(Math.max(index, 0), buttons.length - 1);
  customSelectUi.highlightedIndex = safeIndex;
  buttons.forEach((button, buttonIndex) => button.classList.toggle("is-highlighted", buttonIndex === safeIndex));

  if (focus) {
    buttons[safeIndex].focus({ preventScroll: true });
    buttons[safeIndex].scrollIntoView({ block: "nearest" });
  }
}

/**
 * Purpose: Close the close custom select workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function closeCustomSelect(restoreFocus = false) {
  const select = customSelectUi.openSelect;
  const trigger = select?.closest(".custom-select-shell")?.querySelector(":scope > .custom-select-trigger");
  const timedConfirmationShell = customSelectUi.menu?._timedConfirmationShell
    || select?.closest?.("[data-timed-scan-confirmation]")
    || null;

  customSelectUi.menu?.remove();
  customSelectUi.menu = null;
  customSelectUi.openSelect = null;
  customSelectUi.highlightedIndex = -1;
  timedConfirmationShell?._setCustomSelectOpen?.(false);

  if (select) syncCustomSelect(select);
  if (restoreFocus) trigger?.focus();
}

/**
 * Purpose: Run the custom select option rows workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function customSelectOptionRows(select, query = "") {
  const cleanQuery = String(query || "").trim().toLowerCase();
  const rows = [];
  let currentGroup = "";

  [...select.options].forEach((option, index) => {
    if (option.hidden) return;
    const text = option.textContent?.trim() || option.value;
    if (cleanQuery && !`${text} ${option.value}`.toLowerCase().includes(cleanQuery)) return;

    const parentGroup = option.parentElement instanceof HTMLOptGroupElement
      ? option.parentElement.label.trim()
      : "";

    if (parentGroup && parentGroup !== currentGroup) {
      rows.push({ type: "group", label: parentGroup });
      currentGroup = parentGroup;
    }

    rows.push({ type: "option", option, index, text });
  });

  return rows;
}

/**
 * Purpose: Render the render custom select options workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderCustomSelectOptions(select, optionsHost, query = "") {
  optionsHost.replaceChildren();
  const rows = customSelectOptionRows(select, query);

  if (!rows.some((row) => row.type === "option")) {
    const empty = document.createElement("div");
    empty.className = "custom-select-empty";
    empty.textContent = "No matching options";
    optionsHost.append(empty);
    customSelectUi.highlightedIndex = -1;
    return;
  }

  rows.forEach((row) => {
    if (row.type === "group") {
      const group = document.createElement("div");
      group.className = "custom-select-group";
      group.textContent = row.label;
      optionsHost.append(group);
      return;
    }

    const button = document.createElement("button");
    button.type = "button";
    button.className = "custom-select-option";
    button.dataset.customOptionIndex = String(row.index);
    button.disabled = Boolean(row.option.disabled);
    button.setAttribute("role", "option");
    button.setAttribute("aria-selected", row.index === select.selectedIndex ? "true" : "false");
    button.classList.toggle("is-selected", row.index === select.selectedIndex);
    button.classList.toggle("is-date-option", select.id === "deliveryDateSelect" || select.dataset.deliveryDateSelect === "true");
    const rackStatusCue = String(row.option.dataset.rackStatus || "").trim();
    const rackRouteCue = String(row.option.dataset.rackRoute || "").trim();
    const rackSetColor = String(row.option.dataset.rackColor || "").trim();
    const bayStatusBadge = String(row.option.dataset.bayStatusBadge || "").trim();
    const bayStatusKind = String(row.option.dataset.bayStatusKind || "").trim();
    if (bayStatusBadge) {
      button.classList.add("bay-target-option-v442", `is-${bayStatusKind || "available"}`);
    }
    if (rackStatusCue) button.classList.add(`rack-select-status-${rackStatusCue}`);
    if (rackRouteCue) button.classList.add(`rack-select-route-${rackRouteCue}`);
    if (rackSetColor) {
      button.dataset.rackColor = rackSetColor;
      button.style.setProperty("--rack-location-color", rackSetColor);
    }

    const label = document.createElement("span");
    label.className = "custom-select-option-label";
    label.textContent = String(row.option.dataset.baySelectedLabel || "").trim() || row.text;

    const bayStatusCue = bayStatusBadge ? document.createElement("b") : null;
    if (bayStatusCue) {
      bayStatusCue.className = `bay-target-status-badge-v442 is-${bayStatusKind || "available"}`;
      bayStatusCue.textContent = bayStatusBadge;
      bayStatusCue.title = String(row.option.dataset.bayStatusLabel || "Bay status");
    }

    const rackCueWrap = rackStatusCue || rackRouteCue ? document.createElement("span") : null;
    if (rackCueWrap) {
      rackCueWrap.className = "rack-select-option-cues-v345";
      if (rackStatusCue) {
        const statusCueDot = document.createElement("i");
        statusCueDot.className = `rack-select-option-status-v345 rack-select-status-${rackStatusCue}`;
        statusCueDot.title = String(row.option.dataset.rackStatusLabel || "Rack status");
        rackCueWrap.append(statusCueDot);
      }
      const routeLabel = String(row.option.dataset.rackRouteLabel || "").trim();
      if (rackRouteCue && routeLabel) {
        const routeCuePill = document.createElement("b");
        routeCuePill.className = `rack-select-option-route-v345 rack-select-route-${rackRouteCue}`;
        routeCuePill.textContent = routeLabel;
        rackCueWrap.append(routeCuePill);
      }
    }

    const check = document.createElement("span");
    check.className = "custom-select-option-check";
    check.setAttribute("aria-hidden", "true");

    const indicatorKind = String(row.option.dataset.customIndicator || "").trim();
    const indicatorCount = Math.max(Number(row.option.dataset.customIndicatorCount || 0), 0);
    const indicator = document.createElement("span");
    button.classList.toggle("has-indicator", Boolean(indicatorKind));
    indicator.className = `custom-select-option-indicator${indicatorKind ? ` is-${indicatorKind}` : ""}`;
    indicator.hidden = !indicatorKind;
    indicator.textContent = indicatorKind === "new" ? "!" : "";
    indicator.title = indicatorKind === "new"
      ? customSelectUpdateIndicatorTitle(select, row.option, indicatorCount)
      : "";

    if (rackCueWrap) button.append(rackCueWrap);
    button.append(label);
    if (bayStatusCue) button.append(bayStatusCue);
    button.append(indicator, check);
    const deleteAction = String(row.option.dataset.customDeleteAction || "").trim();
    const optionRow = deleteAction ? document.createElement("div") : null;
    if (optionRow) {
      optionRow.className = "custom-select-option-row";
      optionRow.append(button);
      optionsHost.append(optionRow);
    } else {
      optionsHost.append(button);
    }

    button.addEventListener("click", () => {
      if (row.option.disabled) return;
      const changed = select.selectedIndex !== row.index;
      select.selectedIndex = row.index;
      syncCustomSelect(select);
      closeCustomSelect(true);

      if (changed) {
        void playAppSound("collapse_close");
        select.dispatchEvent(new Event("input", { bubbles: true }));
        select.dispatchEvent(new Event("change", { bubbles: true }));
      }
    });

    if (optionRow) {
      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "custom-select-option-delete";
      deleteButton.setAttribute("aria-label", `Delete ${row.text}`);
      deleteButton.title = `Delete ${row.text}`;
      deleteButton.dataset.customDeleteAction = deleteAction;
      deleteButton.innerHTML = `<span class="custom-select-delete-icon" aria-hidden="true"></span>`;
      deleteButton.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        select.dispatchEvent(new CustomEvent("custom-option-delete", {
          bubbles: true,
          detail: {
            action: deleteAction,
            value: row.option.value,
            text: row.text,
            index: row.index,
          },
        }));
        closeCustomSelect(true);
      });
      optionRow.append(deleteButton);
    }
  });

  if (select.id === "printDateQuickSelect") appendPrintQuickDateHistoryControl(select, optionsHost, query);

  const enabledButtons = [...optionsHost.querySelectorAll("[data-custom-option-index]:not(:disabled)")];
  const selectedEnabledIndex = enabledButtons.findIndex((button) => Number(button.dataset.customOptionIndex) === select.selectedIndex);
  setCustomSelectHighlight(selectedEnabledIndex >= 0 ? selectedEnabledIndex : 0, false);
}

/**
 * Purpose: Open the open custom select workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function openCustomSelect(select) {
  if (!customSelectIsEligible(select) || select.disabled) return;
  if (customSelectUi.openSelect === select) {
    closeCustomSelect(true);
    void playAppSound("collapse_close");
    return;
  }

  closeCustomSelect(false);
  void playAppSound("collapse_open");
  customSelectUi.openSelect = select;

  const shell = select.closest(".custom-select-shell");
  const trigger = shell?.querySelector(":scope > .custom-select-trigger");
  if (!shell || !trigger) return;

  const menu = document.createElement("div");
  const timedConfirmationShell = select.closest("[data-timed-scan-confirmation]");
  const scanContextMenu = select.id === "deliveryDateSelect" || select.id === "deliveryStageSelect";
  const rackSelectMenu = [...select.options].some((option) => Boolean(option.dataset.rackStatus));
  const rackTransferMenu = Boolean(select.closest(".rack-transfer-dialog-v356"));
  menu.className = `custom-select-menu${timedConfirmationShell ? " is-timed-confirmation-menu" : ""}${scanContextMenu ? " is-scan-context-menu" : ""}${rackSelectMenu ? " is-rack-select-menu-v351" : ""}${rackTransferMenu ? " is-rack-transfer-menu-v357" : ""}`;
  // v0.357: Move Rack lives inside the Operations modal, but its shared menu is
  // mounted under <body>. Give that menu an explicit top-level stack so it can
  // never render behind the modal panel or its backdrop.
  if (rackTransferMenu) menu.style.zIndex = "60000";
  menu._timedConfirmationShell = timedConfirmationShell || null;
  timedConfirmationShell?._setCustomSelectOpen?.(true);
  menu.id = `${select.id || `customSelect${Date.now()}`}Menu`;
  menu.dataset.selectId = select.id || "";
  menu.setAttribute("role", "listbox");
  menu.setAttribute("aria-label", customSelectAccessibleLabel(select));

  const optionsHost = document.createElement("div");
  optionsHost.className = "custom-select-options";

  const visibleOptionCount = [...select.options].filter((option) => !option.hidden).length;
  if (visibleOptionCount >= 10) {
    const searchWrap = document.createElement("label");
    searchWrap.className = "custom-select-search";

    const searchIcon = document.createElement("span");
    searchIcon.className = "custom-select-search-icon";
    searchIcon.setAttribute("aria-hidden", "true");

    const search = document.createElement("input");
    search.type = "search";
    search.autocomplete = "off";
    search.placeholder = "Filter options...";
    search.setAttribute("aria-label", `Filter ${customSelectAccessibleLabel(select)}`);
    search.addEventListener("input", () => {
      renderCustomSelectOptions(select, optionsHost, search.value);
      positionCustomSelectMenu();
    });
    search.addEventListener("keydown", (event) => {
      if (event.key === "ArrowDown") {
        event.preventDefault();
        setCustomSelectHighlight(0);
      } else if (event.key === "Escape") {
        event.preventDefault();
        closeCustomSelect(true);
      }
    });

    searchWrap.append(searchIcon, search);
    menu.append(searchWrap);
  }

  menu.append(optionsHost);
  document.body.append(menu);
  customSelectUi.menu = menu;

  trigger.setAttribute("aria-controls", menu.id);
  renderCustomSelectOptions(select, optionsHost);
  menu.dataset.optionSignatureV471 = customSelectOptionSignature(select);
  syncCustomSelect(select);
  positionCustomSelectMenu();

  if (select.id === "printDateQuickSelect") {
    let loadingOlderDates = false;
    optionsHost.addEventListener("scroll", () => {
      if (loadingOlderDates || select.dataset.hasMoreHistory !== "true") return;
      const distanceFromBottom = optionsHost.scrollHeight - optionsHost.scrollTop - optionsHost.clientHeight;
      if (distanceFromBottom > 18) return;
      loadingOlderDates = true;
      extendPrintQuickDateMenu(select, optionsHost, "");
      window.requestAnimationFrame(() => { loadingOlderDates = false; });
    }, { passive: true });
  }

  menu.addEventListener("keydown", (event) => {
    const enabledButtons = [...menu.querySelectorAll("[data-custom-option-index]:not(:disabled)")];
    const focusedIndex = enabledButtons.indexOf(document.activeElement);

    if (event.key === "ArrowDown") {
      event.preventDefault();
      setCustomSelectHighlight(focusedIndex >= 0 ? focusedIndex + 1 : customSelectUi.highlightedIndex + 1);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setCustomSelectHighlight(focusedIndex >= 0 ? focusedIndex - 1 : customSelectUi.highlightedIndex - 1);
    } else if (event.key === "Home") {
      event.preventDefault();
      setCustomSelectHighlight(0);
    } else if (event.key === "End") {
      event.preventDefault();
      setCustomSelectHighlight(enabledButtons.length - 1);
    } else if (event.key === "Escape" || event.key === "Tab") {
      closeCustomSelect(event.key === "Escape");
    }
  });

  const searchInput = menu.querySelector(".custom-select-search input");
  if (searchInput) {
    searchInput.focus();
  } else {
    requestAnimationFrame(() => setCustomSelectHighlight(customSelectUi.highlightedIndex >= 0 ? customSelectUi.highlightedIndex : 0));
  }
}

/**
 * Purpose: Run the enhance custom select workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function enhanceCustomSelect(select) {
  if (!customSelectIsEligible(select) || select.dataset.customSelectEnhanced === "true") return;

  const shell = document.createElement("span");
  shell.className = "custom-select-shell";
  shell.dataset.customSelectFor = select.id || "dynamic";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "custom-select-trigger";
  trigger.setAttribute("role", "combobox");
  trigger.setAttribute("aria-haspopup", "listbox");
  trigger.setAttribute("aria-expanded", "false");
  trigger.setAttribute("aria-label", customSelectAccessibleLabel(select));

  const value = document.createElement("span");
  value.className = "custom-select-value";

  const indicator = document.createElement("span");
  indicator.className = "custom-select-value-indicator";
  indicator.hidden = true;
  indicator.setAttribute("aria-hidden", "true");

  const arrow = document.createElement("span");
  arrow.className = "custom-select-arrow";
  arrow.setAttribute("aria-hidden", "true");

  trigger.append(value, indicator, arrow);
  select.parentNode?.insertBefore(shell, select);
  shell.append(select, trigger);

  select.dataset.customSelectEnhanced = "true";
  select.classList.add("custom-select-native");
  select.tabIndex = -1;
  select.setAttribute("aria-hidden", "true");

  trigger.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openCustomSelect(select);
  });

  trigger.addEventListener("keydown", (event) => {
    if (["Enter", " ", "ArrowDown", "ArrowUp"].includes(event.key)) {
      event.preventDefault();
      openCustomSelect(select);
    }
  });

  select.addEventListener("input", () => syncCustomSelect(select));
  select.addEventListener("change", () => syncCustomSelect(select));

  syncCustomSelect(select);
}

/**
 * Purpose: Run the enhance custom selects workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function enhanceCustomSelects(root = document) {
  if (root instanceof HTMLSelectElement) {
    enhanceCustomSelect(root);
    return;
  }
  root.querySelectorAll?.("select").forEach((select) => enhanceCustomSelect(select));
}

/**
 * Purpose: Run the init custom select system workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function initCustomSelectSystem() {
  if (customSelectUi.initialized) return;
  customSelectUi.initialized = true;

  enhanceCustomSelects(document);

  customSelectUi.observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      if (mutation.type === "childList") {
        mutation.addedNodes.forEach((node) => {
          if (!(node instanceof Element)) return;
          if (node instanceof HTMLSelectElement || node.matches?.("select")) {
            enhanceCustomSelect(node);
            return;
          }
          // v0.354: most modal/card mutations contain no selects. Avoid a
          // querySelectorAll() walk for every inserted row unless a select is
          // actually present in that subtree.
          if (node.querySelector?.("select")) enhanceCustomSelects(node);
        });
      }

      if (mutation.target instanceof HTMLSelectElement) {
        const select = mutation.target;
        if (select.dataset.customSelectEnhanced === "true") syncCustomSelect(select);
        else enhanceCustomSelect(select);
      }
    });
  });

  customSelectUi.observer.observe(document.body, {
    childList: true,
    subtree: true,
    attributes: true,
    // v0.353: ignore unrelated class churn from modal animations and card
    // state changes. The enhanced select only needs availability changes here.
    attributeFilter: ["disabled", "hidden"],
  });

  document.addEventListener("click", (event) => {
    if (!customSelectUi.openSelect || !customSelectUi.menu) return;
    const trigger = customSelectUi.openSelect.closest(".custom-select-shell")?.querySelector(":scope > .custom-select-trigger");
    if (customSelectUi.menu.contains(event.target) || trigger?.contains(event.target)) return;
    closeCustomSelect(false);
  }, true);

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && customSelectUi.openSelect) closeCustomSelect(true);
  });

  document.addEventListener("change", (event) => {
    if (!(event.target instanceof HTMLSelectElement)) return;
    queueMicrotask(() => syncCustomSelect(event.target));
    if (event.target.dataset.customSelectEnhanced !== "true") void playAppSound("collapse_close");
  }, true);
  window.addEventListener("resize", () => customSelectUi.openSelect && positionCustomSelectMenu());
  window.addEventListener("scroll", () => {
    if (["deliveryDateSelect", "deliveryStageSelect"].includes(customSelectUi.openSelect?.id)) {
      window.requestAnimationFrame(positionCustomSelectMenu);
    }
  }, { passive: true });
  document.addEventListener("scroll", (event) => {
    if (!customSelectUi.openSelect || customSelectUi.menu?.contains(event.target)) return;
    // Date and Stage live inside the sticky Scan panel. Closing their menu on
    // every document scroll made the Stage control appear unclickable after the
    // panel became sticky. Keep those two context menus open and follow the
    // trigger instead; other custom selects retain the normal close-on-scroll
    // behavior.
    if (["deliveryDateSelect", "deliveryStageSelect"].includes(customSelectUi.openSelect.id)) {
      window.requestAnimationFrame(positionCustomSelectMenu);
      return;
    }
    closeCustomSelect(false);
  }, true);

}

/**
 * Purpose: Run the canonical barcode workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function canonicalBarcode(order, item) {
  return `T200${pad(order, 6)}${pad(item, 3)}000`;
}

/**
 * Purpose: Parse one Bay Scanner manual reference into a six-digit order and one-to-three-digit item.
 * Effects: Performs validation only and does not change browser or server state.
 * Flow: Accepts compact and separated floor-entry formats while rejecting ambiguous values instead of guessing.
 */
function parseBayManualOrderItemReference(value) {
  const text = String(value || "").trim();
  if (!text) return null;

  const clean = cleanBarcode(text);
  if (/^T200\d{12}$/.test(clean)) {
    return {
      order: clean.slice(4, 10),
      item: clean.slice(10, 13),
      barcode: clean,
    };
  }

  const separated = text.match(/^\s*(\d{6})\s*(?:[.\/\\-]+|\s+)\s*(\d{1,3})\s*$/);
  if (separated) {
    const order = separated[1];
    const item = separated[2].padStart(3, "0");
    return { order, item, barcode: canonicalBarcode(order, item) };
  }

  const compact = text;
  if (/^\d{7,9}$/.test(compact)) {
    const order = compact.slice(0, 6);
    const item = compact.slice(6).padStart(3, "0");
    return { order, item, barcode: canonicalBarcode(order, item) };
  }

  return null;
}

/** Return the locale used by every user-facing date, time, and number formatter. */
function appLocale() {
  // es-US keeps U.S. numeric conventions while translating month/day names and
  // date-time language for Spanish-speaking floor users.
  return state.language === "es" ? "es-US" : "en-US";
}

/** Translate locale-generated English date text that was already on screen when Spanish was selected. */
function translateEnglishLocaleDateV359(value) {
  const text = String(value || "").trim();
  if (state.language !== "es" || !text) return text;
  const hasEnglishMonthOrDay = /\b(?:Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sun|Mon|Tue|Wed|Thu|Fri|Sat|January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\b/i.test(text);
  const hasEnglishClock = /\b(?:AM|PM)\b/i.test(text);
  if (!hasEnglishMonthOrDay && !hasEnglishClock) return text;
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;

  const hasTime = hasEnglishClock || /\d{1,2}:\d{2}/.test(text);
  const hasWeekday = /\b(?:Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sun|Mon|Tue|Wed|Thu|Fri|Sat)\b/i.test(text);
  const hasYear = /\b\d{4}\b/.test(text);
  const usesLongMonth = /\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\b/i.test(text);
  const dateOptions = {
    ...(hasWeekday ? { weekday: usesLongMonth ? "long" : "short" } : {}),
    year: hasYear ? "numeric" : undefined,
    month: usesLongMonth ? "long" : "short",
    day: "numeric",
    ...(hasTime ? { hour: "numeric", minute: "2-digit" } : {}),
  };
  Object.keys(dateOptions).forEach((key) => dateOptions[key] === undefined && delete dateOptions[key]);
  return new Intl.DateTimeFormat(appLocale(), dateOptions).format(parsed);
}

/**
 * Purpose: Normalize the format display date workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function formatDisplayDate(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  const parsed = match
    ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
    : new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;
  return parsed.toLocaleDateString(appLocale(), {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
  });
}

/** Format delivery dates as M/D/YYYY for compact selectors and grouped lists. */
function formatNumericDeliveryDate(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  const parsed = match
    ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12, 0, 0, 0)
    : new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;
  return `${parsed.getMonth() + 1}/${parsed.getDate()}/${parsed.getFullYear()}`;
}

/**
 * Purpose: Normalize the format date time workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function formatDateTime(value) {
  if (!value) return "";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString(appLocale());
}

/**
 * Purpose: Split one scan timestamp into compact date and time labels for line-detail ribbons.
 * Effects: Performs an in-memory calculation without changing shared state.
 * Flow: Parses the stored timestamp once and returns safe display text for the Scan table.
 */
function formatScanDateTimeParts(value) {
  if (!value) return { date: "Date not recorded", time: "Time not recorded" };
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return { date: String(value), time: "" };
  }
  return {
    date: parsed.toLocaleDateString(appLocale(), { month: "numeric", day: "numeric", year: "2-digit" }),
    time: parsed
      .toLocaleTimeString(appLocale(), { hour: "numeric", minute: "2-digit" })
      .replace(/\s+/g, "")
      .toLowerCase(),
  };
}


/**
 * Resolve whether a completed scan happened on/before its effective delivery
 * date or after it. Priority date moves use the new delivery date so the active
 * copy is judged against the date operators are actually working from.
 */
function scanTimingMetaV447(item = {}, deliveryDateOverride = "") {
  const scanValue = String(item?.lastScannedAt || item?.lastScanTime || "").trim();
  const deliveryValue = String(
    deliveryDateOverride
    || item?.priorityDeliveryDate
    || item?.deliveryDate
    || state.meta?.deliveryDate
    || "",
  ).trim();
  if (!scanValue || !deliveryValue) return { known: false, late: false, label: "SCANNED:" };

  const scanDate = new Date(scanValue);
  if (Number.isNaN(scanDate.getTime())) return { known: false, late: false, label: "SCANNED:" };
  const scanKey = `${scanDate.getFullYear()}-${pad(scanDate.getMonth() + 1, 2)}-${pad(scanDate.getDate(), 2)}`;
  const deliveryMatch = deliveryValue.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  let deliveryKey = deliveryValue;
  if (deliveryMatch) {
    deliveryKey = `${deliveryMatch[1]}-${pad(Number(deliveryMatch[2]), 2)}-${pad(Number(deliveryMatch[3]), 2)}`;
  } else {
    const deliveryDate = new Date(deliveryValue);
    if (Number.isNaN(deliveryDate.getTime())) return { known: false, late: false, label: "SCANNED:" };
    deliveryKey = `${deliveryDate.getFullYear()}-${pad(deliveryDate.getMonth() + 1, 2)}-${pad(deliveryDate.getDate(), 2)}`;
  }
  const late = scanKey > deliveryKey;
  return { known: true, late, label: late ? "LATE:" : "ON TIME:", scanKey, deliveryKey };
}

function scanTimePillMarkupV447(item = {}, deliveryDateOverride = "") {
  if (!item?.lastScannedAt) return "";
  const scanTimestamp = formatScanDateTimeParts(item.lastScannedAt);
  const scanStation = String(item.lastScannedStation || "").trim();
  // v0.452: prerequisite scans synthesized by an Indian Trail override must be
  // unmistakable. They satisfy workflow quantity but are not presented as a
  // normal Airport floor scan or as an on-time/late physical scan.
  const indianTrailOverride = scanStation.toLowerCase() === "scan override it";
  if (indianTrailOverride) {
    const title = `Scan Override IT at ${formatDateTime(item.lastScannedAt)}`;
    return `<span class="last-scan-pill-v157 is-it-override-v452" title="${escapeHtml(title)}">
      <span class="last-scan-pill-icon-v157" aria-hidden="true">&#8635;</span>
      <span class="last-scan-pill-label-v157">SCAN OVERRIDE IT:</span>
      <b>${escapeHtml(scanTimestamp.date)}</b>
      ${scanTimestamp.time ? `<span class="last-scan-pill-divider-v157" aria-hidden="true">at</span><b>${escapeHtml(scanTimestamp.time)}</b>` : ""}
    </span>`;
  }
  const timing = scanTimingMetaV447(item, deliveryDateOverride);
  const title = `Last scanned ${formatDateTime(item.lastScannedAt)}${scanStation ? ` at ${scanStation}` : ""}${timing.known ? ` · ${timing.late ? "Late" : "On time"}` : ""}`;
  return `<span class="last-scan-pill-v157 ${timing.late ? "is-late-v447" : "is-on-time-v447"}" title="${escapeHtml(title)}">
    <span class="last-scan-pill-icon-v157" aria-hidden="true">${timing.late ? "!" : "&#10003;"}</span>
    <span class="last-scan-pill-label-v157">${escapeHtml(timing.label)}</span>
    <b>${escapeHtml(scanTimestamp.date)}</b>
    ${scanTimestamp.time ? `<span class="last-scan-pill-divider-v157" aria-hidden="true">at</span><b>${escapeHtml(scanTimestamp.time)}</b>` : ""}
    ${scanStation ? `<span class="last-scan-pill-divider-v157" aria-hidden="true">&bull;</span><em>${escapeHtml(scanStation)}</em>` : ""}
  </span>`;
}

/**
 * Purpose: Run the today key workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function todayKey() {
  const now = new Date();
  return `${now.getFullYear()}-${pad(now.getMonth() + 1, 2)}-${pad(now.getDate(), 2)}`;
}

/**
 * Purpose: Run the date input value workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function dateInputValue(date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1, 2)}-${pad(date.getDate(), 2)}`;
}

const IMPORT_MAX_DATE = "";

/**
 * Purpose: Run the default import from date workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function defaultImportFromDate() {
  const from = new Date();
  from.setDate(from.getDate() - 7);
  return dateInputValue(from);
}

/**
 * Purpose: Run the reset import date window workflow for the browser application.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function resetImportDateWindow() {
  if (els.importFromDate) els.importFromDate.value = defaultImportFromDate();
  if (els.importToDate) {
    els.importToDate.value = "";
    els.importToDate.placeholder = "Newest future list";
  }
}

/**
 * Purpose: Run the current import date window workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function currentImportDateWindow() {
  const dateFrom = (els.importFromDate?.value || defaultImportFromDate()).trim();
  const dateTo = (els.importToDate?.value || "").trim();

  if (els.importFromDate && !els.importFromDate.value) els.importFromDate.value = dateFrom;
  if (els.importToDate && !els.importToDate.value) els.importToDate.placeholder = "Newest future list";

  return { dateFrom, dateTo };
}

/**
 * Purpose: Normalize the parse date key workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function parseDateKey(value) {
  const parts = String(value || "").split("-").map(Number);
  if (parts.length !== 3 || parts.some(Number.isNaN)) return null;
  return new Date(parts[0], parts[1] - 1, parts[2]);
}

/**
 * Purpose: Run the filter lists by overview range workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function filterListsByOverviewRange(lists = state.lists) {
  if (state.overviewRange === "all") return lists.slice();

  if (state.overviewRange === "custom") {
    const start = parseDateKey(state.statisticsCustomDateFrom);
    const end = parseDateKey(state.statisticsCustomDateTo);
    if (!start || !end) return lists.slice();
    start.setHours(0, 0, 0, 0);
    end.setHours(23, 59, 59, 999);
    return lists.filter((list) => {
      const date = parseDateKey(list.deliveryDate);
      return date && date >= start && date <= end;
    });
  }

  const days = Number(state.overviewRange || 30);
  if (!days) return lists.slice();
  const end = new Date();
  end.setHours(23, 59, 59, 999);
  const start = new Date(end);
  start.setDate(start.getDate() - days + 1);
  start.setHours(0, 0, 0, 0);
  return lists.filter((list) => {
    const date = parseDateKey(list.deliveryDate);
    return date && date >= start && date <= end;
  });
}

/** Return the actual date keys represented by the active Statistics range. */
function statisticsActiveRangeKeysV455() {
  if (state.overviewRange === "custom") {
    const dateFrom = String(state.statisticsCustomDateFrom || "");
    const dateTo = String(state.statisticsCustomDateTo || "");
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateFrom) && /^\d{4}-\d{2}-\d{2}$/.test(dateTo)) {
      return { dateFrom, dateTo };
    }
  }

  if (state.overviewRange === "all") {
    const dates = [...new Set((state.lists || [])
      .map((list) => String(list?.deliveryDate || "").trim())
      .filter((date) => /^\d{4}-\d{2}-\d{2}$/.test(date)))]
      .sort();
    return dates.length ? { dateFrom: dates[0], dateTo: dates[dates.length - 1] } : { dateFrom: "", dateTo: "" };
  }

  const days = Math.max(Number(state.overviewRange || 30), 1);
  const end = new Date();
  end.setHours(12, 0, 0, 0);
  const start = new Date(end);
  start.setDate(start.getDate() - days + 1);
  return { dateFrom: dateInputValue(start), dateTo: dateInputValue(end) };
}

/** Keep the calendar button synchronized with the range used by every chart view. */
function syncStatisticsChartRangeControlV455() {
  const range = statisticsActiveRangeKeysV455();
  let label = localizedUiValue("All delivery dates");
  if (range.dateFrom && range.dateTo) {
    // v0.456: Statistics reporting ranges use compact numeric dates everywhere
    // the operator reads the active range; calendar month headings remain textual.
    label = range.dateFrom === range.dateTo
      ? formatNumericDeliveryDate(range.dateFrom)
      : `${formatNumericDeliveryDate(range.dateFrom)} – ${formatNumericDeliveryDate(range.dateTo)}`;
  }
  if (els.statisticsChartRangeText) els.statisticsChartRangeText.textContent = label;
  if (els.statisticsChartRangeButton) {
    const expanded = Boolean(els.statisticsDateCalendar && !els.statisticsDateCalendar.hidden);
    els.statisticsChartRangeButton.setAttribute("aria-expanded", expanded ? "true" : "false");
    els.statisticsChartRangeButton.title = `${localizedUiValue("Chart date range")}: ${label}`;
  }
}

/**
 * Purpose: Run the latest delivery date workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function latestDeliveryDate(lists = state.lists) {
  const dates = lists.map((list) => list.deliveryDate).filter(Boolean).sort();
  return dates[dates.length - 1] || todayKey();
}

/**
 * Purpose: Run the dashboard date key workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function dashboardDateKey(lists = state.lists) {
  const today = todayKey();
  return lists.some((list) => list.deliveryDate === today) ? today : latestDeliveryDate(lists);
}

/**
 * Purpose: Run the progress percent workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function progressPercent(list) {
  return Number(list?.totalQty || 0) ? (Number(list.scannedQty || 0) / Number(list.totalQty || 1)) * 100 : 0;
}

/**
 * Purpose: Normalize the format percent workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function formatPercent(value) {
  return `${Math.round(Number(value || 0))}%`;
}

/**
 * Purpose: Run the stage category workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function configuredStageDefinitionV346(list) {
  const stageText = String(list?.stage || "").trim().toLowerCase();
  return (state.manualEditLookups?.stages || []).find((definition) => {
    const display = String(definition.displayName || definition.label || "").trim().toLowerCase();
    const key = String(definition.key || definition.value || "").trim().toLowerCase();
    return Boolean(stageText) && (display === stageText || key === stageText);
  }) || null;
}

function stagePresetFromValuesV445(stageValue = "", scannerValue = "", explicitPreset = "") {
  const cleanExplicitPreset = String(explicitPreset || "").trim().toLowerCase();
  if (["airport_staging", "airport_outbound", "indian_trail", "greenville", "cpu", "dtc", "custom_route"].includes(cleanExplicitPreset)) {
    return cleanExplicitPreset;
  }

  const stageText = String(stageValue || "").trim().toLowerCase();
  const scannerText = String(scannerValue || "").trim().toLowerCase();
  const definitions = Array.isArray(state.manualEditLookups?.stages) ? state.manualEditLookups.stages : [];
  const match = definitions.find((definition) => {
    const display = String(definition?.displayName || definition?.label || "").trim().toLowerCase();
    const key = String(definition?.key || definition?.value || "").trim().toLowerCase();
    const configuredScanner = String(definition?.scanner || "").trim().toLowerCase();
    if (!display && !key) return false;
    const stageMatches = Boolean(stageText) && (display === stageText || key === stageText || (display && stageText.includes(display)));
    const scannerMatches = !configuredScanner || !scannerText || configuredScanner === scannerText || scannerText.includes(configuredScanner) || stageText.includes(configuredScanner);
    return stageMatches && scannerMatches;
  });
  if (match?.preset) return String(match.preset).trim().toLowerCase();

  const signal = `${stageText} ${scannerText}`;
  if (/outbound/.test(signal)) return "airport_outbound";
  if (/staging|staged/.test(signal)) return "airport_staging";
  if (/indian trail|received|inbound/.test(signal)) return "indian_trail";
  if (/customer pickup|\bcpu\b/.test(signal)) return "cpu";
  if (/greenville|\bgnv\b/.test(signal)) return "greenville";
  if (/deliver to customer|\bdtc\b/.test(signal)) return "dtc";
  return "";
}

function scanContextPresetV445() {
  return stagePresetFromValuesV445(
    state.meta?.stage || "",
    state.meta?.scanner || "",
    state.meta?.stagePreset || "",
  );
}

/**
 * v0.355 presentation resolver.
 *
 * Backend preset keys remain stable production contracts. Operator-facing names
 * are resolved from Stage definitions, Route lookups, and the cosmetic
 * presentation profile so another facility can rename the workflow without
 * forking backend logic.
 */
function configuredStageByPresetV355(preset, routeCode = "") {
  const cleanPreset = String(preset || "").trim().toLowerCase();
  const cleanRoute = String(routeCode || "").trim().toUpperCase();
  return (state.manualEditLookups?.stages || []).find((definition) => {
    if (String(definition?.preset || "").trim().toLowerCase() !== cleanPreset) return false;
    if (cleanPreset === "custom_route" && cleanRoute) {
      return String(definition?.routeCode || "").trim().toUpperCase() === cleanRoute;
    }
    return true;
  }) || null;
}

function configuredRouteLabelV355(routeCode, fallback = "") {
  const cleanRoute = String(routeCode || "").trim().toUpperCase();
  if (!cleanRoute) return String(fallback || "").trim();
  const row = (state.manualEditLookups?.routes || []).find((item) => String(item?.value || "").trim().toUpperCase() === cleanRoute);
  return String(row?.label || row?.value || fallback || cleanRoute).trim() || cleanRoute;
}

function stationDisplayLabelV355(station) {
  const internalName = String(station || "").trim();
  if (!internalName) return "";
  const aliases = state.presentationProfile?.stationAliases || {};
  const direct = String(aliases?.[internalName] || "").trim();
  if (direct) return direct;
  const match = Object.entries(aliases || {}).find(([key]) => String(key || "").trim().toLowerCase() === internalName.toLowerCase());
  return String(match?.[1] || internalName).trim() || internalName;
}

function roleDisplayLabelV355(roleName = "") {
  const internalName = String(roleName || "").trim();
  if (!internalName) return "";
  const receivingSite = stationDisplayLabelV355("Indian Trail") || "Indian Trail";
  const receivingRole = internalName.match(/^Indian Trail\s+(Operator|Lead|Manager)$/i);
  if (receivingRole) return `${receivingSite} ${receivingRole[1]}`;
  return internalName;
}

function workflowPresentationV355() {
  const profile = { ...DEFAULT_PRESENTATION_PROFILE_V355, ...(state.presentationProfile || {}) };
  const staging = configuredStageByPresetV355("airport_staging");
  const outbound = configuredStageByPresetV355("airport_outbound");
  const receiving = configuredStageByPresetV355("indian_trail");
  const branch = configuredStageByPresetV355("greenville");
  const pickup = configuredStageByPresetV355("cpu");
  const direct = configuredStageByPresetV355("dtc");
  const originSite = stationDisplayLabelV355(outbound?.scanner || staging?.scanner || "Airport Rd") || "Airport Rd";
  const receivingSite = stationDisplayLabelV355(receiving?.scanner || "Indian Trail") || "Indian Trail";
  const branchSite = stationDisplayLabelV355(branch?.scanner || configuredRouteLabelV355("GNV", "Greenville") || "Greenville") || "Greenville";
  return {
    ...profile,
    originSite,
    receivingSite,
    branchSite,
    stagingStage: String(staging?.displayName || "Staging").trim() || "Staging",
    outboundStage: String(outbound?.displayName || "Outbound").trim() || "Outbound",
    receivingStage: String(receiving?.displayName || "Received").trim() || "Received",
    branchStage: String(branch?.displayName || configuredRouteLabelV355("GNV", "Greenville")).trim() || "Greenville",
    pickupStage: String(pickup?.displayName || configuredRouteLabelV355("CPU", "Customer Pickup")).trim() || "Customer Pickup",
    directStage: String(direct?.displayName || configuredRouteLabelV355("DTC", "DTC")).trim() || "DTC",
    cpuRoute: configuredRouteLabelV355("CPU", "CPU"),
    dtcRoute: configuredRouteLabelV355("DTC", "DTC"),
    gnvRoute: configuredRouteLabelV355("GNV", branchSite),
  };
}

function portableOperationalTextV355(value = "") {
  const labels = workflowPresentationV355();
  // Replace fixed deployment wording with placeholders first so a configured
  // alias that happens to contain one of the legacy words is never rewritten a
  // second time by a later replacement.
  return String(value || "")
    .replace(/BFS Greenville/g, "__DLS_BRANCH_STAGE_V355__")
    .replace(/Indian Trail/g, "__DLS_RECEIVING_SITE_V355__")
    .replace(/Airport Rd/g, "__DLS_ORIGIN_SITE_V355__")
    .replace(/Greenville/g, "__DLS_BRANCH_ROUTE_V355__")
    .replace(/Customer Pickup/g, "__DLS_PICKUP_ROUTE_V355__")
    .replace(/__DLS_BRANCH_STAGE_V355__/g, labels.branchStage)
    .replace(/__DLS_RECEIVING_SITE_V355__/g, labels.receivingSite)
    .replace(/__DLS_ORIGIN_SITE_V355__/g, labels.originSite)
    .replace(/__DLS_BRANCH_ROUTE_V355__/g, labels.gnvRoute || labels.branchSite)
    .replace(/__DLS_PICKUP_ROUTE_V355__/g, labels.cpuRoute);
}

function routeGroupLabelV355(key) {
  const labels = workflowPresentationV355();
  if (key === "airport") return labels.originSite;
  if (key === "indian_trail") return labels.receivingSite;
  if (key === "greenville") return labels.gnvRoute || labels.branchSite;
  if (key === "cpu") return labels.cpuRoute;
  if (key === "dtc") return labels.dtcRoute;
  return String(key || "");
}

function scanFilterLabelV355(filter) {
  if (filter === "indian-trail-route") return workflowPresentationV355().receivingSite;
  if (filter === "cpu-route") return workflowPresentationV355().cpuRoute;
  if (filter === "dtc-route") return workflowPresentationV355().dtcRoute;
  if (filter === "greenville-route") return workflowPresentationV355().gnvRoute;
  return SCAN_FILTER_LABELS[filter] || filter;
}

function refreshPortableRouteLabelsV355() {
  if (typeof PRINT_ROUTE_GROUPS !== "undefined") {
    for (const group of PRINT_ROUTE_GROUPS) group.label = routeGroupLabelV355(group.value);
  }
}

function companyInitialsV355(companyName = "") {
  const words = String(companyName || "")
    .replace(/&/g, " ")
    .split(/\s+/)
    .map((word) => word.replace(/[^a-z0-9]/gi, ""))
    .filter(Boolean);
  const initials = words.slice(0, 3).map((word) => word[0].toUpperCase()).join("");
  return initials || "APP";
}

function applyPortablePresentationV355() {
  const labels = workflowPresentationV355();
  document.title = labels.applicationName;
  const textMap = {
    applicationName: labels.applicationName,
    companyName: labels.companyName,
    loginProductName: labels.loginProductName,
    originSite: labels.originSite,
    receivingSite: labels.receivingSite,
    branchSite: labels.branchSite,
    stagingStage: labels.stagingStage,
    outboundStage: labels.outboundStage,
    receivingStage: labels.receivingStage,
    cpuRoute: labels.cpuRoute,
    dtcRoute: labels.dtcRoute,
    gnvRoute: labels.gnvRoute,
  };
  document.querySelectorAll("[data-portable-label-v355]").forEach((node) => {
    const key = node.dataset.portableLabelV355;
    if (textMap[key]) node.textContent = textMap[key];
  });
  document.querySelectorAll("[data-portable-template-v355]").forEach((node) => {
    const template = node.dataset.portableTemplateV355 || "";
    node.textContent = template.replace(/\{([a-zA-Z0-9]+)\}/g, (_match, key) => textMap[key] || `{${key}}`);
  });
  document.querySelectorAll("[data-portable-aria-v355]").forEach((node) => {
    const template = node.dataset.portableAriaV355 || "";
    node.setAttribute("aria-label", template.replace(/\{([a-zA-Z0-9]+)\}/g, (_match, key) => textMap[key] || `{${key}}`));
  });
  document.querySelectorAll("[data-portable-title-v355]").forEach((node) => {
    const template = node.dataset.portableTitleV355 || "";
    node.title = template.replace(/\{([a-zA-Z0-9]+)\}/g, (_match, key) => textMap[key] || `{${key}}`);
  });
  document.querySelectorAll("[data-portable-placeholder-v355]").forEach((node) => {
    const template = node.dataset.portablePlaceholderV355 || "";
    node.placeholder = template.replace(/\{([a-zA-Z0-9]+)\}/g, (_match, key) => textMap[key] || `{${key}}`);
  });

  const useInstalledLogo = labels.useDefaultBrandLogo !== false;
  // v0.358: make logo ownership explicit. When the installed Presentation logo
  // is selected, no generated company/application text may compete with it in
  // the sidebar. The text/initials brand is reserved for logo-disabled sites.
  document.body.classList.toggle("portable-text-brand-v355", !useInstalledLogo);
  document.body.classList.toggle("portable-installed-logo-v358", useInstalledLogo);
  document.querySelectorAll("[data-portable-logo-v355]").forEach((image) => {
    image.setAttribute("alt", `${labels.companyName} logo`);
    image.setAttribute("aria-hidden", useInstalledLogo ? "false" : "true");
  });
  document.querySelectorAll("[data-portable-brand-initials-v355]").forEach((node) => {
    node.textContent = companyInitialsV355(labels.companyName);
  });

  const supportEmail = String(labels.supportEmail || "").trim();
  document.querySelectorAll("[data-portable-support-link-v355]").forEach((link) => {
    link.hidden = !supportEmail;
    if (!supportEmail) {
      link.removeAttribute("href");
      return;
    }
    const subject = `${labels.applicationName} Bug Report`;
    const body = "Page or screen:\r\nWhat happened:\r\nWhat you expected:\r\nSteps to repeat the problem:\r\n";
    link.href = `mailto:${encodeURIComponent(supportEmail)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    link.title = `Report a ${labels.applicationName} issue`;
  });

  refreshPortableRouteLabelsV355();
  renderHomeStageFilter();
}

async function loadPresentationProfileV355() {
  if (!state.backend) {
    applyPortablePresentationV355();
    return state.presentationProfile;
  }
  try {
    const payload = await fetchJson("/api/presentation-profile");
    state.presentationProfile = {
      ...DEFAULT_PRESENTATION_PROFILE_V355,
      applicationName: payload?.applicationName || DEFAULT_PRESENTATION_PROFILE_V355.applicationName,
      companyName: payload?.companyName || DEFAULT_PRESENTATION_PROFILE_V355.companyName,
      loginProductName: payload?.loginProductName || DEFAULT_PRESENTATION_PROFILE_V355.loginProductName,
      supportEmail: payload?.supportEmail ?? DEFAULT_PRESENTATION_PROFILE_V355.supportEmail,
      useDefaultBrandLogo: payload?.useDefaultBrandLogo !== false,
      stationAliases: payload?.stationAliases && typeof payload.stationAliases === "object" ? payload.stationAliases : {},
    };
    state.manualEditLookups = {
      ...state.manualEditLookups,
      stages: Array.isArray(payload?.stages) ? payload.stages : state.manualEditLookups.stages,
      routes: Array.isArray(payload?.routes) ? payload.routes : state.manualEditLookups.routes,
      // v0.360: combined glass aliases are safe presentation metadata, so ordinary
      // operators resolve canonical glass names even without Lookup Manager access.
      glassAliases: Array.isArray(payload?.glassAliases) ? payload.glassAliases : state.manualEditLookups.glassAliases,
    };
  } catch (_error) {
    state.presentationProfile = { ...DEFAULT_PRESENTATION_PROFILE_V355 };
  }
  applyPortablePresentationV355();
  return state.presentationProfile;
}

function stageCategory(list) {
  const presetCategory = { airport_staging: "staged", airport_outbound: "outbound", indian_trail: "received", greenville: "greenville", cpu: "pickup", dtc: "dtc", custom_route: "staged" };
  const preset = stagePresetFromValuesV445(list?.stage || "", list?.scanner || "", list?.stagePreset || "");
  if (presetCategory[preset]) return presetCategory[preset];
  return "staged";
}

/** Shared route rows used by Delivery List Management and Automation Import History. */
const DELIVERY_ROUTE_GROUP_DEFINITIONS = Object.freeze([
  Object.freeze({ key: "airport", label: "Airport Road", printRouteGroup: "airport", sort: 0 }),
  Object.freeze({ key: "indian_trail", label: "Indian Trail", printRouteGroup: "indian_trail", sort: 1 }),
  Object.freeze({ key: "greenville", label: "Greenville", printRouteGroup: "greenville", sort: 2 }),
  Object.freeze({ key: "cpu", label: "CPU", printRouteGroup: "cpu", sort: 3 }),
  Object.freeze({ key: "dtc", label: "DTC", printRouteGroup: "dtc", sort: 4 }),
]);

/** Resolve one stage/stage-summary record into the maintained delivery-route row. */
function deliveryRouteGroupForStage(record = {}) {
  const category = stageCategory({
    stage: record.stage || record.label || record.stageSheetName || "",
    scanner: record.scanner || record.stageProfile || "",
    stagePreset: record.stagePreset || "",
  });
  const key = category === "received"
    ? "indian_trail"
    : category === "greenville"
      ? "greenville"
      : category === "pickup"
        ? "cpu"
        : category === "dtc"
          ? "dtc"
          : "airport";
  return DELIVERY_ROUTE_GROUP_DEFINITIONS.find((definition) => definition.key === key)
    || DELIVERY_ROUTE_GROUP_DEFINITIONS[0];
}

/** Choose one authoritative stage summary for each route without double-counting stage copies. */
function condenseImportStageSummariesByRoute(stageSummaries = []) {
  const groups = new Map(DELIVERY_ROUTE_GROUP_DEFINITIONS.map((definition) => [definition.key, []]));
  for (const stage of Array.isArray(stageSummaries) ? stageSummaries : []) {
    groups.get(deliveryRouteGroupForStage(stage).key)?.push(stage);
  }

  const summaryPriority = (stage, definition) => {
    const category = stageCategory({ stage: stage.stage || stage.label || "", scanner: stage.stageProfile || stage.scanner || "", stagePreset: stage.stagePreset || "" });
    const changed = Number(stage.changedLineCount || 0)
      + Number(stage.changedPieceQty || 0)
      + Number(stage.updatedPieceQty || 0)
      + Number(stage.addedPieceQty || stage.newPieceQty || 0)
      + Number(stage.removedLineCount || 0)
      + Number(stage.removedPieceQty || 0);
    const authoritativeAirport = definition.key === "airport" && category === "outbound" ? 1_000_000_000 : 0;
    return authoritativeAirport
      + (changed ? 100_000_000 : 0)
      + (stage.created || stage.reactivated ? 10_000_000 : 0)
      + (changed * 10_000)
      + Number(stage.totalQty || 0);
  };

  return DELIVERY_ROUTE_GROUP_DEFINITIONS.flatMap((definition) => {
    const candidates = groups.get(definition.key) || [];
    if (!candidates.length) return [];
    const representative = candidates
      .slice()
      .sort((a, b) => summaryPriority(b, definition) - summaryPriority(a, definition))[0];
    return [{
      ...representative,
      routeGroupKey: definition.key,
      routeGroupLabel: routeGroupLabelV355(definition.key),
      routeStageCount: candidates.length,
      // Preserve the source rows for diagnostics while rendering one route row.
      // Airport intentionally uses Outbound as its authoritative all-order copy.
      routeStageSummaries: candidates,
    }];
  });
}

/**
 * Purpose: Run the stage label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function stageLabel(list) {
  const configured = configuredStageDefinitionV346(list);
  if (configured?.displayName) return configured.displayName;
  const category = stageCategory(list);
  const labels = workflowPresentationV355();
  if (category === "outbound") return labels.outboundStage;
  if (category === "greenville") return labels.branchStage;
  if (category === "received") return labels.receivingStage;
  if (category === "pickup") return labels.pickupStage;
  if (category === "dtc") return labels.directStage;
  return labels.stagingStage;
}

/** Return the compact operational stage names used by the Scan panel. */
function scanStageLabel(list) {
  const configured = configuredStageDefinitionV346(list);
  if (configured?.displayName) return configured.displayName;
  const category = stageCategory(list);
  const labels = workflowPresentationV355();
  if (category === "outbound") return labels.outboundStage;
  if (category === "greenville") return labels.gnvRoute;
  if (category === "received") return labels.receivingSite;
  if (category === "pickup") return labels.cpuRoute;
  if (category === "dtc") return labels.dtcRoute;
  return labels.stagingStage;
}

/**
 * Purpose: Run the priority lists include indian trail workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function priorityListsIncludeIndianTrail(lists = []) {
  return (Array.isArray(lists) ? lists : []).some((list) => stageCategory(list) === "received");
}

/**
 * Purpose: Run the slugify workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function slugify(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

/**
 * Purpose: Run the unique text workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function uniqueText(values) {
  const seen = new Set();
  const result = [];
  for (const value of values) {
    const clean = String(value || "").trim();
    if (!clean || seen.has(clean.toLowerCase())) continue;
    seen.add(clean.toLowerCase());
    result.push(clean);
  }
  return result;
}

/**
 * Purpose: Run the lists by delivery date workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function listsByDeliveryDate(lists = state.lists) {
  const groups = new Map();
  for (const list of lists) {
    const key = list.deliveryDate || "undated";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(list);
  }
  return [...groups.entries()]
    .sort(([dateA], [dateB]) => String(dateB).localeCompare(String(dateA)))
    .map(([date, dateLists]) => ({
      date,
      lists: dateLists.slice().sort((a, b) => stageSort(a) - stageSort(b) || a.label.localeCompare(b.label)),
    }));
}

/** Parse one YYYY-MM-DD delivery date without UTC shifting. */
function deliveryDateFromKey(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || ""));
  if (!match) return null;
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12, 0, 0, 0);
  return Number.isNaN(date.getTime()) ? null : date;
}

/** Return the Monday for the business week containing one delivery date. */
function deliveryBusinessWeekStart(value) {
  const date = value instanceof Date
    ? new Date(value.getFullYear(), value.getMonth(), value.getDate(), 12, 0, 0, 0)
    : deliveryDateFromKey(value);
  if (!date) return null;
  date.setDate(date.getDate() - ((date.getDay() + 6) % 7));
  return date;
}

function deliveryDateKey(value) {
  if (!(value instanceof Date) || Number.isNaN(value.getTime())) return "";
  return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`;
}

/** Format the same Monday-Friday week separator used by Print / Export. */
function deliveryBusinessWeekLabel(value) {
  const start = deliveryBusinessWeekStart(value);
  if (!start) return "Delivery Dates";
  const end = new Date(start.getFullYear(), start.getMonth(), start.getDate() + 4, 12, 0, 0, 0);
  const current = deliveryBusinessWeekStart(new Date());
  const previous = new Date(current.getFullYear(), current.getMonth(), current.getDate() - 7, 12, 0, 0, 0);
  const next = new Date(current.getFullYear(), current.getMonth(), current.getDate() + 7, 12, 0, 0, 0);
  const key = deliveryDateKey(start);
  const prefix = key === deliveryDateKey(current)
    ? "This Week"
    : key === deliveryDateKey(previous)
      ? "Last Week"
      : key === deliveryDateKey(next)
        ? "Next Week"
        : "Week";
  const range = `${formatNumericDeliveryDate(start)} - ${formatNumericDeliveryDate(end)}`;
  return `${prefix} · ${range}`;
}

/** Group delivery-date records into newest-first Monday-Friday business weeks. */
function deliveryDateGroupsByBusinessWeek(groups) {
  const weeks = new Map();
  for (const group of Array.isArray(groups) ? groups : []) {
    const weekStart = deliveryBusinessWeekStart(group.date);
    const weekKey = deliveryDateKey(weekStart);
    if (!weekKey) continue;
    if (!weeks.has(weekKey)) weeks.set(weekKey, []);
    weeks.get(weekKey).push(group);
  }
  return [...weeks.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([weekKey, weekGroups]) => ({
      weekKey,
      label: deliveryBusinessWeekLabel(weekKey),
      groups: weekGroups.slice().sort((a, b) => String(b.date).localeCompare(String(a.date))),
    }));
}

/** Build newest-first delivery date optgroups with Monday-Friday separators. */
function groupedDeliveryDateOptions(groups, optionHtml) {
  return deliveryDateGroupsByBusinessWeek(groups)
    .map(({ label, groups: weekGroups }) => {
      const options = weekGroups.map((group) => optionHtml(group)).join("");
      return `<optgroup label="${escapeHtml(label)}">${options}</optgroup>`;
    })
    .join("");
}

/**
 * Purpose: Run the stage sort workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function stageSort(list) {
  return { staged: 1, outbound: 2, received: 3, greenville: 4, pickup: 5, dtc: 6 }[stageCategory(list)] || 9;
}

/**
 * Purpose: Run the selected delivery date workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function selectedDeliveryDate() {
  const activeDate = state.lists.find((list) => list.id === state.activeListId)?.deliveryDate || "";
  if (activeDate) return activeDate;
  const detailDate = String(state.meta?.deliveryDate || "");
  if (detailDate && state.lists.some((list) => String(list.deliveryDate || "") === detailDate)) {
    return detailDate;
  }
  return state.lists[0]?.deliveryDate || "";
}

/**
 * Purpose: Run the has permission workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function hasPermission(permission) {
  if (!state.backend) return true;
  return state.permissions.includes(permission);
}

/**
 * Purpose: Run the has any permission workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function hasAnyPermission(permissions) {
  return permissions.some((permission) => hasPermission(permission));
}

function isAdminUser() {
  if (!state.backend) return false;
  return (state.user?.roles || []).some((role) => String(role || "").trim().toLowerCase() === "admin");
}

/**
 * Purpose: Update the set control allowed workflow using the existing shared UI state.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function setControlAllowed(element, allowed, hide = false) {
  if (!element) return;
  element.disabled = !allowed;
  if (hide) element.hidden = !allowed;
  element.classList.toggle("is-disabled", !allowed);
}

/**
 * Purpose: Run the user assigned stations workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function userAssignedStations(user = state.user) {
  const explicit = Array.isArray(user?.assignedStations) ? user.assignedStations : [];
  const stationText = String(user?.station || user?.assignedStation || "");
  const parsed = stationText
    .split(/[|,]/)
    .map((station) => station.trim())
    .filter(Boolean);

  return uniqueText([...explicit, ...parsed]);
}

/**
 * Purpose: Run the user assigned station workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function userAssignedStation(user = state.user) {
  return userAssignedStations(user)[0] || "";
}

/**
 * Purpose: Run the user assigned station label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function userAssignedStationLabel(user = state.user, fallback = "") {
  const stations = userAssignedStations(user);
  if (stations.length) return stations.map((station) => stationDisplayLabelV355(station)).join(", ");
  return String(fallback || "No assigned station").trim();
}

/**
 * Purpose: Run the current scan station workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function currentScanStation() {
  return userAssignedStation() || els.stationSelect?.value || state.meta?.scanner || DEFAULT_STATIONS[0] || "";
}

/**
 * Purpose: Run the request context workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function requestContext() {
  return {
    user: state.user?.username || els.operatorInput?.value || "Scanner",
    station: currentScanStation(),
  };
}

/**
 * Purpose: Open the show import status loading workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may call the backend api, may update shared client state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
function showImportStatusLoading(message, detail = "") {
  if (!els.importPreviewBox) return;

  els.importPreviewBox.hidden = false;
  els.importPreviewBox.classList.remove("success", "review", "notice", "import-status-compact");
  els.importPreviewBox.classList.add("loading");

  els.importPreviewBox.innerHTML = `
    <strong>${escapeHtml(message)}</strong>
    <span class="loading-bar"><i></i></span>
    ${detail ? `<span>${escapeHtml(detail)}</span>` : ""}
  `;
}

/**
 * Purpose: Open the show import status result workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showImportStatusResult(kind, title, detail = "", actionsHtml = "") {
  if (!els.importPreviewBox) return;

  const statusClass = kind === "review" ? "review" : kind === "notice" ? "notice" : "success";

  els.importPreviewBox.hidden = false;
  els.importPreviewBox.classList.remove("loading", "success", "review", "notice");
  els.importPreviewBox.classList.add(statusClass, "import-status-compact");

  els.importPreviewBox.innerHTML = `
    <strong>${escapeHtml(title)}</strong>
    ${detail ? `<span>${escapeHtml(detail)}</span>` : ""}
    ${actionsHtml ? `<div class="import-status-actions">${actionsHtml}</div>` : ""}
  `;
}

/**
 * Purpose: Run the wait for next paint workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function waitForNextPaint() {
  return new Promise((resolve) => {
    requestAnimationFrame(() => {
      requestAnimationFrame(resolve);
    });
  });
}

/**
 * Purpose: Update the update modal scroll lock workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may call the backend api, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
const APP_MODAL_STATE_SELECTOR = [
  ".modal-panel",
  "[role='dialog'][aria-modal='true']",
  "#emailDraftPreviewShell",
  "#actionFeedbackShell",
  "#rushAlertShell",
  "#indianTrailOutboundOverrideShell",
  ".action-confirm-backdrop",
  ".rack-transfer-backdrop",
].join(",");

function modalNodeIsOpen(panel) {
  if (!panel || !panel.isConnected || panel.hidden) return false;
  if (panel.getAttribute?.("aria-hidden") === "true") return false;
  const hiddenAncestor = panel.closest?.("[hidden]");
  return !hiddenAncestor || hiddenAncestor === panel;
}

function appModalUiIsOpen() {
  return document.body?.classList.contains("modal-scroll-locked")
    || [...document.querySelectorAll(APP_MODAL_STATE_SELECTOR)].some(modalNodeIsOpen);
}

/** Remove body-mounted dropdown layers whose source control is no longer usable. */
function cleanupTransientUiLayers() {
  const openSelect = customSelectUi.openSelect;
  const hiddenOwner = openSelect?.closest?.("[hidden], [aria-hidden='true']");
  if (openSelect && (!openSelect.isConnected || hiddenOwner)) closeCustomSelect(false);

  // A custom-select menu is portaled to <body>. If a GUI disappears during an
  // async render, an orphan menu could otherwise remain over Rack page actions
  // and steal pointer events even though no visible dropdown remains.
  document.querySelectorAll(".custom-select-menu").forEach((menu) => {
    if (menu !== customSelectUi.menu) menu.remove();
  });
}

function updateModalScrollLock() {
  cleanupTransientUiLayers();

  // v0.353: avoid getComputedStyle()/getClientRects() here. Those layout reads
  // were being repeated for every mutation while a GUI rendered and caused the
  // large application-wide slowdown seen immediately after opening a modal.
  const modalIsOpen = [...document.querySelectorAll(APP_MODAL_STATE_SELECTOR)].some(modalNodeIsOpen);
  const wasLocked = document.body.classList.contains("modal-scroll-locked");

  document.body.classList.toggle("modal-scroll-locked", modalIsOpen);
  if (wasLocked && !modalIsOpen && state.page === "racks") scheduleRackHeadingHitTargetRepair();
}

let modalScrollLockObserver = null;
function installModalScrollLockObserver() {
  if (modalScrollLockObserver || !document.body) return;
  let pending = false;
  modalScrollLockObserver = new MutationObserver((mutations) => {
    const changesModalState = mutations.some((mutation) => {
      const target = mutation.target instanceof Element ? mutation.target : null;
      if (mutation.type === "attributes") {
        return Boolean(target?.matches?.(APP_MODAL_STATE_SELECTOR));
      }
      return [...mutation.addedNodes, ...mutation.removedNodes].some((node) => (
        node instanceof Element
        && (node.matches?.(APP_MODAL_STATE_SELECTOR) || node.querySelector?.(APP_MODAL_STATE_SELECTOR))
      ));
    });
    if (!changesModalState || pending) return;
    pending = true;
    window.requestAnimationFrame(() => {
      pending = false;
      updateModalScrollLock();
    });
  });
  modalScrollLockObserver.observe(document.body, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ["hidden", "aria-hidden"],
  });
}
installModalScrollLockObserver();

/**
 * Purpose: Load the fetch JSON workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function fetchJson(url, options = {}) {
  const response = await fetch(url, {
    cache: "no-store",
    headers: { "Content-Type": "application/json", ...(options.headers || {}) },
    ...options,
  });
  if (!response.ok) {
    const text = await response.text();
    let message = text || `Request failed: ${response.status}`;
    try {
      const payload = JSON.parse(text);
      message = payload.error || payload.message || message;
    } catch {
      // Keep raw text when the server does not return JSON.
    }
    if (response.status === 403) {
      // Authorization failures are action-level failures, not session failures.
      // Keep the signed-in workspace open and let the caller show the shared
      // access-denied popup instead of redirecting the user to Sign In.
      playAppSound("permission_denied", { force: true });
      if (/^permission denied$/i.test(String(message || "").trim())) {
        message = "You do not have access to perform that action.";
      }
    }
    if (response.status === 401 && state.backend && url !== "/api/login") {
      // A 401 means the session itself is no longer valid. v0.341 prevents
      // role saves from manufacturing this condition by deleting live sessions.
      state.authenticated = false;
      state.user = null;
      state.permissions = [];
      stopNotificationPolling();
      showLogin("Your session has ended. Please sign in again.");
    }
    throw new Error(message);
  }
  const payload = await response.json();
  const method = String(options.method || "GET").toUpperCase();
  if (method !== "GET" && (url.startsWith("/api/admin/") || url.startsWith("/api/racks/") || url.startsWith("/api/operations/"))) {
    window.setTimeout(() => refreshOpenModalActionHistory().catch(() => {}), 80);
  }
  return payload;
}

/**
 * Purpose: Run the detect backend workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function detectBackend() {
  try {
    const health = await fetchJson("/api/health");
    state.backend = Boolean(health.ok);
  } catch {
    state.backend = false;
  }
}

/**
 * Purpose: Open the show login workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showLogin(message = "") {
  if (!els.loginPanel) return;
  els.loginPanel.hidden = false;
  document.querySelector(".app")?.setAttribute("aria-hidden", "true");
  if (els.loginError) {
    els.loginError.textContent = message;
    els.loginError.classList.remove("success");
  }
  window.setTimeout(() => (els.loginPassword || els.loginUsername)?.focus(), 30);
}

/**
 * Purpose: Close the hide login workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function hideLogin() {
  if (!els.loginPanel) return;
  els.loginPanel.hidden = true;
  if (els.passwordResetPanel) els.passwordResetPanel.hidden = true;
  document.querySelector(".app")?.removeAttribute("aria-hidden");
  if (els.loginError) {
    els.loginError.textContent = "";
    els.loginError.classList.remove("success");
  }
}

/**
 * Purpose: Load the load session workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function loadSession() {
  const payload = await fetchJson("/api/session");
  state.authenticated = Boolean(payload.authenticated);
  state.user = payload.user || null;
  state.permissions = state.user?.permissions || [];
  if (state.authenticated) {
    hideLogin();
    if (els.operatorInput) els.operatorInput.value = state.user.displayName || state.user.username || "Scanner";
  }
  return payload;
}

/**
 * Purpose: Run the login workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function login(username, password) {
  const payload = await fetchJson("/api/login", {
    method: "POST",
    body: JSON.stringify({ username, password }),
  });
  state.authenticated = true;
  state.user = payload.user;
  state.permissions = payload.user?.permissions || [];
  hideLogin();
  if (els.loginPassword) els.loginPassword.value = "";
  if (els.operatorInput) els.operatorInput.value = state.user.displayName || state.user.username || "Scanner";
  playAppSound("login", { force: true });
}

/**
 * Purpose: Open the show password reset panel workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showPasswordResetPanel(show = true) {
  if (!els.passwordResetPanel) return;
  els.passwordResetPanel.hidden = !show;
  if (els.loginForm) els.loginForm.hidden = Boolean(show);
  if (els.passwordResetMessage) {
    els.passwordResetMessage.textContent = "";
    els.passwordResetMessage.classList.remove("success");
  }
  if (show) {
    if (els.resetIdentityInput && els.loginUsername?.value) els.resetIdentityInput.value = els.loginUsername.value.trim();
    window.setTimeout(() => (els.resetIdentityInput || els.loginUsername)?.focus(), 30);
  } else {
    window.setTimeout(() => els.loginUsername?.focus(), 30);
  }
}

/**
 * Purpose: Update the set password reset message workflow using the existing shared UI state.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function setPasswordResetMessage(message, success = false) {
  if (!els.passwordResetMessage) return;
  els.passwordResetMessage.textContent = message;
  els.passwordResetMessage.classList.toggle("success", success);
}

/**
 * Purpose: Run the request password reset code workflow for the browser application.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function requestPasswordResetCode() {
  const identity = els.resetIdentityInput?.value.trim() || "";
  if (!identity) throw new Error("Enter your email or username first.");
  const payload = await fetchJson("/api/password-reset/request", {
    method: "POST",
    body: JSON.stringify({ identity }),
  });
  const codeText = payload.resetCode ? ` Reset code: ${payload.resetCode}` : "";
  setPasswordResetMessage(`${payload.message || "Reset request created."}${codeText}`, true);
  if (payload.resetCode && els.resetCodeInput) els.resetCodeInput.value = payload.resetCode;
  els.resetCodeInput?.focus();
}

/**
 * Purpose: Run the confirm password reset workflow for the browser application.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function confirmPasswordReset() {
  const identity = els.resetIdentityInput?.value.trim() || "";
  const resetCode = els.resetCodeInput?.value.trim() || "";
  const newPassword = els.resetNewPasswordInput?.value || "";
  if (!identity || !resetCode || !newPassword) throw new Error("Enter your identity, reset code, and new password.");
  const payload = await fetchJson("/api/password-reset/confirm", {
    method: "POST",
    body: JSON.stringify({ identity, resetCode, newPassword }),
  });
  if (els.loginUsername) els.loginUsername.value = identity;
  if (els.loginPassword) els.loginPassword.value = "";
  if (els.resetCodeInput) els.resetCodeInput.value = "";
  if (els.resetNewPasswordInput) els.resetNewPasswordInput.value = "";
  showPasswordResetPanel(false);
  if (els.loginError) {
    els.loginError.textContent = payload.message || "Password reset. You can sign in now.";
    els.loginError.classList.add("success");
  }
}

/**
 * Purpose: Run the logout workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function logout() {
  if (state.backend) {
    await fetchJson("/api/logout", { method: "POST", body: JSON.stringify({}) });
  }
  state.authenticated = false;
  state.user = null;
  state.permissions = [];
  stopPolling();
  stopNotificationPolling();
  playAppSound("logout", { force: true });
  showLogin("Signed out.");
}

/**
 * Purpose: Run the clean barcode workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function cleanBarcode(value) {
  return String(value || "")
    .replace(/\*/g, "")
    .replace(/[\r\n]/g, "")
    .trim()
    .split("")
    .filter((ch) => /[0-9a-z]/i.test(ch))
    .join("")
    .toUpperCase();
}

/**
 * Purpose: Run the digits only workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function digitsOnly(value) {
  return String(value || "").replace(/\D/g, "");
}

const GREENVILLE_ROUTE_ALIASES = new Set(["GNV", "GRN", "GRVLLE", "GRVILLE", "GRVLE", "GVLLE", "GREENVILLE"]);
const CPU_INDIAN_TRAIL_ROUTE_CODES = new Set(["CPUIT", "CPUINT", "ITCPU", "INTCPU"]);
const CPU_AIR_ROUTE_CODES = new Set(["CPUAIR", "AIRCPU"]);

/**
 * Purpose: Run the canonical route designation workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function canonicalRouteDesignation(value, { jobContext = false } = {}) {
  const text = String(value || "").trim().toUpperCase();
  if (!text) return { matched: false, route: "" };

  const compact = text.replace(/[^A-Z0-9]+/g, "");
  const separator = "[^A-Z0-9]*";
  const tokenStart = "(?:^|[^A-Z0-9])";
  const tokenEnd = "(?![A-Z0-9])";
  const cpuIndianTrailPattern = new RegExp(
    `(?:${tokenStart}CPU${separator}(?:IT|INT)${tokenEnd}|${tokenStart}(?:IT|INT)${separator}CPU${tokenEnd})`,
    "i",
  );
  const cpuAirPattern = new RegExp(
    `(?:${tokenStart}CPU${separator}AIR${tokenEnd}|${tokenStart}AIR${separator}CPU${tokenEnd})`,
    "i",
  );
  /**
   * Purpose: Run the has token workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const hasToken = (token) => new RegExp(`${tokenStart}${token}${tokenEnd}`, "i").test(text);

  if (CPU_INDIAN_TRAIL_ROUTE_CODES.has(compact) || cpuIndianTrailPattern.test(text)) {
    return { matched: true, route: "" };
  }
  if (CPU_AIR_ROUTE_CODES.has(compact) || cpuAirPattern.test(text)) {
    return { matched: true, route: "CPU" };
  }
  if (jobContext) return { matched: false, route: "" };
  if (["DTC", "DELIVERTOCUSTOMER"].includes(compact) || hasToken("DTC")) {
    return { matched: true, route: "DTC" };
  }
  if (GREENVILLE_ROUTE_ALIASES.has(compact) || [...GREENVILLE_ROUTE_ALIASES].some(hasToken)) {
    return { matched: true, route: "GNV" };
  }
  if (["CUSTOMERPICKUP", "PICKUP"].includes(compact)) {
    return { matched: true, route: "CPU" };
  }
  if (compact === "CPU" || hasToken("CPU")) return { matched: true, route: "CPU" };
  if (["INT", "IT", "INDIANTRAIL"].includes(compact)) return { matched: true, route: "" };
  return { matched: false, route: "" };
}

/**
 * Purpose: Run the inferred route workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function inferredRoute(item) {
  const rawRoute = String(item.route || "").trim();
  const explicit = canonicalRouteDesignation(rawRoute);
  const jobHint = canonicalRouteDesignation(item.job, { jobContext: true });
  if (rawRoute) {
    if (explicit.matched) {
      return explicit.route;
    }
    return rawRoute.toUpperCase();
  }
  if (jobHint.matched) return jobHint.route;

  // Generic CPU text in Job Nr. remains Indian Trail unless the backend has
  // already applied a customer-route rule to the ROUTE field.
  return "";
}

/**
 * Purpose: Run the route category workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function routeCategory(item) {
  const route = inferredRoute(item);
  if (route === "CPU") return "cpu";
  if (route === "GNV") return "greenville";
  if (route === "DTC") return "dtc";
  return "indian_trail";
}

/**
 * Purpose: Run the route label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function routeLabel(item) {
  const route = inferredRoute(item);
  if (route === "CPU") return "CPU";
  if (route === "GNV") return "GNV";
  if (route === "DTC") return "DTC";
  return "";
}

/**
 * Purpose: Run the is CPU item workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function isCpuItem(item) {
  return routeCategory(item) === "cpu";
}

/**
 * Purpose: Run the filter items for profile workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function filterItemsForProfile(items, profile) {
  if (profile === "cpu") return items.filter(isCpuItem);
  if (profile === "indian_trail") return items.filter((item) => routeCategory(item) === "indian_trail");
  if (profile === "greenville") return items.filter((item) => routeCategory(item) === "greenville");
  if (profile === "dtc") return items.filter((item) => routeCategory(item) === "dtc");
  return items.slice();
}

/**
 * Purpose: Run the clone items workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function cloneItems(items) {
  const seen = new Map();
  return (items || []).map((item, index) => {
    const baseId = item.id || `${item.order}-${item.item}`;
    const count = seen.get(baseId) || 0;
    seen.set(baseId, count + 1);
    return {
      ...item,
      id: count ? `${baseId}-${count + 1}` : baseId,
      sourceId: baseId,
      lineIndex: index + 1,
      scanned: Number(item.scanned || 0),
      qty: Number(item.qty || 0),
      lastError: item.lastError || "",
    };
  });
}

/**
 * Purpose: Create the create demo lists workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function createDemoLists(payload) {
  const baseItems = payload.items || [];
  const definitions = [
    ["staging-airport", "Staging - Airport Rd", "Airport Rd", "all"],
    ["outbound-airport", "Outbound - Airport Rd", "Airport Rd", "all"],
    ["inbound-indian-trail", "Inbound - Indian Trail", "Indian Trail", "indian_trail"],
    ["bfs-greenville", "BFS Greenville", "Greenville", "greenville"],
    ["customer-pickup", "Customer Pickup", "Customer Pickup", "cpu"],
    ["dtc", "DTC - Deliver to Customer", "DTC", "dtc"],
  ];
  return definitions
    .map(([suffix, stage, scanner, profile]) => {
      const items = filterItemsForProfile(baseItems, profile);
      if (profile !== "all" && !items.length) return null;
      const cloned = cloneItems(items);
      const totalQty = cloned.reduce((sum, item) => sum + Number(item.qty || 0), 0);
      const scannedQty = cloned.reduce((sum, item) => sum + Number(item.scanned || 0), 0);
      return {
        id: `${payload.deliveryDate}-${suffix}`,
        label: `${formatDisplayDate(payload.deliveryDate)} - ${stage}`,
        deliveryDate: payload.deliveryDate,
        stage,
        scanner,
        itemCount: cloned.length,
        totalQty,
        scannedQty,
        deliveryPercent: totalQty ? (scannedQty / totalQty) * 100 : 0,
        onTimeQty: 0,
        lateQty: 0,
        onTimePercent: 0,
        items: cloned,
      };
    })
    .filter(Boolean);
}

/**
 * Purpose: Load the load local stations workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
function loadLocalStations() {
  try {
    const saved = JSON.parse(localStorage.getItem(STATIONS_KEY) || "[]");
    state.stations = uniqueText([...DEFAULT_STATIONS, ...saved]);
  } catch {
    state.stations = DEFAULT_STATIONS.slice();
  }
}

/**
 * Purpose: Run the save local stations workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function saveLocalStations() {
  localStorage.setItem(STATIONS_KEY, JSON.stringify(state.stations));
}

/**
 * Purpose: Render the render station options workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderStationOptions(preferredStation = "") {
  if (!els.stationSelect) return;

  const assignedStations = userAssignedStations();
  const assignedStation = assignedStations[0] || "";
  const current = assignedStation || preferredStation || els.stationSelect.value || state.meta?.scanner || DEFAULT_STATIONS[0];

  state.stations = uniqueText([...DEFAULT_STATIONS, ...state.stations, ...assignedStations, current]);
  els.stationSelect.innerHTML = state.stations
    .map((station) => `<option value="${escapeHtml(station)}">${escapeHtml(stationDisplayLabelV355(station))}</option>`)
    .join("");
  els.stationSelect.value = state.stations.includes(current) ? current : state.stations[0];
  els.stationSelect.disabled = true;
  els.stationSelect.title = assignedStations.length
    ? assignedStations.map((station) => stationDisplayLabelV355(station)).join(", ")
    : "No assigned station on this login; using the selected delivery list default.";

  if (els.stationProfileDisplay) {
    const label = userAssignedStationLabel(state.user, current);
    els.stationProfileDisplay.textContent = label;
    els.stationProfileDisplay.title = els.stationSelect.title;
    els.stationProfileDisplay.classList.toggle("has-multiple", assignedStations.length > 1);
    els.stationProfileDisplay.classList.toggle("is-unassigned", !assignedStations.length);
  }
}

/**
 * Purpose: Load the load stations workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function loadStations() {
  if (state.backend) {
    const payload = await fetchJson("/api/stations");
    state.stations = uniqueText([...DEFAULT_STATIONS, ...(payload.stations || [])]);
  } else {
    loadLocalStations();
  }
  renderStationOptions(state.meta?.scanner);
}

/**
 * Purpose: Create the add station from input workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function addStationFromInput() {
  const name = els.newStationInput?.value.trim() || "";
  if (!name) {
    els.newStationInput?.focus();
    return;
  }
  if (state.backend) {
    const payload = await fetchJson("/api/stations", {
      method: "POST",
      body: JSON.stringify({ name }),
    });
    state.stations = uniqueText([...DEFAULT_STATIONS, ...(payload.stations || [])]);
  } else {
    state.stations = uniqueText([...state.stations, name]);
    saveLocalStations();
  }
  if (els.newStationInput) els.newStationInput.value = "";
  renderStationOptions(name);
  renderAdminStations();
  showSaveConfirmation(`Station ${name} was saved.`);
}

/**
 * Purpose: Remove the remove station workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function removeStation(name) {
  if (!state.backend) return;
  const payload = await fetchJson("/api/stations/remove", {
    method: "POST",
    body: JSON.stringify({ name }),
  });
  state.stations = uniqueText([...DEFAULT_STATIONS, ...(payload.stations || [])]);
  renderStationOptions();
  renderAdminStations();
  if (els.adminModal?.dataset.kind === "lookups" && state.lookupManagerActiveType === "station") {
    renderLookupManagerModal();
    configureAdminModalSectionTabsV345("lookups");
  }
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Update the apply backend payload workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
function applyBackendPayload(payload, { selectionFallbackId = "" } = {}) {
  const previousSelectedId = String(state.selectedId || "");
  const items = cloneItems(payload.items || []);
  const computedTotalQty = pieceCount(items);
  const computedManualItems = items.filter((item) => item.manualOnly || String(item.manualSource || "").trim());
  const computedProtectedManualItems = computedManualItems.filter((item) => item.protectFromAwImport);
  const computedRemakeItems = items.filter(isRemakeItem);
  const computedManualRemakeItems = computedManualItems.filter(isRemakeItem);
  const meta = {
    ...(payload.meta || {}),
    itemCount: items.length,
    totalQty: computedTotalQty,
    sourceTotalQty: Number(payload.meta?.sourceTotalQty ?? (computedTotalQty - pieceCount(computedManualItems))),
    manualPieceQty: Number(payload.meta?.manualPieceQty ?? pieceCount(computedManualItems)),
    manualLineCount: Number(payload.meta?.manualLineCount ?? computedManualItems.length),
    protectedManualPieceQty: Number(payload.meta?.protectedManualPieceQty ?? pieceCount(computedProtectedManualItems)),
    protectedManualLineCount: Number(payload.meta?.protectedManualLineCount ?? computedProtectedManualItems.length),
    remakeLineCount: Number(payload.meta?.remakeLineCount ?? computedRemakeItems.length),
    remakePieceQty: Number(payload.meta?.remakePieceQty ?? pieceCount(computedRemakeItems)),
    sourceRemakePieceQty: Number(payload.meta?.sourceRemakePieceQty ?? (pieceCount(computedRemakeItems) - pieceCount(computedManualRemakeItems))),
    manualRemakePieceQty: Number(payload.meta?.manualRemakePieceQty ?? pieceCount(computedManualRemakeItems)),
  };

  state.meta = meta;
  state.activeListId = meta.id;
  state.items = items;
  state.rushMoveReferences = Array.isArray(payload.rushMoveReferences) ? payload.rushMoveReferences.slice() : [];
  state.recent = payload.recent || [];
  state.errors = payload.errors || [];
  state.lastScan = payload.lastScan || state.recent[0] || null;
  // v0.382: background refreshes and polling must never create or move a Scan
  // selection. Preserve the operator's explicit selection only while that row
  // still exists. A real scan may opt into one explicit fallback row; normal
  // refreshes always leave an empty selection empty instead of jumping to the
  // latest/second row after the polling interval.
  const selectedStillExists = previousSelectedId
    && items.some((item) => String(item.id || "") === previousSelectedId);
  const normalizedFallbackId = String(selectionFallbackId || "");
  const fallbackStillExists = normalizedFallbackId
    && items.some((item) => String(item.id || "") === normalizedFallbackId);
  state.selectedId = selectedStillExists
    ? previousSelectedId
    : (fallbackStillExists ? normalizedFallbackId : null);

  const catalogIndex = state.lists.findIndex((list) => String(list.id || "") === String(meta.id || ""));
  if (catalogIndex >= 0) {
    state.lists[catalogIndex] = {
      ...state.lists[catalogIndex],
      ...meta,
    };
  }
  renderStationOptions(meta.scanner);
}

/**
 * Purpose: Load the load delivery lists workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function loadDeliveryLists(preferredListId = "") {
  if (state.backend) {
    const payload = await fetchJson("/api/delivery-lists");
    state.lists = payload.lists || [];
  }
  renderHome();
  renderStatisticsPage();
  renderDeliveryListSelect();
  if (preferredListId) {
    await activateList(preferredListId, false);
  }
}

/**
 * Purpose: Update the set active list workflow using the existing shared UI state.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function setActiveList(listId) {
  const nextList = state.lists.find((list) => list.id === listId) || state.lists[0];
  if (!nextList) return;
  state.activeListId = nextList.id;
  state.meta = {
    deliveryDate: nextList.deliveryDate,
    stage: nextList.stage,
    scanner: nextList.scanner,
    label: nextList.label,
  };
  state.items = cloneItems(nextList.items || []);
  state.rushMoveReferences = [];
  state.recent = [];
  state.errors = [];
  state.selectedId = null;
  state.lastScan = null;
  restoreState();
  renderStationOptions(nextList.scanner);
}

/**
 * Merge per-user operational flags into the current list before its first paint.
 * This keeps New/Updated, manual-only, and reject status synchronized without a
 * second visible list render after the operator selects a delivery list.
 */
function applyOperationalLineFlags(payload, listId = state.activeListId) {
  if (!payload || String(state.activeListId || "") !== String(listId || "")) return;
  const rows = Array.isArray(payload.items) ? payload.items : [];
  const byId = new Map(rows.map((item) => [String(item.lineItemId || item.id || ""), item]));
  state.items = state.items.map((item) => {
    const current = byId.get(String(item.id || "")) || {};
    return {
      ...item,
      manualOnly: Boolean(current.manualOnly),
      manualSource: String(current.manualSource || ""),
      internalRejectCount: Number(current.internalRejectCount || 0),
      rejectEventCount: Number(current.rejectEventCount || 0),
      lastRejectId: Number(current.lastRejectId || 0),
      lastRejectQty: Number(current.lastRejectQty || 0),
      lastRejectReason: String(current.lastRejectReason || ""),
      lastRejectLocation: String(current.lastRejectLocation || ""),
      lastRejectedAt: String(current.lastRejectedAt || ""),
      lastRejectedBy: String(current.lastRejectedBy || ""),
      lastRejectNotes: String(current.lastRejectNotes || ""),
      lastRejectDeliveryDate: String(current.lastRejectDeliveryDate || ""),
      hasUnseenUpdate: Boolean(current.hasUnseenUpdate),
      userUpdateState: String(current.userUpdateState || ""),
      userUpdateNoticeIds: Array.isArray(current.userUpdateNoticeIds) ? current.userUpdateNoticeIds.slice() : [],
    };
  });
}

/**
 * Purpose: Run the activate list workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function activateList(listId, navigate = true, { selectionFallbackId = "" } = {}) {
  if (!listId) return;
  const previousDeliveryDate = String(state.meta?.deliveryDate || "").trim();
  const previousSearch = state.search;
  const changingList = listId !== state.activeListId;
  let lineFlags = null;
  if (state.backend) {
    const [payload, flagsPayload] = await Promise.all([
      fetchJson(`/api/delivery-lists/${encodeURIComponent(listId)}`),
      fetchJson(`/api/operations/line-flags?listId=${encodeURIComponent(listId)}`).catch(() => null),
    ]);
    applyBackendPayload(payload, { selectionFallbackId });
    lineFlags = flagsPayload;
    applyOperationalLineFlags(lineFlags, listId);
  } else {
    setActiveList(listId);
  }
  const nextDeliveryDate = String(state.meta?.deliveryDate || "").trim();
  const changingDate = Boolean(changingList && previousDeliveryDate !== nextDeliveryDate);
  if (changingDate) {
    state.search = "";
    if (els.searchInput) els.searchInput.value = "";
  } else if (changingList) {
    state.search = previousSearch;
    if (els.searchInput) els.searchInput.value = previousSearch;
  }
  if (changingList || navigate) {
    state.pageIndex = 1;
    state.glassTypeFilters.clear();
    state.lastGlassFilterSignature = "";
  }
  if (navigate) {
    showPage("scan");
  } else {
    renderScanPage();
  }
  if (lineFlags) {
    window.DLSLineUpdates?.applyPayload?.(lineFlags, listId, { prompt: navigate, render: false });
  }
  if (changingDate) {
    window.setTimeout(() => refreshPendingUpdateDates({ force: false }).catch(() => {}), 40);
  }
  if (navigate || document.activeElement === els.scanInput) els.scanInput?.focus();
}

/**
 * Purpose: Run the storage key workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function storageKey() {
  return `${STORAGE_KEY}-${state.activeListId || "default"}`;
}

/**
 * Purpose: Run the save state workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function saveState() {
  if (state.backend) return;
  const payload = {
    scanned: Object.fromEntries(state.items.map((item) => [item.id, item.scanned])),
    recent: state.recent,
    errors: state.errors,
    selectedId: state.selectedId,
    lastScan: state.lastScan,
  };
  localStorage.setItem(storageKey(), JSON.stringify(payload));
}

/**
 * Purpose: Run the restore state workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function restoreState() {
  if (state.backend) return;
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey()) || "{}");
    if (saved.scanned) {
      for (const item of state.items) {
        item.scanned = Math.min(Number(saved.scanned[item.id] || 0), item.qty);
      }
    }
    state.recent = Array.isArray(saved.recent) ? saved.recent.slice(0, 30) : [];
    state.errors = Array.isArray(saved.errors) ? saved.errors.slice(0, 30) : [];
    state.selectedId = saved.selectedId || null;
    state.lastScan = saved.lastScan || null;
  } catch {
    localStorage.removeItem(storageKey());
  }
}

/**
 * Purpose: Run the item status workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function itemStatus(item) {
  if (item.scanned >= item.qty) return "complete";
  if (item.scanned > 0) return "partial";
  return "remaining";
}

/**
 * Purpose: Run the item text workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function itemText(item) {
  return [item.product, item.job, item.customer, item.route, item.processState, item.queueState, item.suggestedBay].join(" ");
}

/**
 * Purpose: Run the is remake item workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function isRemakeItem(item) {
  return /\b(REMAKE|RM)\b/i.test(`${item.processState || ""} ${item.queueState || ""}`);
}

/**
 * Purpose: Run the is rush item workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function isRushItem(item) {
  return /\b(RUSH|SDI)\b/i.test(`${item.processState || ""} ${item.queueState || ""}`);
}

/**
 * Purpose: Run the is remake or rush workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function isRemakeOrRush(item) {
  return isRemakeItem(item) || isRushItem(item);
}

/**
 * Purpose: Run the is new or updated item workflow for the browser application.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function isNewOrUpdatedItem(item) {
  if (state.backend) {
    return Boolean(item?.hasUnseenUpdate || item?.userUpdateState);
  }
  return /\b(NEW LINE|NEW|UPDATED|UPDATE|CHANGED|CHANGE)\b/i.test(`${item.processState || ""} ${item.queueState || ""}`);
}

/**
 * Purpose: Run the has scan error workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function hasScanError(item) {
  return Boolean(String(item?.errorReason || item?.lastError || "").trim());
}

/**
 * Purpose: Run the item piece qty workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function itemPieceQty(item) {
  return Math.max(Number(item?.qty || 0), 0);
}

/**
 * Purpose: Run the item scanned piece qty workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function itemScannedPieceQty(item) {
  return Math.min(Math.max(Number(item?.scanned || 0), 0), itemPieceQty(item));
}

/**
 * Purpose: Run the piece count workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function pieceCount(items) {
  return items.reduce((sum, item) => sum + itemPieceQty(item), 0);
}

/**
 * Purpose: Run the unscanned piece count workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function unscannedPieceCount(items) {
  return items.reduce((sum, item) => sum + Math.max(itemPieceQty(item) - itemScannedPieceQty(item), 0), 0);
}

/**
 * Purpose: Run the unresolved priority items workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function unresolvedPriorityItems(items = state.items) {
  return items.filter((item) => isRemakeOrRush(item) && itemStatus(item) !== "complete");
}

/**
 * Purpose: Run the unresolved remake items workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function unresolvedRemakeItems(items = state.items) {
  return items.filter((item) => isRemakeItem(item) && itemStatus(item) !== "complete");
}

/**
 * Purpose: Run the unresolved rush items workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function unresolvedRushItems(items = state.items) {
  return items.filter((item) => isRushItem(item) && itemStatus(item) !== "complete");
}

/**
 * Purpose: Create or resume the shared browser audio context used for scanner feedback.
 * Effects: Lazily creates one Web Audio context after an operator interaction.
 * Flow: Reuses the existing context so scan feedback never creates duplicate audio engines.
 */
function appAudioContext() {
  const AudioContextClass = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextClass) return null;
  if (!appSoundRuntime.context) {
    try {
      const context = new AudioContextClass();
      const masterGain = context.createGain();
      const compressor = context.createDynamicsCompressor();
      compressor.threshold.value = -16;
      compressor.knee.value = 18;
      compressor.ratio.value = 5;
      compressor.attack.value = 0.003;
      compressor.release.value = 0.18;
      masterGain.gain.value = appSoundRuntime.volumePercent / 100;
      masterGain.connect(compressor);
      compressor.connect(context.destination);
      appSoundRuntime.context = context;
      appSoundRuntime.masterGain = masterGain;
      appSoundRuntime.compressor = compressor;
    } catch (error) {
      appSoundRuntime.lastError = error?.message || "The browser could not create an audio output.";
      return null;
    }
  }
  return appSoundRuntime.context;
}

/** Unlock Web Audio during the operator's first real browser gesture. */
async function unlockAppSounds() {
  const context = appAudioContext();
  if (!context) return false;
  appSoundRuntime.unlocked = true;
  try {
    if (context.state === "suspended") await context.resume();
    if (context.state !== "running") throw new Error(`Browser audio is ${context.state}.`);

    // A one-frame silent buffer completes browser audio activation inside the real user gesture.
    const source = context.createBufferSource();
    source.buffer = context.createBuffer(1, 1, context.sampleRate);
    source.connect(context.destination);
    source.start(0);
    appSoundRuntime.lastError = "";
    for (const kind of APP_SOUND_PRELOAD_KINDS) void loadAppSoundBuffer(kind);
    return true;
  } catch (error) {
    appSoundRuntime.lastError = error?.message || "The browser blocked audio playback.";
    return false;
  }
}

/**
 * Purpose: Persist and synchronize the operator-selected scanner sound volume.
 * Effects: Updates the shared Web Audio master gain and every visible volume control.
 * Flow: Clamps the floor-volume range to 0-200%, persists it locally, and refreshes labels.
 */
function setAppSoundVolume(value, { persist = true } = {}) {
  const volumePercent = Math.max(0, Math.min(Number(value || 0), 200));
  appSoundRuntime.volumePercent = volumePercent;
  if (appSoundRuntime.masterGain && appSoundRuntime.context) {
    appSoundRuntime.masterGain.gain.setTargetAtTime(volumePercent / 100, appSoundRuntime.context.currentTime, 0.015);
  }
  if (persist) {
    try {
      localStorage.setItem(APP_SOUND_VOLUME_KEY, String(volumePercent));
    } catch {
      // Volume persistence is optional in restricted browser modes.
    }
  }
  document.querySelectorAll("[data-app-sound-volume]").forEach((input) => {
    if (Number(input.value) !== volumePercent) input.value = String(volumePercent);
  });
  document.querySelectorAll("[data-app-sound-volume-label]").forEach((label) => {
    label.textContent = `${Math.round(volumePercent)}%`;
  });
  updateAppSoundStatus(
    volumePercent > 0 ? `Sound is on at ${Math.round(volumePercent)}%.` : "Sound is muted. Move the slider to hear cues.",
    volumePercent > 0 ? "ready" : "error",
  );
}

/** Show browser-audio readiness in every visible account sound control. */
function updateAppSoundStatus(message, stateName = "ready") {
  document.querySelectorAll("[data-app-sound-status]").forEach((status) => {
    status.textContent = message;
    status.dataset.soundState = stateName;
  });
}

/**
 * Purpose: Schedule one short synthesized note inside the shared scanner audio context.
 * Effects: Creates a temporary oscillator and gain node that disconnect automatically after playback.
 * Flow: Applies a quick attack/release envelope so operational sounds remain clear without being harsh.
 */
function scheduleAppTone(context, { frequency, start, duration, type = "sine", volume = 0.12 }) {
  const oscillator = context.createOscillator();
  const gain = context.createGain();
  const safeStart = Math.max(Number(start || context.currentTime), context.currentTime);
  const safeDuration = Math.max(Number(duration || 0.1), 0.04);
  const safeVolume = Math.max(0.005, Math.min(Number(volume || 0.12), 0.42));

  oscillator.type = type;
  oscillator.frequency.setValueAtTime(Math.max(Number(frequency || 440), 40), safeStart);
  gain.gain.setValueAtTime(0.0001, safeStart);
  gain.gain.exponentialRampToValueAtTime(safeVolume, safeStart + 0.012);
  gain.gain.exponentialRampToValueAtTime(0.0001, safeStart + safeDuration);
  oscillator.connect(gain);
  gain.connect(appSoundRuntime.masterGain || context.destination);
  oscillator.start(safeStart);
  oscillator.stop(safeStart + safeDuration + 0.025);
}

/**
 * Purpose: Load one editable WAV file for an operational scanner sound.
 * Effects: Caches decoded audio so later scans play without another network request.
 * Flow: Fetches the maintained file, decodes it through Web Audio, and returns null on failure.
 */
async function loadAppSoundBuffer(kind) {
  if (appSoundRuntime.buffers.has(kind)) return appSoundRuntime.buffers.get(kind);
  if (appSoundRuntime.bufferPromises.has(kind)) return appSoundRuntime.bufferPromises.get(kind);
  const context = appAudioContext();
  const file = APP_SOUND_FILES[kind];
  if (!context || !file) return null;
  const promise = fetch(`${file}?v=${APP_SOUND_CACHE_VERSION}`, { cache: "force-cache" })
    .then((response) => {
      if (!response.ok) throw new Error(`Unable to load ${file}`);
      return response.arrayBuffer();
    })
    .then((bytes) => context.decodeAudioData(bytes))
    .then((buffer) => {
      appSoundRuntime.buffers.set(kind, buffer);
      return buffer;
    })
    .catch((error) => {
      appSoundRuntime.lastError = error?.message || `Unable to load ${file}.`;
      return null;
    })
    .finally(() => appSoundRuntime.bufferPromises.delete(kind));
  appSoundRuntime.bufferPromises.set(kind, promise);
  return promise;
}

/**
 * Purpose: Play a decoded editable sound file through the shared floor-volume chain.
 * Effects: Routes the WAV through the same master gain and compressor used by synthesized fallback sounds.
 */
function playAppSoundBuffer(context, buffer, delay = 0) {
  const source = context.createBufferSource();
  source.buffer = buffer;
  source.connect(appSoundRuntime.masterGain || context.destination);
  source.start(context.currentTime + Math.max(Number(delay || 0), 0));
}

/** Use the browser's media element path when Web Audio is unavailable or blocked. */
async function playHtmlAppSound(kind, delay = 0) {
  const file = APP_SOUND_FILES[kind];
  if (!file || typeof Audio !== "function") return false;
  if (delay > 0) await new Promise((resolve) => window.setTimeout(resolve, delay * 1000));
  const player = new Audio(`${file}?v=${APP_SOUND_CACHE_VERSION}`);
  player.preload = "auto";
  player.volume = Math.max(0, Math.min(appSoundRuntime.volumePercent / 100, 1));
  appSoundRuntime.htmlPlayers.add(player);
  const release = () => appSoundRuntime.htmlPlayers.delete(player);
  player.addEventListener("ended", release, { once: true });
  player.addEventListener("error", release, { once: true });
  try {
    await player.play();
    appSoundRuntime.lastError = "";
    return true;
  } catch (error) {
    release();
    appSoundRuntime.lastError = error?.message || "The browser blocked audio playback.";
    return false;
  }
}

/**
 * Purpose: Normalize legacy and semantic audio names into one maintained cue key.
 * Effects: Performs an in-memory lookup only.
 * Flow: Resolves the compatibility aliases first, then falls back to the neutral notification cue.
 */
function resolveAppSoundKind(kind = "notification") {
  const requested = String(kind || "notification").trim();
  const resolved = APP_SOUND_ALIASES[requested] || requested;
  return APP_SOUND_FILES[resolved] ? resolved : "notification";
}

/** Return true when a scanner submission is a transportation rack barcode. */
function isRackBarcodeScan(value) {
  return /^RACK/.test(cleanBarcode(value));
}

/**
 * Purpose: Select the most informative scan cue from the latest scan result.
 * Effects: Reads only the supplied scan result and current item classification helpers.
 * Flow: Prioritizes rejected/duplicate states, then successful Rush and remake identification.
 */
function scanSoundKind(entry, fallback = "scan_success") {
  if (!entry) return resolveAppSoundKind(fallback);
  const eventType = String(entry.eventType || entry.type || "").toLowerCase();
  if (!entry.ok) {
    if (eventType.includes("duplicate") || eventType.includes("already")) return "scan_duplicate";
    if (eventType.includes("notice") || eventType.includes("warning") || entry.overrideRequired) return "scan_warning";
    return "scan_error";
  }

  if (isRackBarcodeScan(entry.raw || entry.barcode || entry.rackBarcode || "")) return "rack_barcode";

  const item = entry.item || entry.lineItem || entry;
  if (isRushItem(item) || Boolean(entry.rush || item.rush)) return "scan_rush";
  if (isRemakeItem(item) || Boolean(entry.remake || item.remake)) return "scan_remake";
  return resolveAppSoundKind(fallback);
}

/**
 * Purpose: Play one semantic cue from the Delivery List Scanner audio language.
 * Effects: Plays immediate operational feedback through the shared compressor and volume control.
 * Flow: Uses a cached packaged WAV when available and otherwise loads that exact cue before playback.
 * This prevents a generic fallback tone from sounding before the intended button or scan cue.
 */
function playAppSound(kind = "notice", options = {}) {
  const normalizedKind = resolveAppSoundKind(kind);
  if (!APP_SOUND_ENABLED_KINDS.has(normalizedKind) || appSoundRuntime.volumePercent <= 0) return Promise.resolve(false);
  const now = performance.now();
  const lastPlayedAt = Number(appSoundRuntime.lastPlayedAt.get(normalizedKind) || 0);
  const throttleMs = ["task_complete", "rack_complete", "machine_fault"].includes(normalizedKind) ? 260 : 75;
  if (!options.force && now - lastPlayedAt < throttleMs) return Promise.resolve(false);
  appSoundRuntime.lastPlayedAt.set(normalizedKind, now);

  const context = appAudioContext();
  if (!context) return playHtmlAppSound(normalizedKind, Number(options.delay || 0));
  const delay = Math.max(Number(options.delay || 0), 0);

  const soundCategory = (() => {
    if (["scan_error", "machine_fault"].includes(normalizedKind)) return "error";
    if (normalizedKind === "scan_duplicate") return "duplicate";
    if (normalizedKind === "scan_warning") return "warning";
    if (["task_complete", "rack_complete"].includes(normalizedKind)) return "complete";
    if (["scan_rush", "scan_remake"].includes(normalizedKind)) return "priority";
    if (["save", "print_ready", "email_sent", "import_complete", "rack_barcode"].includes(normalizedKind)) return "confirmed";
    if (["undo", "logout", "rack_reopened", "rack_returned", "destructive_action"].includes(normalizedKind)) return "down";
    if (["redo", "login", "import_start", "notification", "machine_scan", "rack_outbound"].includes(normalizedKind)) return "up";
    return "success";
  })();

  const schedulePattern = () => {
    const start = context.currentTime + delay;
    const patterns = {
      success: [
        { frequency: 261.63, offset: 0, duration: 0.16, type: "triangle", volume: 0.055 },
        { frequency: 523.25, offset: 0.025, duration: 0.13, type: "sine", volume: 0.075 },
        { frequency: 659.25, offset: 0.095, duration: 0.15, type: "sine", volume: 0.085 },
        { frequency: 783.99, offset: 0.17, duration: 0.2, type: "sine", volume: 0.095 },
        { frequency: 1046.5, offset: 0.235, duration: 0.16, type: "triangle", volume: 0.055 },
      ],
      duplicate: [
        { frequency: 440, offset: 0, duration: 0.09, type: "triangle", volume: 0.075 },
        { frequency: 440, offset: 0.11, duration: 0.09, type: "triangle", volume: 0.065 },
      ],
      warning: [
        { frequency: 554.37, offset: 0, duration: 0.1, type: "triangle", volume: 0.075 },
        { frequency: 493.88, offset: 0.11, duration: 0.12, type: "triangle", volume: 0.07 },
      ],
      error: [
        { frequency: 196, offset: 0, duration: 0.13, type: "square", volume: 0.06 },
        { frequency: 164.81, offset: 0.14, duration: 0.16, type: "square", volume: 0.055 },
      ],
      priority: [
        { frequency: 659.25, offset: 0, duration: 0.08, type: "triangle", volume: 0.075 },
        { frequency: 880, offset: 0.09, duration: 0.12, type: "sine", volume: 0.09 },
      ],
      complete: [
        { frequency: 523.25, offset: 0, duration: 0.1, type: "triangle", volume: 0.07 },
        { frequency: 659.25, offset: 0.1, duration: 0.11, type: "triangle", volume: 0.075 },
        { frequency: 783.99, offset: 0.21, duration: 0.17, type: "sine", volume: 0.085 },
      ],
      confirmed: [
        { frequency: 659.25, offset: 0, duration: 0.09, type: "triangle", volume: 0.065 },
        { frequency: 880, offset: 0.08, duration: 0.14, type: "sine", volume: 0.075 },
      ],
      down: [
        { frequency: 587.33, offset: 0, duration: 0.08, type: "triangle", volume: 0.055 },
        { frequency: 440, offset: 0.075, duration: 0.11, type: "triangle", volume: 0.05 },
      ],
      up: [
        { frequency: 440, offset: 0, duration: 0.07, type: "triangle", volume: 0.05 },
        { frequency: 587.33, offset: 0.065, duration: 0.1, type: "sine", volume: 0.06 },
      ],
    };
    for (const note of patterns[soundCategory]) {
      scheduleAppTone(context, { ...note, start: start + note.offset });
    }
  };

  const playReadyCue = async () => {
    const buffer = appSoundRuntime.buffers.get(normalizedKind) || await loadAppSoundBuffer(normalizedKind);
    if (buffer) {
      playAppSoundBuffer(context, buffer, delay);
      return true;
    }
    return playHtmlAppSound(normalizedKind, delay);
  };

  if (context.state === "suspended") {
    return context.resume()
      .then(() => (context.state === "running" ? playReadyCue() : playHtmlAppSound(normalizedKind, delay)))
      .catch(() => playHtmlAppSound(normalizedKind, delay));
  }
  return Promise.resolve(playReadyCue());
}

/** Play one packaged WAV from an explicit operator click and report real browser startup. */
async function testAppSoundCue(kind = "scan_success") {
  const normalizedKind = resolveAppSoundKind(kind);
  if (appSoundRuntime.volumePercent <= 0) {
    updateAppSoundStatus("Sound is muted. Move the volume slider above 0%.", "error");
    return false;
  }
  updateAppSoundStatus("Testing browser audio...", "testing");
  const unlocked = await unlockAppSounds();
  const context = appAudioContext();
  const buffer = context ? await loadAppSoundBuffer(normalizedKind) : null;
  let played = false;
  try {
    if (unlocked && context?.state === "running" && buffer) {
      playAppSoundBuffer(context, buffer);
      played = true;
    } else {
      played = await playHtmlAppSound(normalizedKind);
    }
  } catch (error) {
    appSoundRuntime.lastError = error?.message || "Audio playback failed.";
  }
  updateAppSoundStatus(
    played ? `Sound played at ${Math.round(appSoundRuntime.volumePercent)}%.` : `Sound blocked: ${appSoundRuntime.lastError || "check this site's sound and Windows volume."}`,
    played ? "success" : "error",
  );
  return played;
}

/**
 * Purpose: Build the temporary sound-test controls used during floor tuning.
 * Effects: Returns markup only; all buttons use the shared delegated test handler.
 * Flow: Labels the progress test for the Scan or Bay context while reusing the same three outcome sounds.
 */
function soundTestControlsHtml(context = "scan") {
  const progressLabel = context === "bay" ? "Bay 100%" : "Scan 100%";
  return `
    <section class="scan-sound-test-panel" aria-label="Temporary scanner sound tests">
      <span class="scan-sound-test-copy"><strong>Temporary sound tests</strong><small>Remove after approval</small></span>
      <label class="scan-sound-volume-control">
        <span>Sound volume <strong data-app-sound-volume-label>${Math.round(appSoundRuntime.volumePercent)}%</strong></span>
        <input type="range" min="0" max="200" step="10" value="${Math.round(appSoundRuntime.volumePercent)}" data-app-sound-volume aria-label="Scanner sound volume">
        <small>Up to 200% floor boost</small>
      </label>
      <div class="scan-sound-test-actions">
        <button type="button" data-scan-sound-test="scan_success">Scan</button>
        <button type="button" data-scan-sound-test="scan_duplicate">Duplicate</button>
        <button type="button" data-scan-sound-test="scan_warning">Warning</button>
        <button type="button" data-scan-sound-test="scan_error">Error</button>
        <button type="button" data-scan-sound-test="scan_rush">Rush</button>
        <button type="button" data-scan-sound-test="scan_remake">Remake</button>
        <button type="button" data-progress-sound-test="${escapeHtml(context)}">${escapeHtml(progressLabel)}</button>
      </div>
    </section>
  `;
}

/**
 * Purpose: Fill every maintained temporary sound-test host without duplicating button behavior.
 * Effects: Updates only the test-control placeholders on Scan and Bay Map.
 * Flow: Reads each host context and injects one shared control template.
 */
function renderSoundTestControls(root = document) {
  root.querySelectorAll?.("[data-sound-test-host]").forEach((host) => {
    host.innerHTML = soundTestControlsHtml(host.dataset.soundTestHost || "scan");
  });
  setAppSoundVolume(appSoundRuntime.volumePercent, { persist: false });
}

/**
 * Purpose: Replay the completion animation and fun sound for temporary operator testing.
 * Effects: Toggles the existing celebration class and plays the shared completion cue.
 * Flow: Targets the requested Scan, Bay, or In-Transit progress component and removes the class after the normal animation window.
 */
function replayProgressSoundTest(context = "scan") {
  const selectors = {
    scan: "#scanProgressTrack",
    bay: "#bayPanelRouteMini [data-bay-dual-progress]",
    transit: "#bayFlowPanel [data-progress-context='transit']",
  };
  const targets = [...document.querySelectorAll(selectors[context] || selectors.scan)];
  for (const target of targets) {
    target.classList.remove("is-celebrating");
    void target.offsetWidth;
    target.classList.add("is-celebrating");
    window.setTimeout(() => target.classList.remove("is-celebrating"), 1900);
  }
  playAppSound("task_complete", { force: true });
  showFloatingNotice(`${context === "bay" ? "Bay Map" : context === "transit" ? "In-Transit" : "Scan"} 100% sound test played.`, "success");
}

/**
 * Purpose: Process the scan flash workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function scanFlash(kind = "notice", soundKind = "") {
  playAppSound(soundKind || kind);
  const className = kind === "success" ? "scan-flash-success" : kind === "error" ? "scan-flash-error" : "scan-flash-notice";
  document.body.classList.remove("scan-flash-success", "scan-flash-error", "scan-flash-notice");
  void document.body.offsetWidth;
  document.body.classList.add(className);
  window.setTimeout(() => document.body.classList.remove(className), 900);
}

/**
 * Purpose: Resolve the get stats workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function getStats(items = state.items, errors = state.errors) {
  const totalQty = pieceCount(items);
  const scannedQty = items.reduce((sum, item) => sum + itemScannedPieceQty(item), 0);
  const remainingQty = Math.max(totalQty - scannedQty, 0);

  const remainingItems = pieceCount(items.filter((item) => itemStatus(item) === "remaining"));
  const partialItems = pieceCount(items.filter((item) => itemStatus(item) === "partial"));
  const completeItems = pieceCount(items.filter((item) => itemStatus(item) === "complete"));
  const errorCount = unscannedPieceCount(items.filter(hasScanError));

  const percent = totalQty ? (scannedQty / totalQty) * 100 : 0;

  return { totalQty, scannedQty, remainingQty, partialItems, completeItems, remainingItems, percent, errorCount };
}

/**
 * Purpose: Resolve which Scan-page filter group owns a filter key.
 * Effects: None; this is the shared ownership map used by filtering and button state.
 * Flow: Searches the maintained filter groups and returns the matching group name or an empty string.
 */
function scanFilterGroup(filter) {
  return Object.entries(SCAN_FILTER_GROUPS).find(([, filters]) => filters.includes(filter))?.[0] || "";
}

/**
 * Purpose: Test one delivery-list item against one normalized Scan-page filter.
 * Effects: None; all filter predicates stay centralized so desktop and mobile views cannot drift.
 * Flow: Evaluates status, attention, or route rules and returns whether the item belongs to that filter.
 */
function itemMatchesScanFilter(item, filter) {
  const status = itemStatus(item);
  if (filter === "remaining" || filter === "partial" || filter === "complete") return status === filter;
  if (filter === "internal-rejects") return Number(item.internalRejectCount || 0) > 0;
  if (filter === "errors") return hasScanError(item);
  if (filter === "remakes") return isRemakeItem(item);
  if (filter === "rushes") return isRushItem(item);
  if (filter === "priority") return isRemakeOrRush(item);
  if (filter === "updated") return isNewOrUpdatedItem(item);
  if (filter === "cpu-route") return routeCategory(item) === "cpu";
  if (filter === "dtc-route") return routeCategory(item) === "dtc";
  if (filter === "greenville-route") return routeCategory(item) === "greenville";
  if (filter === "indian-trail-route") return routeCategory(item) === "indian_trail";
  return false;
}

/**
 * Purpose: Report whether a Scan-page filter button is currently selected.
 * Effects: None; the All button is treated as active only when no specific filters are selected.
 * Flow: Reads the shared Set and returns one consistent active-state answer for every renderer.
 */
function isScanFilterActive(filter) {
  return filter === "all" ? state.activeFilters.size === 0 : state.activeFilters.has(filter);
}

/**
 * Purpose: Synchronize Scan-page filter button styling and accessibility state.
 * Effects: Updates every desktop or mobile filter button currently in the DOM.
 * Flow: Applies the shared selected Set, including the special All/clear state, without rerendering the list.
 */
function syncScanFilterButtons() {
  document.querySelectorAll("[data-filter]").forEach((button) => {
    const active = isScanFilterActive(button.dataset.filter || "all");
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  renderActiveScanFilters();
}

/** Return the visible markers owned by the Scan table Flag column. */
function scanFlagLabels(item) {
  if (!item) return [];
  return [
    isRemakeItem(item) ? "Remake" : "",
    isRushItem(item) ? "Rush" : "",
    Number(item.internalRejectCount || 0) > 0 ? "Internal Reject" : "",
    item.manualOnly ? "Manual scan only" : "",
  ].filter(Boolean);
}

/** Return one stable display/sort value for a Scan-page column. */
function scanColumnValue(item, key) {
  if (!item) return "";
  if (key === "job") return `${item.job || ""} ${item.product || ""}`.trim();
  if (key === "order") return Number(item.order || 0);
  if (key === "item") return Number(item.item || 0);
  if (key === "qty") return Number(item.qty || 0);
  if (key === "dimensions") return String(item.dimensions || "");
  if (key === "customer") return String(item.customer || "");
  if (key === "flags") return scanFlagLabels(item).join(" ");
  if (key === "route") return routeLabel(item) || "Indian Trail";
  if (key === "location") return scanLocationPresentation(item).label || "";
  if (key === "progress") {
    const qty = Math.max(Number(item.qty || 0), 0);
    return qty ? Math.min(Math.max(Number(item.scanned || 0), 0), qty) / qty : 0;
  }
  return "";
}

/** Sort the filtered Scan-page rows by the active clickable column header. */
function sortScanItems(items) {
  const key = String(state.scanSortKey || "");
  const column = SCAN_TABLE_COLUMNS[key];
  if (!column) return items.slice();
  const direction = state.scanSortDirection === "desc" ? -1 : 1;
  return items.slice().sort((left, right) => {
    if (key === "flags") {
      const leftFlags = scanFlagLabels(left);
      const rightFlags = scanFlagLabels(right);
      const leftHasFlags = leftFlags.length > 0;
      const rightHasFlags = rightFlags.length > 0;
      if (leftHasFlags !== rightHasFlags) {
        // The first/ascending click intentionally puts flagged rows at the top.
        return (leftHasFlags ? -1 : 1) * direction;
      }
      const flagDifference = leftFlags.join(" ").localeCompare(rightFlags.join(" "), undefined, {
        numeric: true,
        sensitivity: "base",
      });
      if (flagDifference) return flagDifference * direction;
    } else {
      const a = scanColumnValue(left, key);
      const b = scanColumnValue(right, key);
      if (column.type === "number") {
        const difference = Number(a || 0) - Number(b || 0);
        if (difference) return difference * direction;
      } else {
        const difference = String(a || "").localeCompare(String(b || ""), undefined, {
          numeric: true,
          sensitivity: "base",
        });
        if (difference) return difference * direction;
      }
    }
    return String(left.id || "").localeCompare(String(right.id || ""), undefined, { numeric: true }) * direction;
  });
}

function syncScanTableHeaders() {
  document.querySelectorAll(".delivery-table thead th[data-scan-column]").forEach((header) => {
    const key = header.dataset.scanColumn || "";
    const sorted = state.scanSortKey === key;
    header.classList.toggle("is-sorted", sorted);
    header.setAttribute("aria-sort", sorted ? (state.scanSortDirection === "desc" ? "descending" : "ascending") : "none");
    const indicator = header.querySelector("[data-scan-sort-indicator]");
    if (indicator) indicator.textContent = sorted ? (state.scanSortDirection === "desc" ? "↓" : "↑") : "";
  });
}

/** Render active filter chips, including every selected glass type. */
function renderActiveScanFilters() {
  const selected = Object.values(SCAN_FILTER_GROUPS)
    .flat()
    .filter((filter) => state.activeFilters.has(filter) && filter !== "priority");
  const selectedGlassTypes = [...state.glassTypeFilters].sort((a, b) => a.localeCompare(b));
  const selectionCount = selected.length + selectedGlassTypes.length;
  const priorityOpen = unscannedPieceCount(state.items.filter((item) => isRemakeItem(item) || isRushItem(item)));

  if (els.scanFilterPriorityState) {
    els.scanFilterPriorityState.textContent = priorityOpen ? "!" : "\u2713";
    els.scanFilterPriorityState.classList.toggle("has-alert", Boolean(priorityOpen));
    els.scanFilterPriorityState.classList.toggle("is-clear", !priorityOpen);
    els.scanFilterPriorityState.setAttribute(
      "aria-label",
      priorityOpen ? `${priorityOpen} remake or Rush pieces still need scanning` : "No open remakes or rushes",
    );
  }
  if (!els.scanActiveFilterBar || !els.scanActiveFilterChips) return;
  els.scanActiveFilterBar.classList.toggle("has-active-filters", Boolean(selectionCount));
  els.scanActiveFilterChips.innerHTML = [
    ...selected.map((filter) => {
      const group = scanFilterGroup(filter) || "status";
      return `<button class="scan-filter-chip is-${escapeHtml(group)}" type="button" data-remove-scan-filter="${escapeHtml(filter)}"><i aria-hidden="true"></i><span>${escapeHtml(scanFilterLabelV355(filter))}</span><b aria-hidden="true">&times;</b></button>`;
    }),
    ...selectedGlassTypes.map(
      (label) => `<button class="scan-filter-chip is-glass glass-tone-chip" ${glassToneAttributes(label)} type="button" data-remove-glass-filter="${escapeHtml(label)}"><i aria-hidden="true"></i><span>${escapeHtml(label)}</span><b aria-hidden="true">&times;</b></button>`,
    ),
    ...(state.scanSortKey && SCAN_TABLE_COLUMNS[state.scanSortKey]
      ? [`<button class="scan-filter-chip is-sort-v328" type="button" data-clear-scan-sort><i aria-hidden="true"></i><span>${escapeHtml(SCAN_TABLE_COLUMNS[state.scanSortKey].label)} ${state.scanSortDirection === "desc" ? "↓" : "↑"}</span><b aria-hidden="true">&times;</b></button>`]
      : []),
  ].join("");
}

/**
 * Purpose: Toggle one Scan-page filter while preserving other selected filter groups.
 * Effects: Mutates the shared filter Set; selecting All clears every active filter.
 * Flow: Adds or removes the requested key, then synchronizes all visible filter buttons.
 */
function toggleScanFilter(filter) {
  if (!filter || filter === "all") {
    state.activeFilters.clear();
  } else if (state.activeFilters.has(filter)) {
    state.activeFilters.delete(filter);
  } else if (scanFilterGroup(filter)) {
    state.activeFilters.add(filter);
  }
  syncScanFilterButtons();
  document.dispatchEvent(new CustomEvent("dls:scan-filters-changed", {
    detail: { filters: [...state.activeFilters] },
  }));
}

/**
 * Purpose: Filter Scan-page items using combinable status, attention, route, glass, and search criteria.
 * Effects: None; reads shared state and returns a filtered copy.
 * Flow: Uses OR within each selected filter group and AND between groups, then applies glass and text search.
 */
function filteredItems() {
  const search = state.search.trim().toLowerCase();

  return state.items.filter((item) => {
    const matchesSelectedGroups = Object.values(SCAN_FILTER_GROUPS).every((groupFilters) => {
      const selectedFilters = groupFilters.filter((filter) => state.activeFilters.has(filter));
      return !selectedFilters.length || selectedFilters.some((filter) => itemMatchesScanFilter(item, filter));
    });

    if (!matchesSelectedGroups) return false;
    if (state.glassTypeFilters.size && !state.glassTypeFilters.has(glassTypeLabel(item))) return false;
    if (!search) return true;

    const haystack = [item.order, item.item, item.job, item.customer, item.dimensions, item.product, item.route, item.barcode]
      .join(" ")
      .toLowerCase();

    return haystack.includes(search);
  });
}

/**
 * Purpose: Run the group items by glass workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function groupItemsByGlass(items) {
  const groups = new Map();
  for (const item of items) {
    const label = glassTypeLabel(item);
    if (!groups.has(label)) groups.set(label, []);
    groups.get(label).push(item);
  }
  return [...groups.entries()].map(([label, items]) => ({ label, items }));
}

/**
 * Purpose: Resolve the get paged items workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function getPagedItems() {
  const filtered = filteredItems();
  const groups = groupItemsByGlass(filtered);

  // v0.473: column sorting is intentionally scoped inside each glass-type
  // section. Operators keep the maintained glass headers/separation while the
  // selected column controls row order within every glass type.
  const orderedEntries = groups.flatMap((group) =>
    sortScanItems(group.items).map((item) => ({ label: group.label, item, flat: false })),
  );
  const rows = orderedEntries.map((entry) => entry.item);

  const totalPages = Math.max(1, Math.ceil(orderedEntries.length / state.pageSize));
  state.pageIndex = Math.min(Math.max(state.pageIndex, 1), totalPages);

  const pageStart = (state.pageIndex - 1) * state.pageSize;
  const pageEntries = orderedEntries.slice(pageStart, pageStart + state.pageSize);

  const pageGroups = [];
  for (const entry of pageEntries) {
    const lastGroup = pageGroups[pageGroups.length - 1];
    if (lastGroup && lastGroup.label === entry.label) {
      lastGroup.items.push(entry.item);
    } else {
      pageGroups.push({ label: entry.label, flat: false, items: [entry.item] });
    }
  }

  const pageRows = pageEntries.map((entry) => entry.item);
  return { rows, pageRows, pageGroups, totalPages };
}

/**
 * Purpose: Run the stage verb workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function stageVerb() {
  const category = stageCategory(state.meta || {});
  return {
    received: "Received",
    outbound: "Outbound",
    pickup: "CPU",
    greenville: "Greenville",
    dtc: "Delivered",
    staged: "Staged",
  }[category] || "Staged";
}

/**
 * Purpose: Render the render process state workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function fabricationStatusKeyV474(order = "", item = "", job = "") {
  return [order, item, job].map((value) => String(value || "").trim().toUpperCase()).join("|");
}

function cachedFabricationStatusV474(item = {}) {
  return state.fabricationStatusCacheV474.get(fabricationStatusKeyV474(item.order, item.item, item.job)) || null;
}

function compactMachineLabelV475(value = "") {
  const machine = String(value || "").trim();
  if (!machine) return "";
  if (/water\s*jet|waterjet|\bwj\b/i.test(machine)) return "WaterJet";
  if (/denver/i.test(machine)) return "Denver";
  return machine.replace(/\s+CNC\b/i, "").trim() || machine;
}

function safeProgressColorV476(value = "", fallback = "#64748b") {
  const color = String(value || "").trim();
  return /^#[0-9a-f]{6}$/i.test(color) ? color : fallback;
}

function productionMachineColorV476(machine = "") {
  const label = compactMachineLabelV475(machine).toLowerCase();
  const colors = state.productionFileSettings?.machineColors || {};
  if (label.includes("waterjet")) return safeProgressColorV476(colors.waterjet, "#7c3aed");
  if (label.includes("denver")) return safeProgressColorV476(colors.denver, "#2563eb");
  return "#64748b";
}

function progressStageColorV476(label = "") {
  const signal = String(label || "").trim().toLowerCase();
  if (signal.includes("not scanned") || signal.includes("not started")) return "#7b8796";
  if (signal.includes("waterjet") || signal === "wj") return productionMachineColorV476("WaterJet");
  if (signal.includes("denver")) return productionMachineColorV476("Denver");
  if (signal.includes("not fabricated") || signal.includes("fabrication")) return "#7b8796";
  if (signal.includes("staged") || signal.includes("staging")) return "#4d74e6";
  if (signal.includes("outbound")) return "#d89a1f";
  if (signal.includes("received") || signal.includes("inbound") || signal.includes("indian trail")) return "#41b979";
  if (/\bcpu\b/.test(signal) || signal.includes("customer pickup")) return "#9b70dd";
  if (signal.includes("greenville") || /\bgnv\b/.test(signal)) return "#43b4c8";
  if (/\bdtc\b/.test(signal) || signal.includes("deliver to customer")) return "#e26da4";
  return "#718096";
}

function progressStageIconKindV476(label = "") {
  const signal = String(label || "").trim().toLowerCase();
  if (signal.includes("waterjet") || signal === "wj") return "waterjet";
  if (signal.includes("denver")) return "denver";
  if (signal.includes("staged") || signal.includes("staging")) return "staging";
  if (signal.includes("outbound")) return "outbound";
  if (signal.includes("received") || signal.includes("inbound") || signal.includes("indian trail")) return "received";
  if (/\bcpu\b/.test(signal)) return "cpu";
  if (signal.includes("greenville") || /\bgnv\b/.test(signal)) return "greenville";
  if (/\bdtc\b/.test(signal)) return "dtc";
  return "clock";
}

function fabricationProgressPresentationV474(item = {}) {
  const status = cachedFabricationStatusV474(item);
  if (!status) return null;
  const machine = compactMachineLabelV475(status.actualMachine || status.machine || status.assignedMachine || "");
  if (!machine && !status.sketchMatched) return null;
  if (status.fabricated === true && machine) {
    return { text: `${machine} 1/1`, label: machine, scanned: 1, qty: 1, complete: true, className: "fabricated-v474" };
  }
  if (status.sketchMatched && status.fabricated === false) {
    return { text: machine ? `${machine} 0/1` : "Not Fabricated", label: machine || "Fabrication", scanned: 0, qty: 1, complete: false, className: "not-fabricated-v474" };
  }
  if (status.sketchMatched && machine && status.fabricated == null) {
    return { text: `${machine} 0/1`, label: machine, scanned: 0, qty: 1, complete: false, className: "fabrication-unknown-v474" };
  }
  return null;
}

function scanNextDestinationLabelV475(item = {}) {
  const route = String(item.route || "").trim().toUpperCase();
  const labels = workflowPresentationV355();
  if (/\bCPU\b/.test(route)) return labels.cpuRoute || "CPU";
  if (/\bDTC\b/.test(route)) return labels.dtcRoute || "DTC";
  if (/\bGNV\b|GREENVILLE/.test(route)) return labels.gnvRoute || labels.branchStage || "Greenville";
  if (/INDIAN\s*TRAIL|\bIT\b/.test(route)) return labels.receivingStage || labels.receivingSite || "Received";
  return "";
}

/**
 * v0.475 compact Scan progress: one completed/current checkpoint above the next
 * required scanner stage. This keeps useful manufacturing context readable in
 * the narrow Progress column without long prose strings.
 */
function scanProgressPairV475(item = {}) {
  const qty = Math.max(0, Number(item.qty || 0));
  const scanned = Math.min(Math.max(0, Number(item.scanned || 0)), qty || Number(item.scanned || 0));
  const category = stageCategory(state.meta || {});
  const labels = workflowPresentationV355();
  const fabrication = fabricationProgressPresentationV474(item);
  const currentLabel = {
    staged: labels.stagingStage || "Staged",
    outbound: labels.outboundStage || "Outbound",
    received: labels.receivingStage || "Received",
    pickup: labels.cpuRoute || "CPU",
    greenville: labels.gnvRoute || labels.branchStage || "Greenville",
    dtc: labels.dtcRoute || "DTC",
  }[category] || stageVerb();
  const current = { label: currentLabel, scanned, qty, complete: qty > 0 && scanned >= qty, tone: "current" };

  if (category === "staged") {
    if (!fabrication && scanned <= 0) {
      const fabricationStatus = cachedFabricationStatusV474(item);
      // v0.478: once production hydration confirms the item has no machine or
      // fabrication assignment, identify that state explicitly instead of
      // implying that a fabrication scan is still expected.
      const noFabricationRequired = fabricationStatus && !compactMachineLabelV475(
        fabricationStatus.actualMachine || fabricationStatus.machine || fabricationStatus.assignedMachine || "",
      ) && !fabricationStatus.sketchMatched;
      return {
        previous: {
          label: noFabricationRequired ? "No Fab" : "Not Scanned",
          scanned: 0, qty, complete: false,
          tone: noFabricationRequired ? "no-fab-v478" : "not-scanned",
        },
        next: current,
      };
    }
    if (!current.complete) return { previous: fabrication, next: current };
    return { previous: current, next: { label: labels.outboundStage || "Outbound", scanned: 0, qty, complete: false, tone: "next" } };
  }
  if (category === "outbound") {
    if (!current.complete) return { previous: { label: labels.stagingStage || "Staged", scanned: qty, qty, complete: true, tone: "complete" }, next: current };
    const destination = scanNextDestinationLabelV475(item);
    return { previous: current, next: destination ? { label: destination, scanned: 0, qty, complete: false, tone: "next" } : null };
  }
  if (["received", "pickup", "greenville", "dtc"].includes(category)) {
    if (!current.complete) return { previous: { label: labels.outboundStage || "Outbound", scanned: qty, qty, complete: true, tone: "complete" }, next: current };
    return { previous: current, next: null };
  }
  return { previous: fabrication, next: current };
}

function progressStepHtmlV475(step, role = "") {
  if (!step) return "";
  const scanned = Math.max(0, Number(step.scanned || 0));
  const qty = Math.max(0, Number(step.qty || 0));
  const stateClass = step.complete ? "is-complete-v475" : role === "previous" ? "is-prior-pending-v475" : "is-next-v475";
  const toneClass = step.tone === "no-fab-v478" ? "is-no-fab-v478" : "";
  return `<span class="scan-progress-step-v475 ${stateClass} ${toneClass}" style="--progress-step-color:${escapeHtml(progressStageColorV476(step.label || "Progress"))}"><b>${escapeHtml(step.label || "Progress")}</b><strong>${escapeHtml(scanned)}/${escapeHtml(qty)}</strong></span>`;
}

function scanProgressMarkupV475(item = {}) {
  const pair = scanProgressPairV475(item);
  const left = pair.previous || pair.next || { label: "Progress" };
  const right = pair.next || pair.previous || left;
  const style = `--progress-left:${safeProgressColorV476(progressStageColorV476(left.label))};--progress-right:${safeProgressColorV476(progressStageColorV476(right.label))}`;
  return `<span class="scan-progress-stack-v475 scan-progress-stack-v476" style="${escapeHtml(style)}">${progressStepHtmlV475(pair.previous, "previous")}${pair.previous && pair.next ? `<i aria-hidden="true">→</i>` : ""}${progressStepHtmlV475(pair.next, "next")}</span>`;
}

/** Return the compact current scanner stage for legacy/mobile callers. */
function renderProcessState(item) {
  return `${stageVerb()}: ${item.scanned}/${item.qty}`;
}


/** Keep Inbound override context readable inside the narrow Stage column. */
function processPillMarkupV447(item, processClass, processText) {
  const overrideLabel = String(item?.inboundOverrideLabel || "").trim();
  const rawText = String(processText || "").trim();
  const sequenceMatch = rawText.match(/^IT\s+received\s+(\d+)\s*;\s*Outbound\s+(\d+)$/i);
  const sequenceParts = sequenceMatch
    ? [`Received ${sequenceMatch[1]}`, `Outbound ${sequenceMatch[2]}`]
    : rawText.includes(";")
      ? rawText.split(";").map((part) => part.trim()).filter(Boolean)
      : [];
  const stackedProgress = sequenceParts.length > 1;
  const progressMarkup = stackedProgress
    ? `<span class="process-pill-lines-v449">${sequenceParts.map((part, index) => `<span class="${index ? "is-indented-v449" : ""}">${escapeHtml(part)}</span>`).join("")}</span>`
    : `<span>${escapeHtml(rawText)}</span>`;
  if ((isIndianTrailScanContext() && overrideLabel) || stackedProgress) {
    return `<span class="process-pill ${escapeHtml(processClass)} is-stacked-v447${stackedProgress ? " is-stage-sequence-v449" : ""}">${progressMarkup}${overrideLabel ? `<small>${escapeHtml(overrideLabel)}</small>` : ""}</span>`;
  }
  return `<span class="process-pill ${escapeHtml(processClass)}">${escapeHtml(rawText)}</span>`;
}

/**
 * Purpose: Run the location label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function scanLocationPresentation(item) {
  const currentItem = item || {};
  const indianTrailStage = isIndianTrailScanContext();
  const stagingOrOutboundStage = isStagingScanContext() || isOutboundScanContext();

  // Bay locations belong only to the Indian Trail receiving stage. Once a bay
  // assignment is cleared/cancelled, keep the most recent bay visible as muted
  // history so operators can still see where the glass was physically stored.
  if (indianTrailStage) {
    const currentBay = bayLocationDisplayLabel(currentItem.bayCode, currentItem.bayName);
    const currentBayStatus = String(currentItem.bayStatus || "").trim().toLowerCase();
    const physicallyReceivedHere = Number(currentItem.scanned || 0) > 0 || !currentBayStatus.includes("pre");
    if (currentBay && physicallyReceivedHere) {
      return {
        label: currentBay,
        kind: "bay",
        historical: false,
        title: `Current Indian Trail bay: ${currentBay}`,
      };
    }

    // Before the Indian Trail receive scan, show both pieces of useful floor
    // context in one Location cell: the transport rack and the system's PRE bay.
    if (currentBay && currentBayStatus.includes("pre")) {
      const preRackCode = String(currentItem.rackCode || currentItem.lastRackCode || "").trim().toUpperCase();
      const preRackLabel = preRackCode
        ? rackLocationDisplayLabel(
            preRackCode,
            currentItem.rackCode ? currentItem.rackName : currentItem.lastRackName,
            currentItem.rackCode ? currentItem.rackType : currentItem.lastRackType,
          )
        : "";
      return {
        label: [preRackLabel, `PRE ${currentBay}`].filter(Boolean).join(" · "),
        kind: "preassigned",
        historical: Boolean(!currentItem.rackCode && currentItem.lastRackCode),
        rackLabel: preRackLabel,
        rackCode: preRackCode,
        bayLabel: currentBay,
        title: `${preRackLabel ? `${preRackLabel} · ` : ""}Preassigned to ${currentBay}; scan Indian Trail to confirm the physical bay.`,
      };
    }
    const previousBay = bayLocationDisplayLabel(currentItem.lastBayCode, currentItem.lastBayName);
    if (previousBay) {
      return {
        label: previousBay,
        kind: "bay",
        historical: true,
        title: `Previously stored in ${previousBay}; the bay assignment has been removed.`,
      };
    }

    // If the item has not been assigned to a receiving bay yet, retain the
    // transport rack text on Indian Trail and every downstream workflow. The
    // rack color was already available here; this fallback makes its label
    // visible too instead of leaving a colored but empty Location cell.
    const inboundReceived = Number(currentItem.scanned || 0) > 0
      || currentItem.received === true
      || Number(currentItem.receivedQty || 0) > 0;
    const inboundRackCode = String(currentItem.rackCode || "").trim().toUpperCase();
    const inboundRack = inboundRackCode
      ? rackLocationDisplayLabel(inboundRackCode, currentItem.rackName, currentItem.rackType)
      : "";
    if (inboundRack) {
      // v0.441 compatibility anchor: Transported to Indian Trail in ${inboundRack}.
      return {
        label: inboundRack,
        kind: /^truck/i.test(inboundRack) ? "truck" : "rack",
        historical: inboundReceived,
        title: inboundReceived
          ? `Previously transported to Indian Trail in ${inboundRack}.`
          : `Current transport rack: ${inboundRack}`,
      };
    }
    const inboundPreviousRack = rackHistoryLocationLabel(currentItem);
    if (inboundPreviousRack) {
      return {
        label: inboundPreviousRack,
        kind: /^truck/i.test(inboundPreviousRack) ? "truck" : "rack",
        historical: inboundReceived,
        title: inboundReceived
          ? `Previously transported in ${inboundPreviousRack}.`
          : `Current transport rack: ${inboundPreviousRack}`,
      };
    }
    return { label: "", kind: "bay", historical: false, title: "" };
  }

  // Staging/Outbound should continue to show the transport rack, not the later
  // Indian Trail bay. After receipt, the rack remains useful history and is
  // deliberately rendered in gray instead of being replaced with "Received".
  const rackCode = String(currentItem.rackCode || "").trim().toUpperCase();
  const currentRack = rackCode
    ? rackLocationDisplayLabel(rackCode, currentItem.rackName, currentItem.rackType)
    : "";
  if (currentRack) {
    const receivedDownstream = stagingOrOutboundStage
      && (currentItem.received === true || Number(currentItem.receivedQty || 0) > 0);
    return {
      label: currentRack,
      kind: /^truck/i.test(currentRack) ? "truck" : "rack",
      historical: receivedDownstream,
      title: receivedDownstream
        ? `Previously transported in ${currentRack}; this item has been received downstream.`
        : `Current rack location: ${currentRack}`,
    };
  }

  const previousRack = rackHistoryLocationLabel(currentItem);
  if (previousRack) {
    return {
      label: previousRack,
      kind: /^truck/i.test(previousRack) ? "truck" : "rack",
      historical: true,
      title: `Previously transported in ${previousRack}.`,
    };
  }

  return { label: "", kind: "rack", historical: false, title: "" };
}

function locationLabel(item) {
  return scanLocationPresentation(item).label;
}

function rackHistoryLocationLabel(item) {
  const previousRackCode = String(item?.lastRackCode || "").trim().toUpperCase();
  if (!previousRackCode) return "";
  return rackLocationDisplayLabel(previousRackCode, item?.lastRackName, item?.lastRackType);
}

function locationIsRackHistory(item) {
  const presentation = scanLocationPresentation(item);
  return presentation.historical && presentation.kind !== "bay";
}

/**
 * Purpose: Remove the clear selected line item workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function clearSelectedLineItem(render = true) {
  if (!state.selectedId) return;
  state.selectedId = null;
  saveState();
  if (render) renderScanPage();
}

/**
 * Purpose: Run the can assign rack location workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function canAssignRackLocation() {
  const roles = state.user?.roles || [];
  return Boolean(
    state.backend &&
      isStagingScanContext() &&
      (hasPermission("manage_racks") || roles.includes("Admin") || roles.includes("Supervisor")),
  );
}

/**
 * Purpose: Run the rack status value workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackStatusValue(rack) {
  return String(rack?.status || "").trim().toLowerCase();
}

/**
 * Purpose: Run the rack is locked for line assignment workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackIsLockedForLineAssignment(rack) {
  return ["closed", "complete", "completed", "in transit", "on the way"].includes(rackStatusValue(rack));
}

/**
 * Purpose: Run the rack for code workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackForCode(code) {
  const cleanCode = String(code || "").trim().toUpperCase();
  if (!cleanCode) return null;
  return (state.racks || []).find((rack) => String(rack.code || "").trim().toUpperCase() === cleanCode) || null;
}

/**
 * Purpose: Run the item can show rack location dropdown workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function itemCanShowRackLocationDropdown(item) {
  if (!canAssignRackLocation() || item.id !== state.selectedId) return false;
  if (itemScannedPieceQty(item) <= 0) return false;
  if (item?.received === true || Number(item?.receivedQty || 0) > 0) return false;

  const currentRackCode = String(item.rackCode || "").trim();
  if (!currentRackCode) return true;

  const currentRack = rackForCode(currentRackCode);
  return !currentRack || !rackIsLockedForLineAssignment(currentRack);
}

/**
 * Purpose: Run the location badge class workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function locationBadgeClass(location) {
  const lower = String(location || "").toLowerCase();
  return `location-badge ${
    lower.includes("received")
      ? "received"
      : lower.includes("bay")
        ? "bay"
        : lower.includes("truck")
          ? "truck"
          : "rack"
  }`;
}

/**
 * Purpose: Run the rack location dropdown workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function bayLocationPaletteV446(item = {}) {
  const kind = bayCategoryKind({
    bayCategory: item.bayCategory || "",
    bayType: item.bayType || "",
    mapSection: item.bayMapSection || "",
    displayName: item.bayName || "",
    bayCode: item.bayCode || "",
  });
  return {
    coral: { bg: "#fff2cc", border: "#b7892f", fg: "#4f3600" },
    lr: { bg: "#1f4e79", border: "#143a5e", fg: "#ffffff" },
    rr: { bg: "#1f4e79", border: "#143a5e", fg: "#ffffff" },
    showers: { bg: "#e2efda", border: "#5a9b48", fg: "#173b14" },
    mirror: { bg: "#eee7ff", border: "#8258ca", fg: "#34176d" },
    "bfs-mirror": { bg: "#eee7ff", border: "#8258ca", fg: "#34176d" },
    "framed-mirror": { bg: "#daeef3", border: "#008080", fg: "#003f46" },
    crl: { bg: "#fff7c2", border: "#8f8f11", fg: "#484600" },
    standard: { bg: "#f8fafc", border: "#cdd7e7", fg: "#07122f" },
  }[kind] || { bg: "#f8fafc", border: "#cdd7e7", fg: "#07122f" };
}

function bayLocationStyleV446(item = {}) {
  const palette = bayLocationPaletteV446(item);
  return `--bay-location-bg:${palette.bg};--bay-location-border:${palette.border};--bay-location-fg:${palette.fg}`;
}

function compactBayReferenceV446(label = "") {
  return String(label || "").trim().replace(/^Bay\s+/i, "") || "—";
}

function canAssignBayLocationV449() {
  const roles = state.user?.roles || [];
  return Boolean(
    state.backend
      && isIndianTrailScanContext()
      && (hasPermission("move_bay_items") || hasPermission("receive_indian_trail") || roles.includes("Admin") || roles.includes("Supervisor")),
  );
}

function itemCanShowBayLocationDropdownV449(item) {
  if (!canAssignBayLocationV449() || item?.id !== state.selectedId) return false;
  if (!Number(item?.bayAssignmentId || 0) || !String(item?.bayCode || "").trim()) return false;
  const status = String(item?.bayStatus || "").trim().toLowerCase();
  return !["cleared", "cancelled"].includes(status);
}

function bayLocationEditorV449(item, displayLocation) {
  const currentBayCode = String(item?.bayCode || "").trim();
  const allBays = (state.bays || []).filter((bay) => bay?.active !== false);
  const options = allBays.map((bay) => bayTargetOptionHtmlV442(bay, currentBayCode)).join("");
  const paletteStyle = bayLocationStyleV446(item);
  return `
    <label class="line-bay-location-control-v449" title="Change Bay location" style="${escapeHtml(paletteStyle)}">
      <span class="location-badge bay bay-location-accent-v446 line-bay-location-display-v449">${escapeHtml(displayLocation || currentBayCode)}</span>
      <span class="sr-only">Bay location</span>
      <select data-line-bay-select-v449="${escapeHtml(item.id)}" data-bay-assignment-id-v449="${escapeHtml(item.bayAssignmentId)}" aria-label="Change Bay location" ${options ? "" : "disabled"}>
        ${options || `<option value="${escapeHtml(currentBayCode)}" selected>Loading bays...</option>`}
      </select>
    </label>`;
}

function rackLocationStateV448(item = {}, presentation = {}, rack = null) {
  const removalReason = String(item.lastRackRemovalReason || "").trim().toLowerCase();
  if (presentation.historical && removalReason.includes("overridden by it")) {
    return { key: "overridden-by-it", label: "OVERRIDDEN BY IT" };
  }
  if (presentation.historical) return { key: "prior", label: "PRIOR" };
  const status = String(rack?.status || item.rackStatus || item.lastRackStatus || "").trim().toLowerCase();
  if (["in transit", "on the way"].includes(status)) return { key: "on-the-way", label: "ON THE WAY" };
  if (["closed", "complete", "completed"].includes(status)) return { key: "complete", label: "COMPLETE" };
  if (status === "open" || status === "building" || Boolean(item.rackCode || item.lastRackCode)) {
    return { key: "incomplete", label: "INCOMPLETE" };
  }
  return null;
}

function rackLocationDropdown(item, currentLocation = "") {
  const presentation = scanLocationPresentation(item);
  const displayLocation = presentation.label || currentLocation || "";
  // Once an item is physically in a Bay, the former rack must not tint the
  // current Location cell. Rack color remains only for rack/preassignment views.
  const presentationRackCode = presentation.kind === "bay"
    ? ""
    : String(presentation.rackCode || item.rackCode || item.lastRackCode || "").trim();
  const currentRack = rackForCode(presentationRackCode);
  const rackState = rackLocationStateV448(item, presentation, currentRack);
  const rackComplete = rackState?.key === "complete";
  const rackPrior = rackState?.key === "prior";
  const rackColor = currentRack ? rackSetDisplayColor(rackGroupLabel(currentRack)) : "";
  // v0.452: PRIOR is a completed historical location, so neutral gray replaces
  // the rack-set color instead of leaving a finished rack looking active.
  const resolvedRackColor = rackPrior ? "#94A1AD" : rackComplete ? "#2fa84f" : rackColor;
  const rackStyle = resolvedRackColor ? ` style="--rack-location-color:${escapeHtml(resolvedRackColor)}"` : "";
  const historyClass = presentation.historical
    ? ` is-location-history${presentation.kind === "bay" ? " is-bay-history" : " is-rack-history"}`
    : "";
  // v0.450: cleared Bay locations use the same explicit PRIOR treatment as rack
  // history so the Inbound list keeps physical traceability after Bay Map scan-out.
  const explicitHistoryBadge = presentation.historical && presentation.kind !== "preassigned";
  const bayStyle = presentation.kind === "bay" ? ` style="${escapeHtml(bayLocationStyleV446(item))}"` : "";
  const baseBadge = displayLocation
    ? `<span class="${escapeHtml(locationBadgeClass(displayLocation))}${historyClass}${explicitHistoryBadge ? " has-explicit-prior-v442" : ""}${presentation.kind === "bay" ? " bay-location-accent-v446" : ""}${rackColor ? " rack-location-accent-v349" : ""}"${bayStyle} title="${escapeHtml(presentation.title || displayLocation)}"><span class="location-history-label-v442">${escapeHtml(displayLocation)}</span></span>`
    : "";

  if (presentation.kind === "bay" && itemCanShowBayLocationDropdownV449(item)) {
    return bayLocationEditorV449(item, displayLocation);
  }

  const wrapRackSurface = (content) => resolvedRackColor
    ? `<span class="location-rack-cell-v349${rackComplete ? " is-rack-complete-v353" : ""}"${rackStyle}>${content}</span>`
    : content;
  const wrapRackLocation = (content) => {
    const surface = wrapRackSurface(content);
    if (!rackState || rackState.key === "prior") return surface;
    return `<span class="location-rack-state-stack-v448 is-${escapeHtml(rackState.key)}"><small class="location-rack-state-v448">${escapeHtml(rackState.label)}</small>${surface}</span>`;
  };

  if (presentation.kind === "preassigned") {
    const rackPart = presentation.rackLabel
      ? `<span class="location-preassigned-rack-v442">${escapeHtml(presentation.rackLabel)}</span>`
      : "";
    const bayReference = compactBayReferenceV446(presentation.bayLabel);
    const bayPart = presentation.bayLabel
      ? `<span class="location-preassigned-bay-v442 location-preassigned-bay-v446" style="${escapeHtml(bayLocationStyleV446(item))}" title="Preassigned ${escapeHtml(presentation.bayLabel)}"><span>PRE ${escapeHtml(bayReference)}</span></span>`
      : "";
    return wrapRackLocation(`<span class="location-preassigned-v442 location-preassigned-v446" title="${escapeHtml(presentation.title || displayLocation)}">${rackPart}${bayPart}</span>`);
  }

  if (!itemCanShowRackLocationDropdown(item)) {
    if (explicitHistoryBadge && baseBadge) {
      // v0.446 regression anchor: <b class="location-history-prior-v442">PRIOR</b>${wrapRackLocation(baseBadge)}
      const historyKey = rackState?.key || "prior";
      const historyLabel = rackState?.label || "PRIOR";
      return `<span class="location-history-stack-v446 location-rack-state-stack-v448 is-${escapeHtml(historyKey)}"><b class="location-history-prior-v442">${escapeHtml(historyLabel)}</b>${wrapRackSurface(baseBadge)}</span>`;
    }
    return presentation.kind === "bay" ? baseBadge : wrapRackLocation(baseBadge);
  }

  const currentRackCode = String(item.rackCode || "").trim().toUpperCase() === "T" ? "T" : String(item.rackCode || "").trim();
  const assignableRacks = (state.racks || []).filter((rack) => !rackIsLockedForLineAssignment(rack));
  const rackOptions = groupedRackOptionsHtml(assignableRacks, currentRackCode, { compactSelected: true });
  const currentRackLabel = currentRackCode
    ? rackLocationDisplayLabel(currentRackCode, item.rackName, item.rackType)
    : "";
  const editorLabel = currentRackLabel || "No rack";
  const editorBadgeClass = currentRackLabel
    ? locationBadgeClass(currentRackLabel)
    : "location-badge rack location-badge-empty-v350";

  const control = `
    <label class="line-rack-location-control rack-location-editor-v350" title="Change rack location">
      <span class="${escapeHtml(editorBadgeClass)}${rackColor ? " rack-location-accent-v349" : ""} line-rack-location-display-v350">${escapeHtml(editorLabel)}</span>
      <span class="sr-only">Rack location</span>
      <select data-line-rack-select="${escapeHtml(item.id)}" aria-label="Change rack location" ${rackOptions ? "" : "disabled"}>
        <option value="">${rackOptions ? "No rack" : "Loading racks..."}</option>
        ${rackOptions}
      </select>
    </label>`;

  const content = presentation.historical && baseBadge && !currentRackLabel
    ? `<span class="location-history-stack-v269 is-editable">${control}${baseBadge}</span>`
    : control;
  return wrapRackLocation(content);
}

/**
 * Purpose: Update the shared Scan-page progress meter with consistent text, motion, and completion feedback.
 * Effects: Updates the existing progress DOM and schedules a short completion-animation cleanup.
 * Flow: Normalizes the percentage, updates accessibility values, animates changed progress, and celebrates a newly completed stage.
 */
function updateScanProgress(stats, options = {}) {
  const totalQty = Math.max(Number(stats?.totalQty || 0), 0);
  const scannedQty = Math.max(Number(stats?.scannedQty || 0), 0);
  const percent = Math.max(0, Math.min(Number(stats?.percent || 0), 100));
  const previousPercent = state.lastRenderedProgressPercent;
  const sameList = state.lastRenderedProgressListId === state.activeListId;
  const changed = sameList && previousPercent !== null && Math.abs(percent - previousPercent) > 0.01;
  const newlyComplete = sameList && percent >= 100 && previousPercent !== null && previousPercent < 100;

  if (els.progressText) els.progressText.textContent = `Qty: ${scannedQty}/${totalQty} · ${formatPercent(percent)}`;
  if (els.progressFill) els.progressFill.style.width = `${percent}%`;
  if (els.scanProgressTrack) {
    els.scanProgressTrack.setAttribute("aria-valuenow", String(Math.round(percent)));
    els.scanProgressTrack.setAttribute("aria-valuetext", `${scannedQty} of ${totalQty} pieces, ${formatPercent(percent)} complete`);
    els.scanProgressTrack.classList.toggle("is-idle", percent < 100);
    els.scanProgressTrack.classList.toggle("is-complete", percent >= 100);
    if (changed || options.forceMotion) {
      els.scanProgressTrack.classList.remove("is-updating");
      void els.scanProgressTrack.offsetWidth;
      els.scanProgressTrack.classList.add("is-updating");
      window.setTimeout(() => els.scanProgressTrack?.classList.remove("is-updating"), 700);
    }
  }
  if (els.scanProgressTrack && (newlyComplete || options.celebrate)) {
    els.scanProgressTrack.classList.remove("is-celebrating");
    void els.scanProgressTrack.offsetWidth;
    els.scanProgressTrack.classList.add("is-celebrating");
    window.setTimeout(() => els.scanProgressTrack?.classList.remove("is-celebrating"), 1900);
  }
  if (newlyComplete && !options.preview && options.sound !== false) playAppSound("task_complete", { delay: 0.18 });
  if (!options.preview) {
    state.lastRenderedProgressPercent = percent;
    state.lastRenderedProgressListId = state.activeListId;
  }
}

/**
 * Purpose: Render the Bay Map scanner's mirrored Outbound and Received progress halves.
 * Effects: Replaces only the existing dual-progress meter markup inside the Bay Map route summary.
 * Flow: Calculates both completion percentages, fills each half toward the center, and triggers the shared completion celebration when both reach 100 percent.
 */
function bayDualProgressHtml(outboundQty, outboundTotal, inboundQty, inboundTotal, options = {}) {
  const safeOutboundTotal = Math.max(Number(outboundTotal || 0), 0);
  const safeInboundTotal = Math.max(Number(inboundTotal || 0), 0);
  const outboundPercent = safeOutboundTotal ? Math.min((Number(outboundQty || 0) / safeOutboundTotal) * 100, 100) : 0;
  const inboundPercent = safeInboundTotal ? Math.min((Number(inboundQty || 0) / safeInboundTotal) * 100, 100) : 0;
  const complete = safeOutboundTotal > 0 && safeInboundTotal > 0 && outboundPercent >= 100 && inboundPercent >= 100;
  const contextClass = options.context === "transit" ? "is-transit-card" : "";
  return `
    <div class="bay-dual-progress ${contextClass} ${complete ? "is-filled" : ""} ${options.celebrate ? "is-celebrating" : ""}" data-bay-dual-progress data-progress-context="${escapeHtml(options.context || "scanner")}">
      <div class="bay-dual-progress-half is-outbound" role="progressbar" aria-label="Outbound completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(outboundPercent)}">
        <i style="width:${outboundPercent}%"></i>
      </div>
      <span class="bay-dual-progress-center" aria-hidden="true"><b>✦</b></span>
      <div class="bay-dual-progress-half is-received" role="progressbar" aria-label="Received completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(inboundPercent)}">
        <i style="width:${inboundPercent}%"></i>
      </div>
      <div class="bay-dual-progress-label is-outbound"><span>Outbound</span><strong>${escapeHtml(formatPercent(outboundPercent))}</strong></div>
      <div class="bay-dual-progress-label is-received"><span>Received</span><strong>${escapeHtml(formatPercent(inboundPercent))}</strong></div>
    </div>
  `;
}

/** Update one compact Filters-button badge without rebuilding the drawer. */
function updateScanFilterGlanceBadge(element, count, label) {
  if (!element) return;
  const value = Math.max(Number(count || 0), 0);
  const countElement = element.querySelector("b");
  if (countElement) countElement.textContent = String(value);
  element.classList.toggle("has-items", value > 0);
  element.setAttribute("aria-label", `${value} ${label}`);
}

/**
 * Purpose: Render the render counts workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderCounts() {
  const stats = getStats();
  const totalItems = pieceCount(state.items);
  const glassCounts = new Map();
  for (const item of state.items) {
    const label = glassTypeLabel(item);
    glassCounts.set(label, (glassCounts.get(label) || 0) + Number(item.qty || 0));
  }

  const remakeItems = state.items.filter(isRemakeItem);
  const rushItems = state.items.filter(isRushItem);
  const updatedItems = state.items.filter(isNewOrUpdatedItem);
  const internalRejectItems = state.items.filter((item) => Number(item.internalRejectCount || 0) > 0);

  const remakeOpen = unscannedPieceCount(remakeItems);
  const remakeAll = pieceCount(remakeItems);
  const rushOpen = unscannedPieceCount(rushItems);
  const rushAll = pieceCount(rushItems);
  const updatedCount = pieceCount(updatedItems);
  const internalRejectCount = pieceCount(internalRejectItems);

  const routeCounts = {
    "indian-trail-route": pieceCount(state.items.filter((item) => routeCategory(item) === "indian_trail")),
    "cpu-route": pieceCount(state.items.filter((item) => routeCategory(item) === "cpu")),
    "dtc-route": pieceCount(state.items.filter((item) => routeCategory(item) === "dtc")),
    "greenville-route": pieceCount(state.items.filter((item) => routeCategory(item) === "greenville")),
  };
  if (els.countAll) els.countAll.textContent = `${totalItems}`;
  if (els.countRemaining) els.countRemaining.textContent = `${stats.remainingItems}`;
  if (els.countPartial) els.countPartial.textContent = `${stats.partialItems}`;
  if (els.countComplete) els.countComplete.textContent = `${stats.completeItems}`;
  if (els.countInternalRejects) els.countInternalRejects.textContent = `${internalRejectCount}`;
  const manualRemakeAll = pieceCount(remakeItems.filter((item) => item.manualOnly || String(item.manualSource || "").trim()));
  const sourceRemakeAll = Math.max(remakeAll - manualRemakeAll, 0);
  if (els.countRemakes) {
    els.countRemakes.textContent = manualRemakeAll
      ? `${sourceRemakeAll} A+W + ${manualRemakeAll} manual`
      : `${sourceRemakeAll}`;
    els.countRemakes.title = manualRemakeAll
      ? `${remakeAll} active remake pieces total: ${sourceRemakeAll} from A+W and ${manualRemakeAll} preserved manual`
      : `${sourceRemakeAll} active A+W remake pieces`;
  }
  if (els.countRushes) els.countRushes.textContent = `${rushAll}`;
  document.querySelectorAll('[data-filter="remakes"]').forEach((button) => {
    button.classList.toggle("has-alert", Boolean(remakeOpen));
    button.classList.toggle("is-clear", !remakeOpen);
  });
  document.querySelectorAll('[data-filter="rushes"]').forEach((button) => {
    button.classList.toggle("has-alert", Boolean(rushOpen));
    button.classList.toggle("is-clear", !rushOpen);
  });
  document.querySelectorAll('[data-filter="internal-rejects"]').forEach((button) => {
    button.classList.toggle("has-alert", Boolean(internalRejectCount));
    button.classList.toggle("is-clear", !internalRejectCount);
  });
  if (els.countUpdated) els.countUpdated.textContent = `${updatedCount}`;
  updateScanFilterGlanceBadge(els.scanFilterErrorBadge, stats.errorCount, "scan errors");
  updateScanFilterGlanceBadge(els.scanFilterRemakeBadge, remakeAll, "remake pieces");
  updateScanFilterGlanceBadge(els.scanFilterRushBadge, rushAll, "rush pieces");
  updateScanFilterGlanceBadge(els.scanFilterUpdatedBadge, updatedCount, "new-order pieces");
  updateScanFilterGlanceBadge(els.scanFilterRejectBadge, internalRejectCount, "internal reject pieces");
  if (els.countErrors) els.countErrors.textContent = `${stats.errorCount}`;

  document.querySelectorAll('[data-filter="errors"]').forEach((button) => {
    button.classList.toggle("has-alert", Boolean(stats.errorCount));
    button.classList.toggle("is-error-active-v470", Boolean(stats.errorCount));
  });

  if (els.countIndianTrailRoute) els.countIndianTrailRoute.textContent = `${routeCounts["indian-trail-route"]}`;
  if (els.countCpuRoute) els.countCpuRoute.textContent = `${routeCounts["cpu-route"]}`;
  if (els.countDtcRoute) els.countDtcRoute.textContent = `${routeCounts["dtc-route"]}`;
  if (els.countGreenvilleRoute) els.countGreenvilleRoute.textContent = `${routeCounts["greenville-route"]}`;
  let filterSelectionChanged = false;
  document.querySelectorAll(".route-filter-tab").forEach((button) => {
    const filter = button.dataset.filter || "";
    const count = routeCounts[filter] || 0;
    button.hidden = count === 0;
    if (count === 0 && state.activeFilters.delete(filter)) filterSelectionChanged = true;
  });
  if (filterSelectionChanged) state.pageIndex = 1;
  syncScanFilterButtons();
  for (const selectedGlassType of [...state.glassTypeFilters]) {
    if (!glassCounts.has(selectedGlassType)) state.glassTypeFilters.delete(selectedGlassType);
  }
  if (els.glassFilterTabs) {
    const sortedGlassEntries = [...glassCounts.entries()].sort(
      (a, b) => Number(b[1] || 0) - Number(a[1] || 0) || a[0].localeCompare(b[0]),
    );
    const selectedGlassTypes = [...state.glassTypeFilters].sort((a, b) => a.localeCompare(b));
    const signature = JSON.stringify([selectedGlassTypes, sortedGlassEntries]);
    if (signature !== state.lastGlassFilterSignature) {
      els.glassFilterTabs.innerHTML = [
        `<button class="tab glass-filter-tab ${state.glassTypeFilters.size ? "" : "is-active"}" data-glass-filter="all" type="button" aria-pressed="${state.glassTypeFilters.size ? "false" : "true"}">All Glass Types <span>${totalItems}</span></button>`,
        ...sortedGlassEntries.map(([label, count]) => {
          const active = state.glassTypeFilters.has(label);
          return `<button class="tab glass-filter-tab glass-tone-chip ${active ? "is-active" : ""}" ${glassToneAttributes(label)} data-glass-filter="${escapeHtml(label)}" type="button" aria-pressed="${active ? "true" : "false"}">${escapeHtml(label)} <span>${escapeHtml(count)}</span></button>`;
        }),
      ].join("");
      state.lastGlassFilterSignature = signature;
    }
  }
  renderActiveScanFilters();
  if (els.totalItemsText) els.totalItemsText.textContent = `${state.items.length} rows / ${totalItems} pieces`;
  updateScanProgress(stats);
  if (els.remainingQty) els.remainingQty.textContent = String(stats.remainingQty);
  if (els.partialQty) els.partialQty.textContent = String(stats.partialItems);
  if (els.completeQty) els.completeQty.textContent = String(stats.completeItems);
  if (els.errorQty) els.errorQty.textContent = String(stats.errorCount);
  if (els.remainingPct) els.remainingPct.textContent = formatPercent(100 - stats.percent);
  if (els.partialPct) els.partialPct.textContent = formatPercent(stats.totalQty ? (stats.partialItems / stats.totalQty) * 100 : 0);
  if (els.completePct) els.completePct.textContent = formatPercent(stats.percent);
}

/**
 * Purpose: Render the render pagers workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderPagers(totalRows, totalPages) {
  if (els.pageSize && Number(els.pageSize.value) !== state.pageSize) els.pageSize.value = String(state.pageSize);
  if (els.pageSizeBottom && Number(els.pageSizeBottom.value) !== state.pageSize) els.pageSizeBottom.value = String(state.pageSize);
  /**
   * Purpose: Render the render workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const render = () => {
    const buttons = [];
    buttons.push(`<button type="button" data-page-action="prev" ${state.pageIndex <= 1 ? "disabled" : ""}>&lt;</button>`);
    const pages = [];
    for (let page = 1; page <= totalPages; page += 1) {
      if (page === 1 || page === totalPages || Math.abs(page - state.pageIndex) <= 2) {
        pages.push(page);
      }
    }
    let previous = 0;
    for (const page of pages) {
      if (page - previous > 1) buttons.push("<span>...</span>");
      buttons.push(`<button type="button" data-page-number="${page}" class="${page === state.pageIndex ? "is-active" : ""}">${page}</button>`);
      previous = page;
    }
    buttons.push(`<button type="button" data-page-action="next" ${state.pageIndex >= totalPages ? "disabled" : ""}>&gt;</button>`);
    buttons.push(`<span class="pager-summary">${totalRows} rows</span>`);
    return `<div class="pager">${buttons.join("")}</div>`;
  };
  if (els.scanPagerTop) els.scanPagerTop.innerHTML = render();
  if (els.scanPagerBottom) els.scanPagerBottom.innerHTML = render();
}

/**
 * Purpose: Run the glass type label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
/**
 * Resolve a raw imported glass name through administrator-maintained combine
 * aliases. Alias rows are presentation/reporting identities only: historical
 * line-item product text remains untouched, and chains are flattened safely.
 */
function glassAliasTargetV360(value = "") {
  const original = String(value || "").replace(/\s+/g, " ").trim();
  if (!original) return "";
  const aliases = Array.isArray(state.manualEditLookups?.glassAliases) ? state.manualEditLookups.glassAliases : [];
  const bySource = new Map(aliases.map((item) => [String(item?.value || "").replace(/\s+/g, " ").trim().toLowerCase(), String(item?.label || item?.target || "").replace(/\s+/g, " ").trim()]));
  let current = original;
  const visited = new Set();
  for (let depth = 0; depth < 12; depth += 1) {
    const key = current.toLowerCase();
    if (!key || visited.has(key)) break;
    visited.add(key);
    const next = bySource.get(key);
    if (!next || next.toLowerCase() === key) break;
    current = next;
  }
  return current || original;
}

function glassAliasRowsForTargetV360(target = "") {
  const cleanTarget = String(target || "").replace(/\s+/g, " ").trim();
  if (!cleanTarget) return [];
  const cleanLower = cleanTarget.toLowerCase();
  const identity = glassProfileIdentityKeyV353(cleanTarget);
  return (state.manualEditLookups?.glassAliases || []).filter((item) => {
    const persistedTarget = String(item?.label || item?.target || "").replace(/\s+/g, " ").trim();
    if (!persistedTarget) return false;
    if (persistedTarget.toLowerCase() === cleanLower) return true;
    // v0.461: older persisted combinations can target a pre-normalized label
    // such as `3/8 Clear`. Match the durable physical-profile identity so the
    // same alias rows remain selectable after restart or later label cleanup.
    const persistedKey = String(item?.targetKey || "").trim() || glassProfileIdentityKeyV353(persistedTarget);
    return Boolean(identity && persistedKey === identity);
  });
}

/**
 * v0.460: clear glass must have an explicit heat-treatment identity anywhere
 * operators see it. Legacy/imported Clear or UltraClear text that omits both
 * Tempered and Annealed is operationally Annealed; source product text remains
 * unchanged for audit/history.
 */
function canonicalClearGlassLabelV460(value = "") {
  const raw = String(value || "").replace(/\s+/g, " ").trim();
  if (!raw || /\bmirror\b/i.test(raw) || !/(?:\bclear\b|\bultra\s*clear\b)/i.test(raw)) return raw;
  const tempered = /\b(?:temper(?:ed)?|temp|toughened)\b/i.test(raw);
  const base = raw
    .replace(/\b(?:temper(?:ed)?|temp|toughened|anneal(?:ed)?|ann)\b/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
  return `${base || raw} ${tempered ? "Tempered" : "Annealed"}`.trim();
}

function glassTypeLabel(item) {
  // Resolve combine aliases from the untouched imported source name first; the
  // backend glassType field is a fallback canonical hint, not a replacement for
  // administrator alias ownership.
  const sourceRaw = String(item?.product || item?.job || item?.suggestedBay || "Other Glass").trim() || "Other Glass";
  const backendCanonical = String(item?.glassType || "").trim();
  const combined = glassAliasTargetV360(sourceRaw) || backendCanonical || sourceRaw;
  return canonicalClearGlassLabelV460(combined) || combined;
}

// v0.312: Glass colors are centrally owned by Lookup Manager. Any component
// that needs exact glass-type colors should use these helpers instead of
// inventing a page-local palette, so one administrator choice can be reused.
function normalizeGlassVisualColor(value) {
  const text = String(value || "").trim().toUpperCase();
  return /^#[0-9A-F]{6}$/.test(text) ? text : "";
}

function glassVisualFallbackColor(label, usedColors = new Set()) {
  const text = String(label || "Other Glass").trim().toUpperCase() || "OTHER GLASS";
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619) >>> 0;
  }

  const hslToHex = (hue, saturation = 64, lightness = 44) => {
    const s = saturation / 100;
    const l = lightness / 100;
    const c = (1 - Math.abs(2 * l - 1)) * s;
    const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
    const m = l - c / 2;
    let r = 0;
    let g = 0;
    let b = 0;
    if (hue < 60) [r, g, b] = [c, x, 0];
    else if (hue < 120) [r, g, b] = [x, c, 0];
    else if (hue < 180) [r, g, b] = [0, c, x];
    else if (hue < 240) [r, g, b] = [0, x, c];
    else if (hue < 300) [r, g, b] = [x, 0, c];
    else [r, g, b] = [c, 0, x];
    const channel = (value) => Math.round((value + m) * 255).toString(16).padStart(2, "0");
    return `#${channel(r)}${channel(g)}${channel(b)}`.toUpperCase();
  };

  let hue = Math.round((hash * 137.508) % 360);
  let color = hslToHex(hue);
  let guard = 0;
  while (usedColors.has(color) && guard < 360) {
    hue = (hue + 37) % 360;
    color = hslToHex(hue);
    guard += 1;
  }
  return color;
}

function glassVisualLookupKeyV349(value = "") {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[®™]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .replace(/\s+/g, " ");
}

function buildGlassVisualColorMap(extraLabels = []) {
  const rows = Array.isArray(state.manualEditLookups?.glassColors) ? state.manualEditLookups.glassColors : [];
  const costs = Array.isArray(state.manualEditLookups?.glassCosts) ? state.manualEditLookups.glassCosts : [];
  const labels = new Map();

  const rememberLabelV452 = (value) => {
    const rawLabel = String(value || "").trim();
    if (!rawLabel) return;
    const targetLabel = glassAliasTargetV360(rawLabel) || rawLabel;
    labels.set(glassVisualLookupKeyV349(rawLabel), rawLabel);
    labels.set(glassVisualLookupKeyV349(targetLabel), targetLabel);
  };
  [...rows, ...costs].forEach((item) => rememberLabelV452(item?.value || item?.label));
  (extraLabels || []).forEach(rememberLabelV452);

  // v0.452: a combined source name must never overwrite the canonical profile's
  // configured color. Older source rows can legitimately retain their pre-combine
  // color in storage for reversible uncombine; while combined, only the target
  // profile owns the display color used throughout Scan, Bay Map, racks, and search.
  const overrides = new Map();
  rows.forEach((item) => {
    const rawLabel = String(item?.value || item?.label || "").trim();
    const label = glassAliasTargetV360(rawLabel) || rawLabel;
    const targetLabel = label;
    const rawKey = glassVisualLookupKeyV349(rawLabel);
    const targetKey = glassVisualLookupKeyV349(targetLabel);
    const canonicalKey = glassVisualLookupKeyV349(glassProfileCanonicalLabelV350(targetLabel));
    const color = normalizeGlassVisualColor(item?.color);
    const isCombinedSource = Boolean(rawKey && targetKey && rawKey !== targetKey);
    if (!color || isCombinedSource) return;
    if (targetKey) overrides.set(targetKey, color);
    if (rawKey) overrides.set(rawKey, color);
    if (canonicalKey && targetKey === canonicalKey) overrides.set(`canonical:${canonicalKey}`, color);
  });

  const used = new Set([...overrides.values()]);
  const effectiveColors = new Map();
  const result = new Map();
  [...labels.entries()].sort((a, b) => a[1].localeCompare(b[1])).forEach(([key, label]) => {
    const targetLabel = glassAliasTargetV360(label) || label;
    const targetKey = glassVisualLookupKeyV349(targetLabel);
    const canonicalLabel = glassProfileCanonicalLabelV350(targetLabel) || targetLabel;
    const canonicalKey = glassVisualLookupKeyV349(canonicalLabel);
    const configured = overrides.get(targetKey) || overrides.get(`canonical:${canonicalKey}`);
    let color = effectiveColors.get(targetKey) || effectiveColors.get(`canonical:${canonicalKey}`) || configured;
    if (!color) {
      color = glassVisualFallbackColor(canonicalLabel, used);
      used.add(color);
    }
    if (targetKey) effectiveColors.set(targetKey, color);
    if (canonicalKey) effectiveColors.set(`canonical:${canonicalKey}`, color);
    result.set(key, color);
    result.set(String(label).trim().toLowerCase(), color);
    if (targetKey) result.set(targetKey, color);
    if (targetLabel) result.set(String(targetLabel).trim().toLowerCase(), color);
    if (canonicalKey) result.set(`canonical:${canonicalKey}`, color);
  });
  return result;
}

function glassVisualColor(label, extraLabels = []) {
  const clean = String(label || "Other Glass").trim() || "Other Glass";
  const colorMap = buildGlassVisualColorMap([...(extraLabels || []), clean]);
  return colorMap.get(clean.toLowerCase())
    || colorMap.get(glassVisualLookupKeyV349(clean))
    || glassVisualFallbackColor(clean);
}

function glassVisualCssVariables(label, colorMap = null) {
  const clean = String(label || "Other Glass").trim() || "Other Glass";
  const color = normalizeGlassVisualColor(
    colorMap?.get?.(clean.toLowerCase())
    || colorMap?.get?.(glassVisualLookupKeyV349(clean)),
  ) || glassVisualColor(clean);
  const red = Number.parseInt(color.slice(1, 3), 16);
  const green = Number.parseInt(color.slice(3, 5), 16);
  const blue = Number.parseInt(color.slice(5, 7), 16);
  // v0.457: derive a smoother, slightly more restrained three-stop header
  // gradient from the canonical Lookup Manager color. The glass hue stays
  // recognizable while the section band reads as a polished header, not a
  // saturated color stripe.
  const blendHex = (target, sourceWeight) => {
    const targetRed = Number.parseInt(target.slice(1, 3), 16);
    const targetGreen = Number.parseInt(target.slice(3, 5), 16);
    const targetBlue = Number.parseInt(target.slice(5, 7), 16);
    const mix = (source, targetChannel) => Math.round((source * sourceWeight) + (targetChannel * (1 - sourceWeight)));
    return `#${[mix(red, targetRed), mix(green, targetGreen), mix(blue, targetBlue)]
      .map((channel) => channel.toString(16).padStart(2, "0"))
      .join("")}`.toUpperCase();
  };
  const headerStart = blendHex("#0B2A42", .56);
  const headerMid = blendHex("#153B55", .34);
  const headerEnd = blendHex("#203A50", .10);
  // v0.466: selected glass filters use the higher-contrast of white or navy
  // against the actual color-filled chip. This avoids threshold edge cases on
  // vivid greens/purples while keeping light yellow/clear fills readable.
  const relativeLuminanceV466 = (channels) => {
    const srgb = channels.map((channel) => channel / 255).map((value) => value <= .04045 ? value / 12.92 : ((value + .055) / 1.055) ** 2.4);
    return (.2126 * srgb[0]) + (.7152 * srgb[1]) + (.0722 * srgb[2]);
  };
  const selectionChannelsV466 = [red, green, blue].map((channel) => Math.round((channel * .94) + (255 * .06)));
  const backgroundLuminanceV466 = relativeLuminanceV466(selectionChannelsV466);
  const whiteContrastV466 = 1.05 / (backgroundLuminanceV466 + .05);
  const darkInkChannelsV466 = [16, 36, 58];
  const darkContrastV466 = (backgroundLuminanceV466 + .05) / (relativeLuminanceV466(darkInkChannelsV466) + .05);
  const selectedInk = whiteContrastV466 >= darkContrastV466 ? "#FFFFFF" : "#10243A";
  return [
    `--glass-type-color:${color}`,
    `--glass-type-selected-ink:${selectedInk}`,
    `--glass-type-accent:rgba(${red},${green},${blue},.50)`,
    `--glass-type-border:rgba(${red},${green},${blue},.16)`,
    `--glass-type-soft:rgba(${red},${green},${blue},.024)`,
    `--glass-type-soft-strong:rgba(${red},${green},${blue},.052)`,
    `--glass-type-ring:rgba(${red},${green},${blue},.055)`,
    `--glass-type-header-start:${headerStart}`,
    `--glass-type-header-mid:${headerMid}`,
    `--glass-type-header-end:${headerEnd}`,
  ].join(";");
}

/** Return safe data/style attributes for the shared glass-type gradient language. */
function glassToneAttributes(label, colorMap = null) {
  const clean = String(label || "Other Glass").trim() || "Other Glass";
  return `data-glass-type="${escapeHtml(clean)}" style="${escapeHtml(glassVisualCssVariables(clean, colorMap))}"`;
}

/** Load Lookup Manager glass colors for every authenticated operator, not only admins. */
async function ensureGlassVisualLookupLibrary({ force = false } = {}) {
  if (!state.backend) return state.manualEditLookups?.glassColors || [];
  if (!force && state.glassVisualLookupLoaded) return state.manualEditLookups?.glassColors || [];
  if (!state.glassVisualLookupPromise) {
    state.glassVisualLookupPromise = fetchJson("/api/glass-type-colors")
      .then((payload) => {
        state.manualEditLookups = {
          ...(state.manualEditLookups || {}),
          glassColors: Array.isArray(payload?.glassColors) ? payload.glassColors : [],
          // v0.452: aliases arrive with colors so the first Scan render cannot
          // briefly use a source glass name/color before presentation metadata loads.
          glassAliases: Array.isArray(payload?.glassAliases) ? payload.glassAliases : (state.manualEditLookups?.glassAliases || []),
        };
        state.glassVisualLookupLoaded = true;
        state.lastGlassFilterSignature = "";
        // v0.459: if Statistics painted before the lookup response completed,
        // repaint once so chart colors cannot remain on generated fallbacks.
        if (state.page === "statistics") renderStatisticsPage();
        return state.manualEditLookups.glassColors;
      })
      .catch(() => {
        state.glassVisualLookupLoaded = true;
        return state.manualEditLookups?.glassColors || [];
      })
      .finally(() => { state.glassVisualLookupPromise = null; });
  }
  return state.glassVisualLookupPromise;
}

/** Return whether this priority line was deliberately moved off the visible delivery date. */
function priorityDateMovedOutV441(item) {
  const originalDate = String(state.meta?.deliveryDate || "").trim();
  const targetDate = String(item?.priorityDeliveryDate || "").trim();
  return Boolean((item?.priorityBanner || isRushItem(item || {}) || isRemakeItem(item || {})) && originalDate && targetDate && originalDate !== targetDate);
}

/** Resolve the operator-facing priority ribbon label/reason for one line. */
function priorityBannerMetaV441(item) {
  const meta = item?.priorityBanner && typeof item.priorityBanner === "object" ? item.priorityBanner : null;
  if (meta?.label) return meta;
  if (isRemakeItem(item || {})) return { kind: "remake", label: "Remake", reason: "Imported remake marker" };
  if (isRushItem(item || {})) return { kind: "rush", label: "Rush", reason: "Priority handling" };
  return null;
}

/** Render the compact ribbon immediately above the exact priority line it belongs to. */
function priorityItemRibbonV441(item, options = {}) {
  const meta = priorityBannerMetaV441(item);
  if (!meta) return "";
  const originalDate = String(options.originalDate || state.meta?.deliveryDate || "").trim();
  const targetDate = String(options.targetDate || item?.priorityDeliveryDate || "").trim();
  const moved = Boolean(originalDate && targetDate && originalDate !== targetDate);
  const targetReference = Boolean(options.targetReference);
  const kind = ["remake", "both", "rush"].includes(String(meta.kind || "")) ? String(meta.kind) : "rush";
  const reason = String(meta.reason || "Priority handling").replace(/^\s*(?:Rush|Remake|SDI)\s*-\s*/i, "").trim() || "Priority handling";
  const moveText = moved
    ? targetReference
      ? `Moved here from ${formatDisplayDate(originalDate)} · Active on ${formatDisplayDate(targetDate)}`
      : `Moved to ${formatDisplayDate(targetDate)} · Original ${formatDisplayDate(originalDate)} line kept inactive for tracking`
    : "";
  return `
    <tr class="priority-line-ribbon-row-v441 is-${escapeHtml(kind)}${targetReference ? " is-target" : ""}" data-priority-ribbon-for="${escapeHtml(item?.id || item?.lineItemId || "")}">
      <td colspan="10">
        <div class="priority-line-ribbon-v441 is-${escapeHtml(kind)}${targetReference ? " is-target" : ""}">
          <span class="priority-line-ribbon-flag-v441" aria-hidden="true"></span>
          <strong>${escapeHtml(meta.label || "Priority")}</strong>
          <span class="priority-line-ribbon-reason-v441"><small>Reason</small><b>${escapeHtml(reason)}</b></span>
          ${moveText ? `<span class="priority-line-ribbon-move-v441">${escapeHtml(moveText)}</span>` : ""}
        </div>
      </td>
    </tr>`;
}

/** Keep target-date Rush references searchable without adding them to stage piece totals. */
function visibleRushMoveReferencesV385() {
  const refs = (state.rushMoveReferences || []).filter((entry) => String(entry?.direction || "") === "in");
  if (!refs.length) return [];
  if (state.activeFilters.size && !state.activeFilters.has("rushes")) return [];
  const glassFilters = state.glassTypeFilters || new Set();
  const query = String(state.search || "").trim().toLowerCase();
  return refs.filter((entry) => {
    if (glassFilters.size && !glassFilters.has(glassTypeLabel(entry))) return false;
    if (!query) return true;
    const haystack = [entry.order, entry.item, entry.job, entry.customer, entry.product, entry.dimensions, entry.route]
      .map((value) => String(value || "").toLowerCase())
      .join(" ");
    return haystack.includes(query);
  });
}

function renderRushMoveReferenceRowsV385() {
  return visibleRushMoveReferencesV385().map((entry) => {
    const item = {
      ...entry,
      id: entry.lineItemId || entry.id || "",
      scanned: Number(entry.scanned || 0),
      qty: Number(entry.qty || 0),
      priorityDeliveryDate: entry.targetDeliveryDate || entry.priorityDeliveryDate || "",
      priorityBanner: entry.priorityBanner || null,
    };
    const status = itemStatus(item);
    const glassLabel = glassTypeLabel(item);
    const glassTone = glassToneAttributes(glassLabel);
    const route = routeLabel(item);
    const routeTag = route ? `<span class="route-tag ${escapeHtml(route.toLowerCase())}">${escapeHtml(route)}</span>` : "";
    const locationHtml = rackLocationDropdown(item, locationLabel(item));
    const markers = [
      isRemakeItem(item) ? '<span class="row-marker remake-marker">RM</span>' : "",
      isRushItem(item) ? '<span class="row-marker rush-marker">Rush</span>' : "",
    ].filter(Boolean).join("");
    const scanTimePill = scanTimePillMarkupV447(item, entry.targetDeliveryDate || item.priorityDeliveryDate || "");
    return `
      ${priorityItemRibbonV441(item, { targetReference: true, originalDate: entry.originalDeliveryDate, targetDate: entry.targetDeliveryDate })}
      <tr class="glass-tone-row priority-date-moved-target-row-v441 ${status === "complete" ? "is-complete" : ""} ${item.lastScannedAt ? "has-scan-time-pill-v157" : ""}" ${glassTone} data-priority-moved-reference="${escapeHtml(entry.lineItemId || entry.id || "")}">
        <td class="job-cell-v157"><span class="job-copy-v157 glass-tone-inline" ${glassTone}><span class="job-title">${escapeHtml(item.product || item.job)}</span><span class="job-subtitle">${escapeHtml(item.job)}</span></span>${scanTimePill}</td>
        <td>${escapeHtml(item.order)}</td>
        <td>${escapeHtml(item.item)}</td>
        <td class="qty-cell"><span class="qty-value-v156">${escapeHtml(item.qty || 0)}</span></td>
        <td>${escapeHtml(item.dimensions || "")}</td>
        <td>${escapeHtml(item.customer || "")}</td>
        <td>${markers}</td>
        <td>${routeTag}</td>
        <td class="location-cell">${locationHtml}</td>
        <td>${processPillMarkupV447(item, status, renderProcessState(item))}</td>
      </tr>`;
  }).join("");
}

/**
 * Purpose: Give Delivery List Update Preview a quieter version of the shared glass palette.
 * Effects: Keeps Lookup Manager hue identity while reducing saturation and row intensity so dense previews remain readable.
 * Flow: Blends the configured hue toward its own luminance, then exposes preview-only CSS variables.
 */
function previewGlassVisualCssVariables(label, colorMap = null) {
  const clean = String(label || "Other Glass").trim() || "Other Glass";
  const color = normalizeGlassVisualColor(
    colorMap?.get?.(clean.toLowerCase())
    || colorMap?.get?.(glassVisualLookupKeyV349(clean)),
  ) || glassVisualColor(clean);
  const red = Number.parseInt(color.slice(1, 3), 16);
  const green = Number.parseInt(color.slice(3, 5), 16);
  const blue = Number.parseInt(color.slice(5, 7), 16);
  const gray = Math.round((red * .299) + (green * .587) + (blue * .114));
  const soften = (channel) => Math.round((channel * .68) + (gray * .32));
  const mutedRed = soften(red);
  const mutedGreen = soften(green);
  const mutedBlue = soften(blue);
  const mutedHex = `#${[mutedRed, mutedGreen, mutedBlue].map((value) => value.toString(16).padStart(2, "0")).join("")}`.toUpperCase();
  return [
    `--glass-type-color:${mutedHex}`,
    `--glass-type-border:rgba(${mutedRed},${mutedGreen},${mutedBlue},.30)`,
    `--glass-type-soft:rgba(${mutedRed},${mutedGreen},${mutedBlue},.06)`,
    `--glass-type-row:rgba(${mutedRed},${mutedGreen},${mutedBlue},.08)`,
    `--glass-type-row-strong:rgba(${mutedRed},${mutedGreen},${mutedBlue},.13)`,
    `--glass-type-ring:rgba(${mutedRed},${mutedGreen},${mutedBlue},.09)`,
  ].join(";");
}

/**
 * Purpose: Render the render item row workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderItemRow(item) {
  const orderContext = arguments[1] || {};
  const status = itemStatus(item);
  const glassLabel = glassTypeLabel(item);
  const glassTone = glassToneAttributes(glassLabel);
  const movedOutByPriorityDate = priorityDateMovedOutV441(item);
  const selected = !movedOutByPriorityDate && item.id === state.selectedId;
  const route = routeLabel(item);
  const routeTag = route
    ? `<span class="route-tag ${escapeHtml(route.toLowerCase())}">${escapeHtml(route)}</span>`
    : "";
  const location = locationLabel(item);
  const locationHtml = rackLocationDropdown(item, location);
  const rejectPieceCount = Number(item.internalRejectCount || 0);

  const markers = [
    isRemakeItem(item) ? '<span class="row-marker remake-marker">RM</span>' : "",
    isRushItem(item) ? '<span class="row-marker rush-marker">Rush</span>' : "",
    rejectPieceCount > 0 ? '<span class="row-marker internal-reject-marker">IR</span>' : "",
    item.manualOnly ? '<span class="row-marker manual-only-marker">Manual scan only</span>' : "",
  ].filter(Boolean).join("");

  const rowError = hasScanError(item);
  const processClass = rowError ? "error" : status;
  const processText = rowError ? item.errorReason || item.lastError || "Scan issue" : renderProcessState(item);
  const progressMarkupV475 = rowError ? processPillMarkupV447(item, processClass, processText) : scanProgressMarkupV475(item);
  const displayQty = Math.max(0, Math.trunc(Number(item.qty || 0)));
  const scanTimePill = scanTimePillMarkupV447(item);
  const rejectReason = item.lastRejectReason || "Internal reject";
  const rejectLocation = item.lastRejectLocation || "Unknown process location";
  const rejectTime = item.lastRejectedAt ? formatDateTime(item.lastRejectedAt) : "Time not available";
  const rejectQty = Number(item.lastRejectQty || rejectPieceCount || 0);
  const rejectedBy = item.lastRejectedBy || "System";
  const rejectIncidentRow = rejectPieceCount > 0
    ? `<tr class="internal-reject-detail-row-v154" data-reject-detail-for="${escapeHtml(item.id)}" data-line-detail-ribbon="reject">
        <td colspan="6">
          <div class="internal-reject-incident-strip-v154 line-detail-strip-v156">
            <span class="internal-reject-incident-badge-v154">IR</span>
            <strong class="internal-reject-incident-title-v154">Internal Reject</strong>
            <span><small>Reason</small><b>${escapeHtml(rejectReason)}</b></span>
            <span><small>Machine / location</small><b>${escapeHtml(rejectLocation)}</b></span>
            <span><small>Qty</small><b>${escapeHtml(rejectQty || rejectPieceCount)} pc${rejectQty === 1 ? "" : "s"}</b></span>
            <span><small>Rejected by</small><b>${escapeHtml(rejectedBy)}</b></span>
            <span><small>Incident</small><b>${escapeHtml(rejectTime)}</b></span>
          </div>
        </td>
        <td class="internal-reject-detail-tail-v154" colspan="4" aria-hidden="true"></td>
      </tr>`
    : "";

  const priorityRibbon = priorityItemRibbonV441(item, { targetReference: false });
  const rowIdentityAttribute = movedOutByPriorityDate
    ? `aria-disabled="true" data-priority-moved-source="${escapeHtml(item.id || "")}"`
    : `data-id="${escapeHtml(item.id)}" data-order-v470="${escapeHtml(item.order || "")}" data-item-v477="${escapeHtml(item.item || "")}"`;
  const groupPositionClass = [
    orderContext.first ? "is-order-first-v477" : "",
    orderContext.last ? "is-order-last-v477" : "",
  ].filter(Boolean).join(" ");

  return `
    ${priorityRibbon}
    ${rejectIncidentRow}
    <tr class="glass-tone-row scan-order-item-v477 ${groupPositionClass} ${selected ? "is-selected" : ""} ${status === "complete" ? "is-complete" : ""} ${isNewOrUpdatedItem(item) ? "is-new-line" : ""} ${rejectPieceCount > 0 ? "has-internal-reject" : ""} ${item.lastScannedAt ? "has-scan-time-pill-v157" : ""} ${movedOutByPriorityDate ? "is-priority-date-moved-source-v441" : ""}" ${glassTone} ${rowIdentityAttribute}>
      <td class="job-cell-v157"><span class="job-copy-v157 glass-tone-inline" ${glassTone}><span class="job-title">${escapeHtml(item.product || item.job)}</span><span class="job-subtitle">${escapeHtml(item.job)}</span></span>${scanTimePill}</td>
      <td>${escapeHtml(item.order)}</td>
      <td>${escapeHtml(item.item)}</td>
      <td class="qty-cell" title="${escapeHtml(item.scanned)} scanned of ${escapeHtml(displayQty)}"><span class="qty-value-v156">${escapeHtml(displayQty)}</span></td>
      <td>${escapeHtml(item.dimensions)}</td>
      <td>${escapeHtml(item.customer)}</td>
      <td>${markers}</td>
      <td>${routeTag}</td>
      <td class="location-cell">${locationHtml}</td>
      <td>${progressMarkupV475}</td>
    </tr>`;
}

function groupScanItemsByOrderV477(items = []) {
  const groups = new Map();
  for (const item of items || []) {
    const order = String(item?.order || "").trim();
    const key = order || `unassigned:${String(item?.id || groups.size)}`;
    if (!groups.has(key)) groups.set(key, { order, items: [] });
    groups.get(key).items.push(item);
  }
  return [...groups.values()];
}

function scanOrderGroupHeaderV477(group = {}, { mobile = false } = {}) {
  const items = Array.isArray(group.items) ? group.items : [];
  const first = items[0] || {};
  const order = String(group.order || first.order || "").trim();
  const pieces = items.reduce((sum, item) => sum + Math.max(0, Number(item.qty || 0)), 0);
  const subtitle = [first.customer, first.job].filter(Boolean).join(" · ");
  const content = `<span class="scan-order-group-copy-v477"><small>ORDER</small><strong>${escapeHtml(order || "Unassigned")}</strong>${subtitle ? `<em>${escapeHtml(subtitle)}</em>` : ""}</span><span class="scan-order-group-count-v477">${escapeHtml(items.length)} item${items.length === 1 ? "" : "s"} · ${escapeHtml(pieces)} pc${pieces === 1 ? "" : "s"}</span>${order ? `<button type="button" class="scan-order-detail-button-v477" data-open-order-detail-v474="${escapeHtml(order)}">View order details</button>` : ""}`;
  if (mobile) return `<header class="mobile-order-group-header-v477">${content}</header>`;
  return `<tr class="scan-order-group-v477" data-order-group-v477="${escapeHtml(order)}"><td colspan="10"><div>${content}</div></td></tr>`;
}

function renderOrderGroupedRowsV477(items = []) {
  return groupScanItemsByOrderV477(items).map((group) => {
    const rows = group.items.map((item, index) => renderItemRow(item, {
      first: index === 0,
      last: index === group.items.length - 1,
    })).join("");
    return `${scanOrderGroupHeaderV477(group)}${rows}`;
  }).join("");
}



/**
 * Purpose: Render the render table workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderTable() {
  if (!els.listRows) return;
  const { rows, pageGroups, totalPages } = getPagedItems();
  const rushMoveReferences = renderRushMoveReferenceRowsV385();
  renderPagers(rows.length, totalPages);
  syncScanTableHeaders();
  if (!pageGroups.length && !rushMoveReferences) {
    els.listRows.innerHTML = `<tr><td colspan="10">No rows match the current filters.</td></tr>`;
    return;
  }
  els.listRows.innerHTML = rushMoveReferences + pageGroups
    .map(({ label, flat, items: groupItems }) => {
      if (flat) return renderOrderGroupedRowsV477(groupItems);
      const totalQty = groupItems.reduce((sum, item) => sum + Number(item.qty || 0), 0);
      const scannedQty = groupItems.reduce((sum, item) => sum + Math.min(Number(item.scanned || 0), Number(item.qty || 0)), 0);
      const updatedCount = groupItems.filter(isNewOrUpdatedItem).length;
      const collapsed = state.collapsedGlassTypes.has(label);
      return `
        <tr class="glass-group-row glass-tone-group" ${glassToneAttributes(label)} data-glass-group="${escapeHtml(label)}">
          <td colspan="10">
            <button type="button" data-toggle-glass-group="${escapeHtml(label)}" aria-expanded="${collapsed ? "false" : "true"}">
              <strong class="glass-group-title-v459">${escapeHtml(label)}${updatedCount ? ` <mark class="new-line-marker group-marker glass-group-new-v462" title="New or updated lines">${escapeHtml(updatedCount)} New</mark>` : ""}</strong>
              <span class="glass-group-progress-v459">${escapeHtml(scannedQty)} / ${escapeHtml(totalQty)} pieces</span>
              <small class="glass-group-toggle-v459">${collapsed ? "Expand" : "Collapse"}</small>
            </button>
          </td>
        </tr>
        ${collapsed ? "" : renderOrderGroupedRowsV477(groupItems)}
      `;
    })
    .join("");
}

/**
 * Purpose: Run the staging lists workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function stagingLists() {
  return state.lists.filter((list) => stagePresetFromValuesV445(list?.stage || "", list?.scanner || "", list?.stagePreset || "") === "airport_staging");
}

/**
 * Purpose: Load the refresh racks page workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function refreshRacksPage() {
  if (!hasAnyPermission(["view_racks", "scan_racks", "manage_racks"])) return;
  if (state.backend) {
    const payload = await fetchJson("/api/racks");
    state.racks = payload.racks || [];
    state.rackSummary = payload.summary || null;
  }
  renderRacksPage();
  scheduleRackHeadingHitTargetRepair();
}

/**
 * Purpose: Render the render rack selects workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderRackSelects() {
  const stageLists = stagingLists();
  if (!state.rackScanListId || !stageLists.some((list) => list.id === state.rackScanListId)) {
    state.rackScanListId = stageLists[0]?.id || "";
  }
  if (!state.selectedRackCode || !state.racks.some((rack) => rack.code === state.selectedRackCode)) {
    state.selectedRackCode = state.racks.find((rack) => rack.code === "T")?.code || state.racks[0]?.code || "";
  }
  if (els.rackListSelect) {
    els.rackListSelect.innerHTML = stageLists
      .map((list) => `<option value="${escapeHtml(list.id)}">${escapeHtml(formatDisplayDate(list.deliveryDate))} - ${escapeHtml(list.stage)}</option>`)
      .join("");
    els.rackListSelect.value = state.rackScanListId;
  }
  if (els.rackSelect) {
    els.rackSelect.innerHTML = groupedRackOptionsHtml(state.racks, state.selectedRackCode);
    els.rackSelect.value = state.selectedRackCode;
    syncCustomSelect(els.rackSelect);
  }
}

/**
 * Purpose: Run the rack group label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackGroupLabel(rack) {
  return rack.code === "T" || /truck/i.test(rack.type || "") ? "Truck" : rack.type || "Racks";
}

const RACK_SET_ICON_LIBRARY = [
  ["rack", "Rack"],
  ["truck", "Truck"],
  ["steel", "Steel"],
  ["wood", "Wood"],
  ["aluminum", "Aluminum"],
  ["showers", "Shower"],
  ["mirror", "Mirror"],
  ["spacer", "Spacer"],
  ["coral", "Glass bay"],
  ["glasscart", "A-frame glass cart"],
  ["pallet", "Pallet"],
  ["dolly", "Dolly"],
  ["crate", "Crate"],
  ["warehouse", "Warehouse"],
];

const RACK_SET_COLOR_PALETTE = [
  "#176d72", "#245f9f", "#6b4fa1", "#a5532a", "#2f7d4a",
  "#8a3d67", "#3b6f91", "#8a6a20", "#3f5f4b", "#744d86",
];

function rackSetExplicitVisual(value) {
  const label = String(value || "Racks").trim();
  const rack = (state.racks || []).find((entry) => rackGroupLabel(entry) === label && (entry.setIcon || entry.setColor));
  return {
    icon: String(rack?.setIcon || "").trim().toLowerCase(),
    color: String(rack?.setColor || "").trim().toLowerCase(),
  };
}

function rackSetVisualColor(value) {
  return rackSetExplicitVisual(value).color || "";
}

/**
 * Return the exact rack-set accent used by the Racks page, including the
 * deterministic hue fallback when an older rack set has no saved custom color.
 * Keeping this helper shared prevents Scan Location cells and selectors from
 * drifting away from the rack-set color operators already recognize.
 */
function rackSetDisplayColor(value) {
  const explicit = rackSetVisualColor(value);
  return explicit || `hsl(${rackSetVisualHue(value)} 48% 42%)`;
}

function nextRackSetVisualColor() {
  const groups = new Set((state.racks || []).map((rack) => rackGroupLabel(rack)));
  return RACK_SET_COLOR_PALETTE[groups.size % RACK_SET_COLOR_PALETTE.length];
}

function rackSetIconLibraryHtml(selected = "rack", inputId = "rackSetModalIcon") {
  const current = String(selected || "rack").trim().toLowerCase();
  return `
    <input id="${escapeHtml(inputId)}" type="hidden" value="${escapeHtml(current)}">
    <div class="rack-set-icon-library-v269" role="list" aria-label="Rack set icon library">
      ${RACK_SET_ICON_LIBRARY.map(([value, label]) => `
        <button type="button" class="rack-set-icon-choice-v269 ${current === value ? "is-selected" : ""}" data-rack-set-icon-choice="${escapeHtml(value)}" data-rack-set-icon-target="${escapeHtml(inputId)}" aria-pressed="${current === value ? "true" : "false"}">
          <span class="rack-set-icon-choice-art-v271" aria-hidden="true">
            <span class="rack-set-visual-icon-v269" data-rack-icon="${escapeHtml(value)}"></span>
          </span>
          <small>${escapeHtml(label)}</small>
        </button>`).join("")}
    </div>`;
}

/** Render a quick color palette plus the native custom-color picker. */
function rackSetColorPickerHtml(selectedColor = "#176d72") {
  const current = String(selectedColor || "#176d72").trim().toLowerCase();
  return `
    <div class="rack-set-color-picker-v271">
      <div class="rack-set-color-palette-v271" role="list" aria-label="Suggested rack set colors">
        ${RACK_SET_COLOR_PALETTE.map((color) => `
          <button
            type="button"
            class="rack-set-color-choice-v271 ${current === color.toLowerCase() ? "is-selected" : ""}"
            data-rack-set-color-choice="${escapeHtml(color)}"
            aria-label="Use color ${escapeHtml(color.toUpperCase())}"
            aria-pressed="${current === color.toLowerCase() ? "true" : "false"}"
            style="--rack-set-choice-color:${escapeHtml(color)}"
          ><span aria-hidden="true"></span></button>`).join("")}
      </div>
      <label class="rack-set-custom-color-v271">
        <span>Custom color</span>
        <span class="rack-set-color-control-v269">
          <input id="rackSetModalColor" type="color" value="${escapeHtml(current)}" aria-label="Custom rack set icon color">
          <output data-rack-set-color-output>${escapeHtml(current.toUpperCase())}</output>
        </span>
      </label>
    </div>`;
}

function setRackSetVisualChoice(button) {
  const targetId = String(button?.dataset?.rackSetIconTarget || "").trim();
  const value = String(button?.dataset?.rackSetIconChoice || "rack").trim().toLowerCase();
  const input = targetId ? document.getElementById(targetId) : null;
  if (!input) return;
  input.value = value;
  const library = button.closest(".rack-set-icon-library-v269");
  library?.querySelectorAll("[data-rack-set-icon-choice]").forEach((choice) => {
    const selected = choice === button;
    choice.classList.toggle("is-selected", selected);
    choice.setAttribute("aria-pressed", selected ? "true" : "false");
  });
}


/** Return the maintained rack-set choices used by the individual-rack editor. */
function rackSetFormChoices(selected = "") {
  const current = String(selected || "").trim();
  const labels = [...new Set((state.racks || []).map((rack) => rackGroupLabel(rack)).filter(Boolean))];
  if (current && !labels.includes(current)) labels.push(current);
  if (!labels.length) labels.push("Steel", "Wood", "Truck", "Aluminum", "Other");
  return labels.sort((a, b) => {
    if (a === "Truck") return 1;
    if (b === "Truck") return -1;
    return String(a).localeCompare(String(b));
  });
}

/** Normalize a rack code exactly enough for client-side duplicate checks. */
function rackDraftCode(value = "") {
  let text = String(value || "").replace(/[^A-Za-z0-9]/g, "").toUpperCase();
  if (text.startsWith("RACK")) text = text.slice(4);
  if (text === "NORACK") return "";
  if (text === "TRUCK" || text === "TRUCK1") return "T";
  const truckMatch = text.match(/^TRUCK(\d+)$/);
  if (truckMatch) return Number(truckMatch[1]) === 1 ? "T" : `T${Number(truckMatch[1])}`;
  return text;
}

/** Validate an individual rack before the API request so duplicate identity is obvious. */
function rackFormDraftValidation() {
  const code = rackDraftCode(document.getElementById("rackModalCode")?.value || "");
  const oldCode = rackDraftCode(document.getElementById("rackModalOldCode")?.value || "");
  const requestedName = String(document.getElementById("rackModalName")?.value || "").trim();
  const effectiveName = requestedName || code;
  if (!code) return { ok: false, message: "Enter a rack code." };

  const codeConflict = (state.racks || []).find((rack) => (
    rackDraftCode(rack.code) === code && rackDraftCode(rack.code) !== oldCode
  ));
  if (codeConflict) {
    return { ok: false, message: `Rack code ${code} already exists.` };
  }

  if (effectiveName) {
    const nameKey = effectiveName.toLowerCase();
    const nameConflict = (state.racks || []).find((rack) => (
      rackDraftCode(rack.code) !== oldCode
      && String(rack.name || rack.code || "").trim().toLowerCase() === nameKey
    ));
    if (nameConflict) {
      return { ok: false, message: `Rack name “${effectiveName}” is already used by ${nameConflict.code}.` };
    }
  }
  return { ok: true, message: "Rack code and name are available." };
}

/** Validate rack-set identity and generated codes before sending the create request. */
function rackSetDraftValidation() {
  const name = String(document.getElementById("rackSetModalName")?.value || "").trim();
  const prefix = String(document.getElementById("rackSetModalPrefix")?.value || "")
    .replace(/[^A-Za-z0-9]/g, "")
    .toUpperCase()
    .slice(0, 8);
  const count = Math.max(1, Math.min(Number(document.getElementById("rackSetModalCount")?.value || 1), 100));
  const start = Math.max(1, Math.min(Number(document.getElementById("rackSetModalStart")?.value || 1), 999));
  if (!name) return { ok: false, message: "Enter a rack-set name.", targetCodes: [] };
  if (!prefix) return { ok: false, message: "Enter a code suffix.", targetCodes: [] };

  const existingSet = (state.racks || []).find((rack) => (
    rackGroupLabel(rack).trim().toLowerCase() === name.toLowerCase()
  ));
  if (existingSet) {
    return { ok: false, message: `${name} already exists. Add an individual rack to that set instead.`, targetCodes: [] };
  }

  const targetCodes = Array.from({ length: count }, (_, offset) => {
    const number = start + offset;
    return prefix.length <= 3 ? `R${number}${prefix}` : `${prefix}${number}`;
  });
  const activeCodes = new Set((state.racks || []).map((rack) => rackDraftCode(rack.code)));
  const conflicts = targetCodes.filter((code) => activeCodes.has(rackDraftCode(code)));
  if (conflicts.length) {
    const shown = conflicts.slice(0, 4).join(", ");
    return {
      ok: false,
      message: `${shown}${conflicts.length > 4 ? ", …" : ""} already exist. Change the suffix or starting number.`,
      targetCodes,
    };
  }
  return { ok: true, message: `${targetCodes.length} rack code${targetCodes.length === 1 ? " is" : "s are"} available.`, targetCodes };
}

function rackFormExistingSetRacksHtml(type = "", currentCode = "") {
  const cleanType = String(type || "").trim().toLowerCase();
  const cleanCurrent = rackDraftCode(currentCode);
  const racks = (state.racks || [])
    .filter((rack) => rackGroupLabel(rack).trim().toLowerCase() === cleanType)
    .slice()
    .sort((a, b) => Number(a.sortOrder || 0) - Number(b.sortOrder || 0) || String(a.code || "").localeCompare(String(b.code || ""), undefined, { numeric: true }));
  if (!racks.length) return `<span class="rack-set-existing-empty-v308">No racks exist in this set yet.</span>`;
  return racks.map((rack) => {
    const current = rackDraftCode(rack.code) === cleanCurrent;
    return `<span class="rack-set-existing-rack-v308 ${current ? "is-current" : ""}"><b>${escapeHtml(rack.code)}</b><small>${escapeHtml(rackOperatorDisplayName(rack))}</small><i class="${escapeHtml(rackStatusClassName(rack))}">${escapeHtml(rackStatusLabel(rack))}</i></span>`;
  }).join("");
}

function syncRackDraftValidation(form, validation, selector) {
  const target = form?.querySelector(selector);
  if (target) {
    target.textContent = validation.message;
    target.classList.toggle("is-error", !validation.ok);
    target.classList.toggle("is-ready", validation.ok);
  }
  const submit = form?.querySelector('button[type="submit"]');
  if (submit) submit.disabled = !validation.ok;
}

/** Keep the polished individual-rack preview synchronized with the form values. */
function syncRackFormPreview() {
  const form = document.getElementById("rackFormModal");
  if (!form) return;
  const code = String(document.getElementById("rackModalCode")?.value || "New rack").trim() || "New rack";
  const name = String(document.getElementById("rackModalName")?.value || "Rack display name").trim() || "Rack display name";
  const type = String(document.getElementById("rackModalType")?.value || "Racks").trim() || "Racks";
  const codeNode = form.querySelector("[data-rack-form-preview-code]");
  const nameNode = form.querySelector("[data-rack-form-preview-name]");
  const typeNode = form.querySelector("[data-rack-form-preview-type]");
  const icon = form.querySelector("[data-rack-form-preview-icon]");
  if (codeNode) codeNode.textContent = code;
  if (nameNode) nameNode.textContent = name;
  if (typeNode) typeNode.textContent = type;
  const existingRackHost = form.querySelector("[data-rack-form-existing-racks]");
  if (existingRackHost) existingRackHost.innerHTML = rackFormExistingSetRacksHtml(type, document.getElementById("rackModalOldCode")?.value || code);
  if (icon) {
    icon.dataset.rackIcon = rackSetVisualIcon(type);
    icon.style.setProperty("--rack-set-icon-color", rackSetVisualColor(type) || "#176d72");
  }
  syncRackDraftValidation(form, rackFormDraftValidation(), "[data-rack-form-validation]");
}

/** Keep the rack-set range and visual preview synchronized while the user types. */
function syncRackSetFormPreview() {
  const form = document.getElementById("rackSetFormModal");
  if (!form) return;
  const prefix = String(document.getElementById("rackSetModalPrefix")?.value || "S").replace(/[^A-Za-z0-9]/g, "").toUpperCase().slice(0, 8) || "S";
  const name = String(document.getElementById("rackSetModalName")?.value || "New rack set").trim() || "New rack set";
  const count = Math.max(1, Math.min(Number(document.getElementById("rackSetModalCount")?.value || 1), 100));
  const start = Math.max(1, Math.min(Number(document.getElementById("rackSetModalStart")?.value || 1), 999));
  const iconValue = String(document.getElementById("rackSetModalIcon")?.value || "rack").trim().toLowerCase();
  const color = String(document.getElementById("rackSetModalColor")?.value || "#176d72").trim();
  const firstCode = prefix.length <= 3 ? `R${start}${prefix}` : `${prefix}${start}`;
  const lastNumber = start + count - 1;
  const lastCode = prefix.length <= 3 ? `R${lastNumber}${prefix}` : `${prefix}${lastNumber}`;
  const nameNode = form.querySelector("[data-rack-set-preview-name]");
  const rangeNode = form.querySelector("[data-rack-set-preview-range]");
  const countNode = form.querySelector("[data-rack-set-preview-count]");
  const icon = form.querySelector("[data-rack-set-preview-icon]");
  if (nameNode) nameNode.textContent = name;
  if (rangeNode) rangeNode.textContent = count === 1 ? firstCode : `${firstCode} - ${lastCode}`;
  if (countNode) countNode.textContent = `${count} rack${count === 1 ? "" : "s"}`;
  if (icon) {
    icon.dataset.rackIcon = iconValue;
    icon.style.setProperty("--rack-set-icon-color", color);
  }
  form.style.setProperty("--rack-set-icon-color", color);
  form.querySelectorAll(".rack-set-icon-choice-v269 .rack-set-visual-icon-v269").forEach((choiceIcon) => {
    choiceIcon.style.setProperty("--rack-set-icon-color", color);
  });
  form.querySelectorAll("[data-rack-set-color-choice]").forEach((choice) => {
    const selected = String(choice.dataset.rackSetColorChoice || "").toLowerCase() === color.toLowerCase();
    choice.classList.toggle("is-selected", selected);
    choice.setAttribute("aria-pressed", selected ? "true" : "false");
  });
  const colorOutput = form.querySelector("[data-rack-set-color-output]");
  if (colorOutput) colorOutput.textContent = color.toUpperCase();
  syncRackDraftValidation(form, rackSetDraftValidation(), "[data-rack-set-validation]");
}

/** Return from either add-rack workflow to the maintained Edit Racks workspace. */
function returnToRackManager() {
  state.rackModal = null;
  openAdminModal("racks");
}

/**
 * Return the stable color hue shared by one rack set card and its rack-detail GUI.
 * Known material groups keep intentional colors; custom sets receive a restrained,
 * deterministic hue so their header remains recognizable after every refresh.
 */
function rackSetVisualHue(value) {
  const label = String(value || "Racks").trim().toLowerCase();
  if (/truck/.test(label)) return 174;
  if (/coral/.test(label)) return 39;
  if (/\blr\b|left.*right/.test(label)) return 214;
  if (/\brr\b|right.*return|return.*right/.test(label)) return 219;
  if (/shower|tempered/.test(label)) return 145;
  if (/framed.*mirror|mirror.*framed/.test(label)) return 188;
  if (/bfs.*mirror/.test(label)) return 266;
  if (/mirror|annealed/.test(label)) return 275;
  if (/crl|laurence/.test(label)) return 48;
  if (/spacer/.test(label)) return 198;
  if (/wood|timber/.test(label)) return 31;
  if (/alum/.test(label)) return 204;
  if (/steel|metal|rack/.test(label)) return 211;

  let hash = 0;
  for (const char of label) hash = ((hash * 31) + char.charCodeAt(0)) >>> 0;
  return 196 + (hash % 82);
}

/** Return the maintained icon family for a rack set or individual rack. */
function rackSetVisualIcon(value) {
  const explicit = rackSetExplicitVisual(value).icon;
  if (explicit) return explicit;
  const label = String(value || "Racks").trim().toLowerCase();
  if (/truck/.test(label)) return "truck";
  if (/coral/.test(label)) return "coral";
  if (/\blr\b|left.*right/.test(label)) return "lr";
  if (/\brr\b|right.*return|return.*right/.test(label)) return "rr";
  if (/shower|tempered/.test(label)) return "showers";
  if (/framed.*mirror|mirror.*framed/.test(label)) return "framed-mirror";
  if (/bfs.*mirror/.test(label)) return "bfs-mirror";
  if (/mirror|annealed/.test(label)) return "mirror";
  if (/crl|laurence/.test(label)) return "crl";
  if (/spacer/.test(label)) return "spacer";
  if (/wood|timber/.test(label)) return "wood";
  if (/alum/.test(label)) return "aluminum";
  if (/steel|metal/.test(label)) return "steel";
  return "rack";
}

/** Apply one rack set's color and icon to the shared operations modal header. */
function applyRackOperationsVisual(rack) {
  if (!els.operationsModal || !rack) return;
  const rackSet = rackGroupLabel(rack);
  els.operationsModal.dataset.rackSet = rackSet;
  els.operationsModal.dataset.rackIcon = rackSetVisualIcon(rackSet);
  const setHue = rackSetVisualHue(rackSet);
  els.operationsModal.style.setProperty("--rack-set-hue", String(setHue));
  const setColor = rackSetVisualColor(rackSet);
  const modalAccent = setColor || `hsl(${setHue} 48% 42%)`;
  els.operationsModal.style.setProperty("--rack-modal-accent", modalAccent);
  if (setColor) els.operationsModal.style.setProperty("--rack-set-icon-color", setColor);
  else els.operationsModal.style.removeProperty("--rack-set-icon-color");
}

/** Apply the audited records treatment to the shared Racks History GUI. */
function applyRackHistoryOperationsVisual() {
  if (!els.operationsModal) return;
  els.operationsModal.dataset.rackSet = "Rack History";
  els.operationsModal.dataset.rackIcon = "history";
  els.operationsModal.style.setProperty("--rack-set-hue", "211");
}

/** Clear rack-specific visual state before the shared modal serves another GUI. */
function clearRackOperationsVisual() {
  if (!els.operationsModal) return;
  delete els.operationsModal.dataset.rackSet;
  delete els.operationsModal.dataset.rackIcon;
  els.operationsModal.style.removeProperty("--rack-set-hue");
  els.operationsModal.style.removeProperty("--rack-set-icon-color");
  els.operationsModal.style.removeProperty("--rack-modal-accent");
}

/**
 * Purpose: Run the grouped rack options HTML workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackSelectorGroups(racks = []) {
  const groups = new Map();
  for (const rack of racks) {
    const label = rackGroupLabel(rack);
    if (!groups.has(label)) groups.set(label, []);
    groups.get(label).push(rack);
  }
  return [...groups.entries()]
    .sort(([labelA], [labelB]) => {
      if (labelA === "Truck") return -1;
      if (labelB === "Truck") return 1;
      return labelA.localeCompare(labelB, undefined, { numeric: true, sensitivity: "base" });
    })
    .map(([label, groupRacks]) => [
      label,
      groupRacks.slice().sort((rackA, rackB) => rackOperatorDisplayName(rackA).localeCompare(rackOperatorDisplayName(rackB), undefined, { numeric: true, sensitivity: "base" })),
    ]);
}

function groupedRackOptionsHtml(racks = [], selectedCode = "", options = {}) {
  const includeNoRack = Boolean(options.includeNoRack);
  const disableLocked = Boolean(options.disableLocked);
  const allowCompleted = Boolean(options.allowCompleted);
  const compactSelected = Boolean(options.compactSelected);
  const noRackOption = includeNoRack
    ? `<option value="${NO_RACK_SELECTION}" ${selectedCode === NO_RACK_SELECTION ? "selected" : ""}>No Rack - Leave location blank</option>`
    : "";
  const groupEntries = rackSelectorGroups(racks);

  const groupedOptions = groupEntries
    .map(([label, groupRacks]) => `
      <optgroup label="${escapeHtml(label)}">
        ${groupRacks
          .slice()
          .sort((rackA, rackB) => rackOperatorDisplayName(rackA).localeCompare(rackOperatorDisplayName(rackB), undefined, { numeric: true, sensitivity: "base" }))
          .map((rack) => {
            const status = rackStatusValue(rack);
            const completed = ["closed", "complete", "completed"].includes(status);
            const locked = disableLocked && rackIsLockedForLineAssignment(rack) && !(allowCompleted && completed);
            const statusCue = rackStatusClassName(rack);
            const routeCue = rackDestinationClass(rackResolvedDestination(rack));
            const statusLabel = rackStatusLabel(rack);
            const routeLabel = rackResolvedDestination(rack) ? rackDestinationLabel(rackResolvedDestination(rack)) : "";
            const rackColor = rackSetDisplayColor(rackGroupLabel(rack));
            // Inline Location keeps the compact display name only. Operational
            // selectors retain the full rack summary; syncCustomSelect renders
            // the route separately as the leading colored pill.
            const selectedText = compactSelected
              ? rackOperatorDisplayName(rack)
              : rackOptionLabel(rack);
            const selectedLabel = ` data-selected-label="${escapeHtml(selectedText)}"`;
            return `<option value="${escapeHtml(rack.code)}"${selectedLabel} data-rack-status="${escapeHtml(statusCue)}" data-rack-status-label="${escapeHtml(statusLabel)}" data-rack-route="${escapeHtml(routeCue)}" data-rack-route-label="${escapeHtml(routeLabel)}" data-rack-color="${escapeHtml(rackColor)}" ${String(rack.code) === String(selectedCode) ? "selected" : ""} ${locked ? "disabled" : ""}>${escapeHtml(rackOptionLabel(rack))}</option>`;
          })
          .join("")}
      </optgroup>
    `)
    .join("");

  return `${noRackOption}${groupedOptions}`;
}

/**
 * Purpose: Run the rack code for scan workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function rackCodeForScan(value) {
  const selectedCode = String(value || "").trim();
  return selectedCode === NO_RACK_SELECTION ? "" : selectedCode;
}

/**
 * Normalize a persisted rack name for operator-facing UI without changing the
 * stored rack identity. Older data may contain names such as "Rack 1 Steel";
 * the maintained display convention is "Steel 1" / "Wood 1".
 */
function normalizeRackDisplayName(name = "", type = "") {
  const cleanType = String(type || "").replace(/\s+/g, " ").trim();
  let text = String(name || "").replace(/\s+/g, " ").trim();
  if (!text) return "";

  text = text.replace(/\bracks?\b/gi, " ").replace(/\s+/g, " ").trim();
  const numberFirst = text.match(/^(\d+)\s+(.+)$/);
  if (numberFirst) text = `${numberFirst[2].trim()} ${Number(numberFirst[1])}`;

  // A legacy name may be only "Rack 1" while the set/type carries "Steel".
  // In that case use the type as the human-readable identity instead of "1".
  if (/^\d+$/.test(text) && cleanType && !/truck/i.test(cleanType)) {
    const typeLabel = cleanType.replace(/\bracks?\b/gi, " ").replace(/\s+/g, " ").trim();
    if (typeLabel) return `${typeLabel} ${Number(text)}`;
  }
  return text;
}

/** Return a stable operator label from the persisted truck/rack identity. */
function rackDisplayLabelFromParts(code = "", name = "", type = "") {
  const cleanCode = String(code || "").trim().toUpperCase();
  const cleanName = String(name || "").trim();
  if (cleanCode === "T") return cleanName || "Truck 1";
  const numberedTruck = cleanCode.match(/^(?:R?T)(\d+)$/);
  if (numberedTruck) return cleanName || `Truck ${Number(numberedTruck[1])}`;
  if (/truck/i.test(`${cleanName} ${type || ""}`)) return cleanName || cleanCode || "Truck";
  return normalizeRackDisplayName(cleanName, type) || cleanCode;
}

function rackDisplayCode(rack = {}) {
  const code = String(rack?.code || "").trim().toUpperCase();
  if (code === "T") return "RT1";
  if (/^T\d+$/.test(code)) return `R${code}`;
  return code || "Rack";
}

function rackOperatorDisplayName(rack = {}) {
  return rackDisplayLabelFromParts(rack?.code, rack?.name, rack?.type) || rackDisplayCode(rack);
}

/** Return the concise current-location label used in scanner/order tables. */
function rackLocationDisplayLabel(code = "", name = "", type = "") {
  return rackDisplayLabelFromParts(code, name, type);
}

/** Return the compact operator-facing bay label without exposing internal T-BAY prefixes. */
function bayLocationDisplayLabel(code = "", name = "") {
  const cleanCode = String(code || "").trim();
  const cleanName = String(name || "").trim();

  const compactCanonical = (value) => {
    let text = String(value || "").trim();
    if (!text) return "";
    text = text.replace(/^BAY\s+/i, "").trim();
    // Legacy bay display names can contain doubled separators (for example
    // 12--1). Normalize those for operator-facing labels without changing the
    // stored bay code or assignment identity.
    text = text.replace(/-{2,}/g, "-");
    const match = text.match(/^(?:[A-Z]+-)?BAY[-\s]*(\d+(?:-\d+)*)$/i)
      || text.match(/^(\d+(?:-\d+)*)$/);
    return match ? `Bay ${match[1]}` : "";
  };

  const compactName = compactCanonical(cleanName);
  if (compactName) return compactName;
  const compactCode = compactCanonical(cleanCode);
  if (compactCode) return compactCode;
  if (cleanName) return /^bay\b/i.test(cleanName) ? cleanName.replace(/^bay\b/i, "Bay") : `Bay ${cleanName}`;
  return cleanCode ? `Bay ${cleanCode}` : "";
}

/** Return the compact operator-facing bay label without exposing internal T-BAY prefixes. */
function bayLocationDisplayLabel(code = "", name = "") {
  const cleanCode = String(code || "").trim();
  const cleanName = String(name || "").trim();

  const compactCanonical = (value) => {
    let text = String(value || "").trim();
    if (!text) return "";
    text = text.replace(/^BAY\s+/i, "").trim();
    // Legacy bay display names can contain doubled separators (for example
    // 12--1). Normalize those for operator-facing labels without changing the
    // stored bay code or assignment identity.
    text = text.replace(/-{2,}/g, "-");
    const match = text.match(/^(?:[A-Z]+-)?BAY[-\s]*(\d+(?:-\d+)*)$/i)
      || text.match(/^(\d+(?:-\d+)*)$/);
    return match ? `Bay ${match[1]}` : "";
  };

  const compactName = compactCanonical(cleanName);
  if (compactName) return compactName;
  const compactCode = compactCanonical(cleanCode);
  if (compactCode) return compactCode;
  if (cleanName) return /^bay\b/i.test(cleanName) ? cleanName.replace(/^bay\b/i, "Bay") : `Bay ${cleanName}`;
  return cleanCode ? `Bay ${cleanCode}` : "";
}

/**
 * Purpose: Run the is truck rack workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function isTruckRack(rack) {
  return Boolean(rack && (rack.code === "T" || /^(?:R?T)\d+$/i.test(String(rack.code || "")) || /truck/i.test(rack.type || "")));
}

/**
 * Purpose: Run the next truck rack defaults workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function nextTruckRackDefaults() {
  const truckRacks = (state.racks || []).filter(isTruckRack);
  const usedNumbers = new Set(truckRacks.map((rack) => {
    const match = String(rack.code || "").toUpperCase().match(/^(?:R?T)(\d+)$/);
    return match ? Number(match[1]) : String(rack.code || "").toUpperCase() === "T" ? 1 : 0;
  }).filter(Boolean));
  let number = 2;
  while (usedNumbers.has(number)) number += 1;
  return {
    code: `RT${number}`,
    name: `Truck ${number}`,
    type: "Truck",
  };
}

/**
 * Purpose: Run the rack is received workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackIsReceived(rack) {
  return Boolean(rack?.received);
}

/**
 * Purpose: Run the rack status label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackStatusLabel(rack) {
  const status = String(rack?.status || "Open").trim().toLowerCase();
  const qty = Number(rack?.qty || 0);
  if (rackIsReceived(rack)) return "Received";
  if (status === "in transit") return "On the way";
  if (status === "closed" || status === "complete" || status === "completed") return "Complete";
  if (qty > 0) return "Incomplete";
  return "Empty";
}

/**
 * Purpose: Run the rack status class name workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackStatusClassName(rack) {
  if (rackIsReceived(rack)) return "received";
  const status = String(rack?.status || "Open").trim().toLowerCase();
  const qty = Number(rack?.qty || 0);
  if (status === "in transit") return "in-transit";
  if (status === "closed" || status === "complete" || status === "completed") return "complete";
  if (qty > 0) return "open";
  return "empty";
}

/**
 * Purpose: Run the rack option label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackOptionLabel(rack) {
  const name = rackOperatorDisplayName(rack);
  const qty = Math.max(Number(rack?.qty || 0), 0);
  const pieces = qty > 0 ? `${qty}PC${qty === 1 ? "" : "s"}` : "";
  return [name, pieces, rackStatusLabel(rack)].filter(Boolean).join(" | ");
}

/**
 * Purpose: Run the rack destination label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackDestinationLabel(value) {
  const text = String(value || "Indian Trail").trim();
  if (/^cpu$/i.test(text)) return "CPU";
  if (/^dtc$/i.test(text)) return "DTC";
  if (/green|gnv/i.test(text)) return "GNV";
  if (/indian|trail|^it$/i.test(text)) return "IT";
  return text || "IT";
}

/**
 * Purpose: Run the rack destination class workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackDestinationClass(value) {
  const raw = String(value || "").trim();
  if (!raw || /^(mixed|not set|unassigned)$/i.test(raw)) return "unassigned";
  const text = rackDestinationLabel(raw).toLowerCase();
  if (text.includes("cpu")) return "cpu";
  if (text.includes("green") || text === "gnv") return "greenville";
  if (text.includes("dtc")) return "dtc";
  return "indian-trail";
}

/** Resolve the route shown in an individual rack header from stable rack data. */
function rackResolvedDestination(rack) {
  const explicit = String(rack?.destination || "").trim();
  if (explicit) return explicit;

  const itemDestinations = [...new Set(
    (Array.isArray(rack?.items) ? rack.items : [])
      .map((item) => String(item?.route || item?.destination || "").trim())
      .filter(Boolean)
      .map((value) => rackDestinationLabel(value)),
  )];
  if (itemDestinations.length === 1) return itemDestinations[0];
  if (itemDestinations.length > 1) return "Mixed";

  // A populated rack with no explicit route is the legacy/default Indian Trail case.
  return Number(rack?.qty || 0) > 0 ? "Indian Trail" : "";
}

/**
 * Purpose: Run the rack visual class workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackVisualClass(rack) {
  if (rackIsReceived(rack)) return "is-received";
  const status = String(rack.status || "").toLowerCase();
  if (status === "in transit" || status === "on the way") return "is-in-transit";
  if (status === "closed" || status === "complete" || status === "completed") return "is-complete";
  if (Number(rack.qty || 0) > 0) return "has-items";
  return "is-empty";
}

/**
 * Purpose: Run the rack computed status workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackComputedStatus(rack) {
  return rackStatusClassName(rack);
}

/**
 * Purpose: Run the rack sort number workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackSortNumber(value) {
  const match = String(value || "").match(/\d+/);
  return match ? Number(match[0]) : 0;
}

/**
 * Purpose: Run the filtered sorted racks workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function filteredSortedRacks(racks = []) {
  const statusFilter = state.rackStatusFilter || "all";
  const sortMode = state.rackSort || "code-asc";

  const filtered = racks.filter((rack) => statusFilter === "all" || rackComputedStatus(rack) === statusFilter);

  return filtered.slice().sort((a, b) => {
    if (sortMode === "code-desc") {
      return String(b.code || "").localeCompare(String(a.code || ""), undefined, { numeric: true });
    }

    if (sortMode === "pieces-desc") {
      return Number(b.qty || 0) - Number(a.qty || 0) || String(a.code || "").localeCompare(String(b.code || ""), undefined, { numeric: true });
    }

    if (sortMode === "status") {
      const order = { open: 1, complete: 2, "in-transit": 3, empty: 4 };
      return (order[rackComputedStatus(a)] || 9) - (order[rackComputedStatus(b)] || 9) || String(a.code || "").localeCompare(String(b.code || ""), undefined, { numeric: true });
    }

    return String(a.code || "").localeCompare(String(b.code || ""), undefined, { numeric: true });
  });
}

/**
 * Purpose: Render the render racks page workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderRacksPage() {
  renderRackSelects();

  if (!els.rackGrid) return;

  const rackGroups = new Map();

  for (const rack of state.racks) {
    const label = rackGroupLabel(rack);

    if (!rackGroups.has(label)) {
      rackGroups.set(label, []);
    }

    rackGroups.get(label).push(rack);
  }

  const groups = [...rackGroups.entries()].sort(([a], [b]) => {
    if (a === "Truck") return 1;
    if (b === "Truck") return -1;

    const order = { Steel: 1, Wood: 2 };
    return (order[a] || 50) - (order[b] || 50) || a.localeCompare(b);
  });

  /**
   * Purpose: Render the render rack item workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const renderRackItem = (item, currentRackCode = "") => {
    const rackItemId = String(item.rackItemId || "");
    const rackGlassLabel = glassTypeLabel(item);
    const itemLabel = `${item.order}-${item.item}`;
    const sourceRack = state.racks.find((rack) => String(rack.code) === String(currentRackCode));
    const sourceState = String(sourceRack?.status || "").trim().toLowerCase();
    const blockedReason = sourceState === "closed"
      ? `${rackOptionLabel(sourceRack)} is Complete. Mark it Incomplete before moving or removing rack contents.`
      : sourceState === "in transit"
        ? `${rackOptionLabel(sourceRack)} is On the Way. Mark it Not On The Way or Returned before moving or clearing its contents.`
        : "";
    const moveBlockedAttrs = blockedReason
      ? `aria-disabled="true" data-blocked-reason="${escapeHtml(blockedReason)}" title="${escapeHtml(blockedReason)}"`
      : `title="Move piece"`;
    const clearBlockedAttrs = blockedReason
      ? `aria-disabled="true" data-blocked-reason="${escapeHtml(blockedReason)}" title="${escapeHtml(blockedReason)}"`
      : `title="Clear piece"`;
    return `
      <article class="rack-item glass-tone-card" ${glassToneAttributes(rackGlassLabel)}>
        <div>
          <strong>${escapeHtml(itemLabel)} <span>${escapeHtml(item.customer || "")}</span></strong>
          <small class="rack-item-job-v380">${escapeHtml(item.job || "No Job Nr.")}</small>
          <span class="rack-item-glass-v380 glass-tone-inline"><small>Glass Type</small><b>${escapeHtml(rackGlassLabel)}</b></span>
          <small class="rack-item-piece-meta-v380">${escapeHtml(item.dimensions || "Size not listed")} | Qty ${escapeHtml(item.rackQty || 1)}</small>
          <small class="rack-scan-time">${escapeHtml(item.deliveryDate ? formatNumericDeliveryDate(item.deliveryDate) : item.deliveryLabel || "")}${item.rackAddedAt ? ` | Scanned ${escapeHtml(formatDateTime(item.rackAddedAt))}` : ""}</small>
        </div>
        ${hasPermission("manage_racks") ? `
          <div class="rack-item-actions">
            <button
              type="button"
              class="icon-only icon-move rack-scope-move-button${blockedReason ? " is-blocked" : ""}"
              data-rack-move-item="${escapeHtml(rackItemId)}"
              data-source-rack="${escapeHtml(currentRackCode)}"
              data-rack-item-label="${escapeHtml(itemLabel)}"
              ${moveBlockedAttrs}
              aria-label="Move ${escapeHtml(itemLabel)}"
            ></button>
            <button
              type="button"
              class="icon-only icon-trash danger${blockedReason ? " is-blocked" : ""}"
              data-rack-clear-item="${escapeHtml(rackItemId)}"
              data-rack-clear-label="${escapeHtml(itemLabel)}"
              ${clearBlockedAttrs}
              aria-label="Clear ${escapeHtml(itemLabel)}"
            ></button>
          </div>` : ""}
      </article>`;
  };

  /**
   * Purpose: Render the render rack items workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const renderRackItems = (rack) => {
    const items = rack.items || [];

    if (!items.length) {
      return `<p class="admin-empty">No pieces assigned.</p>`;
    }

    const isTruck = isTruckRack(rack);
    const rackState = String(rack.status || "").toLowerCase();
    const isComplete = rackState === "closed" || rackState === "in transit";

    if (!isTruck) {
      return items.map((item) => renderRackItem(item, rack.code)).join("");
    }

    const byDate = new Map();

    for (const item of items) {
      const key = item.deliveryDate || "No delivery date";

      if (!byDate.has(key)) {
        byDate.set(key, []);
      }

      byDate.get(key).push(item);
    }

    return [...byDate.entries()]
      .sort(([a], [b]) => String(a).localeCompare(String(b)))
      .map(([date, dateItems]) => {
        const dateHasMoveOpen = dateItems.some((item) => String(item.rackItemId || "") === state.rackMoveItemId);
        const dateQty = dateItems.reduce((sum, item) => sum + Number(item.rackQty || 1), 0);

        return `
          <details class="rack-date-group" ${dateHasMoveOpen ? "open" : ""}>
            <summary>
              <strong>${escapeHtml(formatDisplayDate(date))}</strong>
              <span>${escapeHtml(dateQty)} pcs</span>
              ${isComplete ? `<button type="button" data-rack-print="${escapeHtml(rack.code)}" data-rack-print-date="${escapeHtml(date)}">Print This Date</button>` : ""}
            </summary>
            <div>${dateItems.map((item) => renderRackItem(item, rack.code)).join("")}</div>
          </details>
        `;
      })
      .join("");
  };

  /**
   * Purpose: Render the render rack workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const renderRack = (rack) => {
    const hasItems = Number(rack.qty || 0) > 0;
    const isTruck = rack.code === "T" || /truck/i.test(rack.type || "");
    const rackState = String(rack.status || "").toLowerCase();
    const isComplete = rackState === "closed";
    const isInTransit = rackState === "in transit";
    /**
     * Purpose: Run the rack has move open workflow for the browser application.
     * Effects: Updates visible dom state.
     * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
     */
    const rackHasMoveOpen = (rack.items || []).some((item) => String(item.rackItemId || "") === state.rackMoveItemId);
    const rackOpen = state.expandedRackCodes.has(rack.code) || rackHasMoveOpen;

    const rackBlockedReason = isComplete
      ? `${rackOptionLabel(rack)} is Complete. Mark it Incomplete before removing rack contents.`
      : isInTransit
        ? `${rackOptionLabel(rack)} is On the Way. Mark it Not On The Way or Returned before clearing its contents.`
        : "";
    const rackClearAttrs = rackBlockedReason
      ? `aria-disabled="true" data-blocked-reason="${escapeHtml(rackBlockedReason)}" title="${escapeHtml(rackBlockedReason)}"`
      : `title="Clear rack"`;

    const adminActions = hasPermission("manage_racks")
      ? `<span class="rack-summary-actions">
          <button
            type="button"
            class="icon-only icon-pencil"
            data-rack-edit="${escapeHtml(rack.code)}"
            title="Edit rack"
            aria-label="Edit ${escapeHtml(rack.code)}"
          ></button>
          <button
            type="button"
            class="icon-only icon-trash danger${rackBlockedReason ? " is-blocked" : ""}"
            data-rack-clear="${escapeHtml(rack.code)}"
            ${rackClearAttrs}
            aria-label="Clear ${escapeHtml(rack.code)}"
          ></button>
        </span>`
      : "";

    const printLabel = isTruck ? "Print Truck Packing List" : "Print Packing List";
    const printAction =
      hasItems && (isComplete || isInTransit)
        ? `<button type="button" class="rack-card-lifecycle-action-v342 is-print" data-rack-print="${escapeHtml(rack.code)}">${rackModalActionIconSvg("print")}<span>${printLabel}</span></button>`
        : "";

    return `
      <details class="rack-card ${rackVisualClass(rack)}" data-rack-code="${escapeHtml(rack.code)}" ${rackOpen ? "open" : ""}>
        <summary>
          <span class="rack-summary-main">
            <strong>${escapeHtml(rackOperatorDisplayName(rack))}</strong>
            <small>${escapeHtml(rackDisplayCode(rack))}</small>
          </span>
          <span class="rack-summary-qty">${escapeHtml(rack.qty || 0)} pcs</span>
          ${adminActions}
        </summary>
        <div class="rack-card-actions">
          ${
            hasItems
              ? `${printAction}${
                  isInTransit
                    ? rackIsReceived(rack)
                      ? `<button type="button" data-rack-return="${escapeHtml(rack.code)}">Mark Returned</button>`
                      : `<button type="button" data-rack-return="${escapeHtml(rack.code)}">Mark Returned</button><button type="button" data-rack-not-on-way="${escapeHtml(rack.code)}">Not On The Way</button>`
                    : isComplete
                      ? `<button type="button" class="rack-card-lifecycle-action-v342 is-uncomplete" data-rack-uncomplete="${escapeHtml(rack.code)}">${rackModalActionIconSvg("uncomplete")}<span>Uncomplete Rack</span></button>`
                      : `<button type="button" class="rack-card-lifecycle-action-v342 is-complete" data-rack-complete="${escapeHtml(rack.code)}">${rackModalActionIconSvg("complete")}<span>Complete Rack</span></button>`
                }`
              : ""
          }
        </div>
        <div class="rack-item-list">
          ${hasItems ? renderRackItems(rack) : `<p class="admin-empty">No pieces assigned.</p>`}
        </div>
      </details>
    `;
  };

  /**
   * Purpose: Render the render rack column actions workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const renderRackColumnActions = (label) => {
    if (!hasPermission("manage_racks")) return "";

    if (label === "Truck") {
      return `
        <div class="rack-column-actions">
          <button
            type="button"
            class="icon-only icon-pencil light"
            data-rack-edit="T"
            title="Edit Truck 1"
            aria-label="Edit Truck 1"
          ></button>
        </div>
      `;
    }

    return `
      <div class="rack-column-actions">
        <button
          type="button"
          class="icon-only icon-pencil light"
          data-rack-set-edit="${escapeHtml(label)}"
          title="Edit rack set"
          aria-label="Edit ${escapeHtml(label)} rack set"
        ></button>
      </div>
    `;
  };

  /**
   * Purpose: Render the render rack board card workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const renderRackBoardCard = (rack) => {
    const selected = state.selectedRackOverviewCode === rack.code;
    const statusText = rackStatusLabel(rack);
    const statusClass = rackStatusClassName(rack);
    const isTruck = rack.code === "T" || /truck/i.test(rack.type || "");
    const destinationPill = rack.destination
      ? `<small class="rack-destination-pill ${escapeHtml(rackDestinationClass(rack.destination))}">${escapeHtml(rackDestinationLabel(rack.destination))}</small>`
      : "";
    const rackIdentity = rackOperatorDisplayName(rack);
    const rackCodeLabel = rackDisplayCode(rack);

    return `
      <article
        class="rack-board-card ${rackVisualClass(rack)}"
        data-rack-select="${escapeHtml(rack.code)}"
        aria-current="${selected ? "true" : "false"}"
        tabindex="0"
        role="button"
        aria-label="View ${escapeHtml(rackIdentity)} details"
      >
        <div class="rack-board-state-v307 ${escapeHtml(statusClass)}"><i aria-hidden="true"></i><strong>${escapeHtml(statusText)}</strong></div>
        ${destinationPill}
        <div class="rack-board-card-main">
          <strong>${escapeHtml(rackIdentity)}</strong>
          <span>${escapeHtml(rackCodeLabel)}</span>
        </div>

        <div class="rack-board-card-meta">
          <b>${escapeHtml(rack.qty || 0)} pcs</b>
          ${rack.departedAt ? `<time class="rack-departure-time">Outbound ${escapeHtml(formatDateTime(rack.departedAt))}</time>` : ""}
          ${
            rackIsReceived(rack) && hasPermission("scan_racks")
              ? `<button type="button" class="rack-return-inline" data-rack-return="${escapeHtml(rack.code)}">Mark Returned</button>`
              : ""
          }
          ${
            hasPermission("manage_racks")
              ? (() => {
                  const onTheWay = String(rack.status || "").trim().toLowerCase() === "in transit";
                  const reason = onTheWay ? `${rackOptionLabel(rack)} is On the Way. Mark it Not On The Way or Returned before clearing its contents.` : "";
                  return `<button type="button" class="icon-only icon-reset${onTheWay ? " is-blocked" : ""}" data-rack-clear="${escapeHtml(rack.code)}" ${reason ? `aria-disabled="true" data-blocked-reason="${escapeHtml(reason)}" title="${escapeHtml(reason)}"` : `title="Clear rack"`} aria-label="Clear ${escapeHtml(rack.code)}"></button>`;
                })()
              : ""
          }
        </div>
      </article>
    `;
  };

  /**
   * Purpose: Render the render rack board group workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const renderRackBoardGroup = ([label, racks]) => {
    const totalQty = racks.reduce((sum, rack) => sum + Number(rack.qty || 0), 0);
    const activeCount = racks.filter((rack) => Number(rack.qty || 0) > 0).length;
    const completeCount = racks.filter((rack) => {
      const status = String(rack.status || "").trim().toLowerCase();
      return status === "closed" || status === "complete" || status === "completed";
    }).length;

    return `
      <section class="rack-board-group" data-rack-group="${escapeHtml(label)}">
        <header class="rack-board-group-header">
          <div>
            <h2>${escapeHtml(label)}</h2>
            <span>${escapeHtml(racks.length)} ${racks.length === 1 ? "rack" : "racks"} | ${escapeHtml(activeCount)} active | ${escapeHtml(completeCount)} complete</span>
          </div>

          <strong>${escapeHtml(totalQty)} pcs</strong>

          ${renderRackColumnActions(label)}
          ${
            hasPermission("manage_racks")
              ? `<button type="button" class="icon-only icon-reset light" data-rack-set-clear="${escapeHtml(label)}" title="Clear rack set" aria-label="Clear ${escapeHtml(label)} rack set"></button>`
              : ""
          }
        </header>

        <div class="rack-board-card-list">
          ${racks.map(renderRackBoardCard).join("") || `<p class="admin-empty">No ${escapeHtml(label.toLowerCase())} racks.</p>`}
        </div>
      </section>
    `;
  };

  const groupLabels = groups.map(([label]) => label);
  if (!state.selectedRackSetLabel || !groupLabels.includes(state.selectedRackSetLabel)) {
    state.selectedRackSetLabel = groupLabels.find((label) => label !== "Truck") || groupLabels[0] || "";
  }

  const selectedGroup = groups.find(([label]) => label === state.selectedRackSetLabel) || groups[0] || ["", []];
  const selectedGroupLabel = selectedGroup[0];
  const selectedGroupAllRacks = selectedGroup[1] || [];
  const selectedGroupRacks = filteredSortedRacks(selectedGroupAllRacks);

  if (!state.selectedRackOverviewCode || !selectedGroupAllRacks.some((rack) => rack.code === state.selectedRackOverviewCode)) {
    state.selectedRackOverviewCode =
      selectedGroupRacks.find((rack) => Number(rack.qty || 0) > 0)?.code ||
      selectedGroupRacks[0]?.code ||
      selectedGroupAllRacks.find((rack) => Number(rack.qty || 0) > 0)?.code ||
      selectedGroupAllRacks[0]?.code ||
      state.racks.find((rack) => Number(rack.qty || 0) > 0)?.code ||
      state.racks[0]?.code ||
      "";
  }


  /**
   * Purpose: Render the render rack set card workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const renderRackSetCard = ([label, racks]) => {
    const selected = label === selectedGroupLabel;
    const totalQty = racks.reduce((sum, rack) => sum + Number(rack.qty || 0), 0);
    const activeCount = racks.filter((rack) => Number(rack.qty || 0) > 0).length;
    const completeCount = racks.filter((rack) => {
      const status = String(rack.status || "").trim().toLowerCase();
      return status === "closed" || status === "complete" || status === "completed";
    }).length;
    const setClass = slugify(label || "rack-set") || "rack-set";
    const setHue = rackSetVisualHue(label);
    const setIcon = rackSetVisualIcon(label);
    const setColor = rackSetVisualColor(label);
    const setAccent = setColor || `hsl(${setHue} 48% 42%)`;
    const visualStyle = `--rack-set-hue:${setHue};--rack-set-accent:${setAccent}${setColor ? `;--rack-set-icon-color:${setColor}` : ""}`;

    return `
      <button type="button" class="rack-set-card ${escapeHtml(setClass)} ${selected ? "is-selected" : ""}" data-rack-set-select="${escapeHtml(label)}" data-rack-icon="${escapeHtml(setIcon)}" style="${escapeHtml(visualStyle)}">
        <span class="rack-set-icon" data-rack-icon="${escapeHtml(setIcon)}" aria-hidden="true"></span>
        <span class="rack-set-copy">
          <strong>${escapeHtml(label)}</strong>
          <small>${escapeHtml(racks.length)} rack${racks.length === 1 ? "" : "s"}</small>
          <b>${escapeHtml(totalQty)} piece${totalQty === 1 ? "" : "s"}</b>
        </span>
        <span class="rack-set-chevron">›</span>
        <span class="rack-set-meta">${escapeHtml(activeCount)} active | ${escapeHtml(completeCount)} complete</span>
        ${
          hasPermission("manage_racks")
            ? `<span class="rack-set-reset-inline icon-only icon-reset" data-rack-set-clear="${escapeHtml(label)}" title="Clear ${escapeHtml(label)}" aria-label="Clear ${escapeHtml(label)}"></span>`
            : ""
        }
      </button>
    `;
  };

  /**
   * Purpose: Render the render selected rack details workflow using the existing shared UI state.
   * Effects: Updates visible dom state, may update shared client state.
   * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
   */
  const selectedSetQty = selectedGroupAllRacks.reduce((sum, rack) => sum + Number(rack.qty || 0), 0);
  const visibleSetQty = selectedGroupRacks.reduce((sum, rack) => sum + Number(rack.qty || 0), 0);
  const selectedSetHue = rackSetVisualHue(selectedGroupLabel);
  const selectedSetColor = rackSetVisualColor(selectedGroupLabel);
  const selectedSetAccent = selectedSetColor || `hsl(${selectedSetHue} 48% 42%)`;
  const selectedSetIcon = rackSetVisualIcon(selectedGroupLabel);
  const selectedSetVisualStyle = `--selected-rack-set-hue:${selectedSetHue};--selected-rack-set-accent:${selectedSetAccent}${selectedSetColor ? `;--rack-set-icon-color:${selectedSetColor}` : ""}`;

  els.rackGrid.innerHTML = `
    <aside class="rack-sets-sidebar">
      <header>
        <h2>Rack Sets</h2>
        <span>All rack sets at a glance</span>
      </header>
      <div class="rack-set-list">
        ${groups.map(renderRackSetCard).join("") || `<div class="admin-empty">No rack sets found.</div>`}
      </div>
    </aside>

    <section class="rack-center-panel" data-rack-icon="${escapeHtml(selectedSetIcon)}" style="${escapeHtml(selectedSetVisualStyle)}">
      <div class="rack-center-heading">
        <div>
          <h2>${escapeHtml(selectedGroupLabel || "Racks")}</h2>
          <span>${escapeHtml(selectedGroupAllRacks.length)} rack${selectedGroupAllRacks.length === 1 ? "" : "s"} | ${escapeHtml(selectedSetQty)} pieces${selectedGroupRacks.length !== selectedGroupAllRacks.length ? ` | Showing ${escapeHtml(selectedGroupRacks.length)} racks / ${escapeHtml(visibleSetQty)} pieces` : ""}</span>
        </div>
        <div class="rack-center-controls">
          <label class="rack-filter-control">
            <span>Status</span>
            <select data-rack-status-filter>
              <option value="all" ${state.rackStatusFilter === "all" ? "selected" : ""}>All</option>
              <option value="open" ${state.rackStatusFilter === "open" ? "selected" : ""}>Incomplete</option>
              <option value="complete" ${state.rackStatusFilter === "complete" ? "selected" : ""}>Complete</option>
              <option value="in-transit" ${state.rackStatusFilter === "in-transit" ? "selected" : ""}>On the way</option>
              <option value="received" ${state.rackStatusFilter === "received" ? "selected" : ""}>Received</option>
              <option value="empty" ${state.rackStatusFilter === "empty" ? "selected" : ""}>Empty</option>
            </select>
          </label>
          <label class="rack-filter-control">
            <span>Sort</span>
            <select data-rack-sort>
              <option value="code-asc" ${state.rackSort === "code-asc" ? "selected" : ""}>Rack ID (A-Z)</option>
              <option value="code-desc" ${state.rackSort === "code-desc" ? "selected" : ""}>Rack ID (Z-A)</option>
              <option value="pieces-desc" ${state.rackSort === "pieces-desc" ? "selected" : ""}>Pieces (High-Low)</option>
              <option value="status" ${state.rackSort === "status" ? "selected" : ""}>Status</option>
            </select>
          </label>
        </div>
      </div>

      <div class="rack-overview-card-grid">
        ${selectedGroupRacks.map(renderRackBoardCard).join("") || `<p class="admin-empty">No racks in this set.</p>`}
      </div>
    </section>

  `;
}

/**
 * Purpose: Open the show rack destination override dialog workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function showRackDestinationOverrideDialog(payload) {
  const mismatch = payload?.destinationMismatch || {};
  const rackCode = mismatch.rackCode || "selected rack";
  const rackDestination = mismatch.rackDestination || "its current destination";
  const itemDestination = mismatch.itemDestination || "another destination";
  const itemLabel = mismatch.order && mismatch.item ? `${mismatch.order}-${mismatch.item}` : "this item";
  const spanish = state.language === "es";

  return confirmWebAppAction({
    title: spanish ? "Destino incorrecto para este rack" : "Wrong destination for this rack",
    message: spanish
      ? `El rack <strong>${escapeHtml(rackCode)}</strong> está asignado a <strong>${escapeHtml(rackDestination)}</strong>, pero el artículo <strong>${escapeHtml(itemLabel)}</strong> tiene la ruta <strong>${escapeHtml(itemDestination)}</strong>. ¿Desea omitir la verificación y agregarlo de todos modos?`
      : `Rack <strong>${escapeHtml(rackCode)}</strong> is assigned to <strong>${escapeHtml(rackDestination)}</strong>, but item <strong>${escapeHtml(itemLabel)}</strong> is routed to <strong>${escapeHtml(itemDestination)}</strong>. Would you like to override the destination check and add it anyway?`,
    details: mismatch.customer
      ? `${spanish ? "Cliente" : "Customer"}: ${mismatch.customer}`
      : spanish
        ? "La omisión mantendrá el destino actual del rack para este artículo."
        : "The override will keep the rack's current destination for this item.",
    confirmLabel: spanish ? "Sí, omitir destino" : "Yes, override destination",
    cancelLabel: spanish ? "No, cancelar escaneo" : "No, cancel scan",
    danger: false,
  });
}

/**
 * Purpose: Process the submit rack scan workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function submitRackScan(options = {}) {
  const barcode = els.rackScanInput?.value || "";
  const rackCode = els.rackSelect?.value || state.selectedRackCode;
  const listId = els.rackListSelect?.value || state.rackScanListId;
  if (!barcode.trim() || !rackCode || !listId) {
    if (els.rackScanStatus) els.rackScanStatus.textContent = "Choose a staging list and rack, then scan a piece.";
    return;
  }
  const payload = await fetchJson("/api/racks/scan", {
    method: "POST",
    body: JSON.stringify({
      listId,
      rackCode,
      barcode,
      destinationOverride: Boolean(options.destinationOverride),
      ...requestContext(),
    }),
  });
  if (payload.destinationOverrideRequired) {
    const approved = await showRackDestinationOverrideDialog(payload);
    if (approved) return submitRackScan({ ...options, destinationOverride: true });
    if (els.rackScanStatus) els.rackScanStatus.textContent = "Rack scan cancelled.";
    els.rackScanInput?.focus();
    return;
  }
  state.racks = payload.racks || state.racks;
  state.rackSummary = payload.summary || state.rackSummary;
  if (els.rackScanStatus) els.rackScanStatus.textContent = payload.message || "Rack scan recorded.";
  if (els.rackScanInput) els.rackScanInput.value = "";
  renderRacksPage();
  if (listId === state.activeListId) await activateList(listId, false);
  els.rackScanInput?.focus();
}

/**
 * Purpose: Run the choose rack destination workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function chooseRackDestination(rack) {
  const currentDestination = rackDestinationLabel(rack?.destination || "Indian Trail");

  return new Promise((resolve) => {
    document.querySelector(".rack-destination-backdrop")?.remove();

    const shell = document.createElement("div");
    shell.className = "rack-destination-backdrop";
    shell.innerHTML = `
      <section class="rack-destination-dialog" role="dialog" aria-modal="true" aria-labelledby="rackDestinationTitle">
        <button class="modal-close-x gui-close-button rack-destination-close" type="button" data-rack-destination-cancel aria-label="Close">&times;</button>
        <div class="rack-destination-copy">
          <small>Complete rack</small>
          <h2 id="rackDestinationTitle">Where is ${escapeHtml(rack?.code || "this rack")} going?</h2>
          <p>Select the destination before printing the packing list. Indian Trail is the default.</p>
        </div>
        <label class="rack-destination-field">
          <span>Destination</span>
          <select id="rackDestinationSelect">
            ${["Indian Trail", "CPU", "Greenville", "DTC"].map((value) => `<option value="${escapeHtml(value)}" ${rackDestinationLabel(value) === currentDestination ? "selected" : ""}>${escapeHtml(rackDestinationLabel(value))}</option>`).join("")}
          </select>
        </label>
        <div class="rack-destination-actions">
          <button type="button" class="app-cancel-action-v343" data-rack-destination-cancel><span class="app-cancel-icon-v343" aria-hidden="true"></span><span>Cancel</span></button>
          <button type="button" data-rack-destination-confirm>Complete Rack</button>
        </div>
      </section>
    `;

    /**
     * Purpose: Close the close workflow using the existing shared UI state.
     * Effects: Updates visible dom state.
     * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
     */
    const close = (value = "") => {
      shell.remove();
      updateModalScrollLock();
      resolve(value);
    };

    shell.addEventListener("click", (event) => {
      if (event.target === shell || event.target.closest("[data-rack-destination-cancel]")) {
        close("");
        return;
      }
      if (event.target.closest("[data-rack-destination-confirm]")) {
        close(shell.querySelector("#rackDestinationSelect")?.value || "Indian Trail");
      }
    });

    document.body.appendChild(shell);
    document.body.classList.add("modal-scroll-locked");
    shell.querySelector("#rackDestinationSelect")?.focus();
  });
}

