/**
 * Purpose: Run the print selected rack packing slip workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function printSelectedRackPackingSlip(rackCode = state.selectedRackCode, deliveryDateOverride = "") {
  const selectedCode = rackCodeForScan(rackCode);
  if (!selectedCode) return;
  const rack = state.racks.find((item) => item.code === selectedCode);
  if (!rack || !["closed", "in transit"].includes(String(rack.status || "").toLowerCase())) {
    showFloatingNotice("Complete this rack before printing its packing list.", "notice");
    return;
  }
  // A rack-details print represents the rack's complete live contents. Do not
  // silently filter truck racks by whichever Scan-page date happens to be active.
  // Explicit date buttons still pass deliveryDateOverride for a one-date print.
  const dateParam = String(deliveryDateOverride || "").trim();
  if (state.backend) {
    try {
      await fetchJson("/api/racks/packing-history", {
        method: "POST",
        body: JSON.stringify({ rackCode: selectedCode, deliveryDate: dateParam }),
      });
    } catch (error) {
      console.warn("Packing-list history snapshot could not be saved", error);
    }
  }
  launchManagedPrint(rackPackingListUrl(selectedCode, dateParam));
}

/**
 * Purpose: Run the save rack definition workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function saveRackDefinition() {
  const validation = rackFormDraftValidation();
  if (!validation.ok) throw new Error(validation.message);
  const rackCode = rackDraftCode(document.getElementById("rackModalCode")?.value || "");
  const payload = await fetchJson("/api/racks", {
    method: "POST",
    body: JSON.stringify({
      oldRackCode: document.getElementById("rackModalOldCode")?.value || "",
      rackCode,
      name: document.getElementById("rackModalName")?.value || "",
      type: document.getElementById("rackModalType")?.value || "Steel",
    }),
  });
  state.racks = payload.racks || [];
  state.rackSummary = payload.summary || null;
  state.rackManagerSelectedCode = rackCode;
  renderRacksPage();
  renderScanRackTools();
  returnToRackManager();
  showSaveConfirmation(`Rack ${rackCode || "definition"} was saved.`);
}

/**
 * Purpose: Run the selected rack manager rack workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function selectedRackManagerRack(code = state.rackManagerSelectedCode) {
  return state.racks.find((rack) => rack.code === code) || state.racks[0] || null;
}

/**
 * Purpose: Run the populate rack manager quick edit workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function populateRackManagerQuickEdit(code = "") {
  const select = document.getElementById("rackManagerQuickRackSelect");
  const nameInput = document.getElementById("rackManagerQuickName");
  const typeInput = document.getElementById("rackManagerQuickType");
  const rack = selectedRackManagerRack(code || select?.value || state.rackManagerSelectedCode);

  if (!rack) return;

  state.rackManagerSelectedCode = rack.code || "";
  if (select) select.value = rack.code || "";
  if (nameInput) nameInput.value = rack.name || rack.type || rack.code || "";
  if (typeInput) typeInput.value = rack.type || "Steel";
}

/**
 * Purpose: Run the save rack quick edit workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function saveRackQuickEdit() {
  const code = document.getElementById("rackManagerQuickRackSelect")?.value || state.rackManagerSelectedCode || "";
  if (!code) return;

  const payload = await fetchJson("/api/racks", {
    method: "POST",
    body: JSON.stringify({
      rackCode: code,
      name: document.getElementById("rackManagerQuickName")?.value || code,
      type: document.getElementById("rackManagerQuickType")?.value || "Steel",
    }),
  });

  state.racks = payload.racks || [];
  state.rackSummary = payload.summary || null;
  state.rackManagerSelectedCode = code;
  renderRacksPage();
  renderScanRackTools();

  if (!els.adminModal?.hidden && els.adminModalBody?.querySelector(".rack-manager-shell")) {
    els.adminModalBody.innerHTML = adminModalContent("racks");
  }

  showSaveConfirmation(`Rack ${code} was saved.`);
}

/**
 * Purpose: Remove the delete rack definition workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function deleteRackDefinition(rackCode = state.selectedRackCode) {
  if (!rackCode) return;
  const confirmed = await confirmWebAppAction({
    title: "Delete rack?",
    message: `Delete empty rack <strong>${escapeHtml(rackCode)}</strong>?`,
    details: "Rack history stays in scan and audit history. Only the empty rack definition is removed from active use.",
    confirmLabel: "Delete Rack",
  });
  if (!confirmed) return;

  const payload = await fetchJson("/api/racks/delete", { method: "POST", body: JSON.stringify({ rackCode }) });
  state.racks = payload.racks || [];
  state.rackSummary = payload.summary || null;
  if (state.selectedRackOverviewCode === rackCode) state.selectedRackOverviewCode = "";
  if (state.rackManagerSelectedCode === rackCode) state.rackManagerSelectedCode = "";
  if (state.rackManagerEditingRackCode === rackCode) state.rackManagerEditingRackCode = "";
  renderRacksPage();
  renderScanRackTools();

  if (els.adminModal?.dataset.kind === "rackForm") {
    returnToRackManager();
  } else if (!els.adminModal?.hidden && els.adminModalBody?.querySelector(".rack-manager-shell")) {
    els.adminModalBody.innerHTML = adminModalContent("racks");
  }

  showSaveConfirmation(`Rack ${rackCode} was deleted.`);
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Create the create rack set workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function createRackSet() {
  const validation = rackSetDraftValidation();
  if (!validation.ok) throw new Error(validation.message);
  const prefix = String(document.getElementById("rackSetModalPrefix")?.value || "")
    .replace(/[^A-Za-z0-9]/g, "")
    .toUpperCase()
    .slice(0, 8);
  const nameRoot = String(document.getElementById("rackSetModalName")?.value || prefix || "Rack").trim();
  const payload = await fetchJson("/api/racks/create-set", {
    method: "POST",
    body: JSON.stringify({
      prefix,
      nameRoot,
      type: nameRoot,
      count: document.getElementById("rackSetModalCount")?.value || 10,
      start: document.getElementById("rackSetModalStart")?.value || 1,
      setIcon: document.getElementById("rackSetModalIcon")?.value || "rack",
      setColor: document.getElementById("rackSetModalColor")?.value || nextRackSetVisualColor(),
    }),
  });
  state.racks = payload.racks || [];
  state.rackSummary = payload.summary || null;
  renderRacksPage();
  renderScanRackTools();
  returnToRackManager();
  showSaveConfirmation(`Created ${payload.created?.length || 0} rack(s).`);
}

/**
 * Purpose: Open the open rack form workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function openRackForm(rackCode = "", defaults = {}) {
  const existingRack = state.racks.find((item) => item.code === rackCode);
  const rack = existingRack ? { ...existingRack, oldCode: existingRack.code } : { ...defaults };
  state.rackModal = { rack };
  openAdminModal("rackForm", { title: existingRack ? "Edit Rack" : "Add Individual Rack" });
  syncRackFormPreview();
}

/**
 * Purpose: Open the open rack set form workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function openRackSetForm(label = "") {
  if (label) {
    openAdminModal("racks");
    openRackManagerSetEdit(label);
    return;
  }
  const racks = state.racks.filter((rack) => (rack.code === "T" || /truck/i.test(rack.type || "") ? "Truck" : rack.type || "Racks") === label);
  const explicit = rackSetExplicitVisual(label);
  state.rackModal = {
    set: {
      name: label && label !== "Truck" ? label : "",
      prefix: "",
      count: racks.length || 10,
      start: 1,
      icon: explicit.icon || (label ? rackSetVisualIcon(label) : "rack"),
      color: explicit.color || (label ? "#176d72" : nextRackSetVisualColor()),
    },
  };
  openAdminModal("rackSetForm", { title: label ? "Rack Set" : "Add Rack Set" });
  syncRackSetFormPreview();
}

/**
 * Purpose: Remove the delete rack set workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function deleteRackSet(label) {
  const racks = state.racks.filter((rack) => rackGroupLabel(rack) === label && rack.code !== "T");
  if (!racks.length) return;

  const occupied = racks.filter((rack) => Number(rack.qty || 0) > 0);
  if (occupied.length) {
    showFloatingNotice(
      `${label} cannot be deleted until ${occupied.length} rack${occupied.length === 1 ? " is" : "s are"} empty.`,
      "notice",
    );
    return;
  }

  const confirmed = await confirmWebAppAction({
    title: "Delete rack set?",
    message: `Delete <strong>${escapeHtml(label)}</strong> and its <strong>${escapeHtml(racks.length)}</strong> empty rack${racks.length === 1 ? "" : "s"}?`,
    details: "Historical rack scans remain available. The active rack definitions and this set's visual identity are removed.",
    confirmLabel: "Delete Rack Set",
  });
  if (!confirmed) return;

  const payload = await fetchJson("/api/racks/delete", {
    method: "POST",
    body: JSON.stringify({ rackCodes: racks.map((rack) => rack.code) }),
  });

  state.racks = payload.racks || [];
  state.rackSummary = payload.summary || null;
  state.rackManagerEditingSetLabel = "";
  if (state.selectedRackSetLabel === label) state.selectedRackSetLabel = "";
  renderRacksPage();
  renderScanRackTools();
  if (!els.adminModal?.hidden && els.adminModalBody?.querySelector(".rack-manager-shell")) {
    els.adminModalBody.innerHTML = adminModalContent("racks");
  }
  showSaveConfirmation(`${label} rack set was deleted.`);
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Render the render mobile cards workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderMobileItemCardV477(item = {}) {
  const status = itemStatus(item);
  const selected = item.id === state.selectedId;
  const scanned = Math.max(Number(item.scanned || 0), 0);
  const quantity = Math.max(Number(item.qty || 0), 0);
  const scanStateLabel = status === "complete" ? "Complete" : status === "partial" ? "Partially scanned" : "Not scanned";
  const route = routeLabel(item) || "Indian Trail";
  const glassLabel = glassTypeLabel(item);
  const movedOutByPriorityDate = priorityDateMovedOutV441(item);
  const mobilePriorityMeta = priorityBannerMetaV441(item);
  const mobilePriorityRibbon = mobilePriorityMeta
    ? `<div class="mobile-priority-ribbon-v441 is-${escapeHtml(mobilePriorityMeta.kind || "rush")}"><strong>${escapeHtml(mobilePriorityMeta.label || "Priority")}</strong><span>${escapeHtml(String(mobilePriorityMeta.reason || "Priority handling").replace(/^\s*(?:Rush|Remake|SDI)\s*-\s*/i, ""))}</span>${movedOutByPriorityDate ? `<em>Moved to ${escapeHtml(formatDisplayDate(item.priorityDeliveryDate))}</em>` : ""}</div>`
    : "";
  const identity = movedOutByPriorityDate
    ? `aria-disabled="true" data-priority-moved-source="${escapeHtml(item.id || "")}"`
    : `data-id="${escapeHtml(item.id)}" data-order-v470="${escapeHtml(item.order || "")}" data-item-v477="${escapeHtml(item.item || "")}"`;
  return `
    ${mobilePriorityRibbon}
    <article class="mobile-list-card glass-tone-card ${selected ? "is-selected" : ""} is-${escapeHtml(status)} ${movedOutByPriorityDate ? "is-priority-date-moved-source-v441" : ""}" ${glassToneAttributes(glassLabel)} ${identity} data-scan-state="${escapeHtml(status)}">
      <header class="mobile-card-heading">
        <span class="mobile-card-job"><small>Job Nr.</small><b>${escapeHtml(item.job || item.product || "Not provided")}</b></span>
        <span class="mobile-card-scan-state ${escapeHtml(status)}" aria-label="${escapeHtml(`${scanStateLabel}: ${scanned} of ${quantity} pieces scanned`)}">
          <i aria-hidden="true"></i><b>${escapeHtml(scanned)}/${escapeHtml(quantity)}</b><small>${escapeHtml(scanStateLabel)}</small>
        </span>
      </header>
      <div class="mobile-card-fields">
        <span><small>Order Nr.</small><b>${escapeHtml(item.order)}</b></span>
        <span><small>Item Nr.</small><b>${escapeHtml(item.item)}</b></span>
        <span><small>Quantity</small><b>${escapeHtml(quantity)}</b></span>
        <span class="dims"><small>Dimensions</small><b>${escapeHtml(item.dimensions || "-")}</b></span>
      </div>
      <footer class="mobile-card-footer">
        <span class="card-customer">${escapeHtml(item.customer || "No customer")}</span>
        <span class="card-route">${escapeHtml(route)}</span>
      </footer>
    </article>`;
}

function renderMobileCards() {
  if (!els.mobileListCards) return;
  const { pageRows } = getPagedItems();
  const groups = groupScanItemsByOrderV477(pageRows);
  els.mobileListCards.innerHTML = `
    <div class="section-heading">
      <h3>Delivery List</h3>
      <span>${state.items.length} items</span>
    </div>
    ${groups.map((group) => `<section class="mobile-order-group-v477">${scanOrderGroupHeaderV477(group, { mobile: true })}${group.items.map(renderMobileItemCardV477).join("")}</section>`).join("")}
  `;
  syncScanFilterButtons();
}

/**
 * Purpose: Process the scan entry event label workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function scanEntryEventLabel(entry) {
  const type = String(entry?.eventType || "").toLowerCase();
  if (type === "manual_scan") return "Manual scan";
  if (type === "duplicate") return "Duplicate";
  if (type === "import") return "Import";
  if (type === "update") return "Update";
  if (type === "undo") return "Undo";
  if (type === "redo") return "Redo";
  if (type === "rack_move") return "Rack moved";
  if (type === "error") return "Scan error";
  if (type === "notice") return "Notice";
  return type === "scan" ? "Scan" : String(entry?.message || "Activity");
}

/**
 * Purpose: Process the scan entry delivery date hint workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function scanEntryDeliveryDateHint(entry) {
  const combined = `${entry?.message || ""} ${entry?.reason || ""}`.replace(/\s+/g, " ").trim();
  const dated = combined.match(/check (?:the )?delivery list date\s+([^.;]+(?:,\s*[^.;]+)*)/i);
  if (dated?.[1] && !/for the scanned item/i.test(dated[1])) return dated[1].trim();

  // Older saved scan errors included every matching stage after the date.
  // Pull only the date so old history rows follow the cleaner v043 wording too.
  const legacyDate = combined.match(/\b(\d{1,2}\/\d{1,2}\/\d{4}|\d{4}-\d{2}-\d{2})\b/);
  if (!legacyDate?.[1]) return "";
  return /^\d{4}-\d{2}-\d{2}$/.test(legacyDate[1])
    ? formatDisplayDate(legacyDate[1])
    : legacyDate[1];
}

/**
 * Purpose: Process the scan entry compact message workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function scanEntryCompactMessage(entry) {
  if (!entry) return "";
  const type = String(entry.eventType || "").toLowerCase();
  const message = String(entry.message || "").trim();
  const reason = String(entry.reason || "").trim();
  if (type === "error") {
    if (/not on (the )?(selected |active )?delivery list/i.test(`${message} ${reason}`)) {
      const deliveryDate = scanEntryDeliveryDateHint(entry);
      return deliveryDate
        ? `Check delivery list date ${deliveryDate}`
        : "Check the delivery list date for this item";
    }
    if (/multiple|ambiguous/i.test(`${message} ${reason}`)) {
      return "More than one item matched - use the full barcode";
    }
    return message || "Scan needs review";
  }
  if (type === "import") return "Delivery list imported successfully";
  if (type === "update") return "Delivery list updated successfully";
  if (type === "rack_move") return reason || message || "Rack location changed";
  if (type === "duplicate") return message || "Item already complete";
  return [scanEntryIsManual(entry) ? "Manual Scan" : "", message].filter(Boolean).join(" - ") || reason;
}

/**
 * Purpose: Process the scan entry full detail workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function scanEntryFullDetail(entry) {
  const eventType = String(entry?.eventType || "").toLowerCase();
  const moveFrom = String(entry?.rackMoveFrom || "").trim();
  const moveTo = String(entry?.rackMoveTo || "").trim();
  if (eventType === "rack_move" && (moveFrom || moveTo)) {
    return `<strong>Rack moved</strong><span>${escapeHtml(moveFrom || "No rack")} → ${escapeHtml(moveTo || "No rack")}</span>`;
  }
  const message = String(entry?.message || "").trim();
  const reason = String(entry?.reason || "").trim();
  const raw = String(entry?.raw || "").trim();
  const canonical = String(entry?.barcode || "").trim();
  const wrongList = /not on (the )?(selected |active )?delivery list/i.test(`${message} ${reason}`);
  const deliveryDate = wrongList ? scanEntryDeliveryDateHint(entry) : "";
  const displayReason = wrongList
    ? deliveryDate
      ? `Check delivery list date ${deliveryDate}.`
      : "Check the delivery list date for this item."
    : reason;
  const parts = [];
  if (message) parts.push(`<strong>${escapeHtml(message)}</strong>`);
  if (displayReason && displayReason !== message) parts.push(`<span>${escapeHtml(displayReason)}</span>`);
  if (raw && canonical && raw !== canonical) parts.push(`<small>Scanned: ${escapeHtml(raw)} | Resolved: ${escapeHtml(canonical)}</small>`);
  return parts.join("");
}

/**
 * Purpose: Process the scan entry row class workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function scanEntryRowClass(entry) {
  const type = String(entry?.eventType || "").toLowerCase().replace(/[^a-z0-9_-]/g, "-");
  return `${entry?.ok ? "ok" : "error"} event-${type || "activity"} ${scanEntryIsManual(entry) ? "manual" : ""}`.trim();
}

/**
 * Purpose: Update the set last scan workflow using the existing shared UI state.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function scanEntryDisplayItem(entry) {
  const eventItem = entry?.item;
  if (!eventItem) return null;
  const currentItem = (state.items || []).find((item) => String(item.id || "") === String(eventItem.id || ""));
  if (!currentItem) return eventItem;
  return { ...eventItem, ...currentItem };
}

function scanQuantityRemaining(item) {
  const qty = Math.max(Number(item?.qty || 0), 0);
  const scanned = Math.min(Math.max(Number(item?.scanned || 0), 0), qty);
  return Math.max(qty - scanned, 0);
}

function scanQuantityDeliveryDateIsActive(deliveryDate = state.meta?.deliveryDate || "") {
  const cleanDate = String(deliveryDate || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(cleanDate)) return false;
  return cleanDate >= printCalendarDateKey(new Date());
}

function canIncreaseScanQuantity(entry, item) {
  const type = String(entry?.eventType || "").toLowerCase();
  return Boolean(
    entry?.ok &&
    item &&
    Number(item.qty || 0) > 1 &&
    scanQuantityRemaining(item) > 0 &&
    scanQuantityDeliveryDateIsActive(item.deliveryDate || state.meta?.deliveryDate) &&
    ["scan", "manual_scan"].includes(type)
  );
}

function scanQuantityBoostMarkup(entry, item, context = {}) {
  if (!canIncreaseScanQuantity(entry, item)) return "";
  const remaining = scanQuantityRemaining(item);
  const barcode = String(entry?.barcode || entry?.raw || "").trim();
  if (!barcode) return "";
  return `
    <div class="scan-quantity-boost-v328" data-scan-quantity-boost
      data-scan-quantity-barcode="${escapeHtml(barcode)}"
      data-scan-quantity-manual="${scanEntryIsManual(entry) ? "true" : "false"}"
      data-scan-quantity-remaining="${escapeHtml(remaining)}"
      data-scan-quantity-rack="${escapeHtml(context.rackCode || item.rackCode || "")}"
      data-scan-quantity-bay="${escapeHtml(context.bayCode || item.bayCode || "")}">
      <div class="scan-quantity-boost-copy-v328"><small>Multiple pieces?</small><strong>${escapeHtml(remaining)} remaining</strong></div>
      <label><span>Additional Qty</span><input type="number" min="1" max="${escapeHtml(remaining)}" step="1" value="1" data-scan-quantity-input></label>
      <button type="button" class="app-primary-button" data-scan-quantity-add>Add Qty</button>
      <button type="button" class="app-primary-button" data-scan-quantity-all>Scan Remaining</button>
    </div>`;
}

async function submitScanQuantityBoost(control, allRemaining = false) {
  if (!control) return;
  const barcode = String(control.dataset.scanQuantityBarcode || "").trim();
  const remaining = Math.max(Number(control.dataset.scanQuantityRemaining || 0), 0);
  const input = control.querySelector("[data-scan-quantity-input]");
  const requested = allRemaining ? remaining : Number(input?.value || 1);
  const scanQty = Math.min(Math.max(Math.trunc(requested || 1), 1), remaining);
  if (!barcode || !remaining || !scanQty) return;
  control.querySelectorAll("button, input").forEach((node) => { node.disabled = true; });
  try {
    await processScan(barcode, {
      isManual: control.dataset.scanQuantityManual === "true",
      scanQty,
      ...(control.dataset.scanQuantityRack ? { rackCode: control.dataset.scanQuantityRack } : {}),
      ...(control.dataset.scanQuantityBay ? { bayCode: control.dataset.scanQuantityBay } : {}),
    });
    if (els.adminModal?.dataset.kind === "recentScans" && !els.adminModal.hidden && els.adminModalBody) {
      els.adminModalBody.innerHTML = recentScansModalHtml();
      applyLanguageToRoot(els.adminModalBody);
    }
  } catch (error) {
    control.querySelectorAll("button, input").forEach((node) => { node.disabled = false; });
    showScanFailureConfirmation(error.message, {
      stageLabel: stageLabel(state.meta || {}) || state.meta?.stage || "Scan page",
      rawScan: barcode,
      title: "Quantity update not accepted",
    });
  }
}

function setLastScan(entry) {
  if (!entry || !els.lastCard) return;
  state.lastScan = entry;
  els.lastCard.classList.remove("ok", "error");
  els.lastCard.classList.add(entry.ok ? "ok" : "error");
  if (els.lastScanTime) els.lastScanTime.textContent = entry.ok ? "Just now" : entry.eventType === "duplicate" ? "Notice" : "Needs review";
  const manualPrefix = scanEntryIsManual(entry) ? "Manual Scan · " : "";
  const compactMessage = scanEntryCompactMessage(entry);
  const displayItem = scanEntryDisplayItem(entry);
  if (els.lastJob) els.lastJob.textContent = !entry.ok || !displayItem
    ? compactMessage
    : `${manualPrefix}Job Nr. ${displayItem.job || "-"}`;
  if (els.lastBay) {
    const location = displayItem ? scanLocationPresentation(displayItem) : { label: "", kind: "", historical: false };
    els.lastBay.textContent = location.label || "-";
    const locationCard = els.lastBay.closest(".last-bay-location-v321");
    if (locationCard) {
      locationCard.hidden = !location.label;
      locationCard.classList.toggle("is-history", Boolean(location.historical));
      locationCard.classList.toggle("is-bay", location.kind === "bay");
      locationCard.classList.toggle("is-rack", location.kind === "rack" || location.kind === "truck");
      const locationRackCode = location.historical
        ? String(displayItem?.lastRackCode || "").trim()
        : String(displayItem?.rackCode || "").trim();
      const locationRack = (location.kind === "rack" || location.kind === "truck") ? rackForCode(locationRackCode) : null;
      const locationRackComplete = Boolean(locationRack && rackStatusClassName(locationRack) === "complete" && !location.historical);
      const fallbackRackSet = location.kind === "truck"
        ? "Truck"
        : String(location.historical ? (displayItem?.lastRackType || "") : (displayItem?.rackType || "")).trim();
      const locationRackColor = locationRack
        ? (locationRackComplete ? "#2fa84f" : rackSetDisplayColor(rackGroupLabel(locationRack)))
        : (fallbackRackSet ? rackSetDisplayColor(fallbackRackSet) : "");
      locationCard.classList.toggle("has-rack-color-v355", Boolean(locationRackColor));
      if (locationRackColor) locationCard.style.setProperty("--last-scan-location-accent", locationRackColor);
      else locationCard.style.removeProperty("--last-scan-location-accent");
      locationCard.title = location.title || location.label || "";
    }
  }
  if (els.lastOrder) els.lastOrder.textContent = displayItem ? displayItem.order : "-";
  if (els.lastItem) els.lastItem.textContent = displayItem ? displayItem.item : "-";
  if (els.lastQty) els.lastQty.textContent = displayItem ? `${Number(displayItem.scanned || 0)} / ${Number(displayItem.qty || 0)}` : "-";
  if (els.lastDims) els.lastDims.textContent = displayItem ? displayItem.dimensions : "-";
  if (els.lastCustomer) els.lastCustomer.textContent = displayItem ? displayItem.customer : "-";
}

