/**
 * Purpose: Update the apply permission UI workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */


/**
 * Return one representative list per delivery date for the date-selector review marker.
 * Airport Rd Staging owns the broad order-update scope when available; otherwise the
 * first accessible stage is used. The Stage selector is refreshed separately for the
 * active delivery date so route-specific review markers remain independent.
 */
function pendingUpdateMarkerLists(lists = state.lists) {
  const byDate = new Map();
  (Array.isArray(lists) ? lists : []).forEach((list) => {
    const deliveryDate = String(list?.deliveryDate || "").trim();
    if (!deliveryDate) return;
    if (!byDate.has(deliveryDate)) byDate.set(deliveryDate, []);
    byDate.get(deliveryDate).push(list);
  });
  return [...byDate.values()].map((dateLists) =>
    dateLists.find((list) => stagePresetFromValuesV445(list?.stage || "", list?.scanner || "", list?.stagePreset || "") === "airport_staging")
    || dateLists.find((list) => stagePresetFromValuesV445(list?.stage || "", list?.scanner || "", list?.stagePreset || "") === "airport_outbound")
    || dateLists.find((list) => String(list.id || "") === String(state.activeListId || ""))
    || dateLists[0]
  ).filter(Boolean);
}

/**
 * Refresh per-user Scan page update markers for both delivery dates and stages.
 * Date markers use one broad representative stage per date to avoid duplicate API
 * work, while every stage on the active date is checked for its own ! indicator.
 */
async function refreshPendingUpdateDates({ force = false } = {}) {
  if (!state.backend || !Array.isArray(state.lists) || !state.lists.length) {
    state.pendingUpdateDates = new Map();
    state.pendingUpdateStages = new Map();
    renderDeliveryListSelect();
    syncAllCustomSelects();
    return;
  }
  if (!window.DLSLineUpdates?.loadAndApply) {
    window.setTimeout(() => refreshPendingUpdateDates({ force }).catch(() => {}), 450);
    return;
  }

  const requestId = ++state.pendingUpdateDatesRequestId;
  const activeDate = String(selectedDeliveryDate() || "").trim();
  const representativeLists = pendingUpdateMarkerLists();
  const representativeIds = new Set(representativeLists.map((list) => String(list.id || "")));
  const activeDateLists = state.lists.filter((list) => String(list.deliveryDate || "") === activeDate);
  const listsById = new Map();
  [...representativeLists, ...activeDateLists].forEach((list) => {
    const listId = String(list?.id || "").trim();
    if (listId) listsById.set(listId, list);
  });

  const stageCounts = new Map();
  const dateItemKeys = new Map();
  const lists = [...listsById.values()];
  let cursor = 0;
  const worker = async () => {
    while (cursor < lists.length) {
      const list = lists[cursor++];
      const listId = String(list?.id || "").trim();
      const deliveryDate = String(list?.deliveryDate || "").trim();
      if (!listId || !deliveryDate) continue;
      try {
        const flags = await window.DLSLineUpdates.loadAndApply(listId, {
          force,
          prompt: false,
          render: false,
        });
        const pending = Math.max(Number(flags?.pendingLineCount || 0), 0);
        if (deliveryDate === activeDate && pending) stageCounts.set(listId, pending);
        if (!representativeIds.has(listId)) continue;
        if (!dateItemKeys.has(deliveryDate)) dateItemKeys.set(deliveryDate, new Set());
        (flags?.items || []).forEach((item) => {
          if (!item?.hasUnseenUpdate) return;
          const order = String(item.order || "").trim();
          const itemNo = String(item.item || "").trim();
          const fallback = String(item.lineItemId || "").trim();
          dateItemKeys.get(deliveryDate).add(order || itemNo ? `${order}|${itemNo}` : `${listId}|${fallback}`);
        });
      } catch {
        // A single inaccessible or stale stage must not block the remaining markers.
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(5, lists.length) }, worker));
  if (requestId !== state.pendingUpdateDatesRequestId) return;

  state.pendingUpdateStages = stageCounts;
  state.pendingUpdateDates = new Map(
    [...dateItemKeys.entries()]
      .map(([date, keys]) => [date, keys.size])
      .filter(([, count]) => count > 0),
  );
  renderDeliveryListSelect();
  syncAllCustomSelects();
}


function homeTimeGreeting(now = new Date()) {
  const hour = Number(now.getHours());
  if (hour < 12) return "Good morning";
  if (hour < 17) return "Good afternoon";
  return "Good evening";
}

function applyPermissionUi() {
  const displayName = state.user ? state.user.displayName || state.user.username : "Demo";
  const roleText = state.user?.roles?.length ? state.user.roles.map(roleDisplayLabelV355).join(", ") : state.backend ? "Signed in" : "Local demo";
  const rawStationText = userAssignedStation(state.user) || currentScanStation() || "";
  const stationText = rawStationText ? stationDisplayLabelV355(rawStationText) : "No assigned station";
  const initials = state.user ? userInitials(state.user) : "DM";
  const accentClass = state.user ? userAccentClass(state.user) : "accent-default";

  if (els.signedInUser) {
    els.signedInUser.textContent = displayName;
  }

  if (els.signedInRole) {
    els.signedInRole.textContent = `${roleText} • ${stationText}`;
  }

  if (els.userMenuDisplayName) {
    els.userMenuDisplayName.textContent = displayName;
  }

  if (els.userMenuDetails) {
    els.userMenuDetails.textContent = `${roleText} • ${stationText}`;
  }

  if (els.userMenuIdentity) {
    const identity = state.user?.email || state.user?.username || (state.backend ? "Authenticated account" : "Local demo account");
    els.userMenuIdentity.textContent = identity;
  }

  document.querySelectorAll(".user-menu .user-avatar").forEach((avatar) => {
    avatar.textContent = initials;
    avatar.className = `user-avatar ${accentClass}${avatar.classList.contains("user-menu-large-avatar") ? " user-menu-large-avatar" : ""}`;
    avatar.setAttribute("aria-hidden", "true");
  });

  if (els.logoutBtn) els.logoutBtn.hidden = !state.backend || !state.user;
  document.querySelectorAll("[data-permission-any]").forEach((element) => {
    const permissions = element.dataset.permissionAny.split(",").map((value) => value.trim());
    element.hidden = !hasAnyPermission(permissions);
  });
  const canScan = hasPermission("scan_delivery_lists") || hasPermission("receive_indian_trail");
  setControlAllowed(els.scanInput, canScan);
  setControlAllowed(els.globalPrintExportBtn, hasPermission("print_export"), true);
  setControlAllowed(els.undoBtn, hasPermission("correct_scans"), true);
  setControlAllowed(els.redoBtn, hasPermission("correct_scans"), true);
  setControlAllowed(els.folderImportBtn, hasPermission("import_delivery_lists"), true);
  setControlAllowed(els.addStationBtn, hasPermission("manage_stations"));
  setControlAllowed(els.newStationInput, hasPermission("manage_stations"));
}

