/**
 * Purpose: Run the stage progress segments workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function stageProgressSegments(lists) {
  const total = lists.reduce((sum, list) => sum + Number(list.totalQty || 0), 0);
  if (!total) return [];
  const order = ["staged", "outbound", "received", "pickup", "greenville", "dtc"];
  const buckets = new Map();
  for (const list of lists) {
    const category = stageCategory(list);
    const current = buckets.get(category) || { category, label: stageLabel(list), qty: 0 };
    current.qty += Number(list.scannedQty || 0);
    buckets.set(category, current);
  }
  return [...buckets.values()]
    // v0.371: A zero-progress stage must contribute no visible header segment.
    // Filtering here avoids legacy min-width rules from painting a false sliver at 0%.
    .filter((segment) => Number(segment.qty || 0) > 0)
    .sort((a, b) => order.indexOf(a.category) - order.indexOf(b.category))
    .map((segment) => ({ ...segment, percent: Math.min((segment.qty / total) * 100, 100) }));
}

/**
 * Purpose: Run the progress width workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function progressWidth(percent) {
  const value = Math.min(Math.max(Number(percent || 0), 0), 100);
  return value > 0 ? Math.max(value, 1.25) : 0;
}

/**
 * Purpose: Render the render stacked progress workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderStackedProgress(lists, stats) {
  const segments = stageProgressSegments(lists);
  const segmentHtml = segments.length
    ? segments.map((segment) => `<span class="stage-segment ${escapeHtml(segment.category)}" style="width:${progressWidth(segment.percent)}%;" title="${escapeHtml(segment.label)} ${segment.qty}"></span>`).join("")
    : `<span style="width:0%"></span>`;
  const percent = Math.min(Math.max(Number(stats.deliveryPercent || 0), 0), 100);
  return `
    <div class="home-date-progress-v368">
      <div class="home-date-progress-track-v368" role="progressbar" aria-label="Overall delivery completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}">
        <span class="visually-hidden">Overall delivery progress</span>
        <div class="home-date-progress-segments-v368">${segmentHtml}</div>
        <strong>${formatPercent(percent)}</strong>
      </div>
    </div>
  `;
}

/**
 * Purpose: Run the filtered delivery lists workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function filteredDeliveryLists() {
  const search = state.homeSearch.trim().toLowerCase();
  return state.lists.filter((list) => {
    const matchesStage = state.homeStageFilter === "all" || `${list.stage} ${list.scanner}`.toLowerCase().includes(state.homeStageFilter.toLowerCase());
    if (!matchesStage) return false;
    if (!search) return true;
    return [list.label, list.stage, list.scanner, list.deliveryDate].join(" ").toLowerCase().includes(search);
  });
}

/**
 * Purpose: Run the delivery list card workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function deliveryListCard(list, extraClass = "") {
  const percent = progressPercent(list);
  const category = stageCategory(list);
  const onTime = Number(list.onTimePercent || 0);
  const title = stageLabel(list);
  const scannedQty = Number(list.scannedQty || 0);
  const totalQty = Number(list.totalQty || 0);
  const supportText = category === "outbound" ? `On-time ${formatPercent(onTime)}` : "Delivery stage";
  const progressFill = Number(percent || 0) > 0
    ? `<span style="width:${progressWidth(percent)}%"></span>`
    : "";
  return `
    <article class="delivery-list-card delivery-list-card-v367 delivery-list-card-v368 delivery-list-card-v369 ${escapeHtml(category)} ${escapeHtml(extraClass)}" data-open-list="${escapeHtml(list.id)}">
      <div class="delivery-stage-identity-v368 delivery-stage-identity-v369">
        <span class="delivery-stage-icon-v367 delivery-stage-icon-v368" aria-hidden="true"></span>
        <span class="delivery-stage-copy-v368 delivery-stage-copy-v369">
          <strong>${escapeHtml(title)}</strong>
          <small>${escapeHtml(supportText)}</small>
          <span class="delivery-stage-progress-v368 delivery-stage-progress-v369">
            <span class="delivery-stage-progress-track-v367 delivery-stage-progress-track-v368 delivery-stage-progress-track-v369" role="progressbar" aria-label="${escapeHtml(title)} completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(Math.max(Number(percent || 0), 0), 100)}">
              ${progressFill}
              <b>${formatPercent(percent)}</b>
            </span>
            <span class="delivery-stage-progress-count-v368 delivery-stage-progress-count-v369"><strong>${escapeHtml(scannedQty)} / ${escapeHtml(totalQty)}</strong><small>pieces</small></span>
          </span>
        </span>
      </div>
      <span class="delivery-stage-open-v368 delivery-stage-open-v369" aria-hidden="true"><span>Open stage</span><i></i></span>
    </article>
  `;
}

/**
 * Purpose: Render the render today progress workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderTodayProgress() {
  if (!els.todayStageGrid) return;
  const key = dashboardDateKey();
  const lists = state.lists
    .filter((list) => list.deliveryDate === key)
    .sort((a, b) => stageSort(a) - stageSort(b) || a.label.localeCompare(b.label));

  if (els.todayDateLabel) els.todayDateLabel.textContent = formatDisplayDate(key);

  // v0.385: Today can expose a different number of active stages depending on
  // route/date configuration. Feed that live count to CSS so every stage shares
  // one row evenly instead of relying on the older fixed four-column layout.
  const todayStageCount = Math.max(lists.length, 1);
  els.todayStageGrid.style.setProperty("--home-stage-count", String(todayStageCount));
  els.todayStageGrid.dataset.stageCount = String(todayStageCount);

  // v0.362: Keep Home intentionally simple: greeting/date followed immediately
  // by the live stage cards. Summary KPIs were useful data but made the top of
  // Home feel heavier than the operational overview it is meant to be.
  els.todayStageGrid.innerHTML = lists.length
    ? lists.map((list) => {
        const percent = progressPercent(list);
        const scannedQty = Number(list.scannedQty || 0);
        const totalQty = Number(list.totalQty || 0);
        const progressFill = Number(percent || 0) > 0
          ? `<span style="width:${Math.min(percent, 100)}%"></span>`
          : "";
        return `
          <article class="today-stage-card ${escapeHtml(stageCategory(list))}" data-open-list="${escapeHtml(list.id)}" role="button" tabindex="0">
            <div class="today-stage-card-heading">
              <span class="today-stage-name"><i aria-hidden="true"></i><b>${escapeHtml(stageLabel(list))}</b></span>
              <strong><b>${escapeHtml(scannedQty)}</b><small>/ ${escapeHtml(totalQty)}</small></strong>
            </div>
            <div class="list-card-progress${Number(percent || 0) <= 0 ? " is-zero" : ""}" role="progressbar" aria-label="${escapeHtml(stageLabel(list))} completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(percent, 100)}">${progressFill}</div>
            <div class="today-stage-percent">${formatPercent(percent)}</div>
          </article>
        `;
      }).join("")
    : `<div class="admin-empty">No delivery lists are loaded for ${formatDisplayDate(key)}.</div>`;
}

/**
 * Purpose: Render the render home stage filter workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderHomeStageFilter() {
  if (!els.homeStageFilter) return;
  const current = state.homeStageFilter || "all";
  const stageOptions = uniqueText(
    state.lists
      .map((list) => stageLabel(list) || list.stage || list.scanner || "")
      .filter(Boolean),
  ).sort((a, b) => a.localeCompare(b));

  els.homeStageFilter.innerHTML = [
    `<option value="all">All stages</option>`,
    ...stageOptions.map((stage) => `<option value="${escapeHtml(stage)}">${escapeHtml(stage)}</option>`),
  ].join("");
  els.homeStageFilter.value = stageOptions.some((stage) => stage.toLowerCase() === String(current).toLowerCase()) ? current : "all";
  state.homeStageFilter = els.homeStageFilter.value;
}

/**
 * Purpose: Render the dedicated Statistics page from the shared delivery-list and report state.
 * Effects: Updates only the Statistics page controls and visual summaries.
 * Flow: Applies the selected range, then renders priority metrics, the live analytics workspace, and supporting charts.
 */
function renderStatisticsPage() {
  if (!els.statisticsPage) return;
  const overviewLists = filterListsByOverviewRange(state.lists);
  const overview = aggregateListStats(overviewLists);
  if (els.overviewRangeSelect && els.overviewRangeSelect.value !== state.overviewRange) {
    els.overviewRangeSelect.value = state.overviewRange;
  }
  if (els.statisticsLastUpdated) {
    const updated = new Date().toLocaleTimeString(appLocale(), { hour: "numeric", minute: "2-digit" });
    els.statisticsLastUpdated.textContent = `Updated ${updated}`;
  }
  renderHomeStatistics(overviewLists, overview);
}


/** Build the lightweight operations-hub view from data already held by the app.
 *
 * Home intentionally avoids opening new report queries on every render. The hub uses
 * the live delivery-list catalog plus any rack/bay/priority state the operator has
 * already loaded, keeping navigation instant and preserving the modal performance work.
 */
function homeHubTimelineGroups() {
  const today = todayKey();
  const groups = listsByDeliveryDate(state.lists || []);
  const upcoming = groups
    .filter((group) => /^\d{4}-\d{2}-\d{2}$/.test(group.date) && group.date >= today)
    .sort((left, right) => left.date.localeCompare(right.date));
  if (upcoming.length) return upcoming.slice(0, 5);
  return groups.slice(0, 5).reverse();
}

/** Return the single Airport Rd staging source of truth for Forward View. */
function homeAirportStagingStats(lists = []) {
  const candidates = (lists || []).filter((list) =>
    stagePresetFromValuesV445(list?.stage || "", list?.scanner || "", list?.stagePreset || "") === "airport_staging"
  );
  const preferred = candidates.find((list) => String(list?.id || "").toLowerCase().endsWith("-staging-airport"))
    || candidates.slice().sort((a, b) => Number(b?.totalQty || 0) - Number(a?.totalQty || 0))[0]
    || null;
  const totalQty = Math.max(Number(preferred?.totalQty || 0), 0);
  const scannedQty = Math.min(Math.max(Number(preferred?.scannedQty || 0), 0), totalQty || Number(preferred?.scannedQty || 0));
  const percent = totalQty ? (scannedQty / totalQty) * 100 : 0;
  return { list: preferred, totalQty, scannedQty, percent };
}

/** Build the compact Forward View stage counters in workflow order. */
function homeForwardStageCountersV431(lists = [], airport = null) {
  const stageOrder = [
    ["staged", "STG"],
    ["outbound", "OUT"],
    ["received", "IN"],
    ["pickup", "CPU"],
    ["greenville", "GNV"],
    ["dtc", "DTC"],
  ];
  const totals = new Map();

  for (const list of lists || []) {
    const category = stageCategory(list);
    if (!stageOrder.some(([key]) => key === category)) continue;
    const current = totals.get(category) || { scannedQty: 0, totalQty: 0 };
    current.scannedQty += Math.max(Number(list?.scannedQty || 0), 0);
    current.totalQty += Math.max(Number(list?.totalQty || 0), 0);
    totals.set(category, current);
  }

  // Forward View has historically used Airport Road as the authoritative staging
  // source. Keep that exact source while adding the remaining workflow stages.
  if (airport?.list) {
    totals.set("staged", {
      scannedQty: Math.max(Number(airport.scannedQty || 0), 0),
      totalQty: Math.max(Number(airport.totalQty || 0), 0),
    });
  }

  return stageOrder
    .filter(([category]) => totals.has(category))
    .map(([category, shortLabel]) => {
      const stats = totals.get(category) || { scannedQty: 0, totalQty: 0 };
      const scannedQty = Math.min(stats.scannedQty, stats.totalQty || stats.scannedQty);
      return { category, shortLabel, scannedQty, totalQty: stats.totalQty };
    });
}

function renderHomeHub() {
  if (!els.homePage) return;
  const timeline = homeHubTimelineGroups();
  const now = new Date();

  if (els.homeHubUpdated) {
    els.homeHubUpdated.textContent = `Updated ${now.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}`;
  }

  if (els.homeDeliveryTimeline) {
    els.homeDeliveryTimeline.innerHTML = timeline.length ? timeline.map((group) => {
      const airport = homeAirportStagingStats(group.lists);
      const stageCounters = homeForwardStageCountersV431(group.lists, airport);
      const date = parseDateKey(group.date);
      const weekday = date ? date.toLocaleDateString([], { weekday: "short" }) : "Date";
      const isToday = group.date === todayKey();
      return `
        <button type="button" class="home-timeline-card-v358 home-timeline-card-v378${isToday ? " is-today" : ""}" data-home-timeline-date="${escapeHtml(group.date)}">
          <span class="home-timeline-date-v358"><small>${escapeHtml(isToday ? "Today" : weekday)}</small><strong>${escapeHtml(formatNumericDeliveryDate(group.date))}</strong></span>
          <span class="home-timeline-stage-count-v358 home-timeline-stage-count-v383">${escapeHtml(group.lists.length)} stage${group.lists.length === 1 ? "" : "s"}</span>
          <span class="home-timeline-progress-v358 home-timeline-progress-v378" role="progressbar" aria-label="${escapeHtml(formatDisplayDate(group.date))} Airport Road staging completion" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(Math.max(Number(airport.percent || 0), 0), 100)}">
            <i>${Number(airport.percent || 0) > 0 ? `<b style="width:${progressWidth(airport.percent)}%"></b>` : ""}<strong>${formatPercent(airport.percent)}</strong></i>
          </span>
          <span class="home-timeline-summary-v378 home-timeline-summary-v382 home-timeline-summary-v383 home-forward-stage-counters-v431" data-forward-legacy="home-timeline-pieces-v378 home-timeline-pieces-v383" aria-label="Stage piece progress">
            ${stageCounters.map((counter) => `
              <span class="home-forward-stage-counter-v431 ${escapeHtml(counter.category)}" title="${escapeHtml(counter.shortLabel)} ${escapeHtml(counter.scannedQty)} / ${escapeHtml(counter.totalQty)} pieces">
                <i aria-hidden="true"></i>
                <small>${escapeHtml(counter.shortLabel)}</small>
                <strong>${escapeHtml(counter.scannedQty)}/${escapeHtml(counter.totalQty)}</strong>
              </span>
            `).join("")}
          </span>
        </button>
      `;
    }).join("") : `<div class="home-hub-empty-v358"><strong>No upcoming delivery dates</strong><span>Imported delivery lists will appear here automatically.</span></div>`;
  }
}

function focusHomeDeliveryDate(dateKey) {
  const requested = String(dateKey || "").trim();
  if (!requested) return;
  state.homeSearch = "";
  state.homeStageFilter = "all";
  if (els.homeListSearch) els.homeListSearch.value = "";
  const groups = listsByDeliveryDate(filteredDeliveryLists());
  const groupIndex = groups.findIndex((group) => group.date === requested);
  if (groupIndex >= 0) state.homePageIndex = Math.floor(groupIndex / Math.max(Number(state.homePageSize || 25), 1)) + 1;
  state.expandedDeliveryDate = requested;
  renderHome();
  requestAnimationFrame(() => {
    document.querySelector(`.delivery-date-group[data-delivery-date="${CSS.escape(requested)}"]`)?.scrollIntoView({ behavior: "smooth", block: "center" });
  });
}

function runHomeHubAction(action) {
  const normalized = String(action || "").trim().toLowerCase();
  if (normalized === "scan") return showPage("scan");
  if (normalized === "racks") return showPage("racks");
  if (normalized === "bays") return showPage("bays");
  if (normalized === "statistics") return showPage("statistics");
  if (normalized === "rejects") return showPage("rejects");
  if (normalized === "settings") return showPage("admin");
}

/**
 * Purpose: Render the render home workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
/** v0.457: Home Delivery Library animation is CSS-owned again. The open
 * selector is removed on collapse and re-applied on the next expand, which
 * naturally replays the motion without a forced reflow or visible flash. */
function renderHome() {
  if (!els.homePage) return;
  renderHomeStageFilter();
  if (els.homeGreeting) {
    const displayName = state.user?.displayName || state.user?.username || "Operator";
    els.homeGreeting.textContent = `${homeTimeGreeting()}, ${displayName}`;
  }
  renderTodayProgress();
  renderHomeHub();
  const filtered = filteredDeliveryLists();
  const dateGroups = listsByDeliveryDate(filtered);
  const totalHomePages = Math.max(1, Math.ceil(dateGroups.length / state.homePageSize));
  state.homePageIndex = Math.min(Math.max(state.homePageIndex, 1), totalHomePages);
  const pageStart = (state.homePageIndex - 1) * state.homePageSize;
  const visibleDateGroups = dateGroups.slice(pageStart, pageStart + state.homePageSize);
  if (!dateGroups.some((group) => group.date === state.expandedDeliveryDate)) state.expandedDeliveryDate = "";
  if (els.homeListCount) els.homeListCount.textContent = `${dateGroups.length} dates / ${filtered.length} stages`;
  if (els.homeListGrid) {
    const visibleWeekGroups = deliveryDateGroupsByBusinessWeek(visibleDateGroups);
    els.homeListGrid.innerHTML = visibleDateGroups.length
      ? visibleWeekGroups
          .map(({ weekKey, label, groups: weekDateGroups }) => `
            <section class="home-delivery-week" data-home-delivery-week="${escapeHtml(weekKey)}">
              <header class="home-delivery-week-heading">
                <span>${escapeHtml(label)}</span>
                <b>${escapeHtml(weekDateGroups.length)} delivery date${weekDateGroups.length === 1 ? "" : "s"}</b>
              </header>
              <div class="home-delivery-week-list">
                ${weekDateGroups.map((group) => {
                  const stats = aggregateListStats(group.lists);
                  const date = parseDateKey(group.date);
                  const weekday = date ? date.toLocaleDateString([], { weekday: "short" }) : "Date";
                  return `
                    <details class="delivery-date-group delivery-date-group-v367" data-delivery-date="${escapeHtml(group.date)}" ${group.date === state.expandedDeliveryDate ? "open" : ""}>
                      <summary>
                        <span class="home-date-chevron" aria-hidden="true"></span>
                        <span class="home-date-summary-main home-date-summary-main-v367">
                          <span class="home-library-date-v367"><small>${escapeHtml(weekday)}</small><strong>${escapeHtml(formatNumericDeliveryDate(group.date))}</strong></span>
                          <span class="home-library-date-progress-v367">
                            <small>${escapeHtml(group.lists.length)} stages · Delivery on-time ${formatPercent(stats.onTimePercent)}</small>
                            ${renderStackedProgress(group.lists, stats)}
                          </span>
                        </span>
                        <span class="delivery-date-total home-date-piece-summary-v368"><i aria-hidden="true"></i><span><small>Total pieces</small><strong>${escapeHtml(stats.pieceQty || stats.totalQty)}</strong></span></span>
                      </summary>
                      <div class="delivery-stage-list">
                        ${group.lists.map((list) => deliveryListCard(list, "date-grouped")).join("")}
                      </div>
                    </details>
                  `;
                }).join("")}
              </div>
            </section>
          `)
          .join("")
      : `<div class="admin-empty">No delivery lists match.</div>`;
    els.homeListGrid.querySelectorAll(".delivery-date-group").forEach((details) => {
      details.addEventListener("toggle", () => {
        if (!details.open) {
          details.classList.remove("is-expanding");
          return;
        }
        // v0.457: do not force/restart animation classes here. The CSS [open]
        // selector replays once per expansion without flashing the revealed list.
        state.expandedDeliveryDate = details.dataset.deliveryDate || "";
        els.homeListGrid.querySelectorAll(".delivery-date-group").forEach((other) => {
          if (other !== details) other.open = false;
        });
      });
    });
  }
  if (els.homePager) {
    const pagerHtml = `
      <button type="button" data-home-page-action="prev" ${state.homePageIndex <= 1 ? "disabled" : ""}>&lt;</button>
      <span class="pager-summary">Page ${state.homePageIndex} of ${totalHomePages}</span>
      <button type="button" data-home-page-action="next" ${state.homePageIndex >= totalHomePages ? "disabled" : ""}>&gt;</button>
    `;
    els.homePager.innerHTML = pagerHtml;
    if (els.homePagerTop) els.homePagerTop.innerHTML = pagerHtml;
  }
  // Statistics are rendered once near the start of this workflow; avoid a duplicate DOM pass.

  applyPermissionUi();
}

/** Reset every application-level scroll owner after changing pages.
 *
 * Chrome/Edge scroll anchoring can retain a few pixels from the previous page
 * when the newly-visible page has a different height. On the Racks page that
 * placed the top edge of the heading actions underneath the sticky app header,
 * making the upper part of Racks History/Edit Racks appear visible but not
 * clickable. Reset after visibility changes, then confirm again next paint.
 */
function resetPageScrollPosition() {
  window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  document.documentElement.scrollTop = 0;
  document.body.scrollTop = 0;
  const main = document.querySelector(".app > main");
  if (main) {
    main.scrollTop = 0;
    main.scrollLeft = 0;
  }
}

/**
 * Keep Rack Overview heading actions entirely below the sticky application header.
 *
 * Async rack refreshes, modal scrollbar restoration, fullscreen changes, and browser
 * scroll anchoring can occasionally retain only a few pixels of document scroll. The
 * buttons still look normal in that state, but their upper edge sits underneath live
 * header controls and loses hover/click hit testing. Repair the geometry after layout
 * settles instead of forwarding clicks or adding oversized invisible hit targets.
 */
let rackHeadingRepairFrame = 0;

function rackHeadingActionNeedsRepair() {
  if (state.page !== "racks") return false;
  const header = document.querySelector(".app-header");
  const buttons = [els.rackPackingHistoryBtn, els.rackEditOpenBtn].filter((button) => button && button.isConnected && !button.hidden);
  if (!header || !buttons.length) return false;

  const headerRect = header.getBoundingClientRect();
  const headerBottom = headerRect.bottom;
  return buttons.some((button) => {
    const rect = button.getBoundingClientRect();
    if (!rect.width || !rect.height) return false;
    const geometryOverlap = rect.top < headerBottom && rect.bottom > headerBottom;
    if (geometryOverlap) return true;

    const x = rect.left + (rect.width / 2);
    const topY = rect.top + Math.min(6, rect.height * 0.2);
    const bottomY = rect.bottom - Math.min(6, rect.height * 0.2);
    const topHit = document.elementFromPoint(x, topY);
    const bottomHit = document.elementFromPoint(x, bottomY);
    const ownsHit = (node) => Boolean(node && (node === button || button.contains(node)));
    const topBlockedByHeader = !ownsHit(topHit) && Boolean(topHit?.closest?.(".app-header"));
    return topBlockedByHeader && ownsHit(bottomHit);
  });
}

function scheduleRackHeadingHitTargetRepair() {
  if (state.page !== "racks") return;
  window.cancelAnimationFrame(rackHeadingRepairFrame);
  rackHeadingRepairFrame = window.requestAnimationFrame(() => {
    rackHeadingRepairFrame = window.requestAnimationFrame(() => {
      rackHeadingRepairFrame = 0;
      if (!rackHeadingActionNeedsRepair()) return;
      resetPageScrollPosition();
    });
  });
}

/**
 * Purpose: Open the show page workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function clearPageEnterTransitionV0376(view) {
  if (!view) return;
  view.classList.remove("is-page-fading-v0376", "is-page-visible-v0376");
}

function preparePageEnterTransitionV0376(view) {
  if (!view) return;
  clearPageEnterTransitionV0376(view);
  if (window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) return;
  // v0.376: establish the invisible state before the page is unhidden. This
  // prevents the one-frame flash/jump that happened when v0.375 applied an
  // animation only after the new page had already painted at full opacity.
  view.classList.add("is-page-fading-v0376");
}

function startPageEnterTransitionV0376(view) {
  if (!view || window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) return;
  window.requestAnimationFrame(() => {
    if (view.hidden) return;
    view.classList.add("is-page-visible-v0376");
    // v0.385: keep the proven opacity-only transition, but let it breathe a
    // little longer so page changes feel deliberate without becoming slow.
    window.setTimeout(() => clearPageEnterTransitionV0376(view), 310);
  });
}

function prepareBayFlowEntryV0376() {
  const panel = els.bayFlowPanel;
  if (!panel) return;
  panel.classList.remove("is-route-visible-v0376");
  if (window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) {
    panel.classList.remove("is-route-fading-v0376");
    return;
  }
  panel.classList.add("is-route-fading-v0376");
}

function revealBayFlowEntryV0376() {
  const panel = els.bayFlowPanel;
  if (!panel) return;
  if (window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) {
    panel.classList.remove("is-route-fading-v0376", "is-route-visible-v0376");
    return;
  }
  window.requestAnimationFrame(() => {
    panel.classList.add("is-route-visible-v0376");
    window.setTimeout(() => panel.classList.remove("is-route-fading-v0376", "is-route-visible-v0376"), 220);
  });
}

function showPage(page) {
  cleanupTransientUiLayers();
  if (customSelectUi.openSelect) closeCustomSelect(false);
  if (state.bayEditMode && state.bayHoldingSections.size && page !== "bays") {
    showFloatingNotice("Move all grouped bays out of the temporary holding area before leaving the Bay Map.", "error");
    return;
  }
  if (page === "admin" && !hasAnyPermission([
    "view_admin", "reset_delivery_lists", "import_delivery_lists", "edit_delivery_list_items", "create_delivery_list_orders", "delete_delivery_list_items", "delete_delivery_lists",
    "review_superseded_orders", "manage_users", "manage_user_access", "manage_user_assignments", "manage_roles", "view_sessions",
    "manage_stations", "manage_route_rules", "manage_customer_emails", "manage_lookup_values", "manage_automation",
    "manage_production_files",
    "manage_cross_date_scanning", "manage_reject_settings", "manage_bay_layout", "manage_bay_scanner_rules",
    "manage_bay_auto_assigner", "manage_racks",
  ])) page = "home";
  if (page === "bays" && !hasAnyPermission(["view_bays", "view_indian_trail"])) page = "home";
  if (page === "racks" && !hasAnyPermission(["view_racks", "scan_racks", "manage_racks"])) page = "home";
  if (page === "rejects" && !hasAnyPermission(["view_rejects", "log_rejects", "manage_reject_settings", "manage_reject_records", "view_delivery_lists"])) page = "home";
  const pageChanged = state.page !== page;
  if (page === "home") state.expandedDeliveryDate = "";
  state.page = page;
  document.body.dataset.page = page;
  syncSidebarState({ closeMobile: true });
  let activePageView = null;
  document.querySelectorAll(".page-view").forEach((view) => {
    const isActiveView = view.id === `${page === "bays" ? "bayMap" : page}Page`;
    if (isActiveView) {
      activePageView = view;
      preparePageEnterTransitionV0376(view);
      view.hidden = false;
    } else {
      clearPageEnterTransitionV0376(view);
      view.hidden = true;
    }
  });
  resetPageScrollPosition();
  requestAnimationFrame(() => {
    if (state.page === page) {
      resetPageScrollPosition();
      if (page === "racks") scheduleRackHeadingHitTargetRepair();
    }
  });
  if (page === "bays") scheduleBayScannerStickyUpdateV155();
  else resetBayScannerStickyV155();
  document.querySelectorAll("[data-page-target]").forEach((button) => {
    button.classList.toggle("is-active", button.dataset.pageTarget === page);
  });
  updateModalScrollLock();
  requestAnimationFrame(() => updateModalScrollLock());
  if (page === "home") renderHome();
  if (page === "statistics") {
    renderStatisticsPage();
    // v0.471: the startup report query is intentionally asynchronous. If a
    // user reaches Statistics before it completes (or after a transient report
    // failure), page entry now guarantees a retry instead of leaving report-only
    // controls such as Common glass sizes empty.
    if (!activeHomeReportSummaryV472()) void loadHomeReportSummary();
  }
  if (page === "scan") renderScanPage();
  if (page === "racks") {
    refreshRacksPage().catch((error) => showInlineError(error.message, true));
  }
  // Reject history is refreshed on every page entry, replacing the old manual Refresh button.
  if (page === "rejects") refreshRejectPage().catch((error) => showInlineError(error.message, true));
  if (page === "bays") {
    if (pageChanged) {
      els.bayFlowPanel?.classList.add("is-entering");
      prepareBayFlowEntryV0376();
    }
    refreshBayMapPage()
      .catch((error) => showInlineError(error.message))
      .finally(() => {
        if (!pageChanged) return;
        // v0.376: remove the pause/hide state before restarting the truck.
        // The previous order restarted the animation while CSS still forced
        // the truck invisible, so its first visible run could be missed.
        els.bayFlowPanel?.classList.remove("is-entering");
        restartBayTruckAnimation();
        revealBayFlowEntryV0376();
      });
  }
  if (page === "admin") refreshAdminPage().catch((error) => showInlineError(error.message));
  if (page === "scan") {
    els.scanInput?.focus();
    window.setTimeout(() => {
      presentNextUserNotification();
      void pollUserNotifications();
    }, 0);
  }
  // Start only after the page has been prepared and its synchronous renderer
  // has run. Opacity is the only animated property, so headers (including the
  // Settings/Admin header) fade in cleanly without any positional jitter.
  if (activePageView) startPageEnterTransitionV0376(activePageView);
}

/**
 * Purpose: Open the show outbound override dialog workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function showOutboundOverrideDialog(payload, scanText, options = {}) {
  await ensureRacksLoaded().catch(() => {});
  /**
   * Purpose: Run the racks workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const racks = (state.racks || []).filter((rack) => {
    const status = String(rack.status || "").toLowerCase();
    return rack.active !== false && !["closed", "complete", "completed", "in transit"].includes(status);
  });
  const preferredRackCode = rackCodeForScan(state.selectedScanRackCode);
  const defaultRack = preferredRackCode && racks.some((rack) => rack.code === preferredRackCode)
    ? preferredRackCode
    : (racks.find((rack) => rack.code === "T")?.code || racks[0]?.code || "");

  return new Promise((resolve) => {
    document.querySelector(".outbound-override-backdrop")?.remove();
    const item = payload.outboundItem || payload.lastScan?.item || {};
    const dialog = document.createElement("div");
    dialog.className = "outbound-override-backdrop";
    dialog.innerHTML = `
      <section class="outbound-override-dialog" role="dialog" aria-modal="true" aria-labelledby="outboundOverrideTitle">
        <button type="button" class="outbound-override-close gui-close-button" data-outbound-override-cancel aria-label="Close outbound override">&times;</button>
        <div class="outbound-override-icon" aria-hidden="true"></div>
        <div class="outbound-override-copy">
          <span class="outbound-override-eyebrow">Outbound safety check</span>
          <h2 id="outboundOverrideTitle">${escapeHtml(payload.outboundOverrideMessage || "Outbound scan needs review")}</h2>
          <p>${escapeHtml(payload.outboundOverrideReason || "Review this scan before allowing it to continue.")}</p>
        </div>
        <div class="outbound-override-item">
          <span><small>Order</small><strong>${escapeHtml(item.order || "-")}</strong></span>
          <span><small>Item</small><strong>${escapeHtml(item.item || "-")}</strong></span>
          <span><small>Customer</small><strong>${escapeHtml(item.customer || "-")}</strong></span>
          <span><small>Size</small><strong>${escapeHtml(item.dimensions || "-")}</strong></span>
        </div>
        <label class="outbound-override-field">
          <span>Transportation method for this piece</span>
          <select id="outboundOverrideRackSelect">
            <option value="">Choose an open rack or truck...</option>
            ${groupedRackOptionsHtml(racks, defaultRack)}
          </select>
        </label>
        <div class="outbound-override-actions">
          <button type="button" class="app-cancel-action-v343" data-outbound-override-cancel><span class="app-cancel-icon-v343" aria-hidden="true"></span><span>Cancel scan</span></button>
          <button type="button" data-outbound-override-confirm>Override and scan outbound</button>
        </div>
      </section>
    `;

    /**
     * Purpose: Close the close workflow using the existing shared UI state.
     * Effects: Updates visible dom state.
     * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
     */
    const close = (confirmed) => {
      dialog.remove();
      document.body.classList.remove("modal-scroll-locked");
      resolve(Boolean(confirmed));
    };

    dialog.addEventListener("click", (event) => {
      if (event.target === dialog || event.target.closest("[data-outbound-override-cancel]")) {
        close(false);
        return;
      }
      if (event.target.closest("[data-outbound-override-confirm]")) {
        const rackCode = dialog.querySelector("#outboundOverrideRackSelect")?.value || "";
        if (!rackCode) {
          showFloatingNotice("Choose a rack or truck before overriding outbound scan safety.", "error");
          dialog.querySelector("#outboundOverrideRackSelect")?.focus();
          return;
        }
        close(true);
        processScan(scanText, { ...options, outboundOverride: true, rackCode }).catch((error) => showInlineError(error.message, false));
      }
    });

    document.body.appendChild(dialog);
    document.body.classList.add("modal-scroll-locked");
    dialog.querySelector("#outboundOverrideRackSelect")?.focus();
  });
}


/**
 * Purpose: Run the available indian trail bays workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function availableIndianTrailBays(includeBayCode = "") {
  const preservedCode = String(includeBayCode || "").trim();
  return (state.bays || [])
    .filter((bay) => bayAvailableForNewOrderAssignment(bay) || (preservedCode && bay.bayCode === preservedCode))
    .sort(bayOverrideSort);
}

/**
 * Purpose: Run the indian trail bay options HTML workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function indianTrailBayOptionsHtml(selectedCode = "") {
  const grouped = new Map();
  for (const bay of availableIndianTrailBays(selectedCode)) {
    const label = bayOverrideGroupLabel(bay);
    if (!grouped.has(label)) grouped.set(label, []);
    grouped.get(label).push(bay);
  }
  return [...grouped.entries()].map(([label, bays]) => `
    <optgroup label="${escapeHtml(label)}">
      ${bays.map((bay) => `<option value="${escapeHtml(bay.bayCode)}" ${bay.bayCode === selectedCode ? "selected" : ""}>${escapeHtml(bayLocationDisplayLabel(bay.bayCode, bay.displayName))}${bay.status ? ` - ${escapeHtml(bay.status)}` : ""}</option>`).join("")}
    </optgroup>
  `).join("");
}

/**
 * Purpose: Open the show indian trail outbound receive override workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function showIndianTrailOutboundReceiveOverride(payload, scanText, options = {}) {
  await ensureScanBayOverrideBays().catch(() => {});
  const item = payload.item || payload.lastScan?.item || {};
  const itemLabel = `${item.order || "Item"}${item.item ? `-${item.item}` : ""}`;
  const spanish = state.language === "es";
  const existingOrderBayCode = String(payload.existingOrderBayCode || "").trim();
  const preferredBayCode = existingOrderBayCode || payload.preassignedBayCode || options.bayCode || state.selectedBayOverrideCode || "";
  const bays = availableIndianTrailBays(preferredBayCode);

  const approved = await confirmWebAppAction({
    title: spanish ? "Este artículo no ha sido escaneado en Salida" : "This item has not been scanned Outbound",
    message: spanish
      ? `¿Desea omitir el requisito de Salida y recibir <strong>${escapeHtml(itemLabel)}</strong> de todos modos?`
      : `Would you like to override the Outbound requirement and receive <strong>${escapeHtml(itemLabel)}</strong> anyway?`,
    details: spanish
      ? "Seleccionar No cancela el escaneo sin cambiar la cantidad recibida."
      : "Selecting No cancels the scan without changing the received quantity.",
    confirmLabel: spanish ? "Sí, omitir" : "Yes, override",
    cancelLabel: spanish ? "No, cancelar escaneo" : "No, cancel scan",
    danger: false,
  });
  if (!approved) return null;

  const defaultBay = preferredBayCode || bays[0]?.bayCode || "";
  return new Promise((resolve) => {
    document.getElementById("indianTrailOutboundOverrideShell")?.remove();
    const shell = document.createElement("div");
    shell.id = "indianTrailOutboundOverrideShell";
    shell.className = "action-confirm-backdrop indian-trail-override-backdrop";
    shell.innerHTML = `
      <section class="action-confirm-dialog indian-trail-override-dialog" role="dialog" aria-modal="true" aria-labelledby="indianTrailBayOverrideTitle">
        <button type="button" class="action-confirm-close gui-close-button" data-indian-trail-override-cancel aria-label="Close">&times;</button>
        <span class="action-confirm-icon" aria-hidden="true"></span>
        <div class="action-confirm-copy">
          <small class="dialog-eyebrow">${spanish ? "Asignación de bahía de Indian Trail" : "Indian Trail bay assignment"}</small>
          <h2 id="indianTrailBayOverrideTitle">${spanish ? "¿En qué bahía se debe recibir este artículo?" : "What bay should receive this item?"}</h2>
          <p>${spanish ? "Elija la bahía física para" : "Choose the physical bay for"} <strong>${escapeHtml(itemLabel)}</strong> ${spanish ? "antes de completar la omisión." : "before completing the override."}</p>
        </div>
        <div class="indian-trail-override-item">
          <span><small>Order</small><strong>${escapeHtml(item.order || "-")}</strong></span>
          <span><small>Item</small><strong>${escapeHtml(item.item || "-")}</strong></span>
          <span><small>Customer</small><strong>${escapeHtml(item.customer || "-")}</strong></span>
          <span><small>Size</small><strong>${escapeHtml(item.dimensions || "-")}</strong></span>
        </div>
        <label class="indian-trail-override-field">
          <span>${spanish ? "Recibir en la bahía" : "Receive into bay"}</span>
          <select data-indian-trail-override-bay>
            <option value="">${spanish ? "Elija una bahía..." : "Choose a bay..."}</option>
            ${indianTrailBayOptionsHtml(defaultBay)}
          </select>
          ${existingOrderBayCode
            ? `<small class="indian-trail-existing-order-bay-v446">${spanish ? "Bahía ya usada por esta orden" : "Same-order bay recommended"}: ${escapeHtml(bayLocationDisplayLabel(existingOrderBayCode, ""))}</small>`
            : payload.preassignedBayCode
              ? `<small>${spanish ? "Bahía preasignada" : "Preassigned bay"}: ${escapeHtml(bayLocationDisplayLabel(payload.preassignedBayCode, ""))}</small>`
              : ""}
        </label>
        <div class="action-confirm-actions">
          <button type="button" class="action-confirm-cancel app-cancel-action-v343" data-indian-trail-override-cancel><span class="app-cancel-icon-v343" aria-hidden="true"></span><span>${spanish ? "Cancelar escaneo" : "Cancel scan"}</span></button>
          <button type="button" class="action-confirm-confirm" data-indian-trail-override-confirm>${spanish ? "Recibir en la bahía seleccionada" : "Receive in selected bay"}</button>
        </div>
      </section>
    `;
    /**
     * Purpose: Close the close workflow using the existing shared UI state.
     * Effects: Updates visible dom state.
     * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
     */
    const close = (decision = null) => {
      shell.remove();
      updateModalScrollLock();
      resolve(decision);
    };
    shell.addEventListener("click", (event) => {
      if (event.target === shell || event.target.closest("[data-indian-trail-override-cancel]")) {
        close(null);
        return;
      }
      if (event.target.closest("[data-indian-trail-override-confirm]")) {
        const bayCode = shell.querySelector("[data-indian-trail-override-bay]")?.value || "";
        if (!bayCode) {
          showFloatingNotice("Choose a bay before receiving the item.", "error");
          shell.querySelector("[data-indian-trail-override-bay]")?.focus();
          return;
        }
        close({ bayCode, outboundOverride: true, scanText });
      }
    });
    document.body.appendChild(shell);
    applyLanguageToRoot(shell);
    enhanceCustomSelects(shell);
    updateModalScrollLock();
    shell.querySelector("[data-indian-trail-override-bay]")?.focus();
  });
}

/**
 * Purpose: Close the close timed scan confirmation workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may call the backend api, may update shared client state.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function closeTimedScanConfirmation(shellOrId) {
  const shell = typeof shellOrId === "string"
    ? document.getElementById(shellOrId)
    : shellOrId;
  if (!shell) return;
  window.clearInterval(shell._countdownTimer);
  if (customSelectUi.openSelect && shell.contains(customSelectUi.openSelect)) closeCustomSelect(false);
  shell.remove();
  updateModalScrollLock();
}

/**
 * Purpose: Run the mount timed scan confirmation workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function mountTimedScanConfirmation({
  id,
  className = "",
  markup,
  durationSeconds = 12,
  openAllScans = null,
}) {
  document.querySelectorAll("[data-timed-scan-confirmation]").forEach((existingShell) => {
    closeTimedScanConfirmation(existingShell);
  });

  const shell = document.createElement("div");
  shell.id = id;
  shell.dataset.timedScanConfirmation = "true";
  shell.className = `indian-trail-placement-shell${className ? ` ${className}` : ""}`;
  shell.innerHTML = markup;
  shell.style.setProperty("--timed-confirmation-duration", `${durationSeconds}s`);
  document.body.appendChild(shell);
  applyLanguageToRoot(shell);
  enhanceCustomSelects(shell);
  updateModalScrollLock();

  let seconds = durationSeconds;
  let paused = false;
  let pointerInside = false;
  let customSelectOpen = false;
  let editInProgress = false;
  const countdown = shell.querySelector("[data-placement-countdown]");
  const panel = shell.querySelector(".indian-trail-placement-panel");
  if (countdown) countdown.textContent = String(seconds);

  /**
   * Purpose: Pause or resume the timed scan confirmation countdown.
   * Effects: Updates the local timer state and the popup pause styling.
   * Flow: Keeps the timer paused while the popup is hovered or any popup control retains focus.
   */
  const setPaused = (nextPaused) => {
    paused = Boolean(nextPaused);
    shell.classList.toggle("is-timer-paused", paused);
  };
  const syncPausedState = () => {
    setPaused(pointerInside || customSelectOpen || editInProgress || shell.contains(document.activeElement));
  };
  shell._setCustomSelectOpen = (open) => {
    customSelectOpen = Boolean(open);
    syncPausedState();
  };
  shell._setTimedEditInProgress = (editing) => {
    editInProgress = Boolean(editing);
    syncPausedState();
  };

  shell.addEventListener("pointerenter", () => {
    pointerInside = true;
    syncPausedState();
  });
  shell.addEventListener("pointerleave", () => {
    pointerInside = false;
    syncPausedState();
  });
  shell.addEventListener("focusin", syncPausedState);
  shell.addEventListener("focusout", () => window.setTimeout(syncPausedState, 0));
  shell.querySelectorAll("select").forEach((select) => {
    // Native option menus can render outside the popup and fire pointerleave.
    // The focused select keeps the countdown paused until the menu closes.
    select.addEventListener("pointerdown", () => setPaused(true));
    select.addEventListener("change", () => window.setTimeout(syncPausedState, 0));
    select.addEventListener("blur", () => window.setTimeout(syncPausedState, 0));
  });

  shell._countdownTimer = window.setInterval(() => {
    if (paused) return;
    seconds -= 1;
    if (countdown) countdown.textContent = String(Math.max(seconds, 0));
    if (seconds <= 0) closeTimedScanConfirmation(shell);
  }, 1000);

  shell.querySelector("[data-placement-close]")?.addEventListener("click", (event) => {
    event.stopPropagation();
    closeTimedScanConfirmation(shell);
  });

  if (typeof openAllScans === "function" && panel) {
    panel.classList.add("is-clickable");
    panel.tabIndex = 0;
    panel.setAttribute("aria-label", `${panel.getAttribute("aria-label") || "Scan confirmation"}. Click to open All Scans.`);

    /**
     * Purpose: Open the appropriate All Scans view from a timed scan confirmation.
     * Effects: Closes the current popup and opens the supplied shared history workflow.
     * Flow: Ignores interactive child controls, accepts click/keyboard activation, then delegates to the existing All Scans opener.
     */
    const openHistory = async (event) => {
      if (event?.target?.closest?.("button, select, input, label, a, [data-placement-move], [data-placement-close]")) return;
      if (event?.type === "keydown" && !["Enter", " "].includes(event.key)) return;
      event?.preventDefault?.();
      closeTimedScanConfirmation(shell);
      await openAllScans();
    };

    panel.addEventListener("click", openHistory);
    panel.addEventListener("keydown", openHistory);
  }

  return shell;
}

/**
 * Purpose: Close the close indian trail placement prompt workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function closeIndianTrailPlacementPrompt() {
  closeTimedScanConfirmation("indianTrailPlacementShell");
}

/**
 * Purpose: Open the show outbound rack transit prompt workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showOutboundRackTransitPrompt(result) {
  const rackCode = String(result?.rackCode || "").trim();
  if (!rackCode || !result?.rackDepartureAt) return;

  const spanish = state.language === "es";
  const destination = rackDestinationLabel(result.rackDestination || "Indian Trail");
  const pieceCount = Math.max(Number(result.rackPieceCount || result.outboundScannedQty || 0), 0);
  const pieceLabel = spanish
    ? `${pieceCount} pieza${pieceCount === 1 ? "" : "s"}`
    : `${pieceCount} piece${pieceCount === 1 ? "" : "s"}`;
  const title = spanish
    ? `El rack ${rackCode} va en camino a ${destination}`
    : `Rack ${rackCode} is on the way to ${destination}`;
  const detail = spanish
    ? `${pieceLabel} confirmadas en tránsito. El selector de estado ahora muestra este rack.`
    : `${pieceLabel} confirmed in transit. The status selector now shows this rack.`;

  mountTimedScanConfirmation({
    id: "outboundRackTransitShell",
    className: "is-outbound-transit",
    openAllScans: async () => openRecentScansModal(),
    markup: `
      <section class="indian-trail-placement-panel" role="status" aria-live="assertive">
        <div class="indian-trail-placement-icon" aria-hidden="true"></div>
        <div class="indian-trail-placement-copy">
          <small>${spanish ? "RACK ENVIADO DESDE SALIDA" : "OUTBOUND RACK RELEASED"}</small>
          <h2>${escapeHtml(title)}</h2>
          <p>${escapeHtml(detail)}</p>
        </div>
        <div class="outbound-rack-transit-summary">
          <small>${spanish ? "Estado de transporte" : "Transportation status"}</small>
          <strong>${spanish ? "En tránsito" : "In transit"}</strong>
          <span>${escapeHtml(pieceLabel)}</span>
        </div>
        <div class="indian-trail-placement-actions">
          <span class="timed-scan-open-hint">${spanish ? "Haga clic en el aviso para abrir Todos los escaneos" : "Click the notice to open All Scans"}</span>
          <button type="button" data-placement-close>${spanish ? "Listo" : "Done"} <span data-placement-countdown>12</span></button>
        </div>
        <i class="indian-trail-placement-timer" aria-hidden="true"></i>
      </section>
    `,
  });
}

/**
 * Show one compact, timed outcome card for every normal delivery-list scan.
 * The Indian Trail receiving workflow keeps its more specific bay-placement card.
 */
function showStageScanConfirmation(result, options = {}) {
  const entry = result?.lastScan || result || {};
  const item = entry.item || result?.item || {};
  const eventType = String(entry.eventType || entry.type || "").toLowerCase();
  const isNotice = !entry.ok && (
    eventType.includes("duplicate") ||
    eventType.includes("notice") ||
    eventType.includes("warning") ||
    Boolean(entry.overrideRequired)
  );
  const outcome = entry.ok ? "success" : isNotice ? "notice" : "error";
  const title = options.title || (entry.ok
    ? `${item.order || "Scan"}${item.item ? `-${item.item}` : ""} accepted`
    : isNotice
      ? (entry.message || result?.message || "Scan notice")
      : (entry.message || result?.message || "Scan not accepted"));
  const message = [options.message, result?.message, entry.message, entry.reason]
    .map((value) => String(value || "").trim())
    .filter((value, index, values) => value && values.indexOf(value) === index)
    .join(" - ");
  const stage = options.stageLabel || stageLabel(state.meta || {}) || state.meta?.stage || state.meta?.scanner || "Current stage";
  const enteredScan = String(options.rawScan || entry.barcode || result?.barcode || "").trim();
  const hasItemDetails = Boolean(item.order || item.item || item.customer || item.job || item.product || item.dimensions);
  const quantity = item.qty == null
    ? "-"
    : `${Math.max(Number(item.scanned || 0), 0)} / ${Math.max(Number(item.qty || 0), 0)}`;
  const currentRackCode = String(
    result?.rackCode
    || entry?.rackCode
    || item.rackCode
    || options.rackCode
    || "",
  ).trim();
  const selectedRackValue = currentRackCode || NO_RACK_SELECTION;
  const location = currentRackCode || locationLabel(item) || "-";
  const canCorrectRack = Boolean(entry.ok && item.id && canAssignRackLocation());
  const rackOptions = canCorrectRack
    ? groupedRackOptionsHtml(
        (state.racks || []).filter((rack) => !rackIsLockedForLineAssignment(rack) || String(rack.code) === currentRackCode),
        selectedRackValue,
        { includeNoRack: true, compactSelected: true },
      )
    : "";
  const eyebrow = outcome === "success" ? "SCAN ACCEPTED" : outcome === "notice" ? "SCAN NOTICE" : "SCAN ERROR";
  const statusLabel = outcome === "success" ? "Accepted" : outcome === "notice" ? "Review" : "Not accepted";
  const durationSeconds = outcome === "error" ? 10 : 8;
  const jobText = item.job || item.product || "-";

  const shell = mountTimedScanConfirmation({
    id: "stageScanConfirmationShell",
    className: `scan-result-confirmation is-${outcome}`,
    durationSeconds,
    openAllScans: async () => openRecentScansModal(),
    markup: `
      <section class="indian-trail-placement-panel scan-result-panel" role="${outcome === "error" ? "alert" : "status"}" aria-live="${outcome === "error" ? "assertive" : "polite"}">
        <header class="scan-result-header">
          <div class="indian-trail-placement-icon" aria-hidden="true"></div>
          <div class="indian-trail-placement-copy">
            <small>${escapeHtml(eyebrow)}</small>
            <h2>${escapeHtml(title)}</h2>
            <p>${escapeHtml(message || (entry.ok ? `${stage} quantity was updated.` : "Review the scan and try again."))}</p>
          </div>
          <div class="scan-result-status-stack">
            <span class="scan-result-status-badge">${escapeHtml(statusLabel)}</span>
            <span class="scan-result-stage-badge">${escapeHtml(stage)}</span>
          </div>
        </header>

        <div class="scan-result-compact-body">
          ${outcome === "error" ? `
            <div class="scan-result-error-guidance-v161" aria-label="Scan error details">
              <span><small>Entered scan</small><strong>${escapeHtml(enteredScan || "No value captured")}</strong></span>
              <span><small>What went wrong</small><strong>${escapeHtml(message || "The scanner could not accept this entry.")}</strong></span>
            </div>
          ` : ""}
          ${hasItemDetails ? `
            <div class="scan-result-compact-grid" aria-label="Scanned item details">
              <span class="is-primary"><small>Order / Item</small><strong>${escapeHtml(item.order || "-")}<i>/</i>${escapeHtml(item.item || "-")}</strong></span>
              <span class="is-customer"><small>Customer</small><strong title="${escapeHtml(item.customer || "-")}">${escapeHtml(item.customer || "-")}</strong></span>
              <span><small>Qty</small><strong>${escapeHtml(quantity)}</strong></span>
              <span><small>Dimensions</small><strong title="${escapeHtml(item.dimensions || "-")}">${escapeHtml(item.dimensions || "-")}</strong></span>
              <span class="is-job"><small>Glass / Job</small><strong title="${escapeHtml(jobText)}">${escapeHtml(jobText)}</strong></span>
              <span><small>Route</small><strong>${escapeHtml(routeLabel(item) || "-")}</strong></span>
              <span><small>Location</small><strong title="${escapeHtml(location)}">${escapeHtml(location)}</strong></span>
            </div>
          ` : ""}
          ${canCorrectRack ? `
            <label class="scan-result-rack-field scan-result-rack-field-compact">
              <span>Correct rack / truck</span>
              <select class="scan-result-location-rack-select-v385" data-scan-result-rack>${rackOptions}</select>
              <small data-scan-result-rack-status>${currentRackCode ? `Scanned into ${escapeHtml(rackLocationDisplayLabel(currentRackCode, item.rackName, item.rackType))}` : "No rack assigned"}</small>
            </label>
          ` : ""}
        </div>
        ${scanQuantityBoostMarkup(entry, scanEntryDisplayItem(entry) || item, { rackCode: currentRackCode })}

        <footer class="indian-trail-placement-actions scan-result-actions">
          <span class="timed-scan-open-hint">Select the card for All Scans</span>
          <button type="button" data-placement-close>Done <span data-placement-countdown>${durationSeconds}</span></button>
        </footer>
        <i class="indian-trail-placement-timer" aria-hidden="true"></i>
      </section>
    `,
  });

  const rackSelect = shell.querySelector("[data-scan-result-rack]");
  rackSelect?.addEventListener("change", async () => {
    const status = shell.querySelector("[data-scan-result-rack-status]");
    shell._setTimedEditInProgress?.(true);
    rackSelect.disabled = true;
    if (status) status.textContent = "Updating location...";
    try {
      await assignLineItemToRack(item.id, rackCodeForScan(rackSelect.value), { quiet: true });
      if (status) {
        if (rackSelect.value === NO_RACK_SELECTION) {
          status.textContent = "Rack location cleared";
        } else {
          const movedRack = rackForCode(rackSelect.value);
          const movedLabel = movedRack
            ? rackLocationDisplayLabel(movedRack.code, movedRack.name, movedRack.type)
            : rackSelect.value;
          status.textContent = `Moved to ${movedLabel}`;
        }
      }
      shell.classList.add("rack-change-saved");
      shell.classList.remove("rack-change-error");
    } catch (error) {
      rackSelect.value = currentRackCode || NO_RACK_SELECTION;
      if (status) status.textContent = error.message;
      shell.classList.add("rack-change-error");
      shell.classList.remove("rack-change-saved");
    } finally {
      rackSelect.disabled = false;
      syncCustomSelect(rackSelect);
      shell._setTimedEditInProgress?.(false);
    }
  });

  return shell;
}

/**
 * Show the same timed top-of-screen failure card for Scan-page and Bay Scanner errors.
 * This keeps serious validation and backend failures visible long enough for an operator
 * to read the entered value and the exact correction needed.
 */
function showScanFailureConfirmation(message, { stageLabel: failureStage = "Scanner", rawScan = "", title: failureTitle = "Scan not accepted" } = {}) {
  const detail = String(message || "The scanner could not accept this entry.").trim();
  scanFlash("error", "scan_error");
  return showStageScanConfirmation(
    { ok: false, eventType: "error", message: detail, barcode: rawScan },
    { stageLabel: failureStage, rawScan, title: failureTitle },
  );
}

/**
 * Purpose: Open the show indian trail placement prompt workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function showIndianTrailPlacementPrompt(result) {
  if (!result?.ok) return;
  const isRush = Boolean(result.rush);
  const directToTruck = isRush && Boolean(result.rushDirectToTruck);
  if (!directToTruck && !result.bayCode) return;
  await ensureScanBayOverrideBays().catch(() => {});
  closeIndianTrailPlacementPrompt();
  const item = result.lastScan?.item || {};
  const spanish = state.language === "es";
  const itemLabel = `${item.order || "item"}${item.item ? `-${item.item}` : ""}`;
  const priorityDate = result.priorityDeliveryDate ? formatDisplayDate(result.priorityDeliveryDate) : "";
  const oversizeBay = result.oversize && !directToTruck
    ? availableIndianTrailBays(result.bayCode).find((bay) => /oversize/i.test(`${bay.bayType || ""} ${bay.bayCategory || ""} ${bay.mapSection || ""} ${bay.displayName || ""}`))
    : null;
  const selectedCode = oversizeBay?.bayCode || result.bayCode || "";
  const placementBayLabel = bayLocationDisplayLabel(result.bayCode, result.bayDisplay || result.bayName);
  const placementBayShort = placementBayLabel.replace(/^Bay\s+/i, "") || String(result.bayCode || "").trim();
  const infoLabel = spanish ? "Orden escaneada" : "Scanned order";
  const customerLabel = spanish ? "Cliente" : "Customer";
  const jobLabel = "Job Nr.";
  const dimensionsLabel = spanish ? "Dimensiones" : "Dimensions";
  const quantityLabel = spanish ? "Cant." : "QTY";
  const priorityLabel = spanish ? "Entrega prioritaria" : "Priority delivery";
  const handlingLabel = spanish ? "Manejo" : "Handling";
  const orderHeroLabel = spanish ? "COLOQUE ESTA ORDEN EN" : "PLACE THIS ORDER IN";
  const bayHeroPrefix = spanish ? "BAHIA" : "BAY";
  const overrideBayLabel = isRush ? (spanish ? "Bahia urgente" : "Priority Rush bay") : (spanish ? "Cambiar bahia" : "Override bay");
  const moveBayLabel = isRush ? (spanish ? "Mover a bahia urgente seleccionada" : "Move to selected Rush bay") : (spanish ? "Move to the selected bay" : "Move to selected bay");
  const directTruckLabel = spanish ? "Camion del instalador — omitir bahia" : "Installer truck — skip bay";
  const metaPills = [];
  // v0.457: floor operators identify the job first, then customer. Dimensions
  // and total piece quantity are included here so the receive instruction can
  // be verified without looking back at the Scan table.
  metaPills.push(`<span class="indian-trail-placement-meta-pill-v453 is-job-v457"><b>${escapeHtml(jobLabel)}</b><strong>${escapeHtml(item.job || "-")}</strong></span>`);
  metaPills.push(`<span class="indian-trail-placement-meta-pill-v453 is-customer-v457"><b>${escapeHtml(customerLabel)}</b><strong>${escapeHtml(item.customer || "-")}</strong></span>`);
  metaPills.push(`<span class="indian-trail-placement-meta-pill-v453 is-dimensions-v457"><b>${escapeHtml(dimensionsLabel)}</b><strong>${escapeHtml(item.dimensions || "-")}</strong></span>`);
  metaPills.push(`<span class="indian-trail-placement-meta-pill-v453 is-qty-v457"><b>${escapeHtml(quantityLabel)}</b><strong>${escapeHtml(item.qty == null ? "-" : String(item.qty))}</strong></span>`);
  if (priorityDate && isRush) metaPills.push(`<span class="indian-trail-placement-meta-pill-v453 is-priority"><b>${escapeHtml(priorityLabel)}</b><strong>${escapeHtml(priorityDate)}</strong></span>`);
  if (directToTruck) {
    metaPills.push(`<span class="indian-trail-placement-meta-pill-v453 is-direct"><b>${escapeHtml(handlingLabel)}</b><strong>${escapeHtml(directTruckLabel)}</strong></span>`);
  } else if (result.oversize) {
    metaPills.push(`<span class="indian-trail-placement-meta-pill-v453 is-warning"><b>${escapeHtml(handlingLabel)}</b><strong>${escapeHtml(spanish ? "Vidrio sobredimensionado" : "Oversize glass")}</strong></span>`);
  } else if (result.returnedToBay) {
    metaPills.push(`<span class="indian-trail-placement-meta-pill-v453"><b>${escapeHtml(handlingLabel)}</b><strong>${escapeHtml(spanish ? "Articulo devuelto" : "Returned item")}</strong></span>`);
  }
  const shell = mountTimedScanConfirmation({
    id: "indianTrailPlacementShell",
    className: `${isRush ? "is-rush" : ""}${directToTruck ? `${isRush ? " " : ""}is-direct-to-truck` : ""}`,
    openAllScans: async () => openBayAllScansModal(),
    markup: `
      <section class="indian-trail-placement-panel" role="status" aria-live="assertive">
        <div class="indian-trail-placement-icon" aria-hidden="true"></div>
        <div class="indian-trail-placement-copy indian-trail-placement-copy-v453">
          <small>${escapeHtml(infoLabel)}</small>
          <h2>${escapeHtml(itemLabel)}</h2>
          <div class="indian-trail-placement-meta-v453">${metaPills.join("")}</div>
        </div>
        ${directToTruck ? `
          <div class="indian-trail-rush-destination">
            <small>${spanish ? "Destino" : "Destination"}</small>
            <strong>${escapeHtml(directTruckLabel)}</strong>
          </div>
        ` : `
          <div class="indian-trail-placement-destination-v321">
            <small>${escapeHtml(orderHeroLabel)}</small>
            <strong>${escapeHtml(bayHeroPrefix)} ${escapeHtml(placementBayShort)}</strong>
          </div>
          <div class="indian-trail-placement-actions indian-trail-placement-controls-v453">
            <label class="indian-trail-placement-field">
              <span>${escapeHtml(overrideBayLabel)}</span>
              <select data-placement-bay>
                ${indianTrailBayOptionsHtml(selectedCode)}
              </select>
            </label>
            <button type="button" data-placement-move ${result.assignmentId ? "" : "disabled"}>${escapeHtml(moveBayLabel)}</button>
          </div>
        `}
        ${scanQuantityBoostMarkup(result.lastScan || {}, scanEntryDisplayItem(result.lastScan || {}) || item, { bayCode: result.bayCode || "" })}
        <div class="indian-trail-placement-footer-v453">
          <span class="timed-scan-open-hint">${spanish ? "Haga clic en el aviso para abrir Todos los escaneos" : "Click the notice to open All Scans"}</span>
          <button type="button" data-placement-close>${spanish ? "Listo" : "Done"} <span data-placement-countdown>12</span></button>
        </div>
        <i class="indian-trail-placement-timer" aria-hidden="true"></i>
      </section>
    `,
  });
  shell.querySelector("[data-placement-move]")?.addEventListener("click", async () => {
    const newBayCode = shell.querySelector("[data-placement-bay]")?.value || "";
    if (!newBayCode || newBayCode === result.bayCode) {
      closeIndianTrailPlacementPrompt();
      return;
    }
    try {
      await postBayAction("/api/indian-trail/move", {
        assignmentId: result.assignmentId,
        newBayCode,
        reason: `${isRush ? "Rush " : ""}placement popup override from ${result.bayCode}`,
      });
      showFloatingNotice(`Moved ${item.order || "item"}-${item.item || ""} to ${newBayCode}.`, "success");
      closeIndianTrailPlacementPrompt();
    } catch (error) {
      showFloatingNotice(error.message, "error");
    }
  });
}

/**
 * Purpose: Run the process scan workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function crossDateCandidateStatus(candidate) {
  if (candidate.complete) return { label: "Complete", className: "is-complete" };
  if (candidate.requiresConfirmation) return { label: "Review required", className: "needs-review" };
  return { label: "Ready to scan", className: "is-ready" };
}

/** Ask the operator to choose a cross-date match without changing scanner state prematurely. */
function showCrossDateScanSelection(payload) {
  return new Promise((resolve) => {
    document.querySelector(".cross-date-scan-backdrop")?.remove();
    const candidates = Array.isArray(payload.candidates) ? payload.candidates : [];
    const dialog = document.createElement("div");
    dialog.className = "action-confirm-backdrop cross-date-scan-backdrop";
    dialog.innerHTML = `
      <section class="cross-date-scan-dialog" role="dialog" aria-modal="true" aria-labelledby="crossDateScanTitle">
        <button type="button" class="action-confirm-close gui-close-button" data-cross-date-cancel aria-label="Close cross-date selection">&times;</button>
        <header class="cross-date-scan-heading">
          <span class="cross-date-scan-icon" aria-hidden="true"></span>
          <div>
            <small>Selected date: ${escapeHtml(formatDisplayDate(payload.originalDeliveryDate || ""))}</small>
            <h2 id="crossDateScanTitle">${escapeHtml(candidates.length === 1 ? "Item found on another delivery date" : "Choose the correct delivery date")}</h2>
            <p>${escapeHtml(payload.message || "Confirm the delivery list before the scan is applied.")}</p>
          </div>
        </header>
        <div class="cross-date-scan-list">
          ${candidates.map((candidate) => {
            const status = crossDateCandidateStatus(candidate);
            const safetyReason = String(candidate.safetyReason || "").trim();
            return `
              <article class="cross-date-scan-card ${status.className}">
                <div class="cross-date-scan-date">
                  <small>Delivery date</small>
                  <strong>${escapeHtml(formatDisplayDate(candidate.deliveryDate || ""))}</strong>
                  <span>${escapeHtml(candidate.stage || "Stage")} &middot; ${escapeHtml(candidate.scanner || "Scanner")}</span>
                </div>
                <div class="cross-date-scan-order">
                  <small>Order / Item</small>
                  <strong>${escapeHtml(candidate.order || "-")} / ${escapeHtml(candidate.item || "-")}</strong>
                  <span>${escapeHtml(candidate.customer || "No customer")}</span>
                </div>
                <div class="cross-date-scan-details">
                  <span><small>Progress</small><b>${escapeHtml(candidate.scannedQty || 0)} / ${escapeHtml(candidate.qty || 0)}</b></span>
                  <span><small>Route</small><b>${escapeHtml(candidate.route || "Indian Trail")}</b></span>
                  <span><small>Location</small><b>${escapeHtml(candidate.location || "Not assigned")}</b></span>
                </div>
                <div class="cross-date-scan-decision">
                  <span class="cross-date-scan-status ${status.className}">${escapeHtml(status.label)}</span>
                  ${safetyReason ? `<p>${escapeHtml(safetyReason)}</p>` : ""}
                  <button type="button" data-cross-date-list="${escapeHtml(candidate.listId || "")}" ${candidate.selectable ? "" : "disabled"}>
                    ${candidate.requiresConfirmation ? "Select and review" : "Switch date and scan"}
                  </button>
                </div>
              </article>
            `;
          }).join("") || `<div class="admin-empty">No accessible delivery-list match remains available.</div>`}
        </div>
        <footer class="cross-date-scan-footer">
          <span>Only the selected candidate will be scanned. Closing this window leaves the current delivery date unchanged.</span>
          <button type="button" class="app-cancel-action-v343" data-cross-date-cancel><span class="app-cancel-icon-v343" aria-hidden="true"></span><span>Cancel Scan</span></button>
        </footer>
      </section>
    `;

    const close = (candidate = null) => {
      document.removeEventListener("keydown", keyHandler);
      dialog.remove();
      updateModalScrollLock();
      resolve(candidate);
    };
    const keyHandler = (event) => {
      if (event.key === "Escape") close(null);
    };
    dialog.addEventListener("click", (event) => {
      if (event.target === dialog || event.target.closest("[data-cross-date-cancel]")) {
        close(null);
        return;
      }
      const button = event.target.closest("[data-cross-date-list]");
      if (!button || button.disabled) return;
      close(candidates.find((candidate) => String(candidate.listId) === String(button.dataset.crossDateList)) || null);
    });
    document.addEventListener("keydown", keyHandler);
    document.body.appendChild(dialog);
    applyLanguageToRoot(dialog);
    updateModalScrollLock();
    dialog.querySelector("[data-cross-date-list]:not(:disabled), [data-cross-date-cancel]")?.focus();
  });
}

function syncCrossDateListSummary(payload) {
  const matchedListId = String(payload.matchedListId || payload.meta?.id || "");
  const index = state.lists.findIndex((list) => String(list.id || "") === matchedListId);
  if (index < 0 || !Array.isArray(payload.items)) return;
  const totalQty = payload.items.reduce((sum, item) => sum + Number(item.qty || 0), 0);
  const scannedQty = payload.items.reduce((sum, item) => sum + Number(item.scanned || 0), 0);
  state.lists[index] = { ...state.lists[index], totalQty, scannedQty };
}

function showCrossDateSwitchNotice(payload) {
  document.querySelector(".cross-date-switch-notice")?.remove();
  const notice = document.createElement("section");
  notice.className = "cross-date-switch-notice";
  notice.setAttribute("role", "status");
  notice.setAttribute("aria-live", "assertive");
  notice.innerHTML = `
    <span class="cross-date-switch-icon" aria-hidden="true"></span>
    <div><small>Delivery date changed</small><strong>${escapeHtml(payload.crossDateMessage || "The scan was applied to another delivery date.")}</strong>${payload.crossDateSafetyReason ? `<p>${escapeHtml(payload.crossDateSafetyReason)}</p>` : ""}</div>
    <button type="button" class="gui-close-button" aria-label="Close delivery-date notice">&times;</button>
  `;
  const close = () => notice.remove();
  notice.querySelector("button")?.addEventListener("click", close);
  document.body.appendChild(notice);
  applyLanguageToRoot(notice);
  window.setTimeout(close, 7000);
}

async function applyCrossDateSwitchUi(payload, { activateMatched = false } = {}) {
  if (!payload?.crossDateSwitched) return;
  const matchedListId = String(payload.matchedListId || payload.meta?.id || "");
  if (activateMatched && matchedListId && matchedListId !== state.activeListId) {
    await activateList(matchedListId, false);
  }
  if (payload.crossDateClearRack && !payload.destinationOverrideRequired) {
    state.selectedScanRackCode = NO_RACK_SELECTION;
  }
  syncCrossDateListSummary(payload);
  renderDeliveryListSelect();
  syncAllCustomSelects();
  if (matchedListId) {
    const lineFlags = await fetchJson(`/api/operations/line-flags?listId=${encodeURIComponent(matchedListId)}`).catch(() => null);
    if (lineFlags) applyOperationalLineFlags(lineFlags, matchedListId);
  }
  if ((isStagingScanContext() || isOutboundScanContext()) && state.racks.length) {
    await ensureRacksLoaded(true).catch(() => {});
  }
  renderScanPage();
  showCrossDateSwitchNotice(payload);
}

function processScan(rawScan, options = {}) {
  const operation = Promise.resolve().then(() => processScanInternal(rawScan, options));
  state.activeScanOperations.add(operation);
  /**
   * Purpose: Run the cleanup workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const cleanup = () => {
    state.activeScanOperations.delete(operation);
    if (!state.activeScanOperations.size) window.setTimeout(() => presentNextUserNotification(), 0);
  };
  operation.then(cleanup, cleanup);
  return operation;
}

/**
 * Purpose: Run the process scan internal workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function processScanInternal(rawScan, options = {}) {
  const scanText = rawScan.trim();
  if (!scanText || !state.activeListId) return;
  if (state.backend) {
    const indianTrailReceive =
      hasPermission("receive_indian_trail") &&
      isIndianTrailScanContext();
    if (indianTrailReceive) {
      const requestedBayCode = options.bayCode || (state.bayOverrideMode === "manual" ? state.selectedBayOverrideCode || "" : "");
      const usedManualBayAssignment = state.bayOverrideMode === "manual" && Boolean(requestedBayCode);
      if (state.bayOverrideMode === "manual" && !state.selectedBayOverrideCode && !options.bayCode) {
        els.scanBayOverrideSelect?.focus();
        throw new Error("Choose a manual Indian Trail bay before scanning, or switch bay assignment back to Auto.");
      }
      const result = await fetchJson("/api/indian-trail/receive", {
        method: "POST",
        body: JSON.stringify({
          listId: state.activeListId,
          barcode: scanText,
          bayCode: requestedBayCode,
          outboundOverride: Boolean(options.outboundOverride),
          allowReceivedOverride: Boolean(options.allowReceivedOverride),
          isManual: Boolean(options.isManual),
          scanQty: Math.max(1, Math.trunc(Number(options.scanQty || 1))),
          crossDateListId: options.crossDateListId || "",
          crossDateConfirmed: Boolean(options.crossDateConfirmed),
          ...requestContext(),
        }),
      });
      if (result.crossDateSelectionRequired) {
        scanFlash("notice", "scan_warning");
        const candidate = await showCrossDateScanSelection(result);
        if (candidate) {
          await processScan(scanText, {
            ...options,
            crossDateListId: candidate.listId,
            crossDateConfirmed: true,
          });
        }
        return;
      }

      state.lastScan = result.lastScan || state.lastScan;

      if (result.outboundOverrideRequired) {
        if (result.crossDateSwitched) await applyCrossDateSwitchUi(result, { activateMatched: true });
        scanFlash("notice", "scan_warning");
        const decision = await showIndianTrailOutboundReceiveOverride(result, scanText, options);
        if (decision) {
          await processScan(scanText, {
            ...options,
            bayCode: decision.bayCode,
            outboundOverride: true,
          });
        } else {
          await activateList(state.activeListId, false);
          renderScanPage();
        }
        return;
      }

      if (result.ok && usedManualBayAssignment) {
        // Manual placement is intentionally a one-scan override. After success,
        // restore Auto and return the disabled selector to its auto-suggested option.
        resetScanBayOverrideToAutoV443();
      }

      await activateList(result.matchedListId || state.activeListId, false, {
        selectionFallbackId: result.ok ? result.lastScan?.item?.id : "",
      });
      if (result.ok && usedManualBayAssignment) {
        await refreshScanBayOverrideAfterReceiveV443().catch(() => {
          resetScanBayOverrideToAutoV443();
        });
      }
      scanFlash(
        result.ok ? "success" : "error",
        result.crossDateSwitched && result.ok
          ? "delivery_date_changed"
          : (result.ok ? "bay_assigned" : scanSoundKind(result.lastScan || result, "scan_error")),
      );
      renderScanPage();
      if (result.crossDateSwitched) await applyCrossDateSwitchUi(result);
      await refreshBayMapPage().catch(() => {});
      if (result.ok) {
        await showIndianTrailPlacementPrompt(result);
      } else {
        showStageScanConfirmation(result);
      }
      return;
    }
    const rackSelection = Object.prototype.hasOwnProperty.call(options, "rackCode")
      ? options.rackCode
      : (isStagingScanContext() ? state.selectedScanRackCode : "");
    const payload = await fetchJson("/api/scans", {
      method: "POST",
      body: JSON.stringify({
        listId: state.activeListId,
        barcode: scanText,
        rackCode: rackCodeForScan(rackSelection),
        outboundOverride: Boolean(options.outboundOverride),
        destinationOverride: Boolean(options.destinationOverride),
        isManual: Boolean(options.isManual),
        scanQty: Math.max(1, Math.trunc(Number(options.scanQty || 1))),
        crossDateListId: options.crossDateListId || "",
        crossDateConfirmed: Boolean(options.crossDateConfirmed),
        ...requestContext(),
      }),
    });
    if (payload.crossDateSelectionRequired) {
      scanFlash("notice", "scan_warning");
      const candidate = await showCrossDateScanSelection(payload);
      if (candidate) {
        await processScan(scanText, {
          ...options,
          crossDateListId: candidate.listId,
          crossDateConfirmed: true,
        });
      }
      return;
    }
    applyBackendPayload(payload, {
      selectionFallbackId: payload.lastScan?.ok ? payload.lastScan?.item?.id : "",
    });
    const outboundRackDeparture = Boolean(
      isOutboundScanContext() &&
      payload.rackCode &&
      payload.rackDepartureAt,
    );
    if (outboundRackDeparture) {
      state.selectedOutboundRackCode = String(payload.rackCode || "").trim();
    }
    if (payload.destinationOverrideRequired) {
      scanFlash("notice", "scan_warning");
      renderScanPage();
      if (payload.crossDateSwitched) await applyCrossDateSwitchUi(payload);
      const approved = await showRackDestinationOverrideDialog(payload);
      if (approved) {
        await processScan(scanText, { ...options, destinationOverride: true });
      }
      return;
    }
    if (payload.outboundOverrideRequired) {
      scanFlash("error", "scan_warning");
      renderScanPage();
      if (payload.crossDateSwitched) await applyCrossDateSwitchUi(payload);
      await showOutboundOverrideDialog(payload, scanText, options);
      return;
    }
    if (payload.racks) {
      state.racks = payload.racks || state.racks;
      state.rackSummary = payload.rackSummary || state.rackSummary;
    } else if (outboundRackDeparture) {
      await ensureRacksLoaded(true).catch(() => {});
    } else if ((isStagingScanContext() || isOutboundScanContext()) && state.racks.length) {
      // A scan can complete/reopen a rack server-side even when the scan payload
      // omits the rack catalog. Always refresh the cached lifecycle state so the
      // Location color/status reflects the backend immediately.
      void ensureRacksLoaded(true).catch(() => {});
    }
    const acceptedRackBarcode = Boolean(
      isRackBarcodeScan(scanText) &&
      (payload.lastScan ? payload.lastScan.ok : (payload.ok || outboundRackDeparture)),
    );
    scanFlash(
      payload.lastScan?.ok ? "success" : payload.lastScan?.eventType === "duplicate" || payload.lastScan?.eventType === "notice" ? "notice" : "error",
      payload.crossDateSwitched && payload.lastScan?.ok
        ? "delivery_date_changed"
        : acceptedRackBarcode
          ? (outboundRackDeparture ? "rack_outbound" : "rack_barcode")
          : scanSoundKind(payload.lastScan, payload.lastScan?.ok ? (payload.rackCode ? "rack_item_added" : "scan_success") : "scan_error"),
    );
    renderScanPage();
    if (payload.crossDateSwitched) await applyCrossDateSwitchUi(payload);
    if (outboundRackDeparture) {
      showOutboundRackTransitPrompt(payload);
    } else {
      showStageScanConfirmation(payload, { rackCode: rackCodeForScan(rackSelection) });
    }
    return;
  }
  processLocalScan(scanText, options);
}

/**
 * Purpose: Process the submit manual scan workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function submitManualScan() {
  const order = digitsOnly(els.manualOrderInput?.value || "");
  const item = digitsOnly(els.manualItemInput?.value || "");
  if (!order || !item) {
    throw new Error("Manual scan needs an order number and item number.");
  }
  if (!/^\d{6}$/.test(order)) {
    throw new Error("Manual scan order numbers must contain exactly six digits.");
  }
  if (!/^\d{1,3}$/.test(item)) {
    throw new Error("Manual scan item numbers must contain one to three digits.");
  }
  const scanQty = Math.trunc(Number(els.manualScanQtyInput?.value || 1));
  if (!Number.isFinite(scanQty) || scanQty < 1 || scanQty > 999) {
    throw new Error("Manual scan quantity must be between 1 and 999.");
  }
  await processScan(canonicalBarcode(order, item), { isManual: true, scanQty });
  if (els.manualOrderInput) els.manualOrderInput.value = "";
  if (els.manualItemInput) els.manualItemInput.value = "";
  if (els.manualScanQtyInput) els.manualScanQtyInput.value = "1";
  els.scanInput?.focus();
}

/**
 * Purpose: Run the process local scan workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function processLocalScan(scanText, options = {}) {
  const recovered = recoverScan(scanText, { strictOrderItem: Boolean(options.isManual) });
  const timestamp = new Date().toISOString();
  if (!recovered.ok) {
    const noListMatch = ["No unique delivery-list match", "No exact order/item match"].includes(recovered.reason);
    const entry = {
      ok: false,
      eventType: "error",
      barcode: scanText,
      message: noListMatch ? "Item is not on this delivery list" : "Unable to match this scan",
      reason: noListMatch
        ? "Check the delivery date and stage. This barcode may belong to another delivery list."
        : recovered.reason,
      time: timestamp,
    };
    state.errors.unshift(entry);
    state.recent.unshift(entry);
    state.lastScan = entry;
    scanFlash("error", "scan_error");
    saveState();
    renderScanPage();
    showStageScanConfirmation(entry, { local: true });
    return;
  }
  const item = recovered.item;
  if (item.scanned >= item.qty) {
    const entry = { ok: false, eventType: "duplicate", barcode: recovered.barcode, item, message: "Item already complete", reason: "Quantity already scanned", time: timestamp };
    state.recent.unshift(entry);
    state.lastScan = entry;
    scanFlash("notice", "scan_duplicate");
    saveState();
    renderScanPage();
    showStageScanConfirmation(entry, { local: true });
    return;
  }
  const requestedQty = Math.max(1, Math.trunc(Number(options.scanQty || 1)));
  const qtyDelta = Math.min(requestedQty, Math.max(Number(item.qty || 0) - Number(item.scanned || 0), 0));
  item.scanned += qtyDelta;
  state.selectedId = item.id;
  const entry = { ok: true, eventType: options.isManual ? "manual_scan" : "scan", isManual: Boolean(options.isManual), barcode: recovered.barcode, raw: scanText, qtyDelta, item, message: recovered.reason, time: timestamp };
  state.recent.unshift(entry);
  state.lastScan = entry;
  scanFlash("success", scanSoundKind(entry));
  saveState();
  renderScanPage();
  showStageScanConfirmation(entry, { local: true });
}

/**
 * Purpose: Build the build indexes workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function buildIndexes() {
  const byOrderItem = new Map();
  const bySuffixItem = new Map();
  for (const item of state.items) {
    const orderItemKey = `${Number(item.order)}-${Number(item.item)}`;
    const orderMatches = byOrderItem.get(orderItemKey) || [];
    orderMatches.push(item);
    byOrderItem.set(orderItemKey, orderMatches);
    const suffixKey = `${pad(item.order, 6).slice(-3)}-${Number(item.item)}`;
    const suffixMatches = bySuffixItem.get(suffixKey) || [];
    suffixMatches.push(item);
    bySuffixItem.set(suffixKey, suffixMatches);
  }
  return { byOrderItem, bySuffixItem };
}

/**
 * Purpose: Run the recover scan workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
function recoverScan(rawScan, { strictOrderItem = false } = {}) {
  const cleanText = cleanBarcode(rawScan);
  const { byOrderItem, bySuffixItem } = buildIndexes();
  if (/^T200\d{12}$/.test(cleanText)) {
    const order = Number(cleanText.slice(4, 10));
    const item = Number(cleanText.slice(10, 13));
    const matches = byOrderItem.get(`${order}-${item}`) || [];
    if (matches.length === 1) return { ok: true, item: matches[0], barcode: cleanText, reason: strictOrderItem ? "Exact manual order/item" : "Exact label" };
    if (matches.length > 1) return { ok: false, barcode: cleanText, reason: "Ambiguous delivery-list match" };
    if (strictOrderItem) return { ok: false, barcode: cleanText, reason: "No exact order/item match" };
  }
  if (strictOrderItem) return { ok: false, barcode: cleanText, reason: "Manual scans require an exact six-digit order and one-to-three-digit item" };
  const numbers = digitsOnly(cleanText);
  for (let start = 0; start <= numbers.length - 12; start += 1) {
    const windowText = numbers.slice(start, start + 12);
    const order = Number(windowText.slice(0, 6));
    const item = Number(windowText.slice(6, 9));
    const matches = byOrderItem.get(`${order}-${item}`) || [];
    if (matches.length === 1) return { ok: true, item: matches[0], barcode: canonicalBarcode(order, item), reason: "Recovered order/item" };
    if (matches.length > 1) return { ok: false, barcode: canonicalBarcode(order, item), reason: "Ambiguous delivery-list match" };
  }
  for (let start = 0; start <= numbers.length - 9; start += 1) {
    const windowText = numbers.slice(start, start + 9);
    const suffix = windowText.slice(0, 3);
    const itemNumber = Number(windowText.slice(3, 6));
    const matches = bySuffixItem.get(`${suffix}-${itemNumber}`);
    if (matches && matches.length === 1) {
      const match = matches[0];
      return { ok: true, item: match, barcode: canonicalBarcode(match.order, itemNumber), reason: "Recovered suffix/item" };
    }
    if (matches && matches.length > 1) return { ok: false, barcode: cleanText, reason: "Ambiguous delivery-list match" };
  }
  return { ok: false, barcode: cleanText, reason: "No unique delivery-list match" };
}

/**
 * Purpose: Run the reset state workflow for the browser application.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function resetState() {
  if (state.backend) {
    const payload = await fetchJson("/api/reset", {
      method: "POST",
      body: JSON.stringify({ listId: state.activeListId, confirmText: "RESET", ...requestContext() }),
    });
    applyBackendPayload(payload);
    renderScanPage();
    playAppSound("destructive_action", { force: true });
    return;
  }
  for (const item of state.items) item.scanned = 0;
  state.recent = [];
  state.errors = [];
  state.selectedId = null;
  state.lastScan = null;
  saveState();
  renderScanPage();
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Open the show inline error workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showInlineError(message, needsReview = false) {
  const entry = { ok: false, eventType: needsReview ? "error" : "notice", barcode: "SYSTEM", message: "System notice", reason: message, time: new Date().toISOString() };
  if (needsReview) state.errors.unshift(entry);
  state.recent.unshift(entry);
  state.lastScan = entry;

  if (state.page === "scan") {
    scanFlash(needsReview ? "error" : "notice");
    showFloatingNotice(message, needsReview ? "error" : "notice");
    renderScanPage();
    // User-triggered rack/location and configuration failures must not hide in
    // Last Scan. A blocking error now receives the same plain-language popup
    // used elsewhere, while lightweight notices remain nonmodal.
    if (!needsReview) return;
  }

  showActionFeedback({
    kind: needsReview ? "error" : "warning",
    eyebrow: needsReview ? "Action failed" : "Action unavailable",
    title: needsReview ? "Could not complete that action" : "That action is blocked",
    message,
    secondaryLabel: "Got it",
  });
}

/**
 * Purpose: Open the show floating notice workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showFloatingNotice(message, kind = "notice") {
  let notice = document.getElementById("floatingScanNotice");
  if (!notice) {
    notice = document.createElement("div");
    notice.id = "floatingScanNotice";
    notice.className = "floating-scan-notice";
    document.body.appendChild(notice);
  }
  notice.className = `floating-scan-notice ${kind}`;
  notice.innerHTML = `<strong>${escapeHtml(kind === "success" ? "Scan accepted" : kind === "error" ? "Needs review" : "Notice")}</strong><span>${escapeHtml(message)}</span>`;
  notice.classList.remove("is-hiding");
  window.clearTimeout(notice._hideTimer);
  notice._hideTimer = window.setTimeout(() => {
    notice.classList.add("is-hiding");
  }, 5200);
}

/**
 * Purpose: Close the close action feedback workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function closeActionFeedback() {
  document.getElementById("actionFeedbackShell")?.remove();
  updateModalScrollLock();
  window.setTimeout(() => presentNextUserNotification(), 120);
}

/**
 * Purpose: Open the show action feedback workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showActionFeedback({
  kind = "success",
  eyebrow = "Update complete",
  title = "Saved successfully",
  message = "",
  details = [],
  primaryLabel = "",
  secondaryLabel = "Done",
  onPrimary = null,
  onSecondary = null,
} = {}) {
  closeActionFeedback();

  const shell = document.createElement("div");
  shell.id = "actionFeedbackShell";
  shell.className = `action-feedback-shell ${kind}`;
  const detailRows = details
    .filter((detail) => detail && detail.value !== undefined && detail.value !== null && String(detail.value).trim())
    .map((detail) => `
      <div class="action-feedback-detail">
        <small>${escapeHtml(detail.label || "Details")}</small>
        <strong>${escapeHtml(detail.value)}</strong>
      </div>
    `)
    .join("");

  shell.innerHTML = `
    <button class="action-feedback-backdrop" type="button" data-action-feedback-close aria-label="Close"></button>
    <section class="action-feedback-panel" role="dialog" aria-modal="true" aria-labelledby="actionFeedbackTitle">
      <div class="action-feedback-icon" aria-hidden="true"><i></i></div>
      <div class="action-feedback-copy">
        <small>${escapeHtml(eyebrow)}</small>
        <h2 id="actionFeedbackTitle">${escapeHtml(title)}</h2>
        ${message ? `<p>${escapeHtml(message)}</p>` : ""}
      </div>
      ${detailRows ? `<div class="action-feedback-details">${detailRows}</div>` : ""}
      <div class="action-feedback-actions">
        ${primaryLabel ? `<button class="action-feedback-primary" type="button" data-action-feedback-primary>${escapeHtml(primaryLabel)}</button>` : ""}
        <button class="action-feedback-secondary" type="button" data-action-feedback-secondary>${escapeHtml(secondaryLabel)}</button>
      </div>
    </section>
  `;

  document.body.appendChild(shell);
  if (state.language === "es") applyLanguageToRoot(shell);
  updateModalScrollLock();

  /**
   * Purpose: Close the close with secondary workflow using the existing shared UI state.
   * Effects: Updates visible dom state.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const closeWithSecondary = async () => {
    try {
      if (typeof onSecondary === "function") await onSecondary();
    } finally {
      closeActionFeedback();
    }
  };

  shell.querySelector("[data-action-feedback-close]")?.addEventListener("click", closeWithSecondary);
  shell.querySelector("[data-action-feedback-secondary]")?.addEventListener("click", closeWithSecondary);
  shell.querySelector("[data-action-feedback-primary]")?.addEventListener("click", async () => {
    try {
      if (typeof onPrimary === "function") await onPrimary();
    } finally {
      closeActionFeedback();
    }
  });
  shell.querySelector("[data-action-feedback-primary], [data-action-feedback-secondary]")?.focus();
}

function showBlockedAction(message, title = "That action is blocked") {
  showActionFeedback({
    kind: "warning",
    eyebrow: "Action unavailable",
    title,
    message: String(message || "This action is not available in the rack's current state."),
    secondaryLabel: "Got it",
  });
}

document.addEventListener("click", (event) => {
  const blockedControl = event.target.closest?.("[data-blocked-reason]");
  if (!blockedControl) return;
  event.preventDefault();
  event.stopImmediatePropagation();
  showBlockedAction(
    blockedControl.dataset.blockedReason || "This action is currently unavailable.",
    blockedControl.dataset.blockedTitle || "That action is blocked",
  );
}, true);

// v0.353: last-resort UI error boundary. Individual workflows still provide
// specific validation messages, while unexpected runtime/promise failures now
// produce an operator-readable in-app popup instead of silently stopping work.
const unexpectedErrorUi = { handling: false, lastKey: "", lastShownAt: 0 };

function showUnexpectedAppError(error, context = "Application error") {
  if (unexpectedErrorUi.handling) return;
  const rawMessage = error instanceof Error ? error.message : String(error || "Unexpected application error");
  const message = rawMessage.trim() || "The action stopped before it could finish.";
  const key = `${context}::${message}`;
  const now = Date.now();
  if (key === unexpectedErrorUi.lastKey && now - unexpectedErrorUi.lastShownAt < 2500) return;

  unexpectedErrorUi.handling = true;
  unexpectedErrorUi.lastKey = key;
  unexpectedErrorUi.lastShownAt = now;
  try {
    console.error(context, error);
    showActionFeedback({
      kind: "error",
      eyebrow: "Something went wrong",
      title: "The action could not finish",
      message,
      details: [{ label: "Where", value: context }],
      secondaryLabel: "Got it",
    });
  } finally {
    unexpectedErrorUi.handling = false;
  }
}

window.addEventListener("error", (event) => {
  if (!event?.error && !event?.message) return;
  showUnexpectedAppError(event.error || event.message, "Web app runtime");
});

window.addEventListener("unhandledrejection", (event) => {
  showUnexpectedAppError(event?.reason, "Background action");
});

/**
 * Purpose: Confirm that an explicit save/create action completed successfully.
 * Effects: Reuses the single polished action-feedback component for all settings and
 * maintenance saves so users receive consistent confirmation without duplicate popup code.
 * Flow: Accepts a concise message and optional detail rows, then opens the shared success
 * dialog with one Done button. Scans and background refreshes do not call this helper.
 */
function showSaveConfirmation(message = "Your changes are now active.", details = []) {
  playAppSound("save");
  showActionFeedback({
    kind: "success",
    eyebrow: "Save complete",
    title: "Saved successfully",
    message,
    details,
    secondaryLabel: "Done",
  });
}

/**
 * Purpose: Decide whether one application notification is a real operator Rush alert.
 * Effects: None.
 * Flow: Rejects import, review, and automation notices before they can enter the full-screen production-priority queue.
 */
function isRushPopupNotification(notification) {
  const type = String(notification?.type || "").trim().toLowerCase();
  const details = notification?.details || {};
  const source = String(details.source || "").trim().toLowerCase();
  const createdBy = String(notification?.createdBy || details.submittedBy || "").trim().toLowerCase();

  if (type !== "rush") return false;
  if (["sql-delivery-automation", "superseded-order-review", "delivery-import"].includes(source)) return false;
  if (createdBy.startsWith("sql-auto") || createdBy.includes("automation")) return false;
  return true;
}

/**
 * Purpose: Determine whether a Rush popup can interrupt the current Scan workflow.
 * Effects: None.
 * Flow: Keeps only explicit operator Rush submissions in the production-priority queue.
 */
function rushNotificationIsBlocked() {
  return Boolean(
    state.page !== "scan" ||
    state.rushRedirectInProgress ||
    state.activeScanOperations.size ||
    String(els.scanInput?.value || "").trim() ||
    document.getElementById("actionFeedbackShell") ||
    document.getElementById("rushAlertShell") ||
    (els.adminModal && !els.adminModal.hidden) ||
    (els.printOptionsPanel && !els.printOptionsPanel.hidden) ||
    (els.sdiPanel && !els.sdiPanel.hidden)
  );
}

/**
 * Purpose: Run the acknowledge user notification workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function acknowledgeUserNotification(notificationId) {
  const cleanId = Number(notificationId || 0);
  if (!cleanId || !state.backend || !state.authenticated) return;
  await fetchJson("/api/notifications/acknowledge", {
    method: "POST",
    body: JSON.stringify({ notificationId: cleanId }),
  });
}

/**
 * Purpose: Run the rush notification target list workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rushNotificationTargetList(notification) {
  const details = notification?.details || {};
  const accessibleIds = new Set((state.lists || []).map((list) => String(list.id || "")));
  const affectedLists = (Array.isArray(details.affectedLists) ? details.affectedLists : [])
    .filter((list) => list && accessibleIds.has(String(list.id || "")));
  const legacyListId = String(details.listId || "");
  if (!affectedLists.length && legacyListId && accessibleIds.has(legacyListId)) {
    const list = state.lists.find((entry) => String(entry.id) === legacyListId);
    if (list) affectedLists.push(list);
  }
  if (!affectedLists.length) return null;

  const currentId = String(state.activeListId || "");
  const currentMatch = affectedLists.find((list) => String(list.id || "") === currentId);
  if (currentMatch) return currentMatch;

  const currentCategory = stageCategory(state.meta || {});
  return affectedLists.find((list) => stageCategory(list) === currentCategory)
    || affectedLists.find((list) => stageCategory(list) === "staged")
    || affectedLists[0];
}

/**
 * Purpose: Open the open rush notification list workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function openRushNotificationList(notification) {
  const targetList = rushNotificationTargetList(notification);
  state.activeFilters = new Set(["rushes"]);
  syncScanFilterButtons();
  state.search = "";
  state.pageIndex = 1;
  if (els.searchInput) els.searchInput.value = "";

  if (targetList?.id) {
    await activateList(String(targetList.id), true);
  } else {
    showPage("scan");
    renderScanPage();
  }
  showFloatingNotice(
    targetList
      ? `Opened ${stageLabel(targetList)} and filtered the delivery list to Rush items.`
      : "Filtered the current delivery list to Rush items.",
    "success",
  );
}

/**
 * Purpose: Run the wait for active scan operations workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function waitForActiveScanOperations() {
  while (state.activeScanOperations.size) {
    await Promise.allSettled([...state.activeScanOperations]);
  }
  await new Promise((resolve) => window.setTimeout(resolve, 0));
}

/**
 * Purpose: Run the acknowledge rush and open workflow for the browser application.
 * Effects: Updates visible dom state, may call the backend api.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function acknowledgeRushAndOpen(notification, button) {
  if (state.rushRedirectInProgress) return;
  state.rushRedirectInProgress = true;
  const notificationId = Number(notification?.id || state.activeNotificationId || 0);
  const hadActiveScans = state.activeScanOperations.size > 0;
  const pendingInput = String(els.scanInput?.value || "").trim();
  if (button) {
    button.disabled = true;
    button.textContent = state.language === "es" ? "Finalizando escaneos..." : "Finishing current scans...";
  }
  document.getElementById("rushAlertShell")?.remove();
  updateModalScrollLock();

  try {
    await waitForActiveScanOperations();
    const remainingInput = String(els.scanInput?.value || "").trim() || (hadActiveScans ? "" : pendingInput);
    if (remainingInput) {
      if (els.scanInput) els.scanInput.value = "";
      await processScan(remainingInput);
      await waitForActiveScanOperations();
    }
    await acknowledgeUserNotification(notificationId);
    if (notificationId) state.acknowledgedNotificationIds.add(notificationId);
    state.activeNotificationId = 0;
    await openRushNotificationList(notification);
  } catch (error) {
    if (pendingInput && els.scanInput && !els.scanInput.value) els.scanInput.value = pendingInput;
    state.activeNotificationId = 0;
    showFloatingNotice(`Rush acknowledgment was paused: ${error.message}`, "error");
    window.setTimeout(() => showRushAlert(notification), 180);
  } finally {
    state.rushRedirectInProgress = false;
    window.setTimeout(() => presentNextUserNotification(), 180);
  }
}

/**
 * Purpose: Open the show rush alert workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function showRushAlert(notification) {
  if (!isRushPopupNotification(notification) || rushNotificationIsBlocked()) return false;
  const notificationId = Number(notification.id || 0);
  const details = notification.details || {};
  const spanish = state.language === "es";
  const job = String(details.job || "").trim();
  const order = String(details.order || "").trim();
  const lookup = String(details.lookup || "").trim();
  const customer = String(details.customer || "").trim();
  const deliveryDate = String(details.deliveryDate || "").trim();
  const previousDeliveryDate = String(details.previousDeliveryDate || "").trim();
  const deliveryDateLabel = deliveryDate ? formatDisplayDate(deliveryDate) : "";
  const previousDeliveryDateLabel = previousDeliveryDate ? formatDisplayDate(previousDeliveryDate) : "";
  const itemCount = Math.max(Number(details.items || 0), 1);
  const itemLabels = Array.isArray(details.itemLabels) ? details.itemLabels.filter(Boolean).join(", ") : String(details.itemLabels || "").trim();
  const route = String(details.route || "").trim();
  const productLabels = Array.isArray(details.products) ? details.products.filter(Boolean).map((value) => String(value).trim()).filter(Boolean) : [];
  const productSummary = productLabels.length ? productLabels.join("; ") : String(details.products || "").trim();
  const productSummaryHtml = productLabels.length
    ? productLabels.map((label) => `<span class="glass-tone-inline" ${glassToneAttributes(label)}>${escapeHtml(label)}</span>`).join("")
    : escapeHtml(productSummary);
  const reason = String(details.reason || "").trim();
  const submittedBy = String(details.submittedBy || notification.createdBy || "").trim();
  const affectedLists = Array.isArray(details.affectedLists) ? details.affectedLists : [];
  const affectsIndianTrail = priorityListsIncludeIndianTrail(affectedLists);
  const directToTruck = affectsIndianTrail && Boolean(details.directToTruck);
  const affectedStages = [...new Set(
    affectedLists
      .map((list) => stageLabel(list))
      .filter(Boolean),
  )].join(" → ");
  const importedFromIntake = String(details.source || "").toLowerCase() === "priority-intake-match";
  const title = spanish
    ? (importedFromIntake ? "Orden urgente importada" : "Nueva orden urgente")
    : (importedFromIntake ? "Rush Order Imported" : "New Rush Submitted");
  const message = spanish
    ? (importedFromIntake
      ? `${job || order || lookup || "Este trabajo"} llegó desde A+W y se marcó automáticamente como urgente. Priorice este trabajo.`
      : `${job || order || lookup || "Este trabajo"} fue marcado como urgente${customer ? ` para ${customer}` : ""}${deliveryDateLabel ? ` para la nueva fecha de entrega ${deliveryDateLabel}` : ""}. Priorice este trabajo.`)
    : (importedFromIntake
      ? `${job || order || lookup || "This work"} arrived from A+W and was automatically marked Rush. Prioritize this work.`
      : `${job || order || lookup || "This work"} was marked as Rush${customer ? ` for ${customer}` : ""}${deliveryDateLabel ? ` for the new delivery date ${deliveryDateLabel}` : ""}. Prioritize this work.`);

  const shell = document.createElement("div");
  shell.id = "rushAlertShell";
  shell.className = "rush-alert-shell";
  shell.dataset.notificationId = String(notificationId);
  shell.innerHTML = `
    <div class="rush-alert-backdrop" aria-hidden="true"></div>
    <section class="rush-alert-panel" role="alertdialog" aria-modal="true" aria-labelledby="rushAlertTitle">
      <div class="rush-alert-icon" aria-hidden="true"><i>!</i></div>
      <div class="rush-alert-copy">
        <small>${spanish ? "ALERTA DE PRODUCCION" : "PRODUCTION PRIORITY ALERT"}</small>
        <h2 id="rushAlertTitle">${escapeHtml(title)}</h2>
        <p>${escapeHtml(message)}</p>
      </div>
      <div class="rush-alert-details">
        ${job ? `<div><small>${spanish ? "Num. de trabajo" : "Job Nr."}</small><strong>${escapeHtml(job)}</strong></div>` : ""}
        ${order ? `<div><small>${spanish ? "Orden" : "Order"}</small><strong>${escapeHtml(order)}</strong></div>` : ""}
        ${itemLabels ? `<div><small>${spanish ? "Articulos" : "Items"}</small><strong>${escapeHtml(itemLabels)}</strong></div>` : ""}
        ${customer ? `<div><small>${spanish ? "Cliente" : "Customer"}</small><strong>${escapeHtml(customer)}</strong></div>` : ""}
        ${route ? `<div><small>${spanish ? "Ruta" : "Route"}</small><strong>${escapeHtml(route)}</strong></div>` : ""}
        ${affectedStages ? `<div class="rush-alert-wide-detail"><small>${spanish ? "Etapas afectadas" : "Applicable stages"}</small><strong>${escapeHtml(affectedStages)}</strong></div>` : ""}
        ${deliveryDateLabel ? `<div class="rush-alert-date-detail"><small>${spanish ? "Nueva fecha de entrega" : "New delivery date"}</small><strong>${escapeHtml(deliveryDateLabel)}</strong></div>` : ""}
        ${previousDeliveryDateLabel && previousDeliveryDate !== deliveryDate ? `<div><small>${spanish ? "Fecha de entrega anterior" : "Previous delivery date"}</small><strong>${escapeHtml(previousDeliveryDateLabel)}</strong></div>` : ""}
        ${affectsIndianTrail ? `<div class="rush-alert-wide-detail ${directToTruck ? "rush-alert-truck-detail" : ""}"><small>${spanish ? "Manejo en Indian Trail" : "Indian Trail handling"}</small><strong>${escapeHtml(directToTruck ? (spanish ? "Enviar directamente al camion del instalador; no colocar en una bahia" : "Send straight to installer truck; do not place in a bay") : (spanish ? "Acelerar hacia la bahia prioritaria indicada" : "Expedite into the assigned priority bay"))}</strong></div>` : ""}
        ${productSummary ? `<div class="rush-alert-wide-detail"><small>${spanish ? "Productos / tamaños" : "Products / sizes"}</small><strong class="glass-tone-list-v379">${productSummaryHtml}</strong></div>` : ""}
        ${reason ? `<div class="rush-alert-wide-detail"><small>${spanish ? "Motivo" : "Reason"}</small><strong>${escapeHtml(reason)}</strong></div>` : ""}
        ${details.responsible ? `<div><small>${spanish ? "Responsable" : "Responsible"}</small><strong>${escapeHtml(details.responsible)}</strong></div>` : ""}
        <div><small>${spanish ? "Artículos prioritarios" : "Priority items"}</small><strong>${escapeHtml(itemCount)}</strong></div>
        ${submittedBy ? `<div><small>${spanish ? "Enviado por" : "Submitted by"}</small><strong>${escapeHtml(submittedBy)}</strong></div>` : ""}
      </div>
      <p class="rush-alert-scan-note">${spanish ? "Puede continuar escaneando. Al reconocer, los escaneos actuales terminaran antes de abrir la lista urgente." : "You can keep scanning. Acknowledging waits for current scans to finish before opening the Rush list."}</p>
      <button class="rush-alert-acknowledge" type="button" data-rush-alert-acknowledge>${spanish ? "Reconocer y ver urgente" : "Acknowledge Rush & View"}</button>
    </section>
  `;
  document.body.appendChild(shell);
  state.activeNotificationId = notificationId;
  updateModalScrollLock();
  shell.querySelector("[data-rush-alert-acknowledge]")?.addEventListener("click", (event) => {
    acknowledgeRushAndOpen(notification, event.currentTarget).catch((error) => {
      showInlineError(error?.message || "The Rush request could not be opened.", true);
    });
  });
  els.scanInput?.focus();
  return true;
}

/**
 * Purpose: Run the present next user notification workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function presentNextUserNotification() {
  if (!state.authenticated || document.hidden || rushNotificationIsBlocked()) return;
  const next = state.notificationQueue.shift();
  if (!next) return;
  if (!showRushAlert(next)) {
    state.notificationQueue.unshift(next);
    return;
  }
  playAppSound("notification");
}

/**
 * Purpose: Run the poll user notifications workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function pollUserNotifications() {
  // Modal workspaces are interaction-heavy. Defer background notification
  // fetch/render work until the GUI closes so it cannot steal a frame or open
  // a competing popup while the operator is scrolling or editing.
  if (!state.backend || !state.authenticated || document.hidden || appModalUiIsOpen()) return;
  try {
    const payload = await fetchJson("/api/notifications/pending");
    const knownIds = new Set([
      ...state.notificationQueue.map((notification) => Number(notification.id || 0)),
      ...state.acknowledgedNotificationIds,
      Number(state.activeNotificationId || 0),
    ]);
    for (const notification of payload.notifications || []) {
      const notificationId = Number(notification.id || 0);
      if (!notificationId || knownIds.has(notificationId)) continue;
      knownIds.add(notificationId);
      if (!isRushPopupNotification(notification)) continue;
      state.notificationQueue.push(notification);
    }
    presentNextUserNotification();
  } catch {
    // Notification polling must never interrupt scanning.
  }
}

/**
 * Purpose: Run the start notification polling workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function startNotificationPolling() {
  stopNotificationPolling();
  void pollUserNotifications();
  state.notificationPollTimer = window.setInterval(() => {
    void pollUserNotifications();
  }, 7000);
}

/**
 * Purpose: Run the stop notification polling workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function stopNotificationPolling() {
  if (state.notificationPollTimer) window.clearInterval(state.notificationPollTimer);
  state.notificationPollTimer = null;
  state.notificationQueue = [];
  state.activeNotificationId = 0;
  state.acknowledgedNotificationIds.clear();
  document.getElementById("rushAlertShell")?.remove();
}

/**
 * Purpose: Run the restore fullscreen after managed print workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function restoreFullscreenAfterManagedPrint() {
  const shouldRestore = Boolean(state.restoreFullscreenAfterPrint);
  state.restoreFullscreenAfterPrint = false;
  window.focus();
  if (!shouldRestore || document.fullscreenElement || !document.fullscreenEnabled) return;

  try {
    await document.documentElement.requestFullscreen();
  } catch {
    showFullscreenRecoveryPrompt({
      eyebrow: "Print complete",
      message: "The print window closed. Your browser requires one click to enter fullscreen again.",
    });
  }
}

/**
 * Purpose: Run the stop managed print window watch workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function stopManagedPrintWindowWatch(printWindow = null) {
  if (printWindow && state.managedPrintWindow && state.managedPrintWindow !== printWindow) return;
  if (state.managedPrintWatchTimer) {
    window.clearInterval(state.managedPrintWatchTimer);
    state.managedPrintWatchTimer = null;
  }
  if (!printWindow || state.managedPrintWindow === printWindow) {
    state.managedPrintWindow = null;
  }
}

/**
 * Purpose: Run the finish managed print session workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function finishManagedPrintSession(printWindow = null, options = {}) {
  if (printWindow && state.managedPrintWindow && state.managedPrintWindow !== printWindow) return;
  stopManagedPrintWindowWatch(printWindow);
  if (options.printed) playAppSound("print_ready", { force: true });
  await restoreFullscreenAfterManagedPrint();
}

/**
 * Purpose: Run the check managed print window closed workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function checkManagedPrintWindowClosed() {
  const printWindow = state.managedPrintWindow;
  if (!printWindow) return;

  let isClosed = false;
  try {
    isClosed = Boolean(printWindow.closed);
  } catch {
    return;
  }

  if (isClosed) {
    finishManagedPrintSession(printWindow).catch(() => {});
  }
}

/**
 * Purpose: Run the watch managed print window workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function watchManagedPrintWindow(printWindow) {
  stopManagedPrintWindowWatch();
  state.managedPrintWindow = printWindow;
  state.managedPrintWatchTimer = window.setInterval(checkManagedPrintWindowClosed, 250);
}

/**
 * Purpose: Run the launch managed print workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function launchManagedPrint(url, windowName = "deliveryListPrintWindow") {
  state.restoreFullscreenAfterPrint = Boolean(document.fullscreenElement);
  const printWindow = window.open(url, windowName, "popup=yes,width=1180,height=860,resizable=yes,scrollbars=yes");
  if (!printWindow) {
    state.restoreFullscreenAfterPrint = false;
    showInlineError("Allow popups to open the print preview.", false);
    return null;
  }
  watchManagedPrintWindow(printWindow);
  printWindow.focus();
  return printWindow;
}

/**
 * Purpose: Run the print current page managed workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function printCurrentPageManaged() {
  state.restoreFullscreenAfterPrint = Boolean(document.fullscreenElement);
  /**
   * Purpose: Run the after print workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const afterPrint = () => {
    window.removeEventListener("afterprint", afterPrint);
    playAppSound("print_ready", { force: true });
    restoreFullscreenAfterManagedPrint();
  };
  window.addEventListener("afterprint", afterPrint);
  window.print();
}

/**
 * Purpose: Run the run global search workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function hydrateFabricationStatusesV474(rows = [], { context = "scan" } = {}) {
  if (!state.backend || !hasPermission("global_search")) return;
  const candidates = [];
  for (const row of rows || []) {
    const order = String(row?.order || "").trim();
    const item = String(row?.item || "").trim();
    const job = String(row?.job || "").trim();
    if (!order) continue;
    const key = fabricationStatusKeyV474(order, item, job);
    if (state.fabricationStatusCacheV474.has(key) || state.fabricationStatusPendingV474.has(key)) continue;
    state.fabricationStatusPendingV474.add(key);
    candidates.push({ key, order, item, job });
    if (candidates.length >= 80) break;
  }
  if (!candidates.length) return;

  ++state.fabricationStatusBatchTokenV474;
  const repaint = () => {
    if (context === "search") {
      const query = String(state.globalSearchLastQuery || "").trim();
      if (query && query === String(els.headerGlobalSearchInput?.value || "").trim()) {
        state.globalSearchLastResults = state.globalSearchLastResults.map((row) => ({
          ...row,
          fabrication: state.fabricationStatusCacheV474.get(fabricationStatusKeyV474(row.order, row.item, row.job)) || row.fabrication,
        }));
        renderGlobalSearchResults(state.globalSearchLastResults);
      }
    } else if (context === "scan" && state.page === "scan") {
      scheduleScanRender();
    }
  };

  // Smaller sequential requests publish the first machine result quickly while
  // keeping PDF/network-share work bounded. Total work is unchanged and the
  // scanner still paints before any production evidence is requested.
  const chunkSize = 10;
  for (let offset = 0; offset < candidates.length; offset += chunkSize) {
    const chunk = candidates.slice(offset, offset + chunkSize);
    try {
      const payload = await fetchJson("/api/production-files/status-batch", {
        method: "POST",
        body: JSON.stringify({ items: chunk }),
      });
      for (const result of payload.results || []) {
        const key = String(result.key || fabricationStatusKeyV474(result.order, result.item, result.job));
        state.fabricationStatusCacheV474.set(key, result.status || {});
      }
    } catch (_error) {
      // Production evidence is supplemental UI state. A temporarily unreachable
      // share must not turn Scan/Search into an error path or block their paint.
    } finally {
      chunk.forEach(({ key }) => state.fabricationStatusPendingV474.delete(key));
    }
    repaint();
  }
}

async function runGlobalSearch() {
  if (!hasPermission("global_search")) return [];
  const query = els.headerGlobalSearchInput?.value.trim() || "";
  const requestId = ++state.globalSearchRequestId;
  if (query.length < 2) {
    state.globalSearchLastQuery = "";
    state.globalSearchLastResults = [];
    renderGlobalSearchResults([]);
    return [];
  }
  const [payload] = await Promise.all([
    fetchJson(`/api/search?q=${encodeURIComponent(query)}`),
    ensureGlassVisualLookupLibrary().catch(() => []),
  ]);
  const results = payload.results || [];
  if (requestId !== state.globalSearchRequestId || query !== (els.headerGlobalSearchInput?.value.trim() || "")) {
    return [];
  }
  state.globalSearchLastQuery = query;
  state.globalSearchLastResults = results;
  renderGlobalSearchResults(results);
  // v0.474: keep keystroke-to-result latency tied to SQLite only; fabrication
  // evidence arrives as a single asynchronous batch after the cards are visible.
  hydrateFabricationStatusesV474(results, { context: "search" }).catch(() => {});
  return results;
}

/**
 * Purpose: Run the global search process class workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function globalSearchProcessClass(text, result = {}) {
  const signal = `${text || ""} ${result.stage || ""} ${result.scanner || ""} ${result.bayCode || ""} ${result.bay || ""} ${result.rackCode || ""} ${result.rackType || ""}`.toLowerCase();
  if (signal.includes("bay")) return "bay";
  if (signal.includes("truck") || result.rackCode === "T" || /^T\d+$/i.test(String(result.rackCode || ""))) return "truck";
  if (signal.includes("rack") || result.rackCode) return "rack";
  if (signal.includes("not scanned") || signal.includes("not started")) return "not-started";
  if (signal.includes("partial") || /\b\d+\s*\/\s*\d+\b/.test(signal)) return "partial";
  if (signal.includes("complete") || signal.includes("received") || signal.includes("inbound")) return "received";
  if (signal.includes("outbound")) return "outbound";
  if (signal.includes("staging")) return "staging";
  if (signal.includes("customer pickup") || /\bcpu\b/.test(signal)) return "cpu";
  if (signal.includes("greenville") || /\bgnv\b/.test(signal)) return "greenville";
  if (signal.includes("dtc") || signal.includes("deliver to customer")) return "dtc";
  return "default";
}

/**
 * Purpose: Run the global search status badges workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
/** Return the stage accent used by compact Smart Search result gradients/cells. */
function globalSearchStageColorV430(result = {}) {
  const stageKey = globalSearchStageKeyV435(result);
  return {
    staging: "#4d74e6",
    outbound: "#d89a1f",
    received: "#41b979",
    cpu: "#9b70dd",
    greenville: "#43b4c8",
    dtc: "#e26da4",
    bay: "#238a72",
    truck: "#7659c9",
    rack: "#4f74bd",
    partial: "#c89020",
    unscanned: "#94a3b8",
    default: "#60758d",
  }[stageKey] || "#60758d";
}

/** Return a distinct, search-friendly route accent using the maintained route palette. */
function globalSearchRouteColorV430(route = "") {
  const raw = String(route || "").trim().toUpperCase();
  if (!raw) return "#8191a3";

  // Smart Search commonly receives short route codes from imported delivery lists.
  // Normalize the maintained routes here without changing the underlying route value.
  if (["IT", "INDIAN TRAIL", "INDIAN-TRAIL"].includes(raw)) return "#3aa667";
  if (["CPU", "CUSTOMER PICKUP", "CUSTOMER-PICKUP"].includes(raw)) return "#e28a2b";
  if (["DTC", "DELIVER TO CUSTOMER", "DELIVER-TO-CUSTOMER"].includes(raw)) return "#d65391";
  if (["GNV", "GRN", "GREENVILLE"].includes(raw)) return "#16a3ad";
  if (["AIRPORT", "AIRPORT ROAD", "AIRPORT-ROAD", "AR"].includes(raw)) return "#4f7fd3";

  return customerRouteVisualColorV347(raw);
}

function globalSearchStatusBadges(result) {
  // v0.439: the Stage cell is presentation-owned. Show the administrator's
  // Lookup Manager display name rather than a physical location such as Truck 2.
  const label = globalSearchStageDisplayNameV439(result);
  const processSignal = String(result.locationText || label || "Not Scanned Yet").trim();
  return `<small class="global-result-status ${globalSearchProcessClass(processSignal, result)}">${escapeHtml(label)}</small>`;
}

/** Resolve the current Smart Search stage through the Stage Lookup Manager. */
function globalSearchStageDisplayNameV439(result = {}) {
  const hasScan = Boolean(result.lastScanTime || Number(result.scanned || 0) > 0);
  if (!hasScan) return "Not Scanned Yet";

  const definitions = Array.isArray(state.manualEditLookups?.stages) ? state.manualEditLookups.stages : [];
  const storedStage = String(result.stage || "").trim();
  const storedStageLower = storedStage.toLowerCase();
  const exact = definitions.find((definition) => {
    const display = String(definition?.displayName || definition?.label || "").trim().toLowerCase();
    const key = String(definition?.key || definition?.value || "").trim().toLowerCase();
    return Boolean(storedStageLower) && (display === storedStageLower || key === storedStageLower);
  });
  if (exact?.displayName || exact?.label) return String(exact.displayName || exact.label).trim();

  const stageKey = globalSearchStageKeyV435(result);
  const presetByKey = {
    staging: "airport_staging",
    outbound: "airport_outbound",
    received: "indian_trail",
    cpu: "cpu",
    greenville: "greenville",
    dtc: "dtc",
  };
  const configured = presetByKey[stageKey] ? configuredStageByPresetV355(presetByKey[stageKey]) : null;
  if (configured?.displayName) return String(configured.displayName).trim();

  const labels = workflowPresentationV355();
  const fallbackByKey = {
    staging: labels.stagingStage,
    outbound: labels.outboundStage,
    received: labels.receivingStage,
    cpu: labels.pickupStage,
    greenville: labels.branchStage,
    dtc: labels.directStage,
  };
  return String(fallbackByKey[stageKey] || storedStage || result.locationText || "Last scanned stage").trim();
}

/** Format Smart Search scan timestamps without seconds for a compact status cell. */
function globalSearchScanDateTimeV439(value) {
  if (!value) return "";
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return String(value);
  return parsed.toLocaleString(appLocale(), {
    month: "numeric",
    day: "numeric",
    year: "2-digit",
    hour: "numeric",
    minute: "2-digit",
  });
}

/** Format Global Search delivery dates as compact M/D/YY values. */
function globalSearchCompactDateV425(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  const parsed = match
    ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12, 0, 0, 0)
    : new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;
  return parsed.toLocaleDateString(appLocale(), { month: "numeric", day: "numeric", year: "2-digit" });
}

/** Resolve the operational stage used by the v0.435 Smart Search card wash/icon. */
function globalSearchStageKeyV435(result = {}) {
  const preset = stagePresetFromValuesV445(result.stage || "", result.scanner || "", result.stagePreset || "");
  const presetKey = {
    airport_staging: "staging",
    airport_outbound: "outbound",
    indian_trail: "received",
    cpu: "cpu",
    greenville: "greenville",
    dtc: "dtc",
  }[preset];
  if (presetKey) return presetKey;
  const locationSignal = `${result.locationText || ""}`.toLowerCase();
  if (locationSignal.includes("bay")) return "bay";
  if (locationSignal.includes("truck")) return "truck";
  if (locationSignal.includes("rack")) return "rack";
  if (locationSignal.includes("partial")) return "partial";
  if (!result.lastScanTime && !Number(result.scanned || 0)) return "unscanned";
  return "default";
}

