/**
 * Purpose: Create the add spacer bay workflow using the existing shared UI state.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function addSpacerBay() {
  const selected = selectedBay();
  const mapSection = await promptWebAppAction({
    title: "Add bay-map spacer",
    message: "Choose the bay group where the spacer should be added.",
    label: "Bay group",
    value: selected?.mapSection || "",
    placeholder: "Example: Showers",
    confirmLabel: "Add Spacer",
  });
  if (!mapSection) return;
  const before = bayLayoutSnapshot((bay) => bay.mapSection === mapSection);
  const result = await fetchJson("/api/indian-trail/bays/add", {
    method: "POST",
    body: JSON.stringify({
      mapSection,
      bayCategory: "Spacer",
      prefix: "Spacer",
      count: 1,
      spacer: true,
      ...requestContext(),
    }),
  });
  state.bays = result.bays || state.bays;
  const after = bayLayoutSnapshot((bay) => bay.mapSection === mapSection || result.created?.includes(bay.bayCode));
  pushBayLayoutHistory("add spacer", before, after);
  if (result.created?.[0]) state.selectedBayCode = result.created[0];
  renderBayMapPage();
  renderBayLayoutSelect();
  populateBayLayoutForm();
  showSaveConfirmation("A spacer was added to the Bay Map.");
}

