/**
 * Purpose: Load one existing lookup row into the guided editor.
 * Effects: Updates Lookup Manager UI state and form values without writing to the backend.
 * Flow: Finds the requested row by type/value, activates the matching tab, re-renders once, then fills and focuses the editor for an upsert save.
 */
function useLookupInEditor(type, value) {
  const cleanType = ["product", "route", "process", "glass_cost", "glass_color", "stage_definition"].includes(type) ? type : "product";
  const item = lookupItemsForType(cleanType).find((entry) => String(entry.value || "") === String(value || ""));
  if (!item) return;

  state.lookupManagerActiveType = cleanType;
  renderLookupManagerModal();
  const valueInput = document.getElementById("lookupValueInput");
  const labelInput = document.getElementById("lookupLabelInput");
  const categoryInput = document.getElementById("lookupCategoryInput");
  const matchInput = document.getElementById("lookupMatchTermsInput");
  const costInput = document.getElementById("lookupCostInput");
  const colorInput = document.getElementById("lookupColorInput");
  if (valueInput) valueInput.value = item.value || "";
  if (labelInput) labelInput.value = item.label || item.value || "";
  if (categoryInput) categoryInput.value = item.category || "";
  if (matchInput) matchInput.value = item.matchTerms || "";
  if (costInput) costInput.value = item.rate !== null && item.rate !== "" && Number.isFinite(Number(item.rate)) ? String(item.rate) : "";
  if (colorInput) colorInput.value = normalizeGlassVisualColor(item.color) || glassVisualColor(item.value || item.label);
  syncLookupManagerFormGuidance();
  openLookupEditorV470({ focusSelector: "#lookupValueInput" });
  valueInput?.select();
}

/**
 * Purpose: Clear the current Lookup Manager editor without changing saved lookup data.
 * Effects: Resets current form fields and the live preview.
 * Flow: Clears all editable fields, restores contextual guidance, and returns focus to the saved-value field.
 */
function clearLookupManagerForm() {
  ["lookupValueInput", "lookupLabelInput", "lookupCategoryInput", "lookupMatchTermsInput", "lookupCostInput"].forEach((id) => {
    const input = document.getElementById(id);
    if (input) input.value = "";
  });
  const colorInput = document.getElementById("lookupColorInput");
  if (colorInput) colorInput.value = glassVisualColor(lookupEditorMeta("glass_color").example.split(" → ")[0]);
  syncLookupManagerFormGuidance();
  document.getElementById("lookupValueInput")?.focus();
}

/**
 * Purpose: Filter the visible Lookup Manager library without rebuilding the editor form.
 * Effects: Updates row visibility, result counts, and the no-results message in the open modal.
 * Flow: Stores the normalized query, compares it to each row's maintained search text, and toggles only the active library rows.
 */
function filterLookupManagerLibrary(query) {
  state.lookupManagerSearch = String(query || "");
  const clean = state.lookupManagerSearch.trim().toLowerCase();
  const rows = [...document.querySelectorAll("[data-lookup-row]")];
  let visibleCount = 0;
  rows.forEach((row) => {
    const visible = !clean || String(row.dataset.lookupSearch || "").includes(clean);
    row.hidden = !visible;
    if (visible) visibleCount += 1;
  });
  const counter = document.querySelector("[data-lookup-visible-count]");
  if (counter) counter.textContent = `${visibleCount} / ${rows.length}`;

  document.querySelectorAll("[data-lookup-group]").forEach((group) => {
    const groupRows = [...group.querySelectorAll("[data-lookup-row]")];
    const groupVisible = groupRows.filter((row) => !row.hidden).length;
    group.hidden = groupVisible === 0;
    const groupCounter = group.querySelector("[data-lookup-group-count]");
    if (groupCounter) groupCounter.textContent = String(groupVisible);
  });

  let empty = document.querySelector("[data-lookup-filter-empty]");
  const list = document.querySelector("[data-lookup-row-list]");
  if (!visibleCount && rows.length && list) {
    if (!empty) {
      empty = document.createElement("div");
      empty.dataset.lookupFilterEmpty = "true";
      empty.className = "lookup-empty-state";
      empty.innerHTML = "<strong>No matching lookup values</strong><span>Try a shorter search or clear the search field.</span>";
      list.appendChild(empty);
      applyLanguageToRoot(empty);
    }
    empty.hidden = false;
  } else if (empty) {
    empty.hidden = true;
  }
}

/**
 * Purpose: Save one manual-edit lookup value through the existing Lookup Manager workflow.
 * Effects: Writes the lookup through the backend, refreshes shared lookup state and the open modal, and shows the shared save confirmation.
 * Flow: Reads and validates the current form fields, posts the normalized value, adopts the returned lookup buckets, then re-renders the same modal.
 */
async function saveManualEditLookup() {
  const type = document.getElementById("lookupTypeInput")?.value || "";
  const value = document.getElementById("lookupValueInput")?.value.trim() || "";
  const label = document.getElementById("lookupLabelInput")?.value.trim() || value;
  const category = document.getElementById("lookupCategoryInput")?.value.trim() || "";
  const matchTerms = document.getElementById("lookupMatchTermsInput")?.value.trim() || "";
  const costText = document.getElementById("lookupCostInput")?.value.trim() || "";
  const colorText = document.getElementById("lookupColorInput")?.value.trim() || "";

  if (!value) {
    throw new Error(["glass_cost", "glass_color"].includes(type) ? "Glass type is required." : "Lookup value is required.");
  }

  const request = { type, value, label, category, matchTerms };
  if (type === "glass_cost") {
    const rate = Number(costText);
    if (!costText || !Number.isFinite(rate) || rate < 0) {
      throw new Error("Enter a valid glass cost per SQFT.");
    }
    request.rate = rate;
  } else if (type === "glass_color") {
    const color = normalizeGlassVisualColor(colorText);
    if (!color) throw new Error("Choose a valid glass color.");
    request.color = color;
  }

  const payload = await fetchJson("/api/admin/manual-edit-lookups", {
    method: "POST",
    body: JSON.stringify(request),
  });

  adoptManualEditLookups(payload);
  if (type === "glass_color") {
    state.glassVisualLookupLoaded = true;
    state.lastGlassFilterSignature = "";
    renderScanPage();
    if (state.page === "bays") renderBayMapPage();
  }

  // v0.261: Refresh the report summary after a pricing save so the next
  // Statistics view and PDF use the new material rate without a browser reload.
  if (type === "glass_cost") await loadHomeReportSummary();

  state.lookupManagerActiveType = type || state.lookupManagerActiveType;
  renderLookupManagerModal();
  showSaveConfirmation(type === "glass_cost"
    ? `${value} material cost was saved to the Lookup Manager.`
    : type === "glass_color"
      ? `${value} visual color was saved to the Lookup Manager.`
      : `${label || value} was saved to the Lookup Manager.`);
}

/** Remove one Lookup Manager row through the shared tombstone workflow. */
async function removeManualEditLookupV346(type, value, label = value) {
  const cleanType = String(type || "").trim();
  const cleanValue = String(value || "").trim();
  if (!cleanType || !cleanValue) return;
  const stageRemoval = cleanType === "stage_definition";
  const confirmed = await confirmWebAppAction({
    title: stageRemoval ? `Remove stage ${label}?` : `Remove ${label}?`,
    message: stageRemoval
      ? "Future imports will stop creating this stage definition. Existing delivery-list records remain available until removed intentionally."
      : "This value will be removed from the active Lookup Manager library. Historical delivery-list rows are not rewritten.",
    details: stageRemoval ? "You can restore the stage later by saving the same stage key again." : "A discovered/default value is hidden with an administrator tombstone so it does not immediately reappear from historical imports.",
    confirmLabel: stageRemoval ? "Remove Stage" : "Remove Value",
    danger: true,
  });
  if (!confirmed) return;
  const payload = await fetchJson("/api/admin/manual-edit-lookups/remove", {
    method: "POST",
    body: JSON.stringify({ type: cleanType, value: cleanValue }),
  });
  adoptManualEditLookups(payload);
  renderLookupManagerModal();
  configureAdminModalSectionTabsV345("lookups");
  showSaveConfirmation(`${label || cleanValue} was removed from the active library.`);
}

