/**
 * Purpose: Run the save rack set quick edit workflow for the browser application.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function saveRackSetQuickEdit() {
  const oldLabel = state.rackManagerEditingSetLabel || "";
  const newType = String(document.getElementById("rackManagerSetTypeInput")?.value || oldLabel).trim() || oldLabel;
  const nameRoot = String(document.getElementById("rackManagerSetNameRootInput")?.value || newType).trim() || newType;
  const setIcon = String(document.getElementById("rackManagerSetIconInput")?.value || rackSetVisualIcon(oldLabel) || "rack").trim();
  const setColor = String(document.getElementById("rackManagerSetColorInput")?.value || rackSetVisualColor(oldLabel) || "#176d72").trim();
  /**
   * Purpose: Run the racks workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const racks = (state.racks || []).filter((rack) => rackGroupLabel(rack) === oldLabel);

  if (!oldLabel || !racks.length) return;

  let latestPayload = null;

  for (const rack of racks) {
    const number = rackSortNumber(rack.code);
    const isTruck = isTruckRack(rack);
    const nextType = isTruck ? "Truck" : newType;
    const nextName = isTruck
      ? rack.code === "T"
        ? rack.name || "Truck 1"
        : `${nameRoot || "Truck"}${number ? ` ${number}` : ""}`
      : `${nameRoot}${number ? ` ${number}` : ""}`;

    latestPayload = await fetchJson("/api/racks", {
      method: "POST",
      body: JSON.stringify({
        oldRackCode: rack.code,
        rackCode: rack.code,
        name: nextName,
        type: nextType,
        setIcon,
        setColor,
        visualSourceType: oldLabel,
      }),
    });
  }

  state.racks = latestPayload?.racks || state.racks || [];
  state.rackSummary = latestPayload?.summary || state.rackSummary || null;
  state.rackManagerEditingSetLabel = "";
  state.selectedRackSetLabel = newType;
  renderRacksPage();
  renderScanRackTools();

  if (!els.adminModal?.hidden && els.adminModalBody?.querySelector(".rack-manager-shell")) {
    els.adminModalBody.innerHTML = adminModalContent("racks");
  }

  showSaveConfirmation(`${oldLabel} rack set was saved.`);
}

/**
 * Purpose: Run the rack manager modal HTML workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rackManagerModalHtml() {
  const groups = new Map();
  for (const rack of state.racks || []) {
    const label = rackGroupLabel(rack);
    if (!groups.has(label)) groups.set(label, []);
    groups.get(label).push(rack);
  }

  const sortedGroups = [...groups.entries()].sort(([a], [b]) => {
    if (a === "Truck") return -1;
    if (b === "Truck") return 1;
    const order = { Steel: 1, Wood: 2, Coral: 3 };
    return (order[a] || 50) - (order[b] || 50) || a.localeCompare(b);
  });

  const selectedRack = selectedRackManagerRack(state.rackManagerSelectedCode) || state.racks[0] || null;
  state.rackManagerSelectedCode = selectedRack?.code || "";

  return `
    <div class="rack-manager-shell">
      <div class="rack-manager-topbar">
        <div>
          <strong>Rack Manager</strong>
          <span>Create rack sets first, add individual racks where they belong, and edit each group without leaving this workspace.</span>
        </div>
        <span class="rack-manager-summary">${escapeHtml(sortedGroups.length)} sets · ${escapeHtml(state.racks.length)} racks</span>
      </div>

      <section class="rack-manager-create-grid" aria-label="Add rack configuration">
        <button type="button" class="rack-manager-create-card is-set" data-rack-manager-new-set>
          <span class="rack-manager-create-icon rack-set-create-icon" aria-hidden="true"></span>
          <span><strong>Add Rack Set</strong><small>Create a new group for racks that share the same purpose or material.</small></span>
          <b aria-hidden="true">+</b>
        </button>
        <button type="button" class="rack-manager-create-card is-rack" data-rack-manager-new-rack>
          <span class="rack-manager-create-icon rack-create-icon" aria-hidden="true"></span>
          <span><strong>Add Individual Rack</strong><small>Create one rack and assign it to an existing rack set.</small></span>
          <b aria-hidden="true">+</b>
        </button>
      </section>

      ${rackManagerRackEditHtml() || rackManagerSetEditHtml()}

      <div class="rack-manager-grid">
        ${
          sortedGroups.length
            ? sortedGroups
                .map(([label, racks]) => {
                  const totalQty = racks.reduce((sum, rack) => sum + Number(rack.qty || 0), 0);
                  const setRacks = racks.filter((rack) => rack.code !== "T");
                  const emptyRackCount = setRacks.filter((rack) => Number(rack.qty || 0) === 0).length;
                  const canDeleteSet = setRacks.length > 0 && emptyRackCount === setRacks.length;

                  const expanded = state.expandedRackManagerGroups.has(label);
                  return `
                    <details class="rack-manager-group rack-manager-group-v272" data-rack-manager-group="${escapeHtml(label)}" ${expanded ? "open" : ""}>
                      <summary class="rack-manager-group-summary-v272">
                        <span class="rack-manager-group-icon rack-set-visual-icon-v269" data-rack-icon="${escapeHtml(rackSetVisualIcon(label))}" style="--rack-set-icon-color:${escapeHtml(rackSetVisualColor(label) || "#176d72")}" aria-hidden="true"></span>
                        <div class="rack-manager-group-copy-v272">
                          <h3>${escapeHtml(label)}</h3>
                          <span>${escapeHtml(racks.length)} rack${racks.length === 1 ? "" : "s"} | ${escapeHtml(totalQty)} pcs</span>
                        </div>
                        <span class="rack-manager-expand-hint-v272" aria-hidden="true">
                          <i></i>
                          <b class="rack-manager-expand-closed-v272">View racks</b>
                          <b class="rack-manager-expand-open-v272">Hide racks</b>
                        </span>
                        <div class="rack-manager-group-actions">
                          <button type="button" class="icon-only icon-plus" data-rack-manager-add-to-set="${escapeHtml(label)}" title="Add ${label === "Truck" ? "another truck" : `rack to ${escapeHtml(label)}`}" aria-label="Add ${label === "Truck" ? "another truck" : `rack to ${escapeHtml(label)}`}"></button>
                          <button type="button" class="icon-only icon-pencil" data-rack-set-edit="${escapeHtml(label)}" title="Edit ${escapeHtml(label)} set" aria-label="Edit ${escapeHtml(label)} set"></button>
                          <button type="button" class="icon-only icon-trash danger${canDeleteSet ? "" : " is-blocked"}" data-rack-set-delete="${escapeHtml(label)}" ${canDeleteSet ? "" : `aria-disabled="true" data-blocked-reason="Clear all ${escapeHtml(label)} racks before deleting this set."`} title="${canDeleteSet ? `Delete ${escapeHtml(label)} rack set` : `Clear all ${escapeHtml(label)} racks before deleting this set`}" aria-label="${canDeleteSet ? `Delete ${escapeHtml(label)} rack set` : `${escapeHtml(label)} rack set cannot be deleted until every rack is empty`}"></button>
                        </div>
                      </summary>

                      <div class="rack-manager-rows">
                        ${racks
                          .slice()
                          .sort((a, b) => Number(a.sortOrder || 0) - Number(b.sortOrder || 0) || String(a.code).localeCompare(String(b.code), undefined, { numeric: true }))
                          .map((rack) => {
                            const qty = Number(rack.qty || 0);
                            const isTruck = isTruckRack(rack);
                            const legacyTruck = rack.code === "T";
                            const canDelete = !legacyTruck && qty === 0;
                            const status = rackStatusLabel(rack);
                            const statusClass = rackStatusClassName(rack);

                            const isEditing = state.rackManagerEditingRackCode === rack.code;

                            return `
                              <article class="rack-manager-row ${isEditing ? "is-editing" : ""}">
                                <div>
                                  <strong>${escapeHtml(rackOperatorDisplayName(rack))}</strong>
                                  <span>${escapeHtml(rackDisplayCode(rack))}</span>
                                </div>
                                <span class="rack-status-badge ${escapeHtml(statusClass)}">${escapeHtml(status)}</span>
                                <b>${escapeHtml(qty)} pcs</b>
                                <button type="button" class="icon-only icon-pencil" data-rack-edit="${escapeHtml(rack.code)}" title="Edit rack" aria-label="Edit ${escapeHtml(rack.code)}"></button>
                                <button type="button" class="icon-only icon-trash danger${canDelete ? "" : " is-blocked"}" data-rack-delete="${escapeHtml(rack.code)}" ${canDelete ? "" : `aria-disabled="true" data-blocked-reason="Clear all pieces from ${escapeHtml(rack.code)} before deleting this rack."`} title="${canDelete ? "Delete empty rack" : "Clear all pieces before deleting this rack"}" aria-label="Delete ${escapeHtml(rack.code)}"></button>
                              </article>
                            `;
                          })
                          .join("")}
                      </div>
                    </details>
                  `;
                })
                .join("")
            : `<div class="admin-empty">No racks available. Create a rack set to get started.</div>`
        }
      </div>
    </div>
  `;
}

