function closeRoleCreateModal() {
  document.getElementById("roleCreateModalV340")?.remove();
  document.getElementById("roleCreateBackdropV340")?.remove();
  updateModalScrollLock();
}

function openRoleCreateModal() {
  closeRoleCreateModal();
  const backdrop = document.createElement("div");
  backdrop.id = "roleCreateBackdropV340";
  backdrop.className = "admin-child-modal-backdrop-v340";
  const dialog = document.createElement("section");
  dialog.id = "roleCreateModalV340";
  dialog.className = "admin-child-modal-v340 role-create-modal-v340";
  dialog.setAttribute("role", "dialog");
  dialog.setAttribute("aria-modal", "true");
  dialog.setAttribute("aria-labelledby", "roleCreateModalTitleV340");
  dialog.innerHTML = roleCreateDialogHtml();
  document.body.append(backdrop, dialog);
  backdrop.addEventListener("click", closeRoleCreateModal);
  dialog.addEventListener("click", (event) => {
    if (event.target.closest("[data-role-create-close]")) closeRoleCreateModal();
  });
  dialog.addEventListener("keydown", (event) => {
    if (event.key === "Escape") closeRoleCreateModal();
  });
  wireRolePermissionControls(dialog);
  updateModalScrollLock();
  window.requestAnimationFrame(() => dialog.querySelector("#newRoleName")?.focus());
}

function wireRolePermissionControls(root = els.adminModalBody) {
  if (!root) return;
  root.querySelectorAll(".permission-category").forEach((category) => {
    if (category.dataset.permissionWired === "true") return;
    category.dataset.permissionWired = "true";
    const summary = category.matches("details") ? category.querySelector(":scope > summary") : null;
    summary?.addEventListener("click", (event) => {
      if (event.target.closest("button, input, label")) return;
      event.preventDefault();
      category.open = !category.open;
    });
    const updateCount = () => {
      const inputs = [...category.querySelectorAll('input[type="checkbox"]')];
      const count = inputs.filter((item) => item.checked).length;
      const badge = category.querySelector("[data-permission-category-count]") || summary?.querySelector("b");
      if (badge) badge.textContent = `${count} / ${inputs.length}`;
    };
    category.querySelectorAll('input[type="checkbox"]').forEach((input) => {
      input.addEventListener("change", () => {
        input.closest("label")?.classList.toggle("is-checked", input.checked);
        updateCount();
      });
    });
    updateCount();
  });
}

async function createRoleFromForm(form) {
  const data = new FormData(form);
  const name = String(data.get("name") || "").trim();
  const description = String(data.get("description") || "").trim();
  const permissions = [...form.querySelectorAll('.role-create-permission-list input[type="checkbox"]:checked')]
    .map((input) => input.value)
    .filter(Boolean);
  const status = form.querySelector("#createRoleStatus");
  const submit = form.querySelector('button[type="submit"]');

  if (!name) {
    status.textContent = "Enter a role name.";
    form.querySelector("#newRoleName")?.focus();
    return;
  }

  if (!permissions.length) {
    const confirmed = await confirmWebAppAction({
      title: "Create role with no permissions?",
      message: `Create <strong>${escapeHtml(name)}</strong> without any permissions?`,
      details: "The role will exist, but users assigned to it will not be able to open application features until permissions are added.",
      confirmLabel: "Create Empty Role",
      danger: false,
    });
    if (!confirmed) return;
  }

  submit.disabled = true;
  status.textContent = "Creating role...";
  try {
    const payload = await fetchJson("/api/admin/roles", {
      method: "POST",
      body: JSON.stringify({ name, description, permissions }),
    });
    state.adminRoles = payload.roles || [];
    state.allPermissions = payload.permissions || state.allPermissions;
    state.rolePermissionOpenRoles.add(name);
    closeRoleCreateModal();
    if (els.adminModalBody) {
      els.adminModalBody.innerHTML = adminModalContent("roles");
      wireRolePermissionControls();
    }
    await refreshAdminPage();
    showSaveConfirmation(`${name} was created and is ready to assign to users.`);
  } catch (error) {
    status.textContent = error.message;
    throw error;
  } finally {
    submit.disabled = false;
  }
}

function setCreateRolePermissionSelection(mode) {
  const form = document.getElementById("createRoleForm");
  if (!form) return;
  const checked = mode === "all";
  form.querySelectorAll('.role-create-permission-list input[type="checkbox"]').forEach((input) => {
    input.checked = checked;
    input.closest("label")?.classList.toggle("is-checked", checked);
  });
  form.querySelectorAll("[data-role-create-category]").forEach((category) => {
    const inputs = [...category.querySelectorAll('input[type="checkbox"]')];
    const badge = category.querySelector("[data-permission-category-count]");
    if (badge) badge.textContent = `${inputs.filter((input) => input.checked).length} / ${inputs.length}`;
  });
  const status = form.querySelector("#createRoleStatus");
  if (status) status.textContent = checked ? "All available permissions selected." : "All permissions cleared.";
}

/**
 * Purpose: Run the permission summary from permissions workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function permissionSummaryFromPermissions(permissions) {
  const list = permissions || [];
  if (list.includes("view_admin")) return "Administration access";
  if (list.includes("manage_users")) return "User and system management";
  if (list.includes("manage_racks") || list.includes("transfer_rack_contents")) return "Rack and transportation management";
  if (list.includes("view_bays")) return "Indian Trail and Bay Map access";
  if (list.includes("scan_delivery_lists") || list.includes("scan")) return "Scanning and delivery-list access";
  return "Custom access";
}

/**
 * Purpose: Run the permission summary for user workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function permissionSummaryForUser(user) {
  const directPermissions = Array.isArray(user?.permissions) ? user.permissions : [];

  if (directPermissions.length) {
    return permissionSummaryFromPermissions(directPermissions);
  }

  const rolePermissions = (state.adminRoles || [])
    .filter((role) => (user?.roles || []).includes(role.name))
    .flatMap((role) => role.permissions || []);

  if (rolePermissions.length) {
    return permissionSummaryFromPermissions(rolePermissions);
  }

  const roleText = (user?.roles || []).map(roleDisplayLabelV355).join(", ");
  return roleText ? `${roleText} access` : "Custom access";
}

/**
 * Purpose: Run the save role permissions workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function saveRolePermissions(roleName) {
  rememberRolePermissionUiState();

  const card = document.querySelector(`[data-role-card="${CSS.escape(roleName)}"]`);

  if (!card) return;

  const permissions = [...card.querySelectorAll("input[type='checkbox']:checked")].map((input) => input.value);

  if (!permissions.length) {
    const confirmed = await confirmWebAppAction({
      title: "Save role with no permissions?",
      message: `Save <strong>${escapeHtml(roleName)}</strong> with no permissions?`,
      details: "Users with this role will not be able to access application features.",
      confirmLabel: "Save Empty Role",
    });
    if (!confirmed) return;
  }

  const payload = await fetchJson("/api/admin/roles/permissions", {
    method: "POST",
    body: JSON.stringify({ role: roleName, permissions }),
  });

  state.adminRoles = payload.roles || [];
  state.allPermissions = payload.permissions || state.allPermissions;

  if (els.adminModalBody) {
    els.adminModalBody.innerHTML = adminModalContent("roles");
    wireRolePermissionControls();
    restoreRolePermissionUiScroll();
  }

  await refreshAdminPage();

  showSaveConfirmation(`${roleName} permissions were saved. Access updates apply immediately to signed-in users with that role.`);
}

/**
 * Purpose: Run the manual edit delivery date for list workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditDeliveryDateForList(listId) {
  const effectiveListId = listId === MANUAL_EDIT_WHOLE_LIST_VALUE_V468 ? state.manualEditListId : listId;
  const selectedList = state.lists.find((item) => item.id === effectiveListId);

  return selectedList?.deliveryDate || state.lists[0]?.deliveryDate || "";
}

/** Return the current Manual Edit scope without replacing its real stage anchor. */
function manualEditWholeListScopeV468() {
  return state.manualEditScopeV468 === "whole";
}

/** Value used by the scope/stage selector. */
function manualEditScopeSelectionValueV468() {
  return manualEditWholeListScopeV468() ? MANUAL_EDIT_WHOLE_LIST_VALUE_V468 : (state.manualEditListId || "");
}

/**
 * Purpose: Run the manual edit stage lists for current delivery workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditStageListsForCurrentDelivery(selectedListId) {
  const deliveryDate = manualEditDeliveryDateForList(selectedListId);
  const stageLists = state.lists
    .filter((list) => list.deliveryDate === deliveryDate)
    .sort((a, b) => stageSort(a) - stageSort(b) || String(a.label || "").localeCompare(String(b.label || "")));

  return stageLists.length ? stageLists : state.lists.slice();
}

/**
 * Purpose: Run the manual edit stage summary workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditStageSummary(listId, wholeList = manualEditWholeListScopeV468()) {
  const list = state.lists.find((item) => item.id === listId) || state.lists[0] || {};

  if (!list.id) {
    return "No stage selected";
  }

  if (wholeList) return `${formatNumericDeliveryDate(list.deliveryDate)} - Whole delivery list`;
  return `${formatNumericDeliveryDate(list.deliveryDate)} - ${list.stage || "Stage"}`;
}

/**
 * Purpose: Run the manual edit modal HTML workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditFilterIsActive(group, value) {
  if (group === "attention") return (state.manualEditFilters.attention || []).includes(value);
  if (group === "glassType") {
    const selected = state.manualEditFilters.glassTypes || [];
    return value === "all" ? selected.length === 0 : selected.includes(value);
  }
  return String(state.manualEditFilters[group] || "all") === value;
}

function manualEditActiveFilterCount() {
  return ["progress", "route", "location"].filter((key) => String(state.manualEditFilters[key] || "all") !== "all").length
    + (state.manualEditFilters.attention || []).length
    + (state.manualEditFilters.glassTypes || []).length;
}

function manualEditFilterButton(group, value, label) {
  return `<button type="button" class="tab ${manualEditFilterIsActive(group, value) ? "is-active" : ""}" data-manual-edit-filter-group="${escapeHtml(group)}" data-manual-edit-filter-value="${escapeHtml(value)}">${escapeHtml(label)}</button>`;
}

