/**
 * Purpose: Run the user initials workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function userInitials(user) {
  const display = String(user?.displayName || user?.username || "?").trim();

  const parts = display
    .split(/\s+/)
    .map((part) => part[0])
    .filter(Boolean);

  if (parts.length >= 2) return `${parts[0]}${parts[1]}`.toUpperCase();

  return display.slice(0, 2).toUpperCase() || "?";
}

/**
 * Purpose: Run the user accent class workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function userAccentClass(user) {
  const text = String(user?.username || user?.displayName || "").toLowerCase();

  if (/admin/.test(text)) return "accent-admin";
  if (/lead|supervisor/.test(text)) return "accent-lead";
  if (/manager/.test(text)) return "accent-manager";
  if (/operator/.test(text)) return "accent-operator";
  if (/trail|it/.test(text)) return "accent-trail";

  return "accent-default";
}

/**
 * Purpose: Run the user action button HTML workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function userActionButtonHtml({ className = "", attr = "", label = "", icon = "", disabled = false }) {
  const safeLabel = escapeHtml(label);

  return `
    <button
      type="button"
      class="user-icon-action ${className}"
      ${attr}
      ${disabled ? "disabled" : ""}
      aria-label="${safeLabel}"
      title="${safeLabel}"
    >
      <span class="user-action-icon ${escapeHtml(icon)}" aria-hidden="true"></span>
    </button>
  `;
}

function availableRoleNames() {
  const names = (state.adminRoles || [])
    .map((role) => String(role?.name || "").trim())
    .filter(Boolean);

  return names.length ? [...new Set(names)].sort((a, b) => a.localeCompare(b)) : ROLE_OPTIONS.slice();
}

/**
 * Purpose: Render one labeled User Manager action using the shared icon library.
 * Effects: Produces markup only; delegated click handlers perform the actual action.
 * Flow: Applies a consistent tone, accessible label, and optional disabled state.
 */
function userManagerActionButtonHtml({ tone = "secondary", attr = "", label = "", icon = "", disabled = false }) {
  const safeLabel = escapeHtml(label);
  const sharedAction = icon === "icon-save-user"
    ? "icon-only icon-save"
    : icon === "icon-trash"
      ? "icon-only icon-trash danger"
      : icon === "icon-pencil"
        ? "icon-only icon-pencil"
        : "";
  if (sharedAction) {
    return `<button type="button" class="${sharedAction}" ${attr} ${disabled ? "disabled" : ""} aria-label="${safeLabel}" title="${safeLabel}"></button>`;
  }

  return `
    <button
      type="button"
      class="user-manager-action-button is-${escapeHtml(tone)}"
      ${attr}
      ${disabled ? "disabled" : ""}
      aria-label="${safeLabel}"
      title="${safeLabel}"
    >
      <span class="user-action-icon ${escapeHtml(icon)}" aria-hidden="true"></span>
      <span class="user-manager-button-label">${safeLabel}</span>
    </button>
  `;
}

